        UserRoleCode.RepairCrew => "CREW",
        UserRoleCode.Reporter => "REPORTER",
        _ => throw new ArgumentOutOfRangeException(nameof(roleCode), roleCode, "Role is not supported by the V2 actor contract.")
    };
