    public async Task<AuthResult> ChangePasswordAsync(
        ChangePasswordCommand command,
        CancellationToken cancellationToken = default)
    {
        if (command is null || command.UserId == Guid.Empty ||
            string.IsNullOrWhiteSpace(command.CurrentPassword) ||
            string.IsNullOrWhiteSpace(command.NewPassword) ||
            string.IsNullOrWhiteSpace(command.IdempotencyKey))
        {
            return new AuthResult(AuthStatus.InvalidInput);
        }

        var requestFingerprint = _passwordChangeFingerprintFactory.Create(command.UserId, command.NewPassword);
        var durableFingerprint = await _identityRepository.GetIdempotencyFingerprintAsync(
            command.UserId,
            "ChangePassword",
            command.IdempotencyKey.Trim(),
            cancellationToken);
        if (durableFingerprint is not null)
        {
            return new AuthResult(durableFingerprint == requestFingerprint
                ? AuthStatus.Success
                : AuthStatus.IdempotentConflict);
        }

        var preparation = await _credentialVerifier.PreparePasswordChangeAsync(
            command.UserId,
            command.CurrentPassword,
            command.NewPassword,
            cancellationToken);
        if (preparation.Status is PasswordChangePreparationStatus.PolicyRejected or PasswordChangePreparationStatus.ReusedPassword)
        {
            return new AuthResult(AuthStatus.PasswordPolicyRejected, ErrorMessage: preparation.ErrorMessage);
        }

        if (preparation.Status != PasswordChangePreparationStatus.Success || preparation.User is null ||
            string.IsNullOrWhiteSpace(preparation.NewPasswordHash) ||
            string.IsNullOrWhiteSpace(preparation.NewSecurityStamp))
        {
            return new AuthResult(AuthStatus.InvalidCredentials);
        }

        var persisted = await _identityRepository.ChangePasswordAtomicAsync(
            command.UserId,
            preparation.User.RowVersion,
            preparation.NewPasswordHash,
            preparation.NewSecurityStamp,
            command.IdempotencyKey.Trim(),
            requestFingerprint,
            command.CorrelationId,
            cancellationToken);
        if (persisted.IdempotentConflict)
        {
            return new AuthResult(AuthStatus.IdempotentConflict);
        }

        if (persisted.StaleConcurrency)
        {
            return new AuthResult(AuthStatus.Conflict);
        }

        return persisted.Succeeded || persisted.IdempotentReplay
            ? new AuthResult(AuthStatus.Success)
            : new AuthResult(AuthStatus.InvalidCredentials);
    }

    public async Task<AuthResult> CompleteForcedPasswordChangeAsync(
        ForcedPasswordChangeCommand command,
        CancellationToken cancellationToken = default)
    {
        if (command is null ||
            string.IsNullOrWhiteSpace(command.Username) ||
            string.IsNullOrWhiteSpace(command.CurrentPassword) ||
            string.IsNullOrWhiteSpace(command.NewPassword) ||
            command.NewPassword != command.ConfirmPassword ||
            command.OperationId == Guid.Empty)
        {
            return new AuthResult(AuthStatus.InvalidInput);
        }

        var preparation = await _credentialVerifier.PrepareForcedPasswordChangeAsync(
            command.Username.Trim(),
            command.CurrentPassword,
            command.NewPassword,
            cancellationToken);
        if (preparation.Status == PasswordChangePreparationStatus.PolicyRejected ||
            preparation.Status == PasswordChangePreparationStatus.ReusedPassword)
        {
            return new AuthResult(AuthStatus.PasswordPolicyRejected, ErrorMessage: preparation.ErrorMessage);
        }

        var user = preparation.User;
        if (preparation.Status != PasswordChangePreparationStatus.Success ||
            user is null ||
            string.IsNullOrWhiteSpace(preparation.NewPasswordHash) ||
            string.IsNullOrWhiteSpace(preparation.NewSecurityStamp))
        {
            return new AuthResult(AuthStatus.InvalidCredentials);
        }

        if (user.Status != UserStatus.Active)
        {
            return new AuthResult(AuthStatus.InvalidCredentials);
        }

        var result = await _identityRepository.CompleteForcedPasswordChangeAtomicAsync(
            user.Id,
            user.RowVersion,
            preparation.NewPasswordHash,
            preparation.NewSecurityStamp,
            _passwordChangeFingerprintFactory.Create(user.Id, command.NewPassword),
            command.OperationId,
            command.CorrelationId,
            cancellationToken);
        return result.Status switch
        {
            ForcedPasswordChangeStatus.Success or ForcedPasswordChangeStatus.IdempotentReplay =>
                new AuthResult(AuthStatus.Success),
            ForcedPasswordChangeStatus.IdempotentConflict or ForcedPasswordChangeStatus.StaleConcurrency =>
                new AuthResult(AuthStatus.Conflict),
            ForcedPasswordChangeStatus.NotRequired => new AuthResult(AuthStatus.NotRequired),
            ForcedPasswordChangeStatus.InvalidInput => new AuthResult(AuthStatus.InvalidInput),
            _ => new AuthResult(AuthStatus.InvalidCredentials)
        };
    }

    private AuthResult Success(
        UserSecurityState user,
        Guid sessionId,
        RefreshTokenMaterial material,
        DateTimeOffset? refreshTokenExpiresAt,
        DateTimeOffset issuedAt,
        SessionTransport transport = SessionTransport.LegacyBearer,
        DateTimeOffset? sessionExpiresAt = default)
    {
        var lifetimeMinutes = transport == SessionTransport.Android ? 15 : _options.AccessTokenLifetimeMinutes;
        var accessToken = _accessTokenFactory.Create(user.Id, sessionId, user.RoleCode, issuedAt, lifetimeMinutes);
        return new AuthResult(
            AuthStatus.Success,
            new AuthTokens(
                accessToken,
                material.Plaintext,
                issuedAt.AddMinutes(lifetimeMinutes),
                refreshTokenExpiresAt,
                checked(lifetimeMinutes * 60),
                user,
                sessionId,
                sessionExpiresAt,
                issuedAt));
    }

    private static string HashSha256(string value) =>
        Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
}

public async Task<IActionResult> RequestPasswordRecovery(
        PasswordRecoveryRequestDto request,
        CancellationToken cancellationToken)
    {
        var result = await _authService.RequestPasswordRecoveryAsync(
            new PasswordRecoveryCommand(request.Email!, CorrelationId()),
            cancellationToken);
        return Accepted($"/api/v1/auth/password-recovery-requests/{result.RequestId:D}");
    }

    private IActionResult MapResult(AuthResult result, bool noContentOnSuccess = false)
    {
        if (result.Status == AuthStatus.Success && !noContentOnSuccess)
            Response.Headers.CacheControl = "no-store";
        return result.Status switch
        {
            AuthStatus.Success when noContentOnSuccess => NoContent(),
            AuthStatus.Success => Ok(new AuthTokenResponseDto(
                result.Tokens!.AccessToken,
                result.Tokens.RefreshToken,
                "Bearer",
                result.Tokens.ExpiresIn,
                result.Tokens.User.MustChangePassword,
                new AuthActorResponseDto(
                    result.Tokens.User.Id,
                    result.Tokens.User.DisplayName,
                    ToV2Role(result.Tokens.User.RoleCode),
                    Convert.ToBase64String(result.Tokens.User.RowVersion)))),
            AuthStatus.InvalidInput => AuthProblem(StatusCodes.Status400BadRequest, ApiErrorCodes.ValidationError, "Bad Request"),
            AuthStatus.InvalidCredentials => AuthProblem(StatusCodes.Status401Unauthorized, ApiErrorCodes.InvalidCredentials, "Unauthorized"),
            AuthStatus.PasswordChangeRequired => AuthProblem(StatusCodes.Status403Forbidden, ApiErrorCodes.PasswordChangeRequired, "Password change required"),
            AuthStatus.PasswordPolicyRejected => AuthProblem(StatusCodes.Status400BadRequest, ApiErrorCodes.ValidationError, "Password policy rejected"),
            AuthStatus.NotRequired => AuthProblem(StatusCodes.Status409Conflict, ApiErrorCodes.ConcurrencyConflict, "Password change is not required"),
            AuthStatus.SessionRevoked => AuthProblem(StatusCodes.Status401Unauthorized, ApiErrorCodes.SessionRevoked, "Session revoked"),
            AuthStatus.RefreshTokenInvalid => AuthProblem(StatusCodes.Status401Unauthorized, ApiErrorCodes.RefreshTokenInvalid, "Invalid refresh token"),
            AuthStatus.RefreshTokenExpired => AuthProblem(StatusCodes.Status401Unauthorized, ApiErrorCodes.RefreshTokenExpired, "Expired refresh token"),
            AuthStatus.IdempotentConflict => AuthProblem(StatusCodes.Status409Conflict, ApiErrorCodes.IdempotencyKeyReused, "Idempotency key reused"),
            AuthStatus.Conflict => AuthProblem(StatusCodes.Status409Conflict, ApiErrorCodes.ConcurrencyConflict, "Conflict"),
            _ => AuthProblem(StatusCodes.Status401Unauthorized, ApiErrorCodes.Unauthorized, "Unauthorized")
        };
    }

    private ObjectResult AuthProblem(int status, string code, string title)
    {
        var problem = new ProblemDetails
        {
            Status = status,
            Title = title,
            Detail = "The authentication request could not be completed.",
            Instance = Request.Path,
            Type = status switch
            {
                StatusCodes.Status400BadRequest => "https://tools.ietf.org/html/rfc9110#section-15.5.1",
                StatusCodes.Status401Unauthorized => "https://tools.ietf.org/html/rfc9110#section-15.5.2",
                StatusCodes.Status403Forbidden => "https://tools.ietf.org/html/rfc9110#section-15.5.4",
                StatusCodes.Status409Conflict => "https://tools.ietf.org/html/rfc9110#section-15.5.10",
                _ => "about:blank"
            }
        };
        problem.Extensions["code"] = code;
        problem.Extensions["correlationId"] = HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString()
            ?? Guid.NewGuid().ToString();
        return new ObjectResult(problem)
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };
    }

    private Guid? CorrelationId() =>
        Guid.TryParse(HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString(), out var value)
            ? value
            : null;

    private static string ToV2Role(UserRoleCode roleCode) => roleCode switch
    {
        UserRoleCode.Supervisor => "SUPERVISOR",
        UserRoleCode.ProjectManager => "PM",
        UserRoleCode.DroneOperator => "OPERATOR",
        UserRoleCode.RepairCrew => "CREW",
        UserRoleCode.Reporter => "REPORTER",
        _ => throw new ArgumentOutOfRangeException(nameof(roleCode), roleCode, "Role is not supported by the V2 actor contract.")
    };
}

using System.Security.Cryptography;
using System.Text;
using RoadGuardSystem.Repositories.Identity;
