public sealed partial class FieldInspectionWorkflowRepository
{
    public async Task<ReporterFileFacts> ValidateRepairEvidenceInTransactionAsync(Guid taskId,
        RepairFieldEvidenceData declaration, Guid originalActor, CancellationToken cancellationToken)
    {
        if (db.Database.CurrentTransaction is null) throw new InvalidOperationException("Caller-owned repair transaction required.");
        try
        {
            var task = await TaskAsync(taskId, cancellationToken);
            var file = await EvidenceFileAsync(task, declaration, cancellationToken, originalActor);
            if (file.State != "VERIFIED") Deny(409, "evidence_pending");
            return file;
        }
        catch (Denied denial) { throw new RepairFieldCoreRejectedException(denial.Result.Status, denial.Result.Code); }
    }

    public async Task<RepairMeasurementAssessment> CaptureRepairAssessmentInTransactionAsync(
        RepairFieldTaskBinding binding, FieldTaskStartOrigin firstStart, Guid actor, Guid effectId,
        RepairMeasurementAssessmentData input, string contentHash, CancellationToken cancellationToken,
        Guid? offlineAdmissionId = null)
    {
        if (db.Database.CurrentTransaction is null) throw new InvalidOperationException("Caller-owned repair transaction required.");
        try
        {
            var task = await TaskAsync(binding.TaskId, cancellationToken);
            if (task.RepairItemId != binding.ItemId || task.ProjectId != binding.ProjectId ||
                task.TaskMode is not ("NORMAL" or "CONDITIONAL_FT") || firstStart.TaskId != task.Id ||
                firstStart.AssignmentId != binding.AssignmentId || firstStart.OriginalActorId != actor ||
                task.Status is not (FieldInspectionTaskStatus.Accepted or FieldInspectionTaskStatus.InProgress))
                Deny(409, "repair_capture_source_conflict");
            if ((input.Evidence ?? []).Any(row => row is null || row.Purpose == "AFTER"))
                throw new ArgumentException("PRE_EXECUTION assessment cannot declare completed repair evidence.");
            if (input.StopConditions is { } stops && (stops.Count > 100 || stops.Keys.Any(code => string.IsNullOrWhiteSpace(code) || code.Length > 200)))
                throw new ArgumentException("Stop observations require bounded explicit policy codes.");
            var resolved = new Dictionary<Guid, OfflineEvidenceAdmissionFacts>();
            if (offlineAdmissionId is Guid admissionId)
            {
                var validator = new OfflineAdmissionValidator(db, clock);
                foreach (var declaration in input.Evidence ?? [])
                {
                    var actual = await validator.ResolveDeclaredEvidenceAsync(binding.ProjectId, task.Id,
                        admissionId, actor, declaration, cancellationToken);
                    if (actual is not null)
                    {
                        if (actual.AdmissionId != admissionId || actual.OriginalActorId != actor ||
                            !string.Equals(actual.Checksum, declaration.ChecksumSha256, StringComparison.OrdinalIgnoreCase) ||
                            actual.Purpose != declaration.Purpose || actual.MediaType != declaration.MediaType ||
                            declaration.FileId is Guid declared && declared != actual.FileId)
                            Deny(409, "evidence_version_mismatch");
                        resolved.Add(declaration.CaptureOriginId, actual);
                    }
                    else if (declaration.FileId is not null) Deny(403, "signed_evidence_admission_required");
                }
            }
            var now = clock.GetUtcNow();
            var session = FieldInspectionSession.Create(Guid.NewGuid(), FieldInspectionPurpose.PreMeasurement,
                task.Id, binding.ProjectId, task.RoadSectionVersionId, task.SurveyId, "REPAIR-PRE-" + Guid.NewGuid().ToString("N"),
                actor, "FIELD inspector", now, null, "PRE_EXECUTION assessment", FieldInspectionSessionStatus.Completed, null);
            var capture = new RepairFieldSubmissionData(input.OriginId, firstStart.Id, null, input.Measurements, input.Evidence,
                input.LocationProof, "MEASUREMENT", null, null, input.DeviceId);
            var measurements = ValidateMeasurements(task, capture, session.Id, actor, now);
            var missing = await ReadinessAsync(task, capture, firstStart, cancellationToken, actor, resolved);
            var evidence = new List<RepairAssessmentEvidenceReference>();
            foreach (var declaration in input.Evidence ?? [])
            {
                resolved.TryGetValue(declaration.CaptureOriginId, out var actual);
                var effectiveDeclaration = actual is null ? declaration : declaration with { FileId = actual.FileId };
                var facts = actual is null ? await CaptureEvidenceFactsAsync(task, declaration, cancellationToken)
                    : await CaptureResolvedEvidenceFactsAsync(task, LegacyRepairEvidence(declaration), actual, cancellationToken);
                string state = "UPLOAD_NOT_CREATED"; string? fileVersion = null; Guid? uploader = null;
                if (effectiveDeclaration.FileId is not null)
                {
                    var file = await EvidenceFileAsync(task, effectiveDeclaration, cancellationToken, actual?.ActualUploaderId ?? actor);
                    state = file.State; fileVersion = file.FileVersion; uploader = file.OwnerId;
                }
                var canonicalChecksum = declaration.ChecksumSha256.ToLowerInvariant();
                var reuse = effectiveDeclaration.FileId is Guid fileId && declaration.Purpose == "BEFORE"
                    ? await db.Set<FieldInspectionEvidenceReuseDecision>().Where(row => row.TaskId == task.Id && row.FileId == fileId &&
                        row.FileChecksum == canonicalChecksum).OrderByDescending(row => row.OccurredAt)
                        .Select(row => (Guid?)row.Id).FirstOrDefaultAsync(cancellationToken)
                    : null;
                evidence.Add(new(Guid.NewGuid(), declaration.CaptureOriginId, effectiveDeclaration.FileId, declaration.Purpose,
                    canonicalChecksum, declaration.MediaType, declaration.CapturedAt, state,
                    fileVersion, uploader, actor, reuse, facts));
            }
            db.Add(session); db.GroundTruthMeasurements.AddRange(measurements);
            return new RepairMeasurementAssessment(effectId, binding.ProjectId, binding.ItemId, binding.Id, task.Id,
                binding.AssignmentId, actor, firstStart.Id, session.Id, effectId, input.OriginId, contentHash,
                JsonSerializer.Serialize(input, Json), now, "PRE_EXECUTION", missing.Count == 0 ? "READY" : "INCOMPLETE",
                JsonSerializer.Serialize(missing, Json), JsonSerializer.Serialize(input.LocationProof, Json),
                missing.Any(reason => reason.StartsWith("LOCATION", StringComparison.Ordinal) || reason.StartsWith("GPS", StringComparison.Ordinal) ||
                    reason.StartsWith("POSITION", StringComparison.Ordinal)) ? "UNKNOWN" : "VERIFIED_CHECKLIST", null)
            {
                Measurements = measurements.Select(row => new RepairAssessmentMeasurementReference(row.Id)).ToArray(),
                Evidence = evidence
            };
        }
        catch (Denied denial) { throw new RepairFieldCoreRejectedException(denial.Result.Status, denial.Result.Code); }
    }
}

using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.BusinessObjects.Clocks;
using RoadGuardSystem.BusinessObjects.Inspections;
using RoadGuardSystem.BusinessObjects.Repairs;

namespace RoadGuardSystem.Repositories.Implementations.Inspections;

public sealed partial class FieldInspectionWorkflowRepository
{
    private async Task RecordRepairFirstStartAsync(FieldInspectionTask task, FieldTaskStartOrigin first, CancellationToken token)
    {
        var item = await db.Set<RepairItem>().FromSqlInterpolated($"SELECT * FROM [RepairItems] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={task.RepairItemId}")
            .SingleOrDefaultAsync(token);
        if (item is null || item.ProjectId != first.ProjectId || item.DefectId != task.DefectId || item.CurrentBindingId is null ||
            item.SupersededByItemId is not null) Deny(409, "repair_binding_not_current");
        var binding = await db.Set<RepairFieldTaskBinding>().SingleAsync(row => row.Id == item.CurrentBindingId, token);
        if (binding.TaskId != task.Id || binding.AssignmentId != first.AssignmentId || binding.CrewId != first.OriginalActorId ||
            binding.ItemId != item.Id || binding.Mode != item.Mode || binding.PlanHash != item.ProposalPlanHash)
            Deny(409, "repair_binding_not_current");
        var obligation = await db.Set<RepairObligation>().FromSqlInterpolated($"SELECT * FROM [RepairObligations] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={item.ObligationId}")
            .SingleAsync(token);
        if (obligation.CurrentRepairItemId != item.Id) Deny(409, "repair_binding_not_current");
        var changed = false;
        if (obligation.OriginalCrewFirstStartId is null)
        {
            db.Entry(obligation).Property(row => row.OriginalCrewFirstStartId).CurrentValue = first.Id;
            changed = true;
        }
        if (item.Mode == RepairMode.FastTrack)
        {
            if (obligation.OriginalCrewFirstStartId != first.Id || binding.AuthorizationId is null)
                Deny(409, "fast_track_original_start_locked");
            var authorization = await db.Set<RepairExecutionAuthorization>().SingleAsync(row => row.Id == binding.AuthorizationId, token);
            if (authorization.ProjectId != binding.ProjectId || authorization.DefectId != binding.DefectId ||
                authorization.TaskId != task.Id || authorization.AssignmentId != first.AssignmentId ||
                authorization.CrewId != first.OriginalActorId || authorization.PolicyRevisionId != binding.PolicyRevisionId ||
                authorization.LocationVersion != binding.LocationVersion || authorization.Permission != RepairTaskMode.ConditionalFastTrack)
                Deny(409, "repair_authorization_scope_conflict");
            changed |= authorization.FirstStartOriginId is null;
            authorization.RecordFirstStart(first.Id, first.ContentHash, first.ClaimedAt, first.ServerReceivedAt, RepairTimeProvenance.Uncertain);
            if (first.VerifiedOriginalAt is DateTimeOffset verified)
            {
                var provenance = first.TimeProvenance == "SERVER_ONLINE" ? RepairTimeProvenance.VerifiedOnline : RepairTimeProvenance.VerifiedOffline;
                authorization.VerifyOriginalStart(first.Id, first.ContentHash, first.ClaimedAt, verified, provenance);
                var existing = await db.Set<DeadlineClock>().SingleOrDefaultAsync(row => row.TargetId == item.Id &&
                    row.Kind == DeadlineClockKind.FastTrackExecution, token);
                if (existing is null)
                    db.Add(DeadlineClock.Create(Guid.NewGuid(), item.ProjectId, DeadlineClockKind.FastTrackExecution, item.Id, first.Id, verified));
                else if (existing.OriginEventId != first.Id || existing.OriginAt != verified) Deny(409, "fast_track_clock_origin_locked");
            }
        }
        if (changed)
        {
            var packageId = db.Entry(item).Property<Guid?>("PackageId").CurrentValue;
            if (packageId is null) Deny(409, "repair_package_source_missing");
            var package = await db.Set<RepairPackage>().FromSqlInterpolated($"SELECT * FROM [RepairPackages] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={packageId}")
                .SingleAsync(token);
            db.Entry(package).Property<long>("MutationRevision").CurrentValue++;
        }
    }
}

using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.BusinessObjects.Defects;
using RoadGuardSystem.Repositories.Repairs;
using RoadGuardSystem.Repositories.Inspections;

namespace RoadGuardSystem.Repositories.Implementations.Inspections;

public sealed partial class FieldInspectionWorkflowRepository
{
    // Uses the unchanged H3 source/location/assignee validators in the caller's atomic repair transaction.
    // It creates neither a generic FIELD task nor an execution grant.
    public async Task<RepairFieldSourceResult> ValidateRepairTaskSourcesInTransactionAsync(Guid projectId,
        RepairFieldTaskData input, Defect defect, CancellationToken cancellationToken)
    {
        if (db.Database.CurrentTransaction is null) throw new InvalidOperationException("Caller-owned repair transaction required.");
        try
        {
            await ValidateSourceAsync(projectId, input, defect.SourceAIDetectionId, cancellationToken);
            await ValidatePinsAsync(projectId, input, cancellationToken);
            await GuardCrewAsync(projectId, input.AssignedToUserId, cancellationToken);
            return new(200);
        }
        catch (Denied denial) { return new(denial.Result.Status, denial.Result.Code); }
    }

    public async Task<RepairFieldSourceResult> ValidateRepairLocationPinsInTransactionAsync(Guid projectId,
        RepairFieldTaskData input, CancellationToken cancellationToken)
    {
        if (db.Database.CurrentTransaction is null) throw new InvalidOperationException("Caller-owned repair transaction required.");
        try { await ValidatePinsAsync(projectId, input, cancellationToken); return new(200); }
        catch (Denied denial) { return new(denial.Result.Status, denial.Result.Code); }
    }
}

using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Inspections;
using RoadGuardSystem.BusinessObjects.PersistenceFacts.Inspections;
using RoadGuardSystem.Repositories.Inspections;
namespace RoadGuardSystem.Repositories.Implementations.Inspections;

public sealed partial class FieldInspectionWorkflowRepository
{
    private async Task<FieldWorkflowResultFact> VerificationSourceAsync(FieldWorkflowCommand c, FieldInspectionTask task, CancellationToken token)
    {
        var query = c.Input as FieldVerificationSourceQueryFact ?? throw new ArgumentException("FIELD source binding required.");
        if (task.DefectId != query.DefectId) Deny(404, "not_found");
        var row = await db.Set<FieldInspectionSubmission>().FromSqlInterpolated($"SELECT * FROM [FieldInspectionSubmissions] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={query.SubmissionId}").AsNoTracking().SingleOrDefaultAsync(token);
        if (row is null || row.TaskId != task.Id || row.ProjectId != c.ProjectId) Deny(404, "not_found");
        if (!string.Equals(row.ContentHash, query.ExpectedContentHash, StringComparison.Ordinal)) Deny(409, "field_source_version_mismatch");
        if (task.Status != FieldInspectionTaskStatus.Completed || task.LifecycleVersion != 2 || task.TaskMode != "MEASURE_ONLY" ||
            await db.Set<FieldInspectionSubmission>().AnyAsync(x => x.TaskId == task.Id && x.Revision > row.Revision, token)) Deny(409, "field_result_insufficient");
        var review = await db.Set<FieldInspectionReview>().FromSqlInterpolated($"SELECT * FROM [FieldInspectionReviews] WITH (UPDLOCK,HOLDLOCK) WHERE [SubmissionId]={row.Id}").AsNoTracking().Where(x => x.Decision != "SUPPLEMENT").SingleOrDefaultAsync(token);
        if (review is null) Deny(409, "field_result_insufficient");
        var payload = Decode<FieldSubmissionInputFact>(row.PayloadJson);
        var start = await db.Set<FieldTaskStartOrigin>().AsNoTracking().SingleAsync(x => x.Id == row.StartOriginId, token);
        if (payload.CaptureType != "MEASUREMENT" || (await ReadinessAsync(task, payload, start, token, row.OriginalActorId)).Count != 0) Deny(409, "field_result_insufficient");
        var evidence = await db.Set<FieldInspectionEvidenceLink>().AsNoTracking().Where(x => x.SubmissionId == row.Id && x.FileId != null).Select(x => x.Id).OrderBy(x => x).ToArrayAsync(token);
        if (evidence.Length == 0) Deny(409, "field_result_insufficient");
        return new(200, Value: new FieldVerificationSourceFactsFact(task.Id, task.DefectId, row.Id, row.ContentHash, review.Decision, evidence,
            task.RoadSectionVersionId, task.SegmentSetId, task.LayoutRevisionId), Version: row.ContentHash);
    }
}

