public sealed partial class FieldInspectionWorkflowRepository(RoadGuardDbContext db, IdempotencyOperationService receipts,
    TimeProvider clock, IOfflineFieldAdmissionValidator? offlineAdmission = null,
    IOfflineEvidenceAdmissionValidator? evidenceAdmission = null) : IFieldInspectionWorkflowRepository
{
    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);
    private sealed class Denied(int status, string code) : Exception { public FieldWorkflowResultFact Result { get; } = new(status, code); }
    private sealed class ExistingReceipt : Exception { }
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Deny(int status, string code) => throw new Denied(status, code);
    private static string Hash(object value) => Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(value, Json))).ToLowerInvariant();
    private static T Decode<T>(string json) => JsonSerializer.Deserialize<T>(json, Json) ?? throw new ArgumentException("Missing structured facts.");
    private static bool IsRead(string action) => action is "list" or "get" or "start-origin" or "submission" or "history" or "geometry" or "evidence" or "verification-source";

    public async Task<FieldWorkflowResultFact> ExecuteAsync(FieldWorkflowCommand command,
        Func<CancellationToken, Task<bool>> projectGuard, CancellationToken cancellationToken)
    {
        try
        {
            if (IsRead(command.Action))
            {
                if (db.Database.CurrentTransaction is not null) return await ApplyInTransactionAsync(command, projectGuard, cancellationToken);
                return await db.Database.CreateExecutionStrategy().ExecuteAsync(async () =>
                {
                    await using var tx = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable, cancellationToken);
                    var result = await ApplyInTransactionAsync(command, projectGuard, cancellationToken);
                    await tx.CommitAsync(cancellationToken); return result;
                });
            }
            var fingerprint = Hash(new { command.ProjectId, command.TaskId, command.Action, command.Input, command.ExpectedVersion, command.Admission.OriginalActorId });
            async Task Guard(CancellationToken token) => await GuardAsync(command, projectGuard, token);
            var outcome = await receipts.ExecuteSerializableAsync(command.Admission.CallerId, command.ProjectId, "h3.field." + command.Action + ".v1",
                command.Key!, fingerprint, async token =>
                {
                    await Guard(token);
                    if (await db.IdempotencyRecords.AsNoTracking().AnyAsync(x => x.ProjectId == command.ProjectId && x.ActorUserId == command.Admission.CallerId &&
                        x.Operation == "h3.field." + command.Action + ".v1" && x.IdempotencyKey == command.Key, token)) throw new ExistingReceipt();
                    var result = await ApplyBusinessAsync(command, token);
                    await db.SaveChangesAsync(token);
                    var value = await FinalizeResultAsync(command, result, token);
                    return (Guid.NewGuid(), JsonSerializer.Serialize(value.Value, Json));
                }, cancellationToken, receiptAccessGuard: Guard);
            if (outcome.Status == IdempotencyOperationStatus.Conflict) return new(409, "idempotency_key_reused");
            return new(outcome.Status == IdempotencyOperationStatus.Replayed ? 200 : 201, Value: Decode<JsonElement>(outcome.OutcomeJson),
                Replayed: outcome.Status == IdempotencyOperationStatus.Replayed);
        }
        catch (ExistingReceipt) { db.ChangeTracker.Clear(); return await ExecuteAsync(command, projectGuard, cancellationToken); }
        catch (Denied error) { return error.Result; }
        catch (FieldCoreRejectedException error) { return new(error.Result.Status, error.Result.Code, error.Result.Value, error.Result.Version, error.Result.Replayed); }
        catch (OfflineAdmissionRejectedException error) { return new(error.Status, error.Code); }
        catch (ArgumentException) { return new(400, "validation_error"); }
        catch (JsonException) { return new(400, "validation_error"); }
        catch (InvalidOperationException error) when (error.Message.StartsWith("Invalid FIELD", StringComparison.Ordinal)) { return new(409, "invalid_state_transition"); }
    }

    public async Task<FieldWorkflowResultFact> ApplyInTransactionAsync(FieldWorkflowCommand command,
        Func<CancellationToken, Task<bool>> projectGuard, CancellationToken cancellationToken)
    {
        if (db.Database.CurrentTransaction is null) throw new InvalidOperationException("Caller-owned FIELD transaction required.");
        try
        {
            await GuardAsync(command, projectGuard, cancellationToken);
            if (IsRead(command.Action)) return await ReadAsync(command, cancellationToken);
            var result = await ApplyBusinessAsync(command, cancellationToken);
            await db.SaveChangesAsync(cancellationToken);
            await GuardAsync(command, projectGuard, cancellationToken);
            return await FinalizeResultAsync(command, result, cancellationToken);
        }
        catch (Denied error) { throw new FieldCoreRejectedException(CoreOutcome(error.Result)); }
        catch (ArgumentException) { throw new FieldCoreRejectedException(new(400, "validation_error")); }
        catch (JsonException) { throw new FieldCoreRejectedException(new(400, "validation_error")); }
        catch (InvalidOperationException error) when (error.Message.StartsWith("Invalid FIELD", StringComparison.Ordinal))
        { throw new FieldCoreRejectedException(new(409, "invalid_state_transition")); }
    }

    public async Task<FieldCoreOutcome> ApplyInternalInTransactionAsync(FieldWorkflowCommand command,
        Func<CancellationToken, Task<bool>> projectGuard, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(command);
        object input = command.Input switch
        {
            FieldStartData value => new FieldStartInputFact(value.OriginId, value.ClaimedAt, value.DeviceId,
                value.MonotonicMilliseconds, value.BootId, value.OfflineProof),
            FieldActionData value => new FieldTaskActionInputFact(value.Reason, value.AssignedToUserId,
                value.Handover is null ? null : new(value.Handover.PerformedPortionState, value.Handover.Summary,
                    value.Handover.StartOriginId, value.Handover.SubmissionIds, value.Handover.RecipientUserId)),
            RepairFieldSubmissionData value => LegacyRepairSubmission(value),
            _ => throw new FieldCoreRejectedException(new(400, "validation_error"))
        };
        // Keep the original canonical representation independently of the compatibility conversion.
        var canonicalInput = JsonSerializer.SerializeToUtf8Bytes(command.Input, Json);
        if (!canonicalInput.AsSpan().SequenceEqual(JsonSerializer.SerializeToUtf8Bytes(input, Json)))
            throw new InvalidOperationException("Internal FIELD input changed its canonical representation.");
        return CoreOutcome(await ApplyInTransactionAsync(command with { Input = input }, projectGuard, cancellationToken));
    }

    private static FieldCoreOutcome CoreOutcome(FieldWorkflowResultFact result)
        => new(result.Status, result.Code, result.Value is null ? null : JsonSerializer.SerializeToElement(result.Value, Json),
            result.Version, result.Replayed);

    private static (Guid OriginId, Guid? DeviceId)? OriginMetadata(object? input) => input switch
    {
        FieldStartInputFact value => (value.OriginId, value.DeviceId),
        FieldSubmissionInputFact value => (value.OriginId, value.DeviceId),
        FieldStartData value => (value.OriginId, value.DeviceId),
        RepairFieldSubmissionData value => (value.OriginId, value.DeviceId),
        _ => null
    };

    private async Task GuardAsync(FieldWorkflowCommand c, Func<CancellationToken, Task<bool>> projectGuard, CancellationToken token)
    {
        var a = c.Admission;
        await Anh02ReceiptAuthority.LockAsync(db, a.CallerId, c.ProjectId, token);
        if (c.Action == "verification-source" && a.CallerRole != UserRoleCode.ProjectManager) Deny(403, "access_forbidden");
        var read = IsRead(c.Action); var pm = c.Action is "create" or "assign" or "cancel" or "reassign" or "review" or "reuse" or "impact";
        var imported = a.Mode is "SYNC" or "HANDOVER";
        if (read ? a.CallerRole is not (UserRoleCode.ProjectManager or UserRoleCode.Supervisor or UserRoleCode.RepairCrew) :
            imported ? a.CallerRole is not (UserRoleCode.ProjectManager or UserRoleCode.RepairCrew) :
            pm ? a.CallerRole != UserRoleCode.ProjectManager : a.CallerRole != UserRoleCode.RepairCrew) Deny(403, "access_forbidden");
        if (!await new AnhHuyFactsRepository(db).IsCurrentActorAsync(a.CallerId, a.CallerRole, token) || !await projectGuard(token)) Deny(403, "access_forbidden");
        if (a.Mode == "DIRECT" && a.OriginalActorId != a.CallerId || a.Mode is not ("DIRECT" or "SYNC" or "HANDOVER")) Deny(403, "access_forbidden");
        var admitted = await ImportedFactsAsync(c, token);
        if (c.Input is FieldTaskCreateInputFact create)
        {
            var defect = await db.Defects.FromSqlInterpolated($"SELECT * FROM [Defects] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={create.DefectId}").AsNoTracking().SingleOrDefaultAsync(token);
            if (defect is null || defect.ProjectId != c.ProjectId) Deny(404, "not_found");
        }
        if (c.TaskId is Guid taskId)
        {
            var task = await db.FieldInspectionTasks.FromSqlInterpolated($"SELECT * FROM [FieldInspectionTasks] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={taskId}").SingleOrDefaultAsync(token);
            if (task is null || task.ProjectId != c.ProjectId) Deny(404, "not_found");
            await db.FieldInspectionAssignments.FromSqlInterpolated($"SELECT * FROM [FieldInspectionAssignments] WITH (UPDLOCK,HOLDLOCK) WHERE [FieldInspectionTaskId]={taskId}").AsNoTracking().ToListAsync(token);
            if (admitted is not null)
            {
                if (!await db.FieldInspectionAssignments.AnyAsync(x => x.Id == admitted.AssignmentId && x.FieldInspectionTaskId == taskId &&
                    x.AssignedToUserId == admitted.OriginalActorId && x.Status == FieldInspectionAssignmentStatus.Active && x.EndedAt == null, token)) Deny(409, "stale_snapshot");
            }
            else if (a.CallerRole == UserRoleCode.RepairCrew && !await db.FieldInspectionAssignments.AnyAsync(x => x.FieldInspectionTaskId == taskId && x.AssignedToUserId == a.CallerId && x.Status == FieldInspectionAssignmentStatus.Active && x.EndedAt == null, token)) Deny(403, "access_forbidden");
            if (c.Input is FieldLocationImpactActionInputFact impact) await ImpactAsync(c, task, impact, token);
            if (c.Input is FieldReviewInputFact review && !await db.Set<FieldInspectionSubmission>().AnyAsync(x => x.Id == review.SubmissionId && x.TaskId == taskId, token)) Deny(404, "not_found");
            if (c.Action == "review" && await db.Set<DeadlineClock>().AnyAsync(x => x.ProjectId == c.ProjectId &&
                x.TargetId == taskId && x.Kind == DeadlineClockKind.ProjectManagerReview && x.AppointedActorId != null &&
                x.AppointedActorId != a.CallerId, token)) Deny(403, "current_review_assignee_required");
            if (c.Input is FieldEvidenceReuseInputFact) await ReuseAsync(c, task, token, true);
            if (c.Input is FieldSubmissionInputFact submission)
            {
                if (!await db.Set<FieldTaskStartOrigin>().AnyAsync(x => x.Id == submission.StartOriginId && x.TaskId == taskId, token)) Deny(404, "not_found");
                if (submission.ParentSubmissionId is Guid parent && !await db.Set<FieldInspectionSubmission>().AnyAsync(x => x.Id == parent && x.TaskId == taskId, token)) Deny(404, "not_found");
                if (admitted is null) foreach (var evidence in submission.Evidence ?? []) if (evidence?.FileId is not null) await EvidenceFileAsync(task, evidence, token, a.OriginalActorId);
            }
        }
    }

    private async Task<FieldWorkflowResultFact> ReadAsync(FieldWorkflowCommand c, CancellationToken token)
    {
        if (c.Action == "list")
        {
            var query = c.Input as FieldTaskListQuery ?? new(null, 50);
            if (query.Limit is < 1 or > 100) Deny(400, "validation_error");
            var rows = db.FieldInspectionTasks.AsNoTracking().Where(x => x.ProjectId == c.ProjectId);
            if (c.Admission.CallerRole == UserRoleCode.RepairCrew) rows = rows.Where(x => db.FieldInspectionAssignments.Any(a => a.FieldInspectionTaskId == x.Id && a.AssignedToUserId == c.Admission.CallerId && a.Status == FieldInspectionAssignmentStatus.Active && a.EndedAt == null));
            if (query.AfterId is Guid after) rows = rows.Where(x => x.Id.CompareTo(after) > 0);
            var tasks = await rows.OrderBy(x => x.Id).Take(query.Limit + 1).ToArrayAsync(token);
            var views = new List<FieldTaskViewFact>(); foreach (var row in tasks.Take(query.Limit)) views.Add(await ViewAsync(row, token));
            return new(200, Value: new { items = views, nextCursor = tasks.Length > query.Limit ? views[^1].Id : (Guid?)null });
        }
        var task = await TaskAsync(c.TaskId!.Value, token);
        if (c.Action == "start-origin")
        {
            var origin = await db.Set<FieldTaskStartOrigin>().AsNoTracking().SingleOrDefaultAsync(x => x.TaskId == task.Id, token);
            if (origin is null) Deny(404, "not_found"); return await FinalizeResultAsync(c, new(200, Value: origin), token);
        }
        if (c.Action == "get") return new(200, Value: await ViewAsync(task, token), Version: Convert.ToBase64String(task.RowVersion));
        if (c.Action == "history") return new(200, Value: new
        {
            assignments = await db.FieldInspectionAssignments.AsNoTracking().Where(x => x.FieldInspectionTaskId == task.Id).OrderBy(x => x.AssignedAt).Select(x => new { x.Id, x.AssignedToUserId, x.AssignedByUserId, x.AssignedAt, x.EndedAt, x.Status, x.Reason }).ToArrayAsync(token),
            events = await db.Set<FieldInspectionTaskEvent>().AsNoTracking().Where(x => x.TaskId == task.Id).OrderBy(x => x.OccurredAt).ThenBy(x => x.Id).Select(x => new { x.Id, x.AssignmentId, x.ActorId, x.Kind, x.Reason, x.OccurredAt, x.FactsJson, x.LocationImpactId, x.LocationImpactDecisionId }).ToArrayAsync(token)
        });
        if (c.Action == "submission")
        {
            var id = c.Input is Guid input ? input : Guid.Empty;
            var row = await db.Set<FieldInspectionSubmission>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == id && x.TaskId == task.Id, token);
            if (row is null) Deny(404, "not_found"); return new(200, Value: await SubmissionViewAsync(row, token), Version: row.ContentHash);
        }
        if (c.Action == "verification-source") return await VerificationSourceAsync(c, task, token);
        if (c.Action == "geometry") return await GeometryAsync(task, token);
        if (c.Action == "evidence") return await EvidenceAsync(c, task, token);
        Deny(404, "not_found"); return null!;
    }

    private Task<FieldInspectionTask> TaskAsync(Guid id, CancellationToken token) => db.FieldInspectionTasks.SingleAsync(x => x.Id == id, token);
    private async Task<FieldInspectionAssignment?> CurrentAssignmentAsync(Guid task, CancellationToken token) => await db.FieldInspectionAssignments.SingleOrDefaultAsync(x => x.FieldInspectionTaskId == task && x.Status == FieldInspectionAssignmentStatus.Active && x.EndedAt == null, token);
    private async Task<FieldTaskViewFact> ViewAsync(FieldInspectionTask task, CancellationToken token)
    {
        var assignment = await CurrentAssignmentAsync(task.Id, token);
        var start = await db.Set<FieldTaskStartOrigin>().AsNoTracking().Where(x => x.TaskId == task.Id).Select(x => (Guid?)x.Id).SingleOrDefaultAsync(token);
        var latest = await db.Set<FieldInspectionSubmission>().AsNoTracking().Where(x => x.TaskId == task.Id).OrderByDescending(x => x.Revision).Select(x => (Guid?)x.Id).FirstOrDefaultAsync(token);
        return new(task.Id, task.ProjectId, task.DefectId, task.SurveyId, task.SourceKind, task.RoadSectionVersionId, task.SegmentSetId, task.LayoutRevisionId,
            task.SlabId, task.Purpose.ToString(), task.TaskMode, task.Status.ToString(), assignment?.Id, assignment?.AssignedToUserId,
            Convert.ToBase64String(task.RowVersion), start, latest, task.MapPublicationId, task.CrsProfileRevisionId, task.RequiredMeasurementType, task.MeasurementScope, task.Instructions, task.DueAt);
    }
    private async Task<FieldSubmissionViewFact> SubmissionViewAsync(FieldInspectionSubmission row, CancellationToken token)
    {
        var payload = Decode<FieldSubmissionInputFact>(row.PayloadJson);
        var root = await db.Set<FieldInspectionSubmission>().AsNoTracking().SingleAsync(x => x.Id == row.RootId, token);
        return new(row.Id, row.TaskId, row.RootId, row.ParentId, row.Revision, row.ServerReceivedAt, root.ServerReceivedAt.AddHours(24), row.Readiness,
            Decode<string[]>(row.MissingReasonsJson), row.ContentHash, payload.Measurements ?? [], payload.Evidence ?? [], payload.CaptureType, payload.Repaired, payload.UnrepairedReason);
    }
}

using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.BusinessObjects.Inspections;
using RoadGuardSystem.BusinessObjects.Reports;
using RoadGuardSystem.BusinessObjects.Projects;
using RoadGuardSystem.BusinessObjects.PersistenceFacts.Inspections;
using RoadGuardSystem.BusinessObjects.PersistenceFacts.Projects;
using RoadGuardSystem.Repositories.Inspections;
using RoadGuardSystem.Repositories.Integration;
using RoadGuardSystem.Repositories.Models.Huy01;
namespace RoadGuardSystem.Repositories.Implementations.Inspections;

public sealed partial class FieldInspectionWorkflowRepository
{
    private async Task<FieldWorkflowResultFact> ReuseAsync(FieldWorkflowCommand c, FieldInspectionTask task, CancellationToken token, bool validateOnly = false)
    {
        var input = c.Input as FieldEvidenceReuseInputFact ?? throw new ArgumentException("Reuse decision input required.");
        if (!validateOnly && task.Status is RoadGuardSystem.aBusinessObjects.Commons.FieldInspectionTaskStatus.Completed or RoadGuardSystem.aBusinessObjects.Commons.FieldInspectionTaskStatus.Cancelled) Deny(409, "invalid_state_transition");
        await db.Files.FromSqlInterpolated($"SELECT * FROM [Files] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.FileId}").AsNoTracking().ToListAsync(token);
        await db.UploadSessions.FromSqlInterpolated($"SELECT * FROM [UploadSessions] WITH (UPDLOCK,HOLDLOCK) WHERE [FileId]={input.FileId}").AsNoTracking().ToListAsync(token);
        await db.Set<HuyDefectSourceLink>().FromSqlInterpolated($"SELECT * FROM [DefectSourceLinks] WITH (UPDLOCK,HOLDLOCK) WHERE [DefectId]={task.DefectId}").AsNoTracking().ToListAsync(token);
        var file = await new AnhHuyFactsRepository(db).GetFileAsync(input.FileId, token);
        if (file is null) Deny(404, "not_found");
        if (file.State != "VERIFIED" || file.Checksum != input.ExpectedChecksum) Deny(409, "evidence_version_mismatch");
        object source;
        if (input.SourceKind == "REPORTER")
        {
            await db.Database.SqlQuery<Guid>($"SELECT [Id] AS [Value] FROM [ReportOriginalEvidence] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.SourceEvidenceId}").ToArrayAsync(token);
            await db.Database.SqlQuery<Guid>($"SELECT [Id] AS [Value] FROM [ReportSupplementEvidence] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.SourceEvidenceId}").ToArrayAsync(token);
            var reports = await db.Set<HuyDefectSourceLink>().AsNoTracking().Where(x => x.DefectId == task.DefectId && x.ProjectId == c.ProjectId && x.EndedAt == null && x.ReportSourceId != null).Select(x => x.ReportSourceId!.Value).ToArrayAsync(token);
            var original = await db.Reports.AsNoTracking().Where(x => reports.Contains(x.Id)).SelectMany(x => x.OriginalEvidence).Where(x => x.Id == input.SourceEvidenceId && x.FileId == input.FileId).SingleOrDefaultAsync(token);
            var supplement = original is null ? await db.ReportSupplements.AsNoTracking().Where(x => reports.Contains(x.ReportId)).SelectMany(x => x.Evidence).Where(x => x.Id == input.SourceEvidenceId && x.FileId == input.FileId).SingleOrDefaultAsync(token) : null;
            var evidence = original ?? supplement;
            if (evidence is null || file.ProjectId is not null || file.Purpose != "REPORT_PHOTO" || file.OwnerId != evidence.OwnerUserId || file.FileVersion != evidence.FileVersion) Deny(403, "evidence_access_forbidden");
            source = new { reportId = evidence.ReportId, evidence.Id, evidence.FileVersion, evidence.OwnerUserId, evidence.CaptureMetadata };
        }
        else if (input.SourceKind == "DRONE")
        {
            await db.SurveyFiles.FromSqlInterpolated($"SELECT * FROM [SurveyFiles] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.SourceEvidenceId}").AsNoTracking().ToListAsync(token);
            var surveyFile = await db.SurveyFiles.AsNoTracking().SingleOrDefaultAsync(x => x.Id == input.SourceEvidenceId && x.FileId == input.FileId && x.SurveyId == task.SurveyId, token);
            if (surveyFile is null || task.SurveyId is null || file.ProjectId != task.ProjectId || file.Purpose is not ("SURVEY_VIDEO" or "TELEMETRY") || surveyFile.Checksum != file.Checksum) Deny(403, "evidence_access_forbidden");
            source = new { surveyFile.Id, surveyFile.SurveyId, surveyFile.CaptureStartedAt, surveyFile.CaptureEndedAt, surveyFile.SyncStatus };
        }
        else throw new ArgumentException("Reporter or Drone source required.");
        if (validateOnly) return new(200);
        var now = clock.GetUtcNow(); var row = FieldInspectionEvidenceReuseDecision.Create(Guid.NewGuid(), c.ProjectId, task.Id, input.FileId, input.SourceEvidenceId, c.Admission.CallerId, input.SourceKind,
            file.Checksum, JsonSerializer.Serialize(new { source, file.FileVersion, file.UploadedAt, file.Purpose, file.Checksum }, Json), input.Reason, now);
        db.Set<FieldInspectionEvidenceReuseDecision>().Add(row); Emit(c, task, await CurrentAssignmentAsync(task.Id, token), "REVIEWED", "Authorized BEFORE evidence reuse", now, row.Id);
        return new(201, Value: new { row.Id, row.TaskId, row.FileId, row.SourceKind, row.FileChecksum, row.Reason, row.OccurredAt });
    }
    private async Task<FieldWorkflowResultFact> EvidenceAsync(FieldWorkflowCommand c, FieldInspectionTask task, CancellationToken token)
    {
        var fileId = c.Input is Guid requested ? requested : Guid.Empty;
        if (fileId == Guid.Empty) Deny(400, "validation_error");
        var link = await db.Set<FieldInspectionEvidenceLink>().AsNoTracking().Where(x => x.TaskId == task.Id && x.FileId == fileId).OrderByDescending(x => x.Id).FirstOrDefaultAsync(token);
        var reuse = await db.Set<FieldInspectionEvidenceReuseDecision>().AsNoTracking().Where(x => x.TaskId == task.Id && x.FileId == fileId).OrderByDescending(x => x.OccurredAt).FirstOrDefaultAsync(token);
        if (link is null && reuse is null) Deny(404, "not_found");
        await db.Files.FromSqlInterpolated($"SELECT * FROM [Files] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={fileId}").AsNoTracking().ToListAsync(token);
        await db.UploadSessions.FromSqlInterpolated($"SELECT * FROM [UploadSessions] WITH (UPDLOCK,HOLDLOCK) WHERE [FileId]={fileId}").AsNoTracking().ToListAsync(token);
        var file = await db.Files.AsNoTracking().SingleOrDefaultAsync(x => x.Id == fileId, token);
        var facts = await new AnhHuyFactsRepository(db).GetFileAsync(fileId, token);
        var scope = await db.FileScopes.AsNoTracking().SingleOrDefaultAsync(x => x.FileId == fileId, token);
        if (file is null || facts is null || scope is null) Deny(404, "not_found");
        if (reuse is null && (scope.ProjectId != task.ProjectId || scope.TargetId != task.Id || scope.Purpose is not ("BEFORE" or "AFTER" or "MEASUREMENT"))) Deny(403, "evidence_access_forbidden");
        if (link is not null && link.DeclaredChecksum != file.Checksum || reuse is not null && reuse.FileChecksum != file.Checksum) Deny(409, "evidence_version_mismatch");
        if (reuse is not null) await ValidateHistoricalReuseAsync(task, reuse, facts, token);
        return new(200, Value: new FieldTaskEvidenceFile(file.Id, facts.State, file.Checksum, file.MimeType, file.SizeBytes, file.StorageUri), Version: file.Checksum);
    }
    private async Task ValidateHistoricalReuseAsync(FieldInspectionTask task, FieldInspectionEvidenceReuseDecision reuse, ReporterFileFacts file, CancellationToken token)
    {
        await db.UploadSessions.FromSqlInterpolated($"SELECT * FROM [UploadSessions] WITH (UPDLOCK,HOLDLOCK) WHERE [FileId]={file.FileId}").AsNoTracking().ToListAsync(token);
        var current = await new AnhHuyFactsRepository(db).GetFileAsync(file.FileId, token);
        if (current is null || current.State != "VERIFIED" || current.Checksum != reuse.FileChecksum) Deny(409, "evidence_version_mismatch");
        using var provenance = JsonDocument.Parse(reuse.ProvenanceJson);
        if (provenance.RootElement.GetProperty("fileVersion").GetString() != current.FileVersion) Deny(409, "evidence_version_mismatch");
        if (reuse.SourceKind == "REPORTER")
        {
            await db.Database.SqlQuery<Guid>($"SELECT [Id] AS [Value] FROM [ReportOriginalEvidence] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={reuse.SourceEvidenceId}").ToArrayAsync(token);
            await db.Database.SqlQuery<Guid>($"SELECT [Id] AS [Value] FROM [ReportSupplementEvidence] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={reuse.SourceEvidenceId}").ToArrayAsync(token);
            var original = await db.Reports.AsNoTracking().SelectMany(x => x.OriginalEvidence).SingleOrDefaultAsync(x => x.Id == reuse.SourceEvidenceId && x.FileId == reuse.FileId, token);
            var supplement = original is null ? await db.ReportSupplements.AsNoTracking().SelectMany(x => x.Evidence).SingleOrDefaultAsync(x => x.Id == reuse.SourceEvidenceId && x.FileId == reuse.FileId, token) : null;
            var evidence = original ?? supplement;
            if (evidence is null || current.OwnerId != evidence.OwnerUserId || current.ProjectId is not null || current.Purpose != "REPORT_PHOTO" || current.FileVersion != evidence.FileVersion ||
                !await db.Set<HuyDefectSourceLink>().AnyAsync(x => x.ProjectId == task.ProjectId && x.DefectId == task.DefectId && x.ReportSourceId == evidence.ReportId &&
                    x.CreatedAt <= reuse.OccurredAt && (x.EndedAt == null || x.EndedAt > reuse.OccurredAt), token)) Deny(403, "evidence_access_forbidden");
        }
        else
        {
            var source = await db.SurveyFiles.AsNoTracking().SingleOrDefaultAsync(x => x.Id == reuse.SourceEvidenceId && x.FileId == reuse.FileId && x.SurveyId == task.SurveyId, token);
            if (source is null || current.ProjectId != task.ProjectId || source.Checksum != current.Checksum) Deny(403, "evidence_access_forbidden");
        }
    }
    private async Task<FieldWorkflowResultFact> GeometryAsync(FieldInspectionTask task, CancellationToken token)
    {
        var setId = task.SegmentSetId.GetValueOrDefault();
        if (setId == Guid.Empty) Deny(409, "source_not_ready");
        var set = await db.RoadSegmentSets.AsNoTracking().SingleOrDefaultAsync(x => x.Id == setId && x.RoadSectionVersionId == task.RoadSectionVersionId, token);
        var route = await db.RoadSectionVersions.AsNoTracking().SingleAsync(x => x.Id == task.RoadSectionVersionId, token);
        if (set is null || set.Status is not ("PUBLISHED" or "SUPERSEDED")) Deny(409, "source_not_ready");
        var segments = await db.RoadSegments.AsNoTracking().Where(x => x.SegmentSetId == setId).OrderBy(x => x.Sequence).Select(x => new { x.Id, x.Sequence, x.FromOffsetMeters, x.ToOffsetMeters, x.StartStationMeters, x.EndStationMeters, x.Geometry }).ToArrayAsync(token);
        object? layout = null;
        if (task.LayoutRevisionId is Guid layoutId)
        {
            var row = await db.Set<PavementLayoutRevision>().AsNoTracking().SingleAsync(x => x.Id == layoutId && x.ProjectId == task.ProjectId, token);
            var preview = Decode<PavementGeometryPreviewFact>(row.SnapshotJson);
            layout = new { row.Id, row.ContentHash, row.Kind, slabs = task.SlabId is null ? preview.Slabs : preview.Slabs.Where(x => x.Key == task.SlabId).ToArray() };
        }
        return new(200, Value: new
        {
            schemaVersion = 1,
            taskId = task.Id,
            projectId = task.ProjectId,
            routeVersionId = task.RoadSectionVersionId,
            segmentSetId = setId,
            task.LayoutRevisionId,
            task.SlabId,
            task.MapPublicationId,
            task.CrsProfileRevisionId,
            route = new { spatialSrid = route.Geometry.SRID, wkt = route.Geometry.AsText(), profileStatus = task.CrsProfileRevisionId is null ? "LEGACY_UNKNOWN" : "PINNED_PROFILE" },
            segments = segments.Select(x => new { x.Id, x.Sequence, x.FromOffsetMeters, x.ToOffsetMeters, x.StartStationMeters, x.EndStationMeters, spatialSrid = x.Geometry?.SRID, wkt = x.Geometry?.AsText() }),
            layout
        },
            Version: Convert.ToBase64String(task.RowVersion));
    }
}

using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Inspections;
using RoadGuardSystem.BusinessObjects.Projects;
using RoadGuardSystem.BusinessObjects.PersistenceFacts.Inspections;
using RoadGuardSystem.BusinessObjects.PersistenceFacts.Projects;
using RoadGuardSystem.Repositories.Inspections;
namespace RoadGuardSystem.Repositories.Implementations.Inspections;

public sealed partial class FieldInspectionWorkflowRepository
{
    private async Task<object> HandoverFactsAsync(FieldInspectionTask task, FieldTaskActionInputFact? action, CancellationToken token)
    {
        if (action is null) throw new ArgumentException("Structured action required.");
        var start = await db.Set<FieldTaskStartOrigin>().AsNoTracking().SingleOrDefaultAsync(x => x.TaskId == task.Id, token);
        if (start is null) return new { performedPortionState = "NOT_STARTED", firstStartOriginId = (Guid?)null };
        var facts = action.Handover;
        if (facts is null || facts.StartOriginId != start.Id || facts.PerformedPortionState is not ("NONE" or "PARTIAL" or "CAPTURED_INTAKE" or "UNKNOWN") ||
            string.IsNullOrWhiteSpace(facts.Summary) || facts.Summary.Trim().Length > 2000 || facts.SubmissionIds is null || facts.SubmissionIds.Length > 100 ||
            facts.SubmissionIds.Any(x => x == Guid.Empty) || facts.SubmissionIds.Distinct().Count() != facts.SubmissionIds.Length ||
            facts.PerformedPortionState == "CAPTURED_INTAKE" && facts.SubmissionIds.Length == 0 || facts.RecipientUserId != action.AssignedToUserId)
            Deny(400, "handover_facts_required");
        if (await db.Set<FieldInspectionSubmission>().CountAsync(x => facts.SubmissionIds.Contains(x.Id) && x.TaskId == task.Id, token) != facts.SubmissionIds.Length) Deny(403, "handover_history_scope_invalid");
        return new
        {
            facts.PerformedPortionState,
            summary = facts.Summary.Trim(),
            facts.SubmissionIds,
            facts.RecipientUserId,
            firstStartOriginId = start.Id,
            start.OriginId,
            start.ContentHash,
            start.VerifiedOriginalAt,
            task.RoadSectionVersionId,
            task.SegmentSetId,
            task.LayoutRevisionId,
            task.SlabId
        };
    }
    private async Task<GeometryLocationImpact> ImpactAsync(FieldWorkflowCommand c, FieldInspectionTask task, FieldLocationImpactActionInputFact input, CancellationToken token)
    {
        var row = await db.Set<GeometryLocationImpact>().FromSqlInterpolated($"SELECT * FROM [GeometryLocationImpacts] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.ImpactId}").SingleOrDefaultAsync(token);
        if (row is null || row.ProjectId != c.ProjectId) Deny(404, "not_found");
        if (row.PreviousRouteVersionId != task.RoadSectionVersionId || !Decode<GeometryAffectedReferenceFact[]>(row.AffectedReferencesJson).Any(x => x.Kind == "FIELD_TASK" && x.Id == task.Id && x.RouteVersionId == task.RoadSectionVersionId && x.SegmentSetId == task.SegmentSetId)) Deny(409, "geometry_version_mismatch");
        if (input.Action is not ("STOP" or "REASSIGN" or "CONTINUE" or "VERIFY") || string.IsNullOrWhiteSpace(input.Reason) || input.Reason.Trim().Length > 2000) Deny(400, "validation_error");
        return row;
    }
    private async Task<FieldWorkflowResultFact> ApplyImpactAsync(FieldWorkflowCommand c, FieldInspectionTask task, FieldInspectionAssignment? assignment, CancellationToken token)
    {
        var input = c.Input as FieldLocationImpactActionInputFact ?? throw new ArgumentException("Impact action required.");
        var impact = await ImpactAsync(c, task, input, token);
        if (task.Status is FieldInspectionTaskStatus.Completed or FieldInspectionTaskStatus.Cancelled) Deny(409, "invalid_state_transition");
        var now = clock.GetUtcNow(); object facts;
        if (input.Action is "STOP" or "REASSIGN")
        {
            var action = new FieldTaskActionInputFact(input.Reason, input.Action == "REASSIGN" ? input.AssignedToUserId : null, input.Handover);
            facts = await HandoverFactsAsync(task, action, token);
            if (input.Action == "STOP") { task.Transition(FieldInspectionTaskStatus.Cancelled); assignment?.End(now, input.Reason); }
            else
            {
                var recipient = input.AssignedToUserId.GetValueOrDefault(); if (recipient == Guid.Empty) Deny(400, "validation_error");
                await GuardCrewAsync(c.ProjectId, recipient, token); assignment?.End(now, input.Reason); task.Reassign();
                assignment = FieldInspectionAssignment.Create(Guid.NewGuid(), task.Id, recipient, c.Admission.CallerId, now, null, FieldInspectionAssignmentStatus.Active, null);
                db.FieldInspectionAssignments.Add(assignment);
            }
        }
        else
        {
            // This re-evaluates immutable old pins. It never adopts replacement location or an official accuracy claim.
            if (task.SegmentSetId is not null) await GeometryAsync(task, token);
            facts = new
            {
                executionStatus = "APPLIED",
                locationReadiness = task.SegmentSetId is null ? "LEGACY_SEGMENT_SET_UNPINNED" : "PINNED_REFERENCE",
                task.RoadSectionVersionId,
                task.SegmentSetId,
                task.LayoutRevisionId,
                task.MapPublicationId,
                task.CrsProfileRevisionId,
                task.SlabId,
                impact.NewRouteVersionId,
                replacementAdopted = false
            };
        }
        var decision = new GeometryLocationImpactDecision
        {
            Id = Guid.NewGuid(),
            ImpactId = impact.Id,
            TaskId = task.Id,
            Action = input.Action,
            Reason = input.Reason.Trim(),
            ActorId = c.Admission.CallerId,
            OccurredAt = now
        }; db.Set<GeometryLocationImpactDecision>().Add(decision);
        Emit(c, task, assignment, input.Action switch { "STOP" => "CANCELLED", "REASSIGN" => "REASSIGNED", "CONTINUE" => "IMPACT_CONTINUE", _ => "IMPACT_VERIFY" }, input.Reason, now,
            facts: facts, impactId: impact.Id, impactDecisionId: decision.Id);
        return new(201, Value: new { decision.Id, decision.ImpactId, taskId = task.Id, decision.Action, executionStatus = "APPLIED", facts });
    }
}

using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using NetTopologySuite.Geometries;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Clocks;
using RoadGuardSystem.BusinessObjects.Inspections;
using RoadGuardSystem.BusinessObjects.PersistenceFacts.Inspections;
using RoadGuardSystem.Repositories.Inspections;
using RoadGuardSystem.Repositories.Integration;
using RoadGuardSystem.Repositories.Offline;
using RoadGuardSystem.Repositories.Repairs;
namespace RoadGuardSystem.Repositories.Implementations.Inspections;

public sealed partial class FieldInspectionWorkflowRepository
{
    // The retained FIELD core owns its original validation and serialization; adapt only the new repair seam.
    private static GroundTruthMeasurement[] ValidateMeasurements(FieldInspectionTask task, RepairFieldSubmissionData input,
        Guid session, Guid actor, DateTimeOffset now)
        => ValidateMeasurements(task, LegacyRepairSubmission(input), session, actor, now);
    private Task<List<string>> ReadinessAsync(FieldInspectionTask task, RepairFieldSubmissionData input,
        FieldTaskStartOrigin start, CancellationToken token, Guid? expectedOwner = null,
        Dictionary<Guid, OfflineEvidenceAdmissionFacts>? resolved = null)
        => ReadinessAsync(task, LegacyRepairSubmission(input), start, token, expectedOwner, resolved);
    private Task<ReporterFileFacts> EvidenceFileAsync(FieldInspectionTask task, RepairFieldEvidenceData declaration,
        CancellationToken token, Guid? expectedOwner = null)
        => EvidenceFileAsync(task, LegacyRepairEvidence(declaration), token, expectedOwner);
    private Task<string> CaptureEvidenceFactsAsync(FieldInspectionTask task, RepairFieldEvidenceData declaration,
        CancellationToken token) => CaptureEvidenceFactsAsync(task, LegacyRepairEvidence(declaration), token);
    private static FieldEvidenceDeclarationFact LegacyRepairEvidence(RepairFieldEvidenceData value)
        => new(value.CaptureOriginId, value.FileId, value.Purpose, value.ChecksumSha256,
            value.MediaType, value.CapturedAt, value.AttemptChecklist);
    private static FieldSubmissionInputFact LegacyRepairSubmission(RepairFieldSubmissionData value)
        => new(value.OriginId, value.StartOriginId, value.ParentSubmissionId,
            value.Measurements?.Select(row => row is null ? null! : new FieldMeasurementInputFact(row.SampleId,
                row.Type, row.Value, row.State, row.UnknownReason, row.Dimension, row.Unit, row.Longitude,
                row.Latitude, row.LocationReason, row.Instrument, row.Method, row.Notes)).ToArray(),
            value.Evidence?.Select(row => row is null ? null! : LegacyRepairEvidence(row)).ToArray(),
            value.LocationProof is null ? null : new(value.LocationProof.Kind, value.LocationProof.Checklist,
                value.LocationProof.Longitude, value.LocationProof.Latitude, value.LocationProof.ObservedSlabId,
                value.LocationProof.ObservedSegmentId, value.LocationProof.ObservedRouteVersionId,
                value.LocationProof.ObservedChainageMeters), value.CaptureType, value.Repaired,
            value.UnrepairedReason, value.DeviceId);
    private async Task<FieldWorkflowResultFact> SubmitAsync(FieldWorkflowCommand c, FieldInspectionTask task, FieldInspectionAssignment assignment, CancellationToken token)
    {
        var input = c.Input as FieldSubmissionInputFact ?? throw new ArgumentException("Submission input required.");
        var hash = Hash(new { task.Id, input, c.Admission.OriginalActorId });
        var duplicate = await OriginAsync(c.ProjectId, input.OriginId, "FIELD_SUBMISSION", hash, c.Admission.OriginalActorId, task.Id, token);
        if (duplicate is not null) return new(200, Value: await db.Set<FieldInspectionSubmission>().AsNoTracking().SingleAsync(x => x.Id == duplicate.EffectId, token));
        if (task.Status is not (FieldInspectionTaskStatus.InProgress or FieldInspectionTaskStatus.SupplementRequired)) Deny(409, "invalid_state_transition");
        var start = await db.Set<FieldTaskStartOrigin>().SingleOrDefaultAsync(x => x.Id == input.StartOriginId && x.TaskId == task.Id, token);
        if (start is null) Deny(409, "first_start_required");
        var latest = await db.Set<FieldInspectionSubmission>().Where(x => x.TaskId == task.Id).OrderByDescending(x => x.Revision).FirstOrDefaultAsync(token);
        if (latest is null ? input.ParentSubmissionId is not null : input.ParentSubmissionId != latest.Id) Deny(409, "submission_lineage_conflict");
        var admitted = await ImportedFactsAsync(c, token);
        var resolved = new Dictionary<Guid, OfflineEvidenceAdmissionFacts>();
        if (admitted is not null)
        {
            if (evidenceAdmission is null) Deny(403, "signed_evidence_admission_required");
            foreach (var declaration in input.Evidence ?? [])
            {
                var facts = await evidenceAdmission.ResolveDeclaredEvidenceAsync(c.ProjectId, task.Id, admitted.AdmissionId,
                    c.Admission.OriginalActorId, new RepairFieldEvidenceData(declaration.CaptureOriginId, declaration.FileId,
                        declaration.Purpose, declaration.ChecksumSha256, declaration.MediaType, declaration.CapturedAt,
                        declaration.AttemptChecklist), token);
                if (facts is not null)
                {
                    if (facts.AdmissionId != admitted.AdmissionId || facts.OriginalActorId != c.Admission.OriginalActorId ||
                        !string.Equals(facts.Checksum, declaration.ChecksumSha256, StringComparison.OrdinalIgnoreCase) || facts.Purpose != declaration.Purpose ||
                        facts.MediaType != declaration.MediaType || declaration.FileId is Guid declared && declared != facts.FileId)
                        Deny(409, "evidence_version_mismatch");
                    resolved.Add(declaration.CaptureOriginId, facts);
                }
                else if (declaration.FileId is not null) Deny(403, "signed_evidence_admission_required");
            }
        }
        var now = clock.GetUtcNow(); var id = admitted?.EffectId ?? Guid.NewGuid();
        var session = FieldInspectionSession.Create(Guid.NewGuid(), task.Purpose, task.Id, c.ProjectId, task.RoadSectionVersionId, task.SurveyId,
            "FIELD-S-" + Guid.NewGuid().ToString("N"), c.Admission.OriginalActorId, "FIELD inspector", now, null, "FIELD capture",
            FieldInspectionSessionStatus.Completed, null);
        var measurements = ValidateMeasurements(task, input, session.Id, c.Admission.OriginalActorId, now);
        var missing = await ReadinessAsync(task, input, start, token, c.Admission.OriginalActorId, resolved);
        var row = FieldInspectionSubmission.Create(id, c.ProjectId, task.Id, latest?.RootId ?? id, latest?.Id, (latest?.Revision ?? 0) + 1,
            assignment.Id, start.Id, session.Id, input.OriginId, hash, c.Admission.OriginalActorId, now, JsonSerializer.Serialize(input, Json),
            missing.Count == 0 ? "READY" : "INCOMPLETE", JsonSerializer.Serialize(missing, Json));
        db.AddRange(FieldInspectionOperationOrigin.Create(id, c.ProjectId, input.OriginId, "FIELD_SUBMISSION", hash, c.Admission.OriginalActorId, input.DeviceId, task.Id, id, now), session, row);
        db.GroundTruthMeasurements.AddRange(measurements);
        foreach (var declaration in input.Evidence ?? [])
        {
            resolved.TryGetValue(declaration.CaptureOriginId, out var actual);
            var capture = actual is null ? await CaptureEvidenceFactsAsync(task, declaration, token) :
                await CaptureResolvedEvidenceFactsAsync(task, declaration, actual, token);
            db.Set<FieldInspectionEvidenceLink>().Add(FieldInspectionEvidenceLink.Create(Guid.NewGuid(), c.ProjectId, task.Id, assignment.Id, id,
                actual?.FileId ?? declaration.FileId, declaration.CaptureOriginId, declaration.Purpose, declaration.ChecksumSha256, declaration.MediaType, capture));
        }
        var proof = input.LocationProof;
        db.Set<FieldInspectionLocationProof>().Add(FieldInspectionLocationProof.Create(Guid.NewGuid(), c.ProjectId, task.Id, id,
            proof?.Kind ?? "UNKNOWN", JsonSerializer.Serialize(proof is null ? new { reason = "No location proof declared" } : (object)proof, Json)));
        if (latest is null) db.Set<DeadlineClock>().Add(DeadlineClock.Create(Guid.NewGuid(), c.ProjectId, DeadlineClockKind.ProjectManagerReview, task.Id, id, now));
        await RoadGuardSystem.Repositories.Messaging.BusinessRequestProducer.CompleteSupplements(db, c.ProjectId, task.Id, now, token);
        task.Transition(FieldInspectionTaskStatus.Submitted); Emit(c, task, assignment, "SUBMITTED", "Immutable FIELD intake", now, id);
        return new(201, Value: row);
    }
    private static GroundTruthMeasurement[] ValidateMeasurements(FieldInspectionTask task, FieldSubmissionInputFact input, Guid session, Guid actor, DateTimeOffset now)
    {
        if (input.CaptureType is not ("MEASUREMENT" or "REPAIR_CLAIM") || input.CaptureType == "MEASUREMENT" && (input.Repaired is not null || input.UnrepairedReason is not null) ||
            input.CaptureType == "REPAIR_CLAIM" && (task.Purpose != FieldInspectionPurpose.PostRepair || input.Repaired is null || input.Repaired == false && string.IsNullOrWhiteSpace(input.UnrepairedReason)))
            throw new ArgumentException("Measurement capture and actual repair claim are distinct.");
        if (input.Measurements?.Length > 200 || input.Evidence?.Length > 100) throw new ArgumentException("Bounded intake arrays required.");
        var rows = new List<GroundTruthMeasurement>(); var samples = new HashSet<string>(StringComparer.Ordinal);
        foreach (var item in input.Measurements ?? [])
        {
            if (item is null || string.IsNullOrWhiteSpace(item.SampleId) || !samples.Add(item.SampleId) || item.Value > 9999999999999.999999m ||
                item.Value is decimal v && decimal.Round(v, 6) != v || !Enum.TryParse<MeasurementType>(item.Type, true, out var type)) throw new ArgumentException("Malformed measurement.");
            if (item.Longitude.HasValue != item.Latitude.HasValue) throw new ArgumentException("Coordinates supplied together.");
            Point? point = item.Longitude is double lon ? new GeometryFactory(new PrecisionModel(), 4326).CreatePoint(new Coordinate(lon, item.Latitude!.Value)) : null;
            rows.Add(GroundTruthMeasurement.CreateCaptured(Guid.NewGuid(), session, item.SampleId, task.RoadSectionVersionId, task.SurveyId, task.DefectId,
                type, item.Value, item.State, item.UnknownReason, item.Dimension, item.Unit, point, item.LocationReason, item.Instrument, item.Method,
                actor.ToString(), now, null, item.Notes ?? "Declared evidence remains independently linked to immutable submission"));
        }
        var captures = new HashSet<Guid>();
        foreach (var item in input.Evidence ?? [])
            if (item is null || !captures.Add(item.CaptureOriginId) || item.CaptureOriginId == Guid.Empty || item.FileId == Guid.Empty ||
                item.Purpose is not ("BEFORE" or "AFTER" or "MEASUREMENT") || item.Purpose == "AFTER" && task.Purpose != FieldInspectionPurpose.PostRepair || string.IsNullOrEmpty(item.ChecksumSha256) || item.ChecksumSha256.Length != 64 ||
                item.ChecksumSha256.Any(x => !Uri.IsHexDigit(x)) || string.IsNullOrWhiteSpace(item.MediaType) || item.MediaType.Length > 120 || item.AttemptChecklist?.Length > 500)
                throw new ArgumentException("Malformed evidence declaration.");
        return rows.ToArray();
    }
    private async Task<List<string>> ReadinessAsync(FieldInspectionTask task, FieldSubmissionInputFact input, FieldTaskStartOrigin start, CancellationToken token, Guid? expectedOwner = null,
        Dictionary<Guid, OfflineEvidenceAdmissionFacts>? resolved = null)
    {
        var missing = new HashSet<string>(StringComparer.Ordinal);
        if (input.Measurements is null || input.Measurements.Length == 0) missing.Add("MEASUREMENT_MISSING");
        else
        {
            if (!input.Measurements.Any(x => Enum.TryParse<MeasurementType>(x.Type, true, out var type) && (byte)type == task.RequiredMeasurementType)) missing.Add("REQUIRED_MEASUREMENT_MISSING");
            if (input.Measurements.Any(x => x.State == "UNKNOWN")) missing.Add("MEASUREMENT_VALUE_UNKNOWN");
        }
        var proof = input.LocationProof;
        if (proof is null || proof.Kind == "UNKNOWN") missing.Add("LOCATION_UNKNOWN");
        else if (proof.Kind == "GPS_CAPTURE")
        {
            if (proof.Longitude is not double lon || proof.Latitude is not double lat || !double.IsFinite(lon) || !double.IsFinite(lat) || lon is < -180 or > 180 || lat is < -90 or > 90)
                throw new ArgumentException("Malformed GPS capture.");
            // Valid GPS is captured evidence. H2 candidate/legacy profiles cannot establish its metric binding.
            // No owner-sourced tolerance/accepted GPS mapping is configured in this package.
            missing.Add("GPS_SOURCE_BINDING_UNAVAILABLE");
            if (proof.Checklist is not null || proof.ObservedSlabId is not null || proof.ObservedSegmentId is not null)
                missing.Add("LOCATION_PROOF_CONTRADICTORY");
        }
        else if (proof.Kind == "POSITION_CHECKLIST")
        {
            if (proof.Longitude is not null || proof.Latitude is not null) missing.Add("LOCATION_PROOF_CONTRADICTORY");
            if (task.SlabId is not null)
            {
                if (proof.Checklist != "SLAB_MARKINGS_CONFIRMED" || task.LayoutRevisionId is null || proof.ObservedSlabId != task.SlabId)
                    missing.Add("POSITION_CHECKLIST_INSUFFICIENT");
            }
            else if (task.SegmentSetId is Guid set && proof.Checklist == "SEGMENT_MARKINGS_CONFIRMED")
            {
                var segment = await db.RoadSegments.AsNoTracking().SingleOrDefaultAsync(x => x.Id == proof.ObservedSegmentId && x.SegmentSetId == set && x.RoadSectionVersionId == task.RoadSectionVersionId, token);
                if (segment is null || proof.ObservedChainageMeters is not double offset || !double.IsFinite(offset) ||
                    segment.FromOffsetMeters is not double from || segment.ToOffsetMeters is not double to || offset < from || offset > to)
                    missing.Add("POSITION_CHECKLIST_INSUFFICIENT");
            }
            else if (proof.Checklist == "ROUTE_CHAINAGE_MARKINGS_CONFIRMED" && proof.ObservedRouteVersionId == task.RoadSectionVersionId)
            {
                var route = await db.RoadSectionVersions.AsNoTracking().SingleAsync(x => x.Id == task.RoadSectionVersionId, token);
                var native = await db.Set<RoadGuardSystem.BusinessObjects.Projects.NativeRouteVersionFacts>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == task.RoadSectionVersionId, token);
                var length = native?.CanonicalLengthMeters ?? route.Geometry.Length;
                if (proof.ObservedChainageMeters is not double offset || !double.IsFinite(offset) || offset < 0 || offset > length)
                    missing.Add("POSITION_CHECKLIST_INSUFFICIENT");
            }
            else missing.Add("POSITION_CHECKLIST_INSUFFICIENT");
        }
        else throw new ArgumentException("Unsupported location proof kind.");
        if (input.Evidence is null || input.Evidence.Length == 0) missing.Add("EVIDENCE_MISSING");
        foreach (var item in input.Evidence ?? [])
        {
            var actual = resolved is not null && resolved.TryGetValue(item.CaptureOriginId, out var facts) ? facts : null;
            if (item.FileId is null && actual is null) { missing.Add("EVIDENCE_UPLOAD_NOT_CREATED"); continue; }
            var file = await EvidenceFileAsync(task, actual is null ? item : item with { FileId = actual.FileId }, token, actual?.ActualUploaderId ?? expectedOwner);
            if (file.State != "VERIFIED") missing.Add("EVIDENCE_PENDING");
            if (input.CaptureType == "REPAIR_CLAIM" && input.Repaired == true && item.Purpose == "AFTER")
            {
                if (item.AttemptChecklist != "POST_REPAIR_CAPTURE" || item.CapturedAt is null || item.CapturedAt > clock.GetUtcNow() ||
                    start.VerifiedOriginalAt is null || item.CapturedAt < start.VerifiedOriginalAt) missing.Add("AFTER_CAPTURE_PROVENANCE_INSUFFICIENT");
            }
        }
        if (input.CaptureType == "REPAIR_CLAIM" && input.Repaired == true)
        {
            if (!(input.Evidence ?? []).Any(x => x.Purpose == "AFTER")) missing.Add("AFTER_EVIDENCE_MISSING");
            // H3 has no trusted H4 attempt/finish binding: a declared capture/checklist is not freshness proof.
            missing.Add("AFTER_ATTEMPT_BINDING_UNAVAILABLE");
        }
        return missing.Order(StringComparer.Ordinal).ToList();
    }
    private async Task<ReporterFileFacts> EvidenceFileAsync(FieldInspectionTask task, FieldEvidenceDeclarationFact declaration, CancellationToken token, Guid? expectedOwner = null)
    {
        if (string.IsNullOrEmpty(declaration.ChecksumSha256) || declaration.ChecksumSha256.Length != 64 || !declaration.ChecksumSha256.All(Uri.IsHexDigit) || string.IsNullOrWhiteSpace(declaration.MediaType))
            throw new ArgumentException("Malformed evidence declaration.");
        var id = declaration.FileId!.Value;
        await db.Files.FromSqlInterpolated($"SELECT * FROM [Files] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={id}").AsNoTracking().ToListAsync(token);
        await db.UploadSessions.FromSqlInterpolated($"SELECT * FROM [UploadSessions] WITH (UPDLOCK,HOLDLOCK) WHERE [FileId]={id}").AsNoTracking().ToListAsync(token);
        var file = await new AnhHuyFactsRepository(db).GetFileAsync(id, token);
        var scope = await db.FileScopes.AsNoTracking().SingleOrDefaultAsync(x => x.FileId == id, token);
        if (file is null || scope is null) Deny(404, "evidence_not_found");
        var normalizedChecksum = declaration.ChecksumSha256.ToLowerInvariant();
        var reuse = declaration.Purpose == "BEFORE" && await db.Set<FieldInspectionEvidenceReuseDecision>().AnyAsync(x => x.TaskId == task.Id && x.FileId == id && x.FileChecksum == normalizedChecksum, token);
        if (reuse)
        {
            var decision = await db.Set<FieldInspectionEvidenceReuseDecision>().AsNoTracking().Where(x => x.TaskId == task.Id && x.FileId == id && x.FileChecksum == normalizedChecksum).OrderByDescending(x => x.OccurredAt).FirstAsync(token);
            await ValidateHistoricalReuseAsync(task, decision, file, token);
        }
        if (!reuse && (scope.ProjectId != task.ProjectId || scope.TargetId != task.Id || scope.Purpose != declaration.Purpose || expectedOwner is Guid owner && file.OwnerId != owner)) Deny(403, "evidence_access_forbidden");
        if (file.Checksum != normalizedChecksum || file.MediaType != declaration.MediaType) Deny(409, "evidence_version_mismatch");
        return file;
    }
    private async Task<string> CaptureEvidenceFactsAsync(FieldInspectionTask task, FieldEvidenceDeclarationFact declaration, CancellationToken token)
    {
        if (declaration.FileId is null) return JsonSerializer.Serialize(new { declared = declaration, state = "UPLOAD_NOT_CREATED" }, Json);
        var file = await EvidenceFileAsync(task, declaration, token);
        return JsonSerializer.Serialize(new { declared = declaration, stateAtIntake = file.State, file.FileVersion, file.OwnerId, file.Purpose, file.UploadedAt }, Json);
    }
    private async Task<string> CaptureResolvedEvidenceFactsAsync(FieldInspectionTask task, FieldEvidenceDeclarationFact declaration,
        OfflineEvidenceAdmissionFacts admitted, CancellationToken cancellationToken)
    {
        var file = await EvidenceFileAsync(task, declaration with { FileId = admitted.FileId }, cancellationToken, admitted.ActualUploaderId);
        return JsonSerializer.Serialize(new
        {
            declared = declaration,
            stateAtIntake = file.State,
            file.FileVersion,
            file.OwnerId,
            file.Purpose,
            file.UploadedAt,
            actualFileId = admitted.FileId,
            offlineAdmission = admitted
        }, Json);
    }
    private async Task<FieldWorkflowResultFact> ReviewAsync(FieldWorkflowCommand c, FieldInspectionTask task, CancellationToken token)
    {
        var input = c.Input as FieldReviewInputFact ?? throw new ArgumentException("Review input required.");
        if (task.Status != FieldInspectionTaskStatus.Submitted) Deny(409, "invalid_state_transition");
        var row = await db.Set<FieldInspectionSubmission>().SingleOrDefaultAsync(x => x.Id == input.SubmissionId && x.TaskId == task.Id, token);
        if (row is null) Deny(404, "not_found");
        if (await db.Set<FieldInspectionSubmission>().AnyAsync(x => x.TaskId == task.Id && x.Revision > row.Revision, token)) Deny(409, "submission_lineage_conflict");
        var payload = Decode<FieldSubmissionInputFact>(row.PayloadJson);
        var start = await db.Set<FieldTaskStartOrigin>().SingleAsync(x => x.Id == row.StartOriginId, token);
        if (input.Decision != "SUPPLEMENT")
        {
            var retained = new Dictionary<Guid, OfflineEvidenceAdmissionFacts>();
            var links = await db.Set<FieldInspectionEvidenceLink>().AsNoTracking().Where(x => x.SubmissionId == row.Id).ToArrayAsync(token);
            foreach (var link in links)
            {
                using var capture = JsonDocument.Parse(link.CaptureFactsJson);
                if (!capture.RootElement.TryGetProperty("offlineAdmission", out var admittedJson)) continue;
                if (!capture.RootElement.TryGetProperty("stateAtIntake", out var state) || state.GetString() != "VERIFIED") continue;
                var admitted = admittedJson.Deserialize<OfflineEvidenceAdmissionFacts>(Json) ?? throw new JsonException("Missing accepted evidence proof.");
                if (admitted.FileId != link.FileId || admitted.OriginalActorId != row.OriginalActorId || admitted.Checksum != link.DeclaredChecksum ||
                    admitted.Purpose != link.Purpose || admitted.MediaType != link.MediaType) Deny(409, "evidence_version_mismatch");
                retained.Add(link.CaptureOriginId, admitted);
            }
            if ((await ReadinessAsync(task, payload, start, token, row.OriginalActorId, retained)).Count != 0) Deny(409, "field_result_insufficient");
        }
        var now = clock.GetUtcNow(); var review = FieldInspectionReview.Create(Guid.NewGuid(), c.ProjectId, task.Id, row.Id, c.Admission.CallerId, input.Decision, input.Reason, now);
        db.Set<FieldInspectionReview>().Add(review);
        if (input.Decision == "SUPPLEMENT")
        {
            var assigned = await CurrentAssignmentAsync(task.Id, token);
            if (assigned is null) Deny(409, "current_assignment_missing");
            RoadGuardSystem.Repositories.Messaging.BusinessRequestProducer.Supplement(db, c.ProjectId,
                "FieldReview", review.Id, task.Id, assigned.AssignedToUserId, now);
        }
        task.Transition(input.Decision == "SUPPLEMENT" ? FieldInspectionTaskStatus.SupplementRequired : FieldInspectionTaskStatus.Completed);
        if (input.Decision != "SUPPLEMENT")
        {
            var reviewClock = await db.Set<DeadlineClock>().SingleAsync(x => x.ProjectId == c.ProjectId && x.TargetId == task.Id && x.Kind == DeadlineClockKind.ProjectManagerReview, token);
            reviewClock.Complete(now);
        }
        Emit(c, task, await CurrentAssignmentAsync(task.Id, token), input.Decision == "SUPPLEMENT" ? "SUPPLEMENT" : "REVIEWED", input.Reason, now, row.Id);
        return new(201, Value: new FieldReviewViewFact(review.Id, task.Id, row.Id, review.Decision, review.ReceiptActivation));
    }
}

using RoadGuardSystem.Repositories.Inspections;
using RoadGuardSystem.Repositories.Offline;

namespace RoadGuardSystem.Repositories.Implementations.Inspections;

public sealed partial class FieldInspectionWorkflowRepository
{
    private async Task<OfflineFieldAdmissionFacts?> ImportedFactsAsync(FieldWorkflowCommand command, CancellationToken cancellationToken)
    {
        var context = command.Admission;
        if (context.Mode == "DIRECT") return null;
        if (context.Mode is not ("SYNC" or "HANDOVER") || command.Action is not ("accept" or "start" or "submit") ||
            context.TrustedOnlineOrigin || context.OfflineAdmissionId is null || offlineAdmission is null)
            Deny(403, "offline_admission_required");
        var facts = await offlineAdmission.ValidateAsync(command, cancellationToken);
        var kind = command.Action switch { "accept" => "FIELD_ACCEPT", "start" => "FIELD_START", _ => "FIELD_SUBMISSION" };
        if (facts is null || facts.AdmissionId != context.OfflineAdmissionId || facts.CallerId != context.CallerId ||
            facts.CallerRole != context.CallerRole || facts.OriginalActorId != context.OriginalActorId || facts.ProjectId != command.ProjectId ||
            facts.TaskId != command.TaskId || facts.Kind != kind || facts.EffectId == Guid.Empty)
            Deny(403, "offline_admission_required");
        if (OriginMetadata(command.Input) is { } origin &&
            (origin.OriginId != facts.EffectId || origin.DeviceId != facts.SourceDeviceId))
            Deny(409, "origin_content_conflict");
        return facts;
    }
}

using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Inspections;
using RoadGuardSystem.BusinessObjects.Repairs;
