public sealed class GeometryWorkflowPersistenceService(RoadGuardDbContext db, IdempotencyOperationService idempotency, TimeProvider? timeProvider = null) : IGeometryWorkflowRepository
{
    private readonly TimeProvider clock = timeProvider ?? TimeProvider.System;
    public Task<bool> CanReadAssignedGeometryAsync(Guid actorId, Guid projectId, Guid routeVersionId, Guid setId, CancellationToken cancellationToken)
        => (from scope in db.SurveyRequestScopes
            join task in db.SurveyRequests on scope.SurveyRequestId equals task.Id
            join assignment in db.SurveyAssignments on task.Id equals assignment.SurveyRequestId
            where task.ProjectId == projectId && scope.RouteSectionVersionId == routeVersionId && scope.SegmentSetId == setId
                && assignment.OperatorUserId == actorId && assignment.EndedAt == null
            select task.Id).AnyAsync(cancellationToken);
    private static string Hash(object value) => Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(value))).ToLowerInvariant();
    private static T Decode<T>(string json) => JsonSerializer.Deserialize<T>(json)!;
    private static string Version(byte[] bytes) => Convert.ToBase64String(bytes);
    private sealed class Rejected(int status, string code) : Exception { public GeometryWorkflowResult Result { get; } = new(status, code); }
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Reject(int status, string code) => throw new Rejected(status, code);
    public async Task<GeometryWorkflowResult> ExecuteAsync(GeometryWorkflowCommand command, Func<GeometryDraftInputFact, int, GeometryPreviewFact> preview,
        Func<Guid, LineString, double, SegmentDefinitionFact, SegmentPreviewFact> segments, CancellationToken cancellationToken)
    {
        var c = command; var ct = cancellationToken;
        try
        {
            var write = c.Action is "draft-create" or "draft-edit" or "confirm" or "set-create" or "set-edit" or "publish" or "profile-create" or "system-create";
            if (!write && db.Database.CurrentTransaction is not null)
            {
                await GuardAsync(c, true, ct);
                return await Run(c, preview, segments, ct);
            }
            if (!write) return await db.Database.CreateExecutionStrategy().ExecuteAsync(async () =>
            {
                await using var transaction = await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable, ct);
                await GuardAsync(c, true, ct);
                var result = await Run(c, preview, segments, ct);
                await transaction.CommitAsync(ct);
                return result;
            });
            var receipt = await idempotency.ExecuteAsync(c.ActorId, c.ProjectId, "Geometry:" + c.Action, c.Key!, Hash(new { c.RoadSectionId, c.DraftId, c.RouteVersionId, c.SetId, c.Input, c.ExpectedVersion }), async token =>
            {
                // Project serialization also covers alias URLs whose draft resolves the existing road only inside the handler.
                var resource = $"anh01:geometry:{c.ProjectId}";
                await db.Database.ExecuteSqlInterpolatedAsync($"DECLARE @lockResult int; EXEC @lockResult = sys.sp_getapplock @Resource={resource}, @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=10000; IF @lockResult < 0 THROW 51000, 'Geometry command lock unavailable', 1;", token);
                await GuardAsync(c, true, token);
                var result = await Run(c, preview, segments, token);
                var id = result.Value switch { GeometryDraftViewFact draft => draft.Id, RoadGeometryVersionViewFact route => route.RouteVersionId, SegmentSetViewFact set => set.Id, _ => c.SetId ?? c.DraftId ?? Guid.NewGuid() };
                db.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), c.ActorId, clock.GetUtcNow(),
                    "geometry_" + c.Action.Replace('-', '_'), "RoadGeometry", id, null,
                    JsonSerializer.Serialize(new { project_id = c.ProjectId, operation = c.Action }), "GEOMETRY_WORKFLOW", "PROJECT_API", null,
                    snapshotAllowedPropertyNames: ["project_id", "operation"]));
                await db.SaveChangesAsync(token);
                return (id, JsonSerializer.Serialize(result));
            }, ct, receiptAccessGuard: token => GuardAsync(c, true, token));
            if (receipt.Status == IdempotencyOperationStatus.Conflict) return new(409, "duplicate_request");
            var restored = Decode<GeometryWorkflowResult>(receipt.OutcomeJson);
            if (restored.Value is JsonElement json) restored = restored with
            {
                Value = c.Action switch
                {
                    "draft-create" or "draft-edit" => json.Deserialize<GeometryDraftViewFact>(),
                    "confirm" => json.Deserialize<RoadGeometryVersionViewFact>(),
                    "profile-create" => json.Deserialize<CrsProfileViewFact>(),
                    "system-create" => json.Deserialize<RouteSystemViewFact>(),
                    _ => json.Deserialize<SegmentSetViewFact>()
                }
            };
            return restored;
        }
        catch (Rejected e) { db.ChangeTracker.Clear(); return e.Result; }
        catch (DbUpdateConcurrencyException) { db.ChangeTracker.Clear(); return new(412, "concurrency_conflict"); }
        catch (DbUpdateException e) when (e.InnerException is SqlException { Number: 2601 or 2627 })
        {
            db.ChangeTracker.Clear();
            return new(409, c.Action == "confirm"
                ? ((GeometryConfirmInputFact)c.Input!).ExpectedCurrentVersionId is null ? "road_section_code_conflict" : "road_section_concurrency_conflict"
                : "segment_publication_conflict");
        }
    }
    private async Task<GeometryWorkflowResult> Run(GeometryWorkflowCommand c, Func<GeometryDraftInputFact, int, GeometryPreviewFact> preview,
        Func<Guid, LineString, double, SegmentDefinitionFact, SegmentPreviewFact> segments, CancellationToken ct)
    {
        var project = await db.Projects.SingleOrDefaultAsync(x => x.Id == c.ProjectId, ct);
        if (project is null) Reject(404, "project_not_found");
        if (project!.Status == RoadGuardSystem.aBusinessObjects.Commons.ProjectStatus.Closed && c.Action is "draft-create" or "draft-edit" or "confirm" or "set-create" or "set-edit" or "publish" or "profile-create" or "system-create") Reject(409, "project_closed");
        var srid = project!.EngineeringUtmSrid ?? 0;
        if (c.Action == "profile-create")
        {
            var input = (CrsProfileInputFact)c.Input!;
            var next = (await db.Set<CrsProfileRevision>().Where(x => x.ProjectId == c.ProjectId && x.Code == input.Code.Trim()).Select(x => (int?)x.Revision).MaxAsync(ct) ?? 0) + 1;
            var profile = new CrsProfileRevision { Id = Guid.NewGuid(), ProjectId = c.ProjectId, Code = input.Code.Trim(), Revision = next, SourceSrid = input.SourceSrid, Status = "CANDIDATE", SampleOnly = input.SampleOnly, PayloadJson = JsonSerializer.Serialize(input), CreatedBy = c.ActorId, CreatedAt = clock.GetUtcNow() };
            db.Add(profile); await db.SaveChangesAsync(ct); return new(201, Value: ProfileView(profile), Version: Hash(profile.PayloadJson));
        }
        if (c.Action == "profile-get")
        {
            var profile = await db.Set<CrsProfileRevision>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == c.DraftId && x.ProjectId == c.ProjectId, ct);
            if (profile is null) Reject(404, "crs_profile_not_found");
            return new(200, Value: ProfileView(profile!), Version: Hash(profile!.PayloadJson));
        }
        if (c.Action == "profile-list") return new(200, Value: (await db.Set<CrsProfileRevision>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId).OrderBy(x => x.Code).ThenBy(x => x.Revision).ToArrayAsync(ct)).Select(ProfileView).ToArray());
        if (c.Action == "system-create")
        {
            var input = (RouteSystemInputFact)c.Input!;
            if (string.IsNullOrWhiteSpace(input.Code) || input.Code.Length > 80 || string.IsNullOrWhiteSpace(input.Name) || input.Name.Length > 255) Reject(422, "route_system_invalid");
            var system = new RoadRouteSystem { Id = Guid.NewGuid(), ProjectId = c.ProjectId, Code = input.Code.Trim(), Name = input.Name.Trim() };
            db.Add(system); await db.SaveChangesAsync(ct); return new(201, Value: new RouteSystemViewFact(system.Id, system.ProjectId, system.Code, system.Name));
        }
        if (c.Action == "system-list") return new(200, Value: await db.Set<RoadRouteSystem>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId).OrderBy(x => x.Code).Select(x => new RouteSystemViewFact(x.Id, x.ProjectId, x.Code, x.Name)).ToArrayAsync(ct));
        RoadSection? section = null;
        if (c.RoadSectionId is Guid sid)
        {
            section = await db.RoadSections.SingleOrDefaultAsync(x => x.Id == sid && x.ProjectId == c.ProjectId, ct);
            if (section is null) Reject(404, "road_section_not_found");
        }
        if (c.Action.StartsWith("draft", StringComparison.Ordinal) || c.Action == "confirm")
        {
            RoadGeometryDraft? draft = null;
            if (c.DraftId is Guid did)
            {
                draft = await db.Set<RoadGeometryDraft>().SingleOrDefaultAsync(x => x.Id == did && x.ProjectId == c.ProjectId && (c.RoadSectionId == null || x.RoadSectionId == c.RoadSectionId), ct);
                if (draft is null) Reject(404, "road_geometry_draft_not_found");
                if (section is null && draft!.RoadSectionId is Guid existingSectionId)
                {
                    section = await db.RoadSections.SingleOrDefaultAsync(x => x.Id == existingSectionId && x.ProjectId == c.ProjectId, ct);
                    if (section is null) Reject(404, "road_section_not_found");
                }
            }
            if (c.Action is "draft-create" or "draft-edit")
            {
                var input = (GeometryDraftInputFact)c.Input!;
                if (input.SourceKind == "NATIVE_ALIGNMENT")
                {
                    input = await ResolveNativeInputAsync(input, c.ProjectId, ct);
                    if (NativeMissing(input).Length == 0) preview(input, input.SourceCrs);
                }
                else preview(input, srid);
                var code = section?.Code ?? input.RoadCode?.Trim();
                if (string.IsNullOrWhiteSpace(code) || code.Length > 80 || input.RoadName?.Length > 255 || (input.BranchCode is not null && input.BranchCode != code)) Reject(422, "geometry_validation_failed");
                if (draft is null) { draft = RoadGeometryDraft.Create(c.ProjectId, c.RoadSectionId, code!, input.RoadName, JsonSerializer.Serialize(input), JsonSerializer.Serialize(input.Coordinates), null, c.ActorId, clock.GetUtcNow()); db.Add(draft); }
                else
                {
                    Match(draft.RowVersion, c.ExpectedVersion); if (draft.Status != "DRAFT") Reject(409, "road_geometry_invalid_state");
                    var previousInput = Decode<GeometryDraftInputFact>(draft.InputJson);
                    var original = previousInput.SourceKind == input.SourceKind && previousInput.SourceCrs == input.SourceCrs && previousInput.SourceFileId == input.SourceFileId ? draft.OriginalCoordinatesJson : JsonSerializer.Serialize(input.Coordinates);
                    draft.Edit(JsonSerializer.Serialize(input), original, null, code!, input.RoadName, c.ActorId, clock.GetUtcNow());
                }
                await db.SaveChangesAsync(ct);
                return new(c.Action == "draft-create" ? 201 : 200, Value: DraftView(draft), Version: Version(draft.RowVersion));
            }
            if (c.ExpectedVersion is not null) Match(draft!.RowVersion, c.ExpectedVersion);
            var stored = Decode<GeometryDraftInputFact>(draft!.InputJson);
            if (stored.SourceKind == "NATIVE_ALIGNMENT") stored = await ResolveNativeInputAsync(stored, c.ProjectId, ct);
            if (c.Action == "draft-get") return new(200, Value: DraftView(draft), Version: Version(draft.RowVersion));
            if (c.Action == "draft-readiness") return new(200, Value: stored, Version: Version(draft.RowVersion));
            if (c.Action == "draft-preview") return new(200, Value: preview(stored, srid), Version: Version(draft.RowVersion));
            if (draft.Status != "DRAFT") Reject(409, "road_geometry_invalid_state");
            var confirm = (GeometryConfirmInputFact)c.Input!;
            if (string.IsNullOrWhiteSpace(confirm.Reason) || confirm.EffectiveFrom == default) Reject(422, "geometry_validation_failed");
            var prepared = preview(stored, srid);
            if (stored.SourceKind == "NATIVE_ALIGNMENT") await ValidateTopologyAsync(stored, c.ProjectId, section?.Id, prepared, preview, segments, ct);
            RoadSectionVersion? current = section is null ? null : await db.RoadSectionVersions.SingleOrDefaultAsync(x => x.RoadSectionId == section.Id && x.IsCurrent, ct);
            if (current?.Id != confirm.ExpectedCurrentVersionId) Reject(409, "road_section_concurrency_conflict");
            if (section is null) { section = RoadSection.Create(Guid.NewGuid(), c.ProjectId, draft.RoadCode, draft.RoadName); db.Add(section); }
            if (current is not null) { current.ClearCurrent(); await db.SaveChangesAsync(ct); }
            var line = stored.SourceKind == "NATIVE_ALIGNMENT"
                ? new GeometryFactory(new PrecisionModel(), stored.SourceCrs).CreateLineString(((double[][])prepared.MetricCenterline.Coordinates).Select(p => new Coordinate(p[0], p[1])).ToArray())
                : new GeometryFactory(new PrecisionModel(), srid).CreateLineString(stored.Coordinates!.Select(p => new Coordinate(p.X, p.Y)).ToArray());
            var version = RoadSectionVersion.Create(Guid.NewGuid(), section.Id, (current?.VersionNo ?? 0) + 1, true, line, confirm.EffectiveFrom, confirm.Reason);
            if (stored.NativeAlignment is { } native)
            {
                version.PinNativeProfile(native.CrsProfileRevisionId);
                db.Add(new NativeRouteVersionFacts { RoadSectionVersionId = version.Id, ProjectId = c.ProjectId, CrsProfileRevisionId = native.CrsProfileRevisionId, RouteSystemId = stored.RouteSystemId!.Value, RouteKind = stored.RouteKind!, ParentRouteVersionId = stored.ParentRouteVersionId, JunctionOffsetMeters = stored.JunctionOffsetMeters, CanonicalLengthMeters = prepared.LengthMeters, DeclaredLengthMeters = stored.DeclaredLengthMeters, CalibrationJson = stored.ChainageCalibration is null ? null : JsonSerializer.Serialize(stored.ChainageCalibration), SampleOnly = prepared.SampleOnly });
            }
            db.Add(version); draft.Confirm(section.Id);
            db.Add(RoadGeometryMetadata.Create(version.Id, draft.Id, JsonSerializer.Serialize(stored), Hash(new { srid, coordinates = stored.Coordinates, stored.NativeAlignment, stored.WidthProfile, stored.StationOriginMeters, stored.SurveyWidthMeters }), c.ActorId, prepared.Wgs84Centerline is null ? null : JsonSerializer.Serialize(prepared.Wgs84Centerline), clock.GetUtcNow()));
            if (current is not null)
            {
                var refs = new List<GeometryAffectedReferenceFact>();
                var field = await db.FieldInspectionTasks.AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.RoadSectionVersionId == current.Id).Select(x => new { x.Id, x.SegmentSetId }).ToArrayAsync(ct);
                refs.AddRange(field.Select(x => new GeometryAffectedReferenceFact("FIELD_TASK", x.Id, current.Id, x.SegmentSetId,
                    x.SegmentSetId.HasValue ? "PINNED_REFERENCE" : "INCOMPLETE", x.SegmentSetId.HasValue ? [] : ["LEGACY_SEGMENT_SET_UNPINNED"])));
                var surveys = await (from scope in db.SurveyRequestScopes.AsNoTracking() join task in db.SurveyRequests.AsNoTracking() on scope.SurveyRequestId equals task.Id where task.ProjectId == c.ProjectId && scope.RouteSectionVersionId == current.Id select new { task.Id, scope.SegmentSetId }).Distinct().ToArrayAsync(ct);
                refs.AddRange(surveys.Select(x => new GeometryAffectedReferenceFact("SURVEY_TASK", x.Id, current.Id, x.SegmentSetId, "READY", [])));
                var defects = await db.Defects.AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.RoadSectionVersionId == current.Id).Select(x => x.Id).ToArrayAsync(ct);
                refs.AddRange(defects.Select(x => new GeometryAffectedReferenceFact("DEFECT", x, current.Id, null, "INCOMPLETE", ["SEGMENT_SET_NOT_PINNED"])));
                var layouts = await db.Set<PavementLayoutRevision>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.RouteVersionId == current.Id).Select(x => new { x.Id, x.SegmentSetId }).ToArrayAsync(ct);
                refs.AddRange(layouts.Select(x => new GeometryAffectedReferenceFact("LAYOUT", x.Id, current.Id, x.SegmentSetId, "PINNED_REFERENCE", [])));
                var maps = await db.Set<GeometryMapPublication>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.RouteVersionId == current.Id).Select(x => new { x.Id, x.SegmentSetId }).ToArrayAsync(ct);
                refs.AddRange(maps.Select(x => new GeometryAffectedReferenceFact("MAP", x.Id, current.Id, x.SegmentSetId, "PINNED_REFERENCE", [])));
                var branches = await db.Set<NativeRouteVersionFacts>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.ParentRouteVersionId == current.Id).Select(x => x.RoadSectionVersionId).ToArrayAsync(ct);
                refs.AddRange(branches.Select(x => new GeometryAffectedReferenceFact("BRANCH", x, current.Id, null, "PINNED_REFERENCE", [])));
                db.Add(new GeometryLocationImpact { Id = Guid.NewGuid(), ProjectId = c.ProjectId, PreviousRouteVersionId = current.Id, NewRouteVersionId = version.Id, AffectedReferencesJson = JsonSerializer.Serialize(refs.OrderBy(x => x.Kind, StringComparer.Ordinal).ThenBy(x => x.Id).ThenBy(x => x.SegmentSetId).ToArray()), RecordedBy = c.ActorId, RecordedAt = clock.GetUtcNow() });
            }
            await db.SaveChangesAsync(ct);
            var confirmed = await RouteView(c.ProjectId, section.Id, version, ct);
            return new(201, Value: confirmed, Version: Hash(confirmed));
        }
        var readGeometry = c.Action is "package" or "set-get" or "geometry-get";
        var routeQuery = readGeometry ? db.RoadSectionVersions.AsNoTracking() : db.RoadSectionVersions;
        var route = await routeQuery.SingleOrDefaultAsync(x => x.Id == c.RouteVersionId && (c.RoadSectionId == null || x.RoadSectionId == c.RoadSectionId), ct);
        if (route is null) Reject(404, "road_section_version_not_found");
        if (section is null) section = await db.RoadSections.SingleOrDefaultAsync(x => x.Id == route!.RoadSectionId && x.ProjectId == c.ProjectId, ct);
        if (section is null) Reject(404, "road_section_version_not_found");
        var view = await RouteView(c.ProjectId, section!.Id, route!, ct);
        if (c.Action == "geometry-get") return new(200, Value: view, Version: Hash(view));
        RoadSegmentSet? set = null;
        if (c.SetId is Guid setId) { var setQuery = readGeometry ? db.RoadSegmentSets.AsNoTracking() : db.RoadSegmentSets; set = await setQuery.SingleOrDefaultAsync(x => x.Id == setId && x.RoadSectionVersionId == route!.Id, ct); if (set is null) Reject(404, "segment_set_not_found"); }
        if (c.Action is "set-get" or "package")
        {
            var setView = await SetView(set!, ct);
            if (c.Action == "package")
            {
                var package = new GeometryPackageViewFact("anh01.geometry.v1", c.ProjectId, view, setView);
                return new(200, Value: package, Version: Hash(package));
            }
            return new(200, Value: setView, Version: setView.Version);
        }
        if (view.MetadataStatus != "COMPLETE") Reject(422, "geometry_metadata_incomplete");
        if (c.Action is "set-preview" or "set-create" or "set-edit")
        {
            var definition = (SegmentDefinitionFact)c.Input!;
            var metadata = await db.Set<RoadGeometryMetadata>().AsNoTracking().SingleAsync(x => x.RoadSectionVersionId == route!.Id, ct);
            var nativeInput = Decode<GeometryDraftInputFact>(metadata.InputJson);
            definition = definition with { NativeAlignment = nativeInput.NativeAlignment, TessellationToleranceMeters = nativeInput.TessellationToleranceMeters, ChainageCalibration = nativeInput.ChainageCalibration };
            var computed = segments(route!.Id, route.Geometry, view.StationOriginMeters!.Value, definition);
            if (c.Action == "set-preview") return new(200, Value: computed);
            if (set is null) { set = RoadSegmentSet.Create(Guid.NewGuid(), route.Id, "DRAFT"); db.Add(set); }
            else
            {
                Match(set.RowVersion, c.ExpectedVersion);
                if (set.Status != "DRAFT") Reject(409, "road_geometry_invalid_state");
                // A no-op must not replace referenced children without updating the parent's rowversion.
                if (set.DefinitionJson == JsonSerializer.Serialize(definition) && set.GeometryHash == computed.DefinitionHash)
                {
                    var unchanged = await SetView(set, ct);
                    return new(200, Value: unchanged, Version: unchanged.Version);
                }
                db.RoadSegments.RemoveRange(await db.RoadSegments.Where(x => x.SegmentSetId == set.Id).ToListAsync(ct));
                await db.SaveChangesAsync(ct);
            }
            set.Define(JsonSerializer.Serialize(definition), computed.DefinitionHash);
            var indexed = new LengthIndexedLine(route.Geometry);
            foreach (var part in computed.Segments)
            {
                var row = RoadSegment.Create(Guid.NewGuid(), set.Id, route.Id, part.Sequence);
                var geometry = definition.NativeAlignment is null ? (LineString)indexed.ExtractLine(part.FromOffsetMeters, part.ToOffsetMeters)
                    : new GeometryFactory(new PrecisionModel(), route.Geometry.SRID).CreateLineString(((double[][])part.MetricGeometry.Coordinates).Select(p => new Coordinate(p[0], p[1])).ToArray());
                row.SetGeometry(part.FromOffsetMeters, part.ToOffsetMeters, view.StationOriginMeters.Value, geometry, part.StartStationMeters, part.EndStationMeters); db.Add(row);
            }
            await db.SaveChangesAsync(ct); var result = await SetView(set, ct); return new(c.Action == "set-create" ? 201 : 200, Value: result, Version: result.Version);
        }
        Match(set!.RowVersion, c.ExpectedVersion); if (set.Status != "DRAFT") Reject(409, "road_geometry_invalid_state");
        if ((await SetView(set, ct)).MetadataStatus != "COMPLETE") Reject(422, "geometry_metadata_incomplete");
        var publication = (SegmentPublishInputFact)c.Input!;
        if (string.IsNullOrWhiteSpace(publication.Reason)) Reject(422, "segment_validation_failed");
        if (!route!.IsCurrent) Reject(409, "road_section_concurrency_conflict");
        var previous = await db.RoadSegmentSets.SingleOrDefaultAsync(x => x.RoadSectionVersionId == route.Id && x.Status == "PUBLISHED", ct);
        if (previous?.Id != publication.ExpectedPublishedSetId) Reject(409, "segment_publication_conflict");
        if (previous is not null) { previous.Supersede(); await db.SaveChangesAsync(ct); }
        set.Publish(c.ActorId, clock.GetUtcNow()); await db.SaveChangesAsync(ct); var published = await SetView(set, ct); return new(200, Value: published, Version: published.Version);
    }
    private static void Match(byte[] version, string? expected) { if (Version(version) != expected) Reject(412, "concurrency_conflict"); }
    private static GeometryDraftViewFact DraftView(RoadGeometryDraft d) { var i = Decode<GeometryDraftInputFact>(d.InputJson); return new(d.Id, d.ProjectId, d.RoadSectionId, d.RoadCode, d.RoadName, d.Status, i.SourceKind, i.SourceCrs, i.SourceFileId, d.SourceChecksum, i.TrackIndex, i.TrackSegmentIndex, Decode<GeometryPointFact[]?>(d.OriginalCoordinatesJson) ?? [], i.Coordinates ?? [], i.StationOriginMeters, i.WidthProfile, i.SurveyWidthMeters, d.CreatedBy, d.UpdatedBy, Version(d.RowVersion), i.NativeAlignment); }
    private static GeometryShapeFact Shape(LineString line) => new("LineString", line.Coordinates.Select(p => new[] { p.X, p.Y }).ToArray());
    private async Task<RoadGeometryVersionViewFact> RouteView(Guid project, Guid section, RoadSectionVersion route, CancellationToken ct)
    {
        var m = await db.Set<RoadGeometryMetadata>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == route.Id, ct); var i = m is null ? null : Decode<GeometryDraftInputFact>(m.InputJson);
        var facts = await db.Set<NativeRouteVersionFacts>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == route.Id, ct);
        var profile = facts is null ? null : await db.Set<CrsProfileRevision>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == facts.CrsProfileRevisionId, ct);
        return new(project, section, route.Id, route.VersionNo, route.IsCurrent, route.EffectiveFrom, m?.SourceDraftId, i?.SourceCrs, route.Geometry.SRID, i?.StationOriginMeters, i?.WidthProfile, i?.SurveyWidthMeters, Shape(route.Geometry), m?.Wgs84GeometryJson is null ? null : Decode<GeometryShapeFact>(m.Wgs84GeometryJson), facts?.CanonicalLengthMeters ?? route.Geometry.Length, m is null ? "LEGACY_INCOMPLETE" : "COMPLETE", m?.ApprovedBy, m?.ApprovedAt, m?.GeometryHash ?? Hash(route.Geometry.AsText()), facts?.CrsProfileRevisionId, facts?.RouteSystemId, facts?.RouteKind, facts?.ParentRouteVersionId, facts?.JunctionOffsetMeters, facts?.DeclaredLengthMeters, i?.ChainageCalibration, profile?.Status, profile?.SampleOnly ?? false);
    }
    private static CrsProfileViewFact ProfileView(CrsProfileRevision profile) => new(profile.Id, profile.ProjectId, profile.Code, profile.Revision, profile.Status, Decode<CrsProfileInputFact>(profile.PayloadJson), profile.CreatedBy, profile.CreatedAt);
    private async Task<GeometryDraftInputFact> ResolveNativeInputAsync(GeometryDraftInputFact input, Guid project, CancellationToken ct)
    {
        // Never trust a client-supplied profile snapshot; pin the immutable project-owned revision.
        input = input with { ResolvedCrsProfile = null };
        if (input.NativeAlignment is null) return input;
        var profile = await db.Set<CrsProfileRevision>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == input.NativeAlignment.CrsProfileRevisionId && x.ProjectId == project, ct);
        if (profile is null) Reject(422, "crs_profile_scope_mismatch");
        if (profile!.SourceSrid != input.SourceCrs || input.NativeAlignment.SpatialSrid != profile.SourceSrid) Reject(422, "crs_profile_srid_mismatch");
        return input with { ResolvedCrsProfile = Decode<CrsProfileInputFact>(profile.PayloadJson) };
    }
    private static string[] NativeMissing(GeometryDraftInputFact input)
    {
        var missing = new List<string>();
        if (input.NativeAlignment is null) missing.Add("nativeAlignment");
        if (input.ResolvedCrsProfile is null) missing.Add("crsProfileRevision");
        if (input.RouteSystemId is null || input.RouteSystemId == Guid.Empty) missing.Add("routeSystemId");
        if (input.RouteKind is not ("MAIN" or "BRANCH")) missing.Add("routeKind");
        if (input.WidthProfile is null || input.WidthProfile.Length == 0 || input.SurveyWidthMeters <= 0) missing.Add("widthProfile");
        if (input.TessellationToleranceMeters is null) missing.Add("tessellationToleranceMeters");
        return missing.ToArray();
    }
    private async Task ValidateTopologyAsync(GeometryDraftInputFact input, Guid project, Guid? section, GeometryPreviewFact child,
        Func<GeometryDraftInputFact, int, GeometryPreviewFact> preview, Func<Guid, LineString, double, SegmentDefinitionFact, SegmentPreviewFact> segments, CancellationToken ct)
    {
        if (!await db.Set<RoadRouteSystem>().AnyAsync(x => x.Id == input.RouteSystemId && x.ProjectId == project, ct)) Reject(422, "route_system_scope_mismatch");
        if (input.RouteKind == "MAIN") { if (input.ParentRouteVersionId is not null || input.JunctionOffsetMeters is not null) Reject(422, "route_topology_invalid"); return; }
        var junction = input.JunctionOffsetMeters ?? double.NaN;
        if (input.RouteKind != "BRANCH" || input.ParentRouteVersionId is null || !double.IsFinite(junction)) Reject(422, "route_topology_invalid");
        var parent = await db.RoadSectionVersions.AsNoTracking().SingleOrDefaultAsync(x => x.Id == input.ParentRouteVersionId, ct);
        var parentFacts = parent is null ? null : await db.Set<NativeRouteVersionFacts>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == parent.Id, ct);
        if (parent is null || parentFacts is null || parentFacts.ProjectId != project || parentFacts.RouteSystemId != input.RouteSystemId || parentFacts.CrsProfileRevisionId != input.NativeAlignment!.CrsProfileRevisionId || !parent.IsCurrent || junction < 0 || junction > parentFacts.CanonicalLengthMeters) Reject(422, "branch_parent_or_junction_invalid");
        var seen = new HashSet<Guid>(); var seenRoads = new HashSet<Guid>();
        if (section is Guid childSection) seenRoads.Add(childSection);
        var ancestor = parent;
        while (ancestor is not null)
        {
            if (seen.Count >= 100000 || !seen.Add(ancestor.Id) || !seenRoads.Add(ancestor.RoadSectionId)) Reject(422, "route_topology_cycle");
            var facts = await db.Set<NativeRouteVersionFacts>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == ancestor.Id, ct);
            ancestor = facts?.ParentRouteVersionId is Guid next ? await db.RoadSectionVersions.AsNoTracking().SingleOrDefaultAsync(x => x.Id == next, ct) : null;
        }
        var metadata = await db.Set<RoadGeometryMetadata>().AsNoTracking().SingleAsync(x => x.RoadSectionVersionId == parent!.Id, ct);
        var parentInput = Decode<GeometryDraftInputFact>(metadata.InputJson);
        var boundaries = junction == 0 || junction == parentFacts!.CanonicalLengthMeters ? new[] { 0d, parentFacts.CanonicalLengthMeters } : new[] { 0d, junction, parentFacts.CanonicalLengthMeters };
        var computed = segments(parent.Id, parent.Geometry, parentInput.StationOriginMeters, new(100, "KEEP", boundaries, parentInput.NativeAlignment, parentInput.TessellationToleranceMeters, parentInput.ChainageCalibration));
        var point = junction == parentFacts.CanonicalLengthMeters ? ((double[][])computed.Segments[^1].MetricGeometry.Coordinates)[^1]
            : ((double[][])computed.Segments[junction == 0 ? 0 : 1].MetricGeometry.Coordinates)[0];
        var start = ((double[][])child.MetricCenterline.Coordinates)[0];
        if (Math.Abs(point[0] - start[0]) > 1e-9 * Math.Max(1, Math.Abs(point[0])) || Math.Abs(point[1] - start[1]) > 1e-9 * Math.Max(1, Math.Abs(point[1]))) Reject(422, "branch_junction_mismatch");
    }
    private async Task GuardAsync(GeometryWorkflowCommand c, bool locked, CancellationToken ct)
    {
        if (locked) await Anh02ReceiptAuthority.LockAsync(db, c.ActorId, c.ProjectId, ct);
        var user = await db.Users.AsNoTracking().SingleOrDefaultAsync(x => x.Id == c.ActorId, ct);
        if (user is null || user.Status != UserStatus.Active || user.MustChangePassword || (c.Role is not null && c.Role != user.RoleCode) || !await db.Roles.AsNoTracking().AnyAsync(x => x.Code == user.RoleCode && x.IsActive, ct)) Reject(403, "access_forbidden");
        var read = c.Action is "draft-get" or "draft-readiness" or "draft-preview" or "geometry-get" or "set-get" or "set-preview" or "package" or "profile-get" or "profile-list" or "system-list";
        if (c.Action == "confirm" ? user.RoleCode != UserRoleCode.Supervisor : !read ? user.RoleCode != UserRoleCode.ProjectManager : user.RoleCode is not (UserRoleCode.ProjectManager or UserRoleCode.Supervisor or UserRoleCode.DroneOperator)) Reject(403, "access_forbidden");
        if (user.RoleCode != UserRoleCode.Supervisor)
        {
            var today = DateOnly.FromDateTime(clock.GetUtcNow().UtcDateTime);
            if (!await db.ProjectMembers.AsNoTracking().AnyAsync(x => x.ProjectId == c.ProjectId && x.UserId == c.ActorId && x.RoleCode == user.RoleCode && x.Status == ProjectMemberStatus.Active && x.ValidFrom <= today && (x.ValidTo == null || x.ValidTo >= today), ct)) Reject(403, "access_forbidden");
        }
        if (user.RoleCode == UserRoleCode.DroneOperator && (c.Action != "package" || c.RouteVersionId is not Guid route || c.SetId is not Guid set || !await CanReadAssignedGeometryAsync(c.ActorId, c.ProjectId, route, set, ct))) Reject(403, "access_forbidden");
        if (c.RoadSectionId is Guid section && !await db.RoadSections.AsNoTracking().AnyAsync(x => x.Id == section && x.ProjectId == c.ProjectId, ct)) Reject(404, "road_section_not_found");
        if (c.DraftId is Guid draft && !c.Action.StartsWith("profile", StringComparison.Ordinal) && !await db.Set<RoadGeometryDraft>().AsNoTracking().AnyAsync(x => x.Id == draft && x.ProjectId == c.ProjectId && (c.RoadSectionId == null || x.RoadSectionId == c.RoadSectionId), ct)) Reject(404, "road_geometry_draft_not_found");
        if (c.RouteVersionId is Guid version && !await (from v in db.RoadSectionVersions.AsNoTracking() join s in db.RoadSections.AsNoTracking() on v.RoadSectionId equals s.Id where v.Id == version && s.ProjectId == c.ProjectId && (c.RoadSectionId == null || v.RoadSectionId == c.RoadSectionId) select v.Id).AnyAsync(ct)) Reject(404, "road_section_version_not_found");
        if (c.SetId is Guid setId && !await db.RoadSegmentSets.AsNoTracking().AnyAsync(x => x.Id == setId && x.RoadSectionVersionId == c.RouteVersionId, ct)) Reject(404, "segment_set_not_found");
    }
    private async Task<SegmentSetViewFact> SetView(RoadSegmentSet set, CancellationToken ct)
    {
        var rows = await db.RoadSegments.AsNoTracking().Where(x => x.SegmentSetId == set.Id).OrderBy(x => x.Sequence).ToListAsync(ct);
        var parts = rows.Select(x =>
        {
            var missing = new List<string>();
            if (x.FromOffsetMeters is null) missing.Add("fromOffsetMeters");
            if (x.ToOffsetMeters is null) missing.Add("toOffsetMeters");
            if (x.StartStationMeters is null) missing.Add("startStationMeters");
            if (x.EndStationMeters is null) missing.Add("endStationMeters");
            if (x.Geometry is null) missing.Add("metricGeometry");
            return new SegmentGeometryViewFact(x.Id, x.Sequence, x.FromOffsetMeters, x.ToOffsetMeters, x.StartStationMeters, x.EndStationMeters,
                x.ToOffsetMeters - x.FromOffsetMeters, x.Geometry is null ? null : Shape(x.Geometry), null, missing.ToArray());
        }).ToArray();
        var setMissing = new List<string>();
        if (set.DefinitionJson is null) setMissing.Add("definition");
        if (set.GeometryHash is null) setMissing.Add("geometryHash");
        if (parts.Length == 0) setMissing.Add("segments");
        if (parts.Any(x => x.MissingMetadata.Length > 0)) setMissing.Add("segments.metadata");
        return new(set.Id, set.RoadSectionVersionId, set.Status, set.DefinitionJson is null ? null : Decode<SegmentDefinitionFact>(set.DefinitionJson), set.GeometryHash,
            parts, set.PublishedBy, set.PublishedAt, Version(set.RowVersion), setMissing.Count == 0 ? "COMPLETE" : "LEGACY_INCOMPLETE", setMissing.ToArray());
    }
}

using System.Security.Cryptography;
using System.Text.Json;
using NetTopologySuite.Geometries;
using NetTopologySuite.LinearReferencing;
using NetTopologySuite.Operation.Union;
using RoadGuardSystem.DTOs.Projects;
namespace RoadGuardSystem.Services.Projects;

public sealed class GeometryValidationException(string code, string detail) : Exception(detail) { public string Code { get; } = code; }
public static class GeometryEngine
{
    public static LineString Line(GeometryPoint[] points, int srid)
    {
        if (points.Length < 2 || points.Length > 100000 || points.Any(p => p is null || !double.IsFinite(p.X) || !double.IsFinite(p.Y))) Fail("geometry_validation_failed", "A finite line with at least two points is required.");
        var line = new GeometryFactory(new PrecisionModel(), srid).CreateLineString(points.Select(p => new Coordinate(p.X, p.Y)).ToArray());
        if (!line.IsSimple || !line.IsValid || line.Length <= 0 || line.Coordinates.Zip(line.Coordinates.Skip(1)).Any(p => p.First.Equals2D(p.Second))) Fail("geometry_validation_failed", "Line must be simple and have positive length without duplicate adjacent vertices.");
        return line;
    }
    public static GeometryPreview Preview(GeometryDraftInput input, int engineeringSrid)
    {
        if (input.SourceKind == "NATIVE_ALIGNMENT") return NativePreview(input);
        if (engineeringSrid is not (32648 or 32649) || input.SourceCrs != engineeringSrid) Fail("unsupported_crs", "A verified CRS transform adapter is required for this source CRS.");
        if (input.SourceKind != "COORDINATES" || input.Coordinates is null || input.SourceFileId is not null || input.TrackIndex is not null || input.TrackSegmentIndex is not null) Fail("geometry_validation_failed", "Coordinates source requires coordinates and no GPX reference.");
        var line = Line(input.Coordinates!, engineeringSrid);
        if (!double.IsFinite(input.StationOriginMeters) || !double.IsFinite(input.StationOriginMeters + line.Length) || string.IsNullOrWhiteSpace(input.ChangeReason) || !double.IsFinite(input.SurveyWidthMeters) || input.SurveyWidthMeters <= 0 || input.WidthProfile is null || input.WidthProfile.Length == 0 || input.WidthProfile.Any(w => w is null)) Fail("geometry_validation_failed", "Station, change reason and a complete width profile are required.");
        double end = 0;
        var pieces = new List<Geometry>(); var indexed = new LengthIndexedLine(line);
        foreach (var width in input.WidthProfile!)
        {
            if (!double.IsFinite(width.FromOffsetMeters) || !double.IsFinite(width.ToOffsetMeters) || !double.IsFinite(width.WidthMeters) || width.WidthMeters <= 0 || width.WidthMeters > input.SurveyWidthMeters || width.FromOffsetMeters != end || width.ToOffsetMeters <= end || width.ToOffsetMeters > line.Length) Fail("geometry_validation_failed", "Width profile must cover the line without gaps or overlaps, inside the survey width.");
            pieces.Add(indexed.ExtractLine(width.FromOffsetMeters, width.ToOffsetMeters).Buffer(width.WidthMeters / 2)); end = width.ToOffsetMeters;
        }
        if (Math.Abs(end - line.Length) > 1e-7) Fail("geometry_validation_failed", "Width profile must end at the line length.");
        return new(input.SourceCrs, engineeringSrid, line.Length, Shape(line), null, Shape(UnaryUnionOp.Union(pieces)), Shape(line.Buffer(input.SurveyWidthMeters / 2)), ["WGS84_TRANSFORM_NOT_CONFIGURED"]);
    }
    public static SegmentPreview Segments(Guid routeId, LineString line, double origin, SegmentDefinition definition)
    {
        if (definition.NativeAlignment is not null) return NativeSegments(routeId, origin, definition);
        if (!double.IsFinite(definition.TargetLengthMeters) || definition.TargetLengthMeters <= 0 || definition.RemainderMode is not ("KEEP" or "MERGE_PREVIOUS")) Fail("segment_validation_failed", "Target length and remainder mode are invalid.");
        var bounds = definition.BoundariesMeters?.ToList() ?? [0];
        if (definition.BoundariesMeters is null)
        {
            if (line.Length / definition.TargetLengthMeters > 100000) Fail("segment_validation_failed", "Too many segments.");
            for (var offset = definition.TargetLengthMeters; offset < line.Length; offset += definition.TargetLengthMeters) bounds.Add(offset);
            if (definition.RemainderMode == "MERGE_PREVIOUS" && bounds.Count > 1 && line.Length % definition.TargetLengthMeters != 0) bounds.RemoveAt(bounds.Count - 1);
            bounds.Add(line.Length);
        }
        if (bounds.Count < 2 || bounds.Count > 100001 || bounds[0] != 0 || Math.Abs(bounds[^1] - line.Length) > 1e-7 || bounds.Any(x => !double.IsFinite(x)) || bounds.Zip(bounds.Skip(1)).Any(x => x.Second <= x.First)) Fail("segment_validation_failed", "Boundaries must increase strictly from zero to line length.");
        var indexed = new LengthIndexedLine(line);
        var segments = bounds.Zip(bounds.Skip(1)).Select((p, index) => new SegmentGeometry(null, index + 1, p.First, p.Second, origin + p.First, origin + p.Second, p.Second - p.First, Shape(indexed.ExtractLine(p.First, p.Second)), null)).ToArray();
        return new(routeId, line.Length, bounds.ToArray(), segments, Hash(new { routeId, definition, boundaries = bounds }));
    }
    private static GeometryPreview NativePreview(GeometryDraftInput input)
    {
        var readiness = CrsProfileEngine.Readiness(input, input.ResolvedCrsProfile);
        if (!readiness.Ready) Fail("geometry_metadata_incomplete", "Native draft is not ready: " + string.Join(',', readiness.MissingFields.Concat(readiness.Errors)));
        if (input.Coordinates is not null || input.SourceFileId is not null || input.TrackIndex is not null || input.TrackSegmentIndex is not null) Fail("native_alignment_invalid", "Native analytic input cannot mix legacy coordinates/GPX references.");
        var alignment = NativeAlignment.Create(input.NativeAlignment!);
        var line = alignment.Extract(0, alignment.Length, input.TessellationToleranceMeters!.Value);
        if (!line.IsSimple || !line.IsValid) Fail("native_alignment_invalid", "Alignment rendering must be simple.");
        var pieces = new List<Geometry>(); double end = 0;
        foreach (var width in input.WidthProfile)
        {
            if (width is null || !double.IsFinite(width.FromOffsetMeters) || !double.IsFinite(width.ToOffsetMeters) || !double.IsFinite(width.WidthMeters) || width.WidthMeters <= 0 || width.WidthMeters > input.SurveyWidthMeters || width.FromOffsetMeters != end || width.ToOffsetMeters <= end || width.ToOffsetMeters > alignment.Length) Fail("geometry_validation_failed", "Width profile must cover analytic length without gaps/overlaps.");
            if (alignment.ArcRanges.Any(a => a.FromOffsetMeters < width.ToOffsetMeters && a.ToOffsetMeters > width.FromOffsetMeters && a.Radius <= input.SurveyWidthMeters / 2)) Fail("geometry_validation_failed", "Offset reaches or crosses an arc centre.");
            pieces.Add(alignment.Extract(width.FromOffsetMeters, width.ToOffsetMeters, input.TessellationToleranceMeters.Value).Buffer(width.WidthMeters / 2)); end = width.ToOffsetMeters;
        }
        if (Math.Abs(end - alignment.Length) > 1e-9 * Math.Max(1, alignment.Length)) Fail("geometry_validation_failed", "Width profile must end at canonical analytic length.");
        GeometryShape? wgs = null;
        var transformed = new List<double[]>();
        foreach (var coordinate in line.Coordinates)
        {
            if (!CrsProfileEngine.TryTransformCanonical(new(coordinate.X, coordinate.Y), input.ResolvedCrsProfile!, out var point)) { transformed.Clear(); break; }
            transformed.Add([point!.X, point.Y]);
        }
        if (transformed.Count > 0) wgs = new("LineString", transformed.ToArray());
        return new(input.SourceCrs, line.SRID, alignment.Length, Shape(line), wgs, Shape(UnaryUnionOp.Union(pieces)), Shape(line.Buffer(input.SurveyWidthMeters / 2)), readiness.Warnings,
            input.NativeAlignment!.CrsProfileRevisionId, input.ResolvedCrsProfile!.SampleOnly);
    }
    private static SegmentPreview NativeSegments(Guid routeId, double origin, SegmentDefinition definition)
    {
        var alignment = NativeAlignment.Create(definition.NativeAlignment!);
        var tolerance = definition.TessellationToleranceMeters ?? 0;
        if (!double.IsFinite(tolerance) || tolerance <= 0) Fail("segment_validation_failed", "Native segments require a rendering tolerance.");
        if (!double.IsFinite(definition.TargetLengthMeters) || definition.TargetLengthMeters <= 0 || definition.RemainderMode is not ("KEEP" or "MERGE_PREVIOUS")) Fail("segment_validation_failed", "Target length/remainder mode is invalid.");
        var bounds = definition.BoundariesMeters?.ToList() ?? [0];
        if (definition.BoundariesMeters is null)
        {
            if (alignment.Length / definition.TargetLengthMeters > 100000) Fail("segment_validation_failed", "Too many segments.");
            for (var offset = definition.TargetLengthMeters; offset < alignment.Length; offset += definition.TargetLengthMeters) bounds.Add(offset);
            if (definition.RemainderMode == "MERGE_PREVIOUS" && bounds.Count > 1 && alignment.Length % definition.TargetLengthMeters != 0) bounds.RemoveAt(bounds.Count - 1);
            bounds.Add(alignment.Length);
        }
        if (bounds.Count is < 2 or > 100001 || bounds[0] != 0 || bounds[^1] != alignment.Length || bounds.Any(x => !double.IsFinite(x)) || bounds.Zip(bounds.Skip(1)).Any(p => p.Second <= p.First)) Fail("segment_validation_failed", "Boundaries must strictly cover analytic length.");
        var parts = bounds.Zip(bounds.Skip(1)).Select((p, index) => new SegmentGeometry(null, index + 1, p.First, p.Second,
            CrsProfileEngine.StationAt(p.First, origin, definition.ChainageCalibration, alignment.Length), CrsProfileEngine.StationAt(p.Second, origin, definition.ChainageCalibration, alignment.Length),
            p.Second - p.First, Shape(alignment.Extract(p.First, p.Second, tolerance)), null)).ToArray();
        return new(routeId, alignment.Length, bounds.ToArray(), parts, Hash(new { routeId, definition, boundaries = bounds }));
    }
    public static string Hash(object value) => Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(value))).ToLowerInvariant();
    public static GeometryShape Shape(Geometry geometry) => geometry switch
    {
        LineString l => new("LineString", l.Coordinates.Select(c => new[] { c.X, c.Y }).ToArray()),
        Polygon p => new("Polygon", new[] { p.ExteriorRing.Coordinates.Select(c => new[] { c.X, c.Y }).ToArray() }.Concat(Enumerable.Range(0, p.NumInteriorRings).Select(i => p.GetInteriorRingN(i).Coordinates.Select(c => new[] { c.X, c.Y }).ToArray())).ToArray()),
        MultiPolygon m => new("MultiPolygon", Enumerable.Range(0, m.NumGeometries).Select(i => Shape(m.GetGeometryN(i)).Coordinates).ToArray()),
        _ => throw new GeometryValidationException("geometry_validation_failed", "Unsupported geometry output.")
    };
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Fail(string code, string detail) => throw new GeometryValidationException(code, detail);
}

using RoadGuardSystem.DTOs.Projects;
namespace RoadGuardSystem.Services.Projects;

public static class CrsProfileEngine
{
    public static void Validate(CrsProfileInput profile)
    {
        if (string.IsNullOrWhiteSpace(profile.Code) || profile.Code.Length > 80 || profile.SourceSrid < 0 || string.IsNullOrWhiteSpace(profile.Datum) || string.IsNullOrWhiteSpace(profile.Projection) || profile.AxisOrder is not ("EN" or "NE") || !double.IsFinite(profile.MetresPerUnit) || profile.MetresPerUnit <= 0 || string.IsNullOrWhiteSpace(profile.SourceReference) || !Hash(profile.SourceChecksum)) Fail("Profile definition and provenance must be explicit.");
        if (profile.Operation is { } operation)
        {
            if (string.IsNullOrWhiteSpace(operation.Method) || string.IsNullOrWhiteSpace(operation.Convention) || operation.Direction != "NATIVE_TO_WGS84" || string.IsNullOrWhiteSpace(operation.SourceReference) || operation.Parameters is null || operation.Parameters.Any(x => !double.IsFinite(x))) Fail("Operation identity, direction, parameters and source must be explicit.");
            if (operation.Method == "SAMPLE_AFFINE_TO_WGS84" && (!profile.SampleOnly || operation.Parameters.Length != 6)) Fail("Sample affine operation cannot be used for official real data.");
            if (operation.PublishedAccuracyMeters is { } accuracy && (!double.IsFinite(accuracy) || accuracy <= 0 || string.IsNullOrWhiteSpace(operation.AccuracySource))) Fail("Operation accuracy requires a source.");
        }
        if (profile.Ellipsoid is { } ellipsoid && (!double.IsFinite(ellipsoid.SemiMajorAxisMeters) || ellipsoid.SemiMajorAxisMeters <= 0 || !double.IsFinite(ellipsoid.InverseFlattening) || ellipsoid.InverseFlattening <= 1 || string.IsNullOrWhiteSpace(ellipsoid.SourceReference))) Fail("Ellipsoid parameters require a source.");
        if (profile.ProjectionDefinition is { } projection && (projection.Parameters is null || projection.Parameters.Count == 0 || projection.Parameters.Any(x => string.IsNullOrWhiteSpace(x.Key) || !double.IsFinite(x.Value)) || string.IsNullOrWhiteSpace(projection.SourceReference))) Fail("Projection parameters require a source.");
        if (profile.SourcedToleranceMeters is { } tolerance && (!double.IsFinite(tolerance) || tolerance <= 0 || string.IsNullOrWhiteSpace(profile.ToleranceSource))) Fail("Accuracy tolerance requires a source.");
        if (profile.IndependentControls?.Any(c => c is null || !Finite(c.Native) || !Finite(c.Wgs84) || string.IsNullOrWhiteSpace(c.IndependentSource)) == true) Fail("Controls require independent provenance and finite coordinates.");
    }
    public static GeometryPoint NormalizeSource(GeometryPoint point, CrsProfileInput profile)
    {
        Validate(profile); if (!Finite(point)) Fail("Source coordinate is not finite.");
        var normalized = profile.AxisOrder == "EN" ? new GeometryPoint(point.X * profile.MetresPerUnit, point.Y * profile.MetresPerUnit) : new GeometryPoint(point.Y * profile.MetresPerUnit, point.X * profile.MetresPerUnit);
        if (!Finite(normalized)) Fail("Source normalization overflowed.");
        return normalized;
    }
    // Executable synthetic adapter only. Other pinned operation identities require an actual verified adapter;
    // no projection/datum parameters or controls are inferred from a province, EPSG label or UTM number.
    public static bool TryTransformCanonical(GeometryPoint point, CrsProfileInput profile, out GeometryPoint? wgs84)
    {
        Validate(profile); wgs84 = null;
        if (!Finite(point) || !profile.SampleOnly || profile.Operation?.Method != "SAMPLE_AFFINE_TO_WGS84") return false;
        var a = profile.Operation.Parameters;
        var candidate = new GeometryPoint(a[0] * point.X + a[1] * point.Y + a[2], a[3] * point.X + a[4] * point.Y + a[5]);
        if (!Finite(candidate) || candidate.X is < -180 or > 180 || candidate.Y is < -90 or > 90) Fail("Configured sample operation is outside WGS84 coordinate bounds.");
        wgs84 = candidate; return true;
    }
    public static GeometryDraftReadiness Readiness(GeometryDraftInput input, CrsProfileInput? profile)
    {
        var missing = new List<string>(); var errors = new List<string>();
        if (!double.IsFinite(input.StationOriginMeters) || !double.IsFinite(input.SurveyWidthMeters)) errors.Add("native_numeric_value_invalid");
        if (input.WidthProfile?.Any(x => x is null || !double.IsFinite(x.FromOffsetMeters) || !double.IsFinite(x.ToOffsetMeters) || !double.IsFinite(x.WidthMeters)) == true) errors.Add("native_width_invalid");
        if (input.NativeAlignment is null) missing.Add("nativeAlignment");
        if (profile is null) missing.Add("crsProfileRevision");
        if (input.RouteSystemId is null || input.RouteSystemId == Guid.Empty) missing.Add("routeSystemId");
        if (input.RouteKind is not ("MAIN" or "BRANCH")) missing.Add("routeKind");
        if (input.WidthProfile is null || input.WidthProfile.Length == 0 || input.SurveyWidthMeters <= 0) missing.Add("widthProfile");
        if (input.TessellationToleranceMeters is null) missing.Add("tessellationToleranceMeters");
        if (string.IsNullOrWhiteSpace(input.ChangeReason)) missing.Add("changeReason");
        if (input.RouteKind == "BRANCH" && (input.ParentRouteVersionId is null || input.JunctionOffsetMeters is null)) missing.Add("branchJunction");
        if (input.RouteKind == "MAIN" && (input.ParentRouteVersionId is not null || input.JunctionOffsetMeters is not null)) errors.Add("main_route_cannot_have_parent");
        if (input.DeclaredLengthMeters is { } declared && (!double.IsFinite(declared) || declared <= 0)) errors.Add("declared_length_invalid");
        try
        {
            if (profile is not null) Validate(profile);
            if (input.NativeAlignment is not null)
            {
                var alignment = NativeAlignment.Create(input.NativeAlignment);
                if (!double.IsFinite(input.StationOriginMeters + alignment.Length)) Fail("Station range overflowed.");
                if (input.WidthProfile is { Length: > 0 })
                {
                    double end = 0;
                    foreach (var width in input.WidthProfile)
                    {
                        if (width is null || !double.IsFinite(width.FromOffsetMeters) || !double.IsFinite(width.ToOffsetMeters) || !double.IsFinite(width.WidthMeters) || width.FromOffsetMeters != end || width.ToOffsetMeters <= end || width.ToOffsetMeters > alignment.Length || width.WidthMeters <= 0 || width.WidthMeters > input.SurveyWidthMeters) Fail("Width intervals must cover canonical length inside survey width.");
                        end = width.ToOffsetMeters;
                    }
                    if (Math.Abs(end - alignment.Length) > 1e-9 * Math.Max(1, alignment.Length)) Fail("Width intervals must cover canonical length.");
                }
                if (input.TessellationToleranceMeters is { } tolerance) alignment.Extract(0, alignment.Length, tolerance);
                ValidateCalibration(input.ChainageCalibration, alignment.Length);
            }
        }
        catch (GeometryValidationException exception) { errors.Add(exception.Code); }
        return new(missing.Count == 0 && errors.Count == 0, missing.ToArray(), errors.ToArray(), "CANDIDATE", profile?.SampleOnly ?? false,
            ["OFFICIAL_CRS_OPERATION_AND_INDEPENDENT_CONTROL_NOT_VERIFIED"]);
    }
    public static void ValidateCalibration(ChainageCalibrationInput? calibration, double length)
    {
        if (calibration is null) return;
        if (string.IsNullOrWhiteSpace(calibration.SourceReference) || !Hash(calibration.SourceChecksum) || string.IsNullOrWhiteSpace(calibration.SelectedReason) || calibration.Controls is null || calibration.Controls.Length < 2 || calibration.Controls.Any(c => c is null || !double.IsFinite(c.GeometricOffsetMeters) || !double.IsFinite(c.StationMeters)) || calibration.Controls[0].GeometricOffsetMeters != 0 || calibration.Controls[^1].GeometricOffsetMeters != length || calibration.Controls.Zip(calibration.Controls.Skip(1)).Any(p => p.Second.GeometricOffsetMeters <= p.First.GeometricOffsetMeters || p.Second.StationMeters <= p.First.StationMeters)) Fail("Chainage calibration must be sourced, PM-selected and monotonically cover the geometric alignment.");
    }
    public static double StationAt(double offset, double origin, ChainageCalibrationInput? calibration, double length)
    {
        ValidateCalibration(calibration, length);
        if (!double.IsFinite(offset) || offset < 0 || offset > length || !double.IsFinite(origin)) Fail("Chainage offset is invalid.");
        if (calibration is null)
        {
            var station = origin + offset;
            if (!double.IsFinite(station)) Fail("Station range overflowed.");
            return station;
        }
        var pair = calibration.Controls.Zip(calibration.Controls.Skip(1)).First(p => offset <= p.Second.GeometricOffsetMeters);
        var fraction = (offset - pair.First.GeometricOffsetMeters) / (pair.Second.GeometricOffsetMeters - pair.First.GeometricOffsetMeters);
        var result = (1 - fraction) * pair.First.StationMeters + fraction * pair.Second.StationMeters;
        if (!double.IsFinite(result)) Fail("Calibrated station overflowed.");
        return result;
    }
    private static bool Hash(string value) => value is { Length: 64 } && value.All(c => c is >= '0' and <= '9' or >= 'a' and <= 'f');
    private static bool Finite(GeometryPoint? point) => point is not null && double.IsFinite(point.X) && double.IsFinite(point.Y);
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Fail(string detail) => throw new GeometryValidationException("crs_profile_invalid", detail);
}

using NetTopologySuite.Geometries;
using RoadGuardSystem.DTOs.Projects;

namespace RoadGuardSystem.Services.Projects;

// Native projected E/N metres. Sampling is a rendering/query approximation, never the canonical length.
public sealed class NativeAlignment
{
    private readonly NativeAlignmentPrimitive[] primitives;
    private readonly double[] ends;
    private readonly int srid;
    public Guid CrsProfileRevisionId { get; }
    public bool IsLegacy { get; }
    public double Length => ends[^1];
    public IReadOnlyList<NativeArcRange> ArcRanges { get; } = [];
    public IReadOnlyList<double> PrimitiveBoundaries => new[] { 0d }.Concat(ends).ToArray();

    private NativeAlignment(NativeAlignmentInput input, bool legacy)
    {
        if ((!legacy && input.CrsProfileRevisionId == Guid.Empty) || input.SpatialSrid < 0 || input.Primitives is null || input.Primitives.Length is < 1 or > 100000)
            Fail("Profile and a bounded primitive sequence are required.");
        CrsProfileRevisionId = input.CrsProfileRevisionId; IsLegacy = legacy; srid = input.SpatialSrid;
        primitives = input.Primitives.ToArray(); ends = new double[primitives.Length];
        var arcs = new List<NativeArcRange>(); double offset = 0;
        for (var index = 0; index < primitives.Length; index++)
        {
            var p = primitives[index];
            if (p is null || !Finite(p.Start) || !Finite(p.End)) Fail("Finite native coordinates are required.");
            if (index > 0 && !Same(primitives[index - 1].End, p.Start)) Fail("Primitive sequence has a gap.");
            double length;
            if (p.Kind == "LINE")
            {
                if (p.Center is not null || p.Radius is not null || p.StartAngleRadians is not null || p.SweepRadians is not null) Fail("LINE cannot contain ARC parameters.");
                length = Distance(p.Start, p.End);
            }
            else if (p.Kind == "ARC")
            {
                if (!Finite(p.Center) || p.Radius is not double r || !double.IsFinite(r) || r <= 0 || p.StartAngleRadians is not double start || !double.IsFinite(start) || p.SweepRadians is not double sweep || !double.IsFinite(sweep) || sweep == 0 || Math.Abs(sweep) >= 2 * Math.PI)
                    Fail("ARC requires a positive radius and a finite signed sweep smaller than a full circle.");
                if (!Same(p.Start, ArcPoint(p, 0)) || !Same(p.End, ArcPoint(p, 1))) Fail("ARC endpoints disagree with its analytic parameters.");
                length = p.Radius!.Value * Math.Abs(p.SweepRadians!.Value);
                arcs.Add(new(offset, offset + length, p.Radius.Value));
            }
            else { Fail("Only LINE and ARC primitives are supported."); return; }
            if (!double.IsFinite(length) || length <= 0 || !double.IsFinite(offset + length)) Fail("Primitive length must be finite and positive.");
            offset += length; ends[index] = offset;
        }
        ArcRanges = arcs.AsReadOnly();
    }

    public static NativeAlignment Create(NativeAlignmentInput input) => new(input, false);
    public static NativeAlignment FromLegacy(LineString geometry)
    {
        ArgumentNullException.ThrowIfNull(geometry);
        return new(new(Guid.Empty, geometry.Coordinates.Zip(geometry.Coordinates.Skip(1))
            .Select(pair => new NativeAlignmentPrimitive("LINE", new(pair.First.X, pair.First.Y), new(pair.Second.X, pair.Second.Y))).ToArray(), geometry.SRID), true);
    }
    public GeometryPoint PointAt(double offset)
    {
        var (p, fraction) = Locate(offset);
        return p.Kind == "ARC" ? ArcPoint(p, fraction) : new(p.Start.X + fraction * (p.End.X - p.Start.X), p.Start.Y + fraction * (p.End.Y - p.Start.Y));
    }
    public GeometryPoint TangentAt(double offset)
    {
        var (p, fraction) = Locate(offset);
        if (p.Kind == "LINE") { var d = Distance(p.Start, p.End); return new((p.End.X - p.Start.X) / d, (p.End.Y - p.Start.Y) / d); }
        var angle = p.StartAngleRadians!.Value + fraction * p.SweepRadians!.Value;
        var direction = Math.Sign(p.SweepRadians.Value);
        return new(-direction * Math.Sin(angle), direction * Math.Cos(angle));
    }
    public LineString Extract(double from, double to, double tessellationTolerance)
    {
        ValidateOffset(from); ValidateOffset(to);
        if (to <= from || !double.IsFinite(tessellationTolerance) || tessellationTolerance <= 0) Fail("Ordered offsets and an explicit positive rendering tolerance are required.");
        var coordinates = new List<Coordinate>();
        for (var index = 0; index < primitives.Length; index++)
        {
            var begin = index == 0 ? 0 : ends[index - 1]; var end = ends[index];
            var lo = Math.Max(from, begin); var hi = Math.Min(to, end);
            if (hi <= lo) continue;
            var p = primitives[index]; int count = 1;
            if (p.Kind == "ARC")
            {
                var radius = p.Radius!.Value;
                var angleStep = 2 * Math.Acos(Math.Clamp(1 - tessellationTolerance / radius, -1, 1));
                if (angleStep <= 0) Fail("Rendering tolerance is below numeric resolution.");
                var required = Math.Ceiling((hi - lo) / radius / Math.Min(angleStep, Math.PI / 2));
                if (required > 100000) Fail("Rendering exceeds the feature vertex bound.");
                count = (int)Math.Max(1, required);
            }
            for (var step = 0; step <= count; step++)
            {
                var point = PointOn(index, lo + (hi - lo) * step / count);
                if (coordinates.Count == 0 || !coordinates[^1].Equals2D(new Coordinate(point.X, point.Y))) coordinates.Add(new(point.X, point.Y));
                if (coordinates.Count > 100001) Fail("Rendering exceeds the feature vertex bound.");
            }
        }
        return new GeometryFactory(new PrecisionModel(), srid).CreateLineString(coordinates.ToArray());
    }
    private GeometryPoint PointOn(int index, double offset)
    {
        var begin = index == 0 ? 0 : ends[index - 1]; var fraction = (offset - begin) / (ends[index] - begin); var p = primitives[index];
        return p.Kind == "ARC" ? ArcPoint(p, fraction) : new(p.Start.X + fraction * (p.End.X - p.Start.X), p.Start.Y + fraction * (p.End.Y - p.Start.Y));
    }
    private (NativeAlignmentPrimitive Primitive, double Fraction) Locate(double offset)
    {
        ValidateOffset(offset);
        var index = Array.FindIndex(ends, end => offset < end);
        if (index < 0) index = ends.Length - 1;
        var start = index == 0 ? 0 : ends[index - 1];
        return (primitives[index], (offset - start) / (ends[index] - start));
    }
    private void ValidateOffset(double offset) { if (!double.IsFinite(offset) || offset < 0 || offset > Length) Fail("Offset is outside the analytic alignment."); }
    private static GeometryPoint ArcPoint(NativeAlignmentPrimitive p, double fraction) => new(p.Center!.X + p.Radius!.Value * Math.Cos(p.StartAngleRadians!.Value + fraction * p.SweepRadians!.Value), p.Center.Y + p.Radius.Value * Math.Sin(p.StartAngleRadians.Value + fraction * p.SweepRadians.Value));
    private static bool Finite(GeometryPoint? p) => p is not null && double.IsFinite(p.X) && double.IsFinite(p.Y);
    private static double Distance(GeometryPoint a, GeometryPoint b) => Math.Sqrt(Math.Pow(a.X - b.X, 2) + Math.Pow(a.Y - b.Y, 2));
    // Floating-point consistency bound only; this does not represent survey accuracy or a CRS tolerance.
    private static bool Same(GeometryPoint a, GeometryPoint b) => Distance(a, b) <= 1e-10 * Math.Max(1, Math.Max(Math.Abs(a.X), Math.Max(Math.Abs(a.Y), Math.Max(Math.Abs(b.X), Math.Abs(b.Y)))));
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Fail(string detail) => throw new GeometryValidationException("native_alignment_invalid", detail);
}

using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.AspNetCore.Authentication.Cookies;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Identity;
using RoadGuardSystem.Services.Authentication;

namespace RoadGuardSystem.API.Authentication;

internal static class WebCookieConfiguration
{
    internal const string Scheme = "RoadGuardWeb";
    internal const string UserScheme = "RoadGuardUser";
    internal const string CookieName = "__Host-RoadGuardSession";
    internal const string RenewalCookieName = "__Host-RoadGuardRenewal";

    internal static string SelectScheme(HttpContext context)
    {
        if (context.Request.Headers.ContainsKey("Authorization"))
            return Microsoft.AspNetCore.Authentication.JwtBearer.JwtBearerDefaults.AuthenticationScheme;
        return IsCookieEligibleRequest(context) && context.Request.Cookies.ContainsKey(CookieName)
            ? Scheme
            : Microsoft.AspNetCore.Authentication.JwtBearer.JwtBearerDefaults.AuthenticationScheme;
    }

    internal static bool IsCookieEligibleRequest(HttpContext context) =>
        context.GetEndpoint()?.Metadata.GetMetadata<WebCookieEligibleAttribute>() is not null ||
        IsCookieEligibleRequest(context.Request.Method, context.Request.Path);

    internal static bool IsCookieEligibleRequest(string method, PathString requestPath)
    {
        var path = requestPath.Value ?? "";
        // Normalize one optional trailing slash, without admitting extra segments.
        if (path.EndsWith('/')) path = path[..^1];
        if (path.Equals("/api/v1/me/inspection-tasks", StringComparison.OrdinalIgnoreCase))
            return HttpMethods.IsGet(method);
        var parts = path.Split('/');
        if (parts.Length >= 4 && parts[0] == "" &&
            parts[1].Equals("api", StringComparison.OrdinalIgnoreCase) &&
            parts[2].Equals("v1", StringComparison.OrdinalIgnoreCase) &&
            parts[3].Equals("notifications", StringComparison.OrdinalIgnoreCase))
        {
            if (parts.Length == 4) return HttpMethods.IsGet(method);
            if (!Guid.TryParse(parts[4], out _)) return false;
            if (parts.Length == 5) return HttpMethods.IsGet(method);
            return parts.Length == 6 && parts[5].Equals("read", StringComparison.OrdinalIgnoreCase)
                && HttpMethods.IsPost(method);
        }
        return IsCookieEligiblePath(requestPath);
    }

    internal static bool IsCookieEligiblePath(PathString requestPath)
    {
        var path = requestPath.Value ?? "";
        return path.Equals("/api/v1/me", StringComparison.OrdinalIgnoreCase)
            || path.StartsWith("/api/v1/profile", StringComparison.OrdinalIgnoreCase)
            || path.Equals("/api/v1/auth/change-password", StringComparison.OrdinalIgnoreCase)
            || path.StartsWith("/api/v1/reports", StringComparison.OrdinalIgnoreCase)
            || path.StartsWith("/api/v1/cases", StringComparison.OrdinalIgnoreCase)
            || IsProjectDefectPath(path)
            || path.Contains("/candidate-decisions", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/candidates", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/labels", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsProjectDefectPath(string path)
    {
        var parts = path.TrimEnd('/').Split('/');
        if (parts.Length is < 6 or > 8 || parts[0] != "" ||
            !parts[1].Equals("api", StringComparison.OrdinalIgnoreCase) ||
            !parts[2].Equals("v1", StringComparison.OrdinalIgnoreCase) ||
            !parts[3].Equals("projects", StringComparison.OrdinalIgnoreCase) ||
            !Guid.TryParse(parts[4], out _) ||
            !parts[5].Equals("defects", StringComparison.OrdinalIgnoreCase)) return false;
        if (parts.Length == 6) return true;
        if (!Guid.TryParse(parts[6], out _)) return false;
        return parts.Length == 7 || parts[7].Equals("assessments", StringComparison.OrdinalIgnoreCase) ||
            parts[7].Equals("verification-decisions", StringComparison.OrdinalIgnoreCase);
    }

    internal static void Configure(CookieAuthenticationOptions options)
    {
        options.Cookie.Name = CookieName;
        options.Cookie.HttpOnly = true;
        options.Cookie.SecurePolicy = CookieSecurePolicy.Always;
        options.Cookie.SameSite = SameSiteMode.Lax;
        options.Cookie.Path = "/";
        options.SlidingExpiration = false;
        options.ExpireTimeSpan = TimeSpan.FromHours(12);
        options.Events = new CookieAuthenticationEvents
        {
            OnValidatePrincipal = async context =>
            {
                var claims = context.Principal;
                if (!Guid.TryParse(claims?.FindFirstValue(JwtRegisteredClaimNames.Sub), out var userId) ||
                    !Guid.TryParse(claims?.FindFirstValue("sid"), out var sessionId) ||
                    !TryRole(claims?.FindFirstValue("role"), out var role))
                {
                    context.RejectPrincipal();
                    return;
                }
                var validator = context.HttpContext.RequestServices.GetRequiredService<AuthoritativeSessionValidator>();
                var result = await validator
                    .ValidateAsync(userId, sessionId, role, context.HttpContext.RequestServices.GetRequiredService<TimeProvider>().GetUtcNow(),
                        SessionTransport.Web, context.HttpContext.RequestAborted);
                if (result == AuthoritativeSessionValidation.MustChangePassword &&
                    PasswordChangeAllowed(context.Request.Method, context.Request.Path)) return;
                if (result == AuthoritativeSessionValidation.SessionRevoked &&
                    HttpMethods.IsPost(context.Request.Method) &&
                    context.Request.Path.Value?.EndsWith("/auth/web/logout", StringComparison.OrdinalIgnoreCase) == true &&
                    context.Request.Headers.TryGetValue("Idempotency-Key", out var key) &&
                    !string.IsNullOrWhiteSpace(key.ToString()) &&
                    await validator.HasCommittedReplayAsync(userId, "Logout", key.ToString().Trim(' '),
                        context.HttpContext.RequestAborted)) return;
                if (result != AuthoritativeSessionValidation.Success) context.RejectPrincipal();
            },
            OnRedirectToLogin = context =>
            {
                context.Response.StatusCode = StatusCodes.Status401Unauthorized;
                return Task.CompletedTask;
            },
            OnRedirectToAccessDenied = context =>
            {
                context.Response.StatusCode = StatusCodes.Status403Forbidden;
                return Task.CompletedTask;
            }
        };
    }

    private static bool PasswordChangeAllowed(string method, PathString path)
    {
        var value = path.Value ?? "";
        if (HttpMethods.IsGet(method))
            return value.EndsWith("/me", StringComparison.OrdinalIgnoreCase) ||
                   value.EndsWith("/auth/web/session", StringComparison.OrdinalIgnoreCase) ||
                   value.EndsWith("/auth/web/csrf", StringComparison.OrdinalIgnoreCase);
        return HttpMethods.IsPost(method) &&
            (value.EndsWith("/auth/web/logout", StringComparison.OrdinalIgnoreCase) ||
             value.EndsWith("/auth/change-password", StringComparison.OrdinalIgnoreCase));
    }

    private static bool TryRole(string? value, out UserRoleCode role)
    {
        try { role = UserRoleCodeExtensions.FromDbCode(value ?? ""); return role != UserRoleCode.Unknown; }
        catch (ArgumentOutOfRangeException) { role = UserRoleCode.Unknown; return false; }
    }
}

using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Antiforgery;
using Microsoft.AspNetCore.Authentication;
using RoadGuardSystem.API.Authentication;
using RoadGuardSystem.aBusinessObjects.Commons;

namespace RoadGuardSystem.API.Middlewares;

public sealed class WebCookieRequestMiddleware(RequestDelegate next)
{
    public async Task InvokeAsync(HttpContext context, IAntiforgery antiforgery)
    {
        if (context.Request.Headers.ContainsKey("Authorization") &&
            context.Request.Cookies.ContainsKey(WebCookieConfiguration.CookieName) &&
            WebCookieConfiguration.IsCookieEligibleRequest(context) &&
            context.User.Identity?.IsAuthenticated == true)
        {
            var cookie = await context.AuthenticateAsync(WebCookieConfiguration.Scheme);
            var bearerActor = context.User.FindFirstValue(JwtRegisteredClaimNames.Sub);
            var cookieActor = cookie.Principal?.FindFirstValue(JwtRegisteredClaimNames.Sub);
            if (cookie.Succeeded && cookieActor is not null && cookieActor != bearerActor)
            {
                await DenyAsync(context, StatusCodes.Status400BadRequest, "validation_error");
                return;
            }
        }

        if (context.User.Identity?.AuthenticationType != WebCookieConfiguration.Scheme ||
            context.Request.Path.StartsWithSegments("/api/v1/auth/web", StringComparison.OrdinalIgnoreCase))
        {
            await next(context);
            return;
        }

        if (!HttpMethods.IsGet(context.Request.Method) && !HttpMethods.IsHead(context.Request.Method) &&
            !HttpMethods.IsOptions(context.Request.Method))
        {
            try { await antiforgery.ValidateRequestAsync(context); }
            catch (AntiforgeryValidationException)
            {
                await DenyAsync(context, StatusCodes.Status403Forbidden, "csrf_failed");
                return;
            }
        }

        await next(context);
    }

    private static Task DenyAsync(HttpContext context, int status, string code)
    {
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/problem+json";
        context.Response.Headers.CacheControl = "no-store";
        return context.Response.WriteAsync(JsonSerializer.Serialize(new
        {
            type = "about:blank",
            title = status switch { 400 => "Bad Request", 403 => "Forbidden", _ => "Unauthorized" },
            status,
            detail = status switch
            {
                400 => "Credentials identify different actors.",
                403 => "The CSRF token is invalid or missing.",
                _ => "The session is no longer active."
            },
            instance = context.Request.Path.Value,
            code,
            correlationId = context.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString()
        }), context.RequestAborted);
    }
}

    private async Task<IActionResult> Run(Guid project, string action, CancellationToken ct, Guid? section = null, Guid? draft = null, Guid? route = null, Guid? set = null, object? input = null)
    {
        if (!Guid.TryParse(User.FindFirstValue(JwtRegisteredClaimNames.Sub), out var actor) || !ProjectRoleClaimParser.TryParse(User.FindFirstValue("role"), out var role)) return Error(401, "unauthorized");
        var etag = Request.Headers.IfMatch.ToString();
        if (!string.IsNullOrEmpty(etag) && (etag.Length < 3 || etag[0] != '"' || etag[^1] != '"')) return Error(412, "concurrency_conflict");
        var result = await service.ExecuteAsync(role, new(actor, project, action, section, draft, route, set, input, Request.Headers["Idempotency-Key"].ToString(), string.IsNullOrEmpty(etag) ? null : etag[1..^1]), ct);
        if (result.Code is not null) return Error(result.Status, result.Code);
        if (result.Version is not null) Response.Headers.ETag = '"' + result.Version + '"';
        if (result.Status == 201)
        {
            if (result.Value is GeometryDraftView d) Response.Headers.Location = $"/api/v1/projects/{project}/road-geometry-drafts/{d.Id}";
            else if (result.Value is RoadGeometryVersionView r) Response.Headers.Location = $"/api/v1/projects/{project}/road-sections/{r.RoadSectionId}/versions/{r.RouteVersionId}/geometry";
            else if (result.Value is SegmentSetView s) Response.Headers.Location = $"/api/v1/projects/{project}/road-sections/{section}/versions/{s.RouteVersionId}/segment-sets/{s.Id}";
            else if (result.Value is System.Text.Json.JsonElement json && json.TryGetProperty("Id", out var id)) Response.Headers.Location = action == "draft-create" ? $"/api/v1/projects/{project}/road-geometry-drafts/{id}" : $"/api/v1/projects/{project}/road-sections/{section}/versions/{route}/segment-sets/{id}";
        }
        return StatusCode(result.Status, result.Value);
    }
    private ObjectResult Error(int status, string code)
    {
        var p = new ProblemDetails { Status = status, Title = "Geometry request failed", Detail = "The geometry request could not be completed.", Instance = Request.Path };
        p.Extensions["code"] = code; p.Extensions["correlationId"] = HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString() ?? Guid.NewGuid().ToString();
        return new ObjectResult(p) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }
}

using RoadGuardSystem.Repositories.Projects;
using RoadGuardSystem.Services.Authorization;
using RoadGuardSystem.aBusinessObjects.Commons;
namespace RoadGuardSystem.Services.Projects;

public sealed class GeometryWorkflowService(IGeometryWorkflowRepository repository, IProjectScopeGuard guard) : IGeometryWorkflowService
{
    public async Task<GeometryWorkflowResult> ExecuteAsync(UserRoleCode role, GeometryWorkflowCommand command, CancellationToken cancellationToken)
    {
        var c = command with { Role = role }; var ct = cancellationToken;
        var read = c.Action is "draft-get" or "draft-readiness" or "draft-preview" or "set-preview" or "geometry-get" or "set-get" or "package" or "profile-get" or "profile-list" or "system-list";
        var operatorPackage = c.Action == "package" && role == UserRoleCode.DroneOperator;
        if (c.ActorId == Guid.Empty || (c.Action == "confirm" ? role != UserRoleCode.Supervisor : read ? !operatorPackage && role is not (UserRoleCode.Supervisor or UserRoleCode.ProjectManager) : role != UserRoleCode.ProjectManager)) return new(403, "access_forbidden");
        if (await guard.AuthorizeAsync(c.ActorId, role, c.ProjectId, ct) is null) return new(403, "access_forbidden");
        if (operatorPackage && (c.RouteVersionId is not Guid routeId || c.SetId is not Guid setId || !await repository.CanReadAssignedGeometryAsync(c.ActorId, c.ProjectId, routeId, setId, ct))) return new(403, "access_forbidden");
        var write = c.Action is "draft-create" or "draft-edit" or "confirm" or "set-create" or "set-edit" or "publish" or "profile-create" or "system-create";
        if (write && (string.IsNullOrWhiteSpace(c.Key) || c.Key.Length > 200)) return new(428, "validation_error");
        if (c.Action is "draft-edit" or "confirm" or "set-edit" or "publish" && string.IsNullOrWhiteSpace(c.ExpectedVersion)) return new(428, "validation_error");
        try
        {
            if (c.Action == "profile-create") CrsProfileEngine.Validate((RoadGuardSystem.DTOs.Projects.CrsProfileInput)c.Input!);
            var result = await repository.ExecuteAsync(c with { Input = RoadGuardSystem.DTOs.BoundaryFactMappings.ToFacts(c.Input) },
                (input, srid) => GeometryEngine.Preview(input, srid),
                (id, line, origin, definition) => GeometryEngine.Segments(id, line, origin, definition), ct);
            result = result with { Value = RoadGuardSystem.DTOs.BoundaryFactMappings.ToWire(result.Value) };
            if (c.Action == "draft-readiness" && result.Value is RoadGuardSystem.DTOs.Projects.GeometryDraftInput draft)
                return result with { Value = CrsProfileEngine.Readiness(draft, draft.ResolvedCrsProfile) };
            return result;
        }
        catch (GeometryValidationException e) { return new(422, e.Code); }
    }
}

using System.Security.Cryptography;
using System.Text.Json;
using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;
using NetTopologySuite.Geometries;
using NetTopologySuite.LinearReferencing;
using RoadGuardSystem.BusinessObjects.Projects;
using RoadGuardSystem.BusinessObjects.Auditing;
using RoadGuardSystem.BusinessObjects.PersistenceFacts.Projects;
using RoadGuardSystem.Repositories.Idempotency;
using RoadGuardSystem.aBusinessObjects.Commons;
namespace RoadGuardSystem.Repositories.Projects;

public sealed class GeometryWorkflowPersistenceService(RoadGuardDbContext db, IdempotencyOperationService idempotency, TimeProvider? timeProvider = null) : IGeometryWorkflowRepository
{
    private readonly TimeProvider clock = timeProvider ?? TimeProvider.System;
    public Task<bool> CanReadAssignedGeometryAsync(Guid actorId, Guid projectId, Guid routeVersionId, Guid setId, CancellationToken cancellationToken)
        => (from scope in db.SurveyRequestScopes
            join task in db.SurveyRequests on scope.SurveyRequestId equals task.Id
            join assignment in db.SurveyAssignments on task.Id equals assignment.SurveyRequestId
            where task.ProjectId == projectId && scope.RouteSectionVersionId == routeVersionId && scope.SegmentSetId == setId
                && assignment.OperatorUserId == actorId && assignment.EndedAt == null
            select task.Id).AnyAsync(cancellationToken);
    private static string Hash(object value) => Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(value))).ToLowerInvariant();
    private static T Decode<T>(string json) => JsonSerializer.Deserialize<T>(json)!;
    private static string Version(byte[] bytes) => Convert.ToBase64String(bytes);
    private sealed class Rejected(int status, string code) : Exception { public GeometryWorkflowResult Result { get; } = new(status, code); }
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Reject(int status, string code) => throw new Rejected(status, code);
    public async Task<GeometryWorkflowResult> ExecuteAsync(GeometryWorkflowCommand command, Func<GeometryDraftInputFact, int, GeometryPreviewFact> preview,
        Func<Guid, LineString, double, SegmentDefinitionFact, SegmentPreviewFact> segments, CancellationToken cancellationToken)
    {
        var c = command; var ct = cancellationToken;
        try
        {
            var write = c.Action is "draft-create" or "draft-edit" or "confirm" or "set-create" or "set-edit" or "publish" or "profile-create" or "system-create";
            if (!write && db.Database.CurrentTransaction is not null)
            {
                await GuardAsync(c, true, ct);
                return await Run(c, preview, segments, ct);
            }
            if (!write) return await db.Database.CreateExecutionStrategy().ExecuteAsync(async () =>
            {
                await using var transaction = await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable, ct);
                await GuardAsync(c, true, ct);
                var result = await Run(c, preview, segments, ct);
                await transaction.CommitAsync(ct);
                return result;
            });
            var receipt = await idempotency.ExecuteAsync(c.ActorId, c.ProjectId, "Geometry:" + c.Action, c.Key!, Hash(new { c.RoadSectionId, c.DraftId, c.RouteVersionId, c.SetId, c.Input, c.ExpectedVersion }), async token =>
            {
                // Project serialization also covers alias URLs whose draft resolves the existing road only inside the handler.
                var resource = $"anh01:geometry:{c.ProjectId}";
                await db.Database.ExecuteSqlInterpolatedAsync($"DECLARE @lockResult int; EXEC @lockResult = sys.sp_getapplock @Resource={resource}, @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=10000; IF @lockResult < 0 THROW 51000, 'Geometry command lock unavailable', 1;", token);
                await GuardAsync(c, true, token);
                var result = await Run(c, preview, segments, token);
                var id = result.Value switch { GeometryDraftViewFact draft => draft.Id, RoadGeometryVersionViewFact route => route.RouteVersionId, SegmentSetViewFact set => set.Id, _ => c.SetId ?? c.DraftId ?? Guid.NewGuid() };
                db.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), c.ActorId, clock.GetUtcNow(),
                    "geometry_" + c.Action.Replace('-', '_'), "RoadGeometry", id, null,
                    JsonSerializer.Serialize(new { project_id = c.ProjectId, operation = c.Action }), "GEOMETRY_WORKFLOW", "PROJECT_API", null,
                    snapshotAllowedPropertyNames: ["project_id", "operation"]));
                await db.SaveChangesAsync(token);
                return (id, JsonSerializer.Serialize(result));
            }, ct, receiptAccessGuard: token => GuardAsync(c, true, token));
            if (receipt.Status == IdempotencyOperationStatus.Conflict) return new(409, "duplicate_request");
            var restored = Decode<GeometryWorkflowResult>(receipt.OutcomeJson);
            if (restored.Value is JsonElement json) restored = restored with
            {
                Value = c.Action switch
                {
                    "draft-create" or "draft-edit" => json.Deserialize<GeometryDraftViewFact>(),
                    "confirm" => json.Deserialize<RoadGeometryVersionViewFact>(),
                    "profile-create" => json.Deserialize<CrsProfileViewFact>(),
                    "system-create" => json.Deserialize<RouteSystemViewFact>(),
                    _ => json.Deserialize<SegmentSetViewFact>()
                }
            };
            return restored;
        }
        catch (Rejected e) { db.ChangeTracker.Clear(); return e.Result; }
        catch (DbUpdateConcurrencyException) { db.ChangeTracker.Clear(); return new(412, "concurrency_conflict"); }
        catch (DbUpdateException e) when (e.InnerException is SqlException { Number: 2601 or 2627 })
        {
            db.ChangeTracker.Clear();
            return new(409, c.Action == "confirm"
                ? ((GeometryConfirmInputFact)c.Input!).ExpectedCurrentVersionId is null ? "road_section_code_conflict" : "road_section_concurrency_conflict"
                : "segment_publication_conflict");
        }
    }
    private async Task<GeometryWorkflowResult> Run(GeometryWorkflowCommand c, Func<GeometryDraftInputFact, int, GeometryPreviewFact> preview,
        Func<Guid, LineString, double, SegmentDefinitionFact, SegmentPreviewFact> segments, CancellationToken ct)
    {
        var project = await db.Projects.SingleOrDefaultAsync(x => x.Id == c.ProjectId, ct);
        if (project is null) Reject(404, "project_not_found");
        if (project!.Status == RoadGuardSystem.aBusinessObjects.Commons.ProjectStatus.Closed && c.Action is "draft-create" or "draft-edit" or "confirm" or "set-create" or "set-edit" or "publish" or "profile-create" or "system-create") Reject(409, "project_closed");
        var srid = project!.EngineeringUtmSrid ?? 0;
        if (c.Action == "profile-create")
        {
            var input = (CrsProfileInputFact)c.Input!;
            var next = (await db.Set<CrsProfileRevision>().Where(x => x.ProjectId == c.ProjectId && x.Code == input.Code.Trim()).Select(x => (int?)x.Revision).MaxAsync(ct) ?? 0) + 1;
            var profile = new CrsProfileRevision { Id = Guid.NewGuid(), ProjectId = c.ProjectId, Code = input.Code.Trim(), Revision = next, SourceSrid = input.SourceSrid, Status = "CANDIDATE", SampleOnly = input.SampleOnly, PayloadJson = JsonSerializer.Serialize(input), CreatedBy = c.ActorId, CreatedAt = clock.GetUtcNow() };
            db.Add(profile); await db.SaveChangesAsync(ct); return new(201, Value: ProfileView(profile), Version: Hash(profile.PayloadJson));
        }
        if (c.Action == "profile-get")
        {
            var profile = await db.Set<CrsProfileRevision>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == c.DraftId && x.ProjectId == c.ProjectId, ct);
            if (profile is null) Reject(404, "crs_profile_not_found");
            return new(200, Value: ProfileView(profile!), Version: Hash(profile!.PayloadJson));
        }
        if (c.Action == "profile-list") return new(200, Value: (await db.Set<CrsProfileRevision>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId).OrderBy(x => x.Code).ThenBy(x => x.Revision).ToArrayAsync(ct)).Select(ProfileView).ToArray());
        if (c.Action == "system-create")
        {
            var input = (RouteSystemInputFact)c.Input!;
            if (string.IsNullOrWhiteSpace(input.Code) || input.Code.Length > 80 || string.IsNullOrWhiteSpace(input.Name) || input.Name.Length > 255) Reject(422, "route_system_invalid");
            var system = new RoadRouteSystem { Id = Guid.NewGuid(), ProjectId = c.ProjectId, Code = input.Code.Trim(), Name = input.Name.Trim() };
            db.Add(system); await db.SaveChangesAsync(ct); return new(201, Value: new RouteSystemViewFact(system.Id, system.ProjectId, system.Code, system.Name));
        }
        if (c.Action == "system-list") return new(200, Value: await db.Set<RoadRouteSystem>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId).OrderBy(x => x.Code).Select(x => new RouteSystemViewFact(x.Id, x.ProjectId, x.Code, x.Name)).ToArrayAsync(ct));
        RoadSection? section = null;
        if (c.RoadSectionId is Guid sid)
        {
            section = await db.RoadSections.SingleOrDefaultAsync(x => x.Id == sid && x.ProjectId == c.ProjectId, ct);
            if (section is null) Reject(404, "road_section_not_found");
        }
        if (c.Action.StartsWith("draft", StringComparison.Ordinal) || c.Action == "confirm")
        {
            RoadGeometryDraft? draft = null;
            if (c.DraftId is Guid did)
            {
                draft = await db.Set<RoadGeometryDraft>().SingleOrDefaultAsync(x => x.Id == did && x.ProjectId == c.ProjectId && (c.RoadSectionId == null || x.RoadSectionId == c.RoadSectionId), ct);
                if (draft is null) Reject(404, "road_geometry_draft_not_found");
                if (section is null && draft!.RoadSectionId is Guid existingSectionId)
                {
                    section = await db.RoadSections.SingleOrDefaultAsync(x => x.Id == existingSectionId && x.ProjectId == c.ProjectId, ct);
                    if (section is null) Reject(404, "road_section_not_found");
                }
            }
            if (c.Action is "draft-create" or "draft-edit")
            {
                var input = (GeometryDraftInputFact)c.Input!;
                if (input.SourceKind == "NATIVE_ALIGNMENT")
                {
                    input = await ResolveNativeInputAsync(input, c.ProjectId, ct);
                    if (NativeMissing(input).Length == 0) preview(input, input.SourceCrs);
                }
                else preview(input, srid);
                var code = section?.Code ?? input.RoadCode?.Trim();
                if (string.IsNullOrWhiteSpace(code) || code.Length > 80 || input.RoadName?.Length > 255 || (input.BranchCode is not null && input.BranchCode != code)) Reject(422, "geometry_validation_failed");
                if (draft is null) { draft = RoadGeometryDraft.Create(c.ProjectId, c.RoadSectionId, code!, input.RoadName, JsonSerializer.Serialize(input), JsonSerializer.Serialize(input.Coordinates), null, c.ActorId, clock.GetUtcNow()); db.Add(draft); }
                else
                {
                    Match(draft.RowVersion, c.ExpectedVersion); if (draft.Status != "DRAFT") Reject(409, "road_geometry_invalid_state");
                    var previousInput = Decode<GeometryDraftInputFact>(draft.InputJson);
                    var original = previousInput.SourceKind == input.SourceKind && previousInput.SourceCrs == input.SourceCrs && previousInput.SourceFileId == input.SourceFileId ? draft.OriginalCoordinatesJson : JsonSerializer.Serialize(input.Coordinates);
                    draft.Edit(JsonSerializer.Serialize(input), original, null, code!, input.RoadName, c.ActorId, clock.GetUtcNow());
                }
                await db.SaveChangesAsync(ct);
                return new(c.Action == "draft-create" ? 201 : 200, Value: DraftView(draft), Version: Version(draft.RowVersion));
            }
            if (c.ExpectedVersion is not null) Match(draft!.RowVersion, c.ExpectedVersion);
            var stored = Decode<GeometryDraftInputFact>(draft!.InputJson);
            if (stored.SourceKind == "NATIVE_ALIGNMENT") stored = await ResolveNativeInputAsync(stored, c.ProjectId, ct);
            if (c.Action == "draft-get") return new(200, Value: DraftView(draft), Version: Version(draft.RowVersion));
            if (c.Action == "draft-readiness") return new(200, Value: stored, Version: Version(draft.RowVersion));
            if (c.Action == "draft-preview") return new(200, Value: preview(stored, srid), Version: Version(draft.RowVersion));
            if (draft.Status != "DRAFT") Reject(409, "road_geometry_invalid_state");
            var confirm = (GeometryConfirmInputFact)c.Input!;
            if (string.IsNullOrWhiteSpace(confirm.Reason) || confirm.EffectiveFrom == default) Reject(422, "geometry_validation_failed");
            var prepared = preview(stored, srid);
            if (stored.SourceKind == "NATIVE_ALIGNMENT") await ValidateTopologyAsync(stored, c.ProjectId, section?.Id, prepared, preview, segments, ct);
            RoadSectionVersion? current = section is null ? null : await db.RoadSectionVersions.SingleOrDefaultAsync(x => x.RoadSectionId == section.Id && x.IsCurrent, ct);
            if (current?.Id != confirm.ExpectedCurrentVersionId) Reject(409, "road_section_concurrency_conflict");
            if (section is null) { section = RoadSection.Create(Guid.NewGuid(), c.ProjectId, draft.RoadCode, draft.RoadName); db.Add(section); }
            if (current is not null) { current.ClearCurrent(); await db.SaveChangesAsync(ct); }
            var line = stored.SourceKind == "NATIVE_ALIGNMENT"
                ? new GeometryFactory(new PrecisionModel(), stored.SourceCrs).CreateLineString(((double[][])prepared.MetricCenterline.Coordinates).Select(p => new Coordinate(p[0], p[1])).ToArray())
                : new GeometryFactory(new PrecisionModel(), srid).CreateLineString(stored.Coordinates!.Select(p => new Coordinate(p.X, p.Y)).ToArray());
            var version = RoadSectionVersion.Create(Guid.NewGuid(), section.Id, (current?.VersionNo ?? 0) + 1, true, line, confirm.EffectiveFrom, confirm.Reason);
            if (stored.NativeAlignment is { } native)
            {
                version.PinNativeProfile(native.CrsProfileRevisionId);
                db.Add(new NativeRouteVersionFacts { RoadSectionVersionId = version.Id, ProjectId = c.ProjectId, CrsProfileRevisionId = native.CrsProfileRevisionId, RouteSystemId = stored.RouteSystemId!.Value, RouteKind = stored.RouteKind!, ParentRouteVersionId = stored.ParentRouteVersionId, JunctionOffsetMeters = stored.JunctionOffsetMeters, CanonicalLengthMeters = prepared.LengthMeters, DeclaredLengthMeters = stored.DeclaredLengthMeters, CalibrationJson = stored.ChainageCalibration is null ? null : JsonSerializer.Serialize(stored.ChainageCalibration), SampleOnly = prepared.SampleOnly });
            }
            db.Add(version); draft.Confirm(section.Id);
            db.Add(RoadGeometryMetadata.Create(version.Id, draft.Id, JsonSerializer.Serialize(stored), Hash(new { srid, coordinates = stored.Coordinates, stored.NativeAlignment, stored.WidthProfile, stored.StationOriginMeters, stored.SurveyWidthMeters }), c.ActorId, prepared.Wgs84Centerline is null ? null : JsonSerializer.Serialize(prepared.Wgs84Centerline), clock.GetUtcNow()));
            if (current is not null)
            {
                var refs = new List<GeometryAffectedReferenceFact>();
                var field = await db.FieldInspectionTasks.AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.RoadSectionVersionId == current.Id).Select(x => new { x.Id, x.SegmentSetId }).ToArrayAsync(ct);
                refs.AddRange(field.Select(x => new GeometryAffectedReferenceFact("FIELD_TASK", x.Id, current.Id, x.SegmentSetId,
                    x.SegmentSetId.HasValue ? "PINNED_REFERENCE" : "INCOMPLETE", x.SegmentSetId.HasValue ? [] : ["LEGACY_SEGMENT_SET_UNPINNED"])));
                var surveys = await (from scope in db.SurveyRequestScopes.AsNoTracking() join task in db.SurveyRequests.AsNoTracking() on scope.SurveyRequestId equals task.Id where task.ProjectId == c.ProjectId && scope.RouteSectionVersionId == current.Id select new { task.Id, scope.SegmentSetId }).Distinct().ToArrayAsync(ct);
                refs.AddRange(surveys.Select(x => new GeometryAffectedReferenceFact("SURVEY_TASK", x.Id, current.Id, x.SegmentSetId, "READY", [])));
                var defects = await db.Defects.AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.RoadSectionVersionId == current.Id).Select(x => x.Id).ToArrayAsync(ct);
                refs.AddRange(defects.Select(x => new GeometryAffectedReferenceFact("DEFECT", x, current.Id, null, "INCOMPLETE", ["SEGMENT_SET_NOT_PINNED"])));
                var layouts = await db.Set<PavementLayoutRevision>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.RouteVersionId == current.Id).Select(x => new { x.Id, x.SegmentSetId }).ToArrayAsync(ct);
                refs.AddRange(layouts.Select(x => new GeometryAffectedReferenceFact("LAYOUT", x.Id, current.Id, x.SegmentSetId, "PINNED_REFERENCE", [])));
                var maps = await db.Set<GeometryMapPublication>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.RouteVersionId == current.Id).Select(x => new { x.Id, x.SegmentSetId }).ToArrayAsync(ct);
                refs.AddRange(maps.Select(x => new GeometryAffectedReferenceFact("MAP", x.Id, current.Id, x.SegmentSetId, "PINNED_REFERENCE", [])));
                var branches = await db.Set<NativeRouteVersionFacts>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId && x.ParentRouteVersionId == current.Id).Select(x => x.RoadSectionVersionId).ToArrayAsync(ct);
                refs.AddRange(branches.Select(x => new GeometryAffectedReferenceFact("BRANCH", x, current.Id, null, "PINNED_REFERENCE", [])));
                db.Add(new GeometryLocationImpact { Id = Guid.NewGuid(), ProjectId = c.ProjectId, PreviousRouteVersionId = current.Id, NewRouteVersionId = version.Id, AffectedReferencesJson = JsonSerializer.Serialize(refs.OrderBy(x => x.Kind, StringComparer.Ordinal).ThenBy(x => x.Id).ThenBy(x => x.SegmentSetId).ToArray()), RecordedBy = c.ActorId, RecordedAt = clock.GetUtcNow() });
            }
            await db.SaveChangesAsync(ct);
            var confirmed = await RouteView(c.ProjectId, section.Id, version, ct);
            return new(201, Value: confirmed, Version: Hash(confirmed));
        }
        var readGeometry = c.Action is "package" or "set-get" or "geometry-get";
        var routeQuery = readGeometry ? db.RoadSectionVersions.AsNoTracking() : db.RoadSectionVersions;
        var route = await routeQuery.SingleOrDefaultAsync(x => x.Id == c.RouteVersionId && (c.RoadSectionId == null || x.RoadSectionId == c.RoadSectionId), ct);
        if (route is null) Reject(404, "road_section_version_not_found");
        if (section is null) section = await db.RoadSections.SingleOrDefaultAsync(x => x.Id == route!.RoadSectionId && x.ProjectId == c.ProjectId, ct);
        if (section is null) Reject(404, "road_section_version_not_found");
        var view = await RouteView(c.ProjectId, section!.Id, route!, ct);
        if (c.Action == "geometry-get") return new(200, Value: view, Version: Hash(view));
        RoadSegmentSet? set = null;
        if (c.SetId is Guid setId) { var setQuery = readGeometry ? db.RoadSegmentSets.AsNoTracking() : db.RoadSegmentSets; set = await setQuery.SingleOrDefaultAsync(x => x.Id == setId && x.RoadSectionVersionId == route!.Id, ct); if (set is null) Reject(404, "segment_set_not_found"); }
        if (c.Action is "set-get" or "package")
        {
            var setView = await SetView(set!, ct);
            if (c.Action == "package")
            {
                var package = new GeometryPackageViewFact("anh01.geometry.v1", c.ProjectId, view, setView);
                return new(200, Value: package, Version: Hash(package));
            }
            return new(200, Value: setView, Version: setView.Version);
        }
        if (view.MetadataStatus != "COMPLETE") Reject(422, "geometry_metadata_incomplete");
        if (c.Action is "set-preview" or "set-create" or "set-edit")
        {
            var definition = (SegmentDefinitionFact)c.Input!;
            var metadata = await db.Set<RoadGeometryMetadata>().AsNoTracking().SingleAsync(x => x.RoadSectionVersionId == route!.Id, ct);
            var nativeInput = Decode<GeometryDraftInputFact>(metadata.InputJson);
            definition = definition with { NativeAlignment = nativeInput.NativeAlignment, TessellationToleranceMeters = nativeInput.TessellationToleranceMeters, ChainageCalibration = nativeInput.ChainageCalibration };
            var computed = segments(route!.Id, route.Geometry, view.StationOriginMeters!.Value, definition);
            if (c.Action == "set-preview") return new(200, Value: computed);
            if (set is null) { set = RoadSegmentSet.Create(Guid.NewGuid(), route.Id, "DRAFT"); db.Add(set); }
            else
            {
                Match(set.RowVersion, c.ExpectedVersion);
                if (set.Status != "DRAFT") Reject(409, "road_geometry_invalid_state");
                // A no-op must not replace referenced children without updating the parent's rowversion.
                if (set.DefinitionJson == JsonSerializer.Serialize(definition) && set.GeometryHash == computed.DefinitionHash)
                {
                    var unchanged = await SetView(set, ct);
                    return new(200, Value: unchanged, Version: unchanged.Version);
                }
                db.RoadSegments.RemoveRange(await db.RoadSegments.Where(x => x.SegmentSetId == set.Id).ToListAsync(ct));
                await db.SaveChangesAsync(ct);
            }
            set.Define(JsonSerializer.Serialize(definition), computed.DefinitionHash);
            var indexed = new LengthIndexedLine(route.Geometry);
            foreach (var part in computed.Segments)
            {
                var row = RoadSegment.Create(Guid.NewGuid(), set.Id, route.Id, part.Sequence);
                var geometry = definition.NativeAlignment is null ? (LineString)indexed.ExtractLine(part.FromOffsetMeters, part.ToOffsetMeters)
                    : new GeometryFactory(new PrecisionModel(), route.Geometry.SRID).CreateLineString(((double[][])part.MetricGeometry.Coordinates).Select(p => new Coordinate(p[0], p[1])).ToArray());
                row.SetGeometry(part.FromOffsetMeters, part.ToOffsetMeters, view.StationOriginMeters.Value, geometry, part.StartStationMeters, part.EndStationMeters); db.Add(row);
            }
            await db.SaveChangesAsync(ct); var result = await SetView(set, ct); return new(c.Action == "set-create" ? 201 : 200, Value: result, Version: result.Version);
        }
        Match(set!.RowVersion, c.ExpectedVersion); if (set.Status != "DRAFT") Reject(409, "road_geometry_invalid_state");
        if ((await SetView(set, ct)).MetadataStatus != "COMPLETE") Reject(422, "geometry_metadata_incomplete");
        var publication = (SegmentPublishInputFact)c.Input!;
        if (string.IsNullOrWhiteSpace(publication.Reason)) Reject(422, "segment_validation_failed");
        if (!route!.IsCurrent) Reject(409, "road_section_concurrency_conflict");
        var previous = await db.RoadSegmentSets.SingleOrDefaultAsync(x => x.RoadSectionVersionId == route.Id && x.Status == "PUBLISHED", ct);
        if (previous?.Id != publication.ExpectedPublishedSetId) Reject(409, "segment_publication_conflict");
        if (previous is not null) { previous.Supersede(); await db.SaveChangesAsync(ct); }
        set.Publish(c.ActorId, clock.GetUtcNow()); await db.SaveChangesAsync(ct); var published = await SetView(set, ct); return new(200, Value: published, Version: published.Version);
    }
    private static void Match(byte[] version, string? expected) { if (Version(version) != expected) Reject(412, "concurrency_conflict"); }
    private static GeometryDraftViewFact DraftView(RoadGeometryDraft d) { var i = Decode<GeometryDraftInputFact>(d.InputJson); return new(d.Id, d.ProjectId, d.RoadSectionId, d.RoadCode, d.RoadName, d.Status, i.SourceKind, i.SourceCrs, i.SourceFileId, d.SourceChecksum, i.TrackIndex, i.TrackSegmentIndex, Decode<GeometryPointFact[]?>(d.OriginalCoordinatesJson) ?? [], i.Coordinates ?? [], i.StationOriginMeters, i.WidthProfile, i.SurveyWidthMeters, d.CreatedBy, d.UpdatedBy, Version(d.RowVersion), i.NativeAlignment); }
    private static GeometryShapeFact Shape(LineString line) => new("LineString", line.Coordinates.Select(p => new[] { p.X, p.Y }).ToArray());
    private async Task<RoadGeometryVersionViewFact> RouteView(Guid project, Guid section, RoadSectionVersion route, CancellationToken ct)
    {
        var m = await db.Set<RoadGeometryMetadata>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == route.Id, ct); var i = m is null ? null : Decode<GeometryDraftInputFact>(m.InputJson);
        var facts = await db.Set<NativeRouteVersionFacts>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == route.Id, ct);
        var profile = facts is null ? null : await db.Set<CrsProfileRevision>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == facts.CrsProfileRevisionId, ct);
        return new(project, section, route.Id, route.VersionNo, route.IsCurrent, route.EffectiveFrom, m?.SourceDraftId, i?.SourceCrs, route.Geometry.SRID, i?.StationOriginMeters, i?.WidthProfile, i?.SurveyWidthMeters, Shape(route.Geometry), m?.Wgs84GeometryJson is null ? null : Decode<GeometryShapeFact>(m.Wgs84GeometryJson), facts?.CanonicalLengthMeters ?? route.Geometry.Length, m is null ? "LEGACY_INCOMPLETE" : "COMPLETE", m?.ApprovedBy, m?.ApprovedAt, m?.GeometryHash ?? Hash(route.Geometry.AsText()), facts?.CrsProfileRevisionId, facts?.RouteSystemId, facts?.RouteKind, facts?.ParentRouteVersionId, facts?.JunctionOffsetMeters, facts?.DeclaredLengthMeters, i?.ChainageCalibration, profile?.Status, profile?.SampleOnly ?? false);
    }
    private static CrsProfileViewFact ProfileView(CrsProfileRevision profile) => new(profile.Id, profile.ProjectId, profile.Code, profile.Revision, profile.Status, Decode<CrsProfileInputFact>(profile.PayloadJson), profile.CreatedBy, profile.CreatedAt);
    private async Task<GeometryDraftInputFact> ResolveNativeInputAsync(GeometryDraftInputFact input, Guid project, CancellationToken ct)
    {
        // Never trust a client-supplied profile snapshot; pin the immutable project-owned revision.
        input = input with { ResolvedCrsProfile = null };
        if (input.NativeAlignment is null) return input;
        var profile = await db.Set<CrsProfileRevision>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == input.NativeAlignment.CrsProfileRevisionId && x.ProjectId == project, ct);
        if (profile is null) Reject(422, "crs_profile_scope_mismatch");
        if (profile!.SourceSrid != input.SourceCrs || input.NativeAlignment.SpatialSrid != profile.SourceSrid) Reject(422, "crs_profile_srid_mismatch");
        return input with { ResolvedCrsProfile = Decode<CrsProfileInputFact>(profile.PayloadJson) };
    }
    private static string[] NativeMissing(GeometryDraftInputFact input)
    {
        var missing = new List<string>();
        if (input.NativeAlignment is null) missing.Add("nativeAlignment");
        if (input.ResolvedCrsProfile is null) missing.Add("crsProfileRevision");
        if (input.RouteSystemId is null || input.RouteSystemId == Guid.Empty) missing.Add("routeSystemId");
        if (input.RouteKind is not ("MAIN" or "BRANCH")) missing.Add("routeKind");
        if (input.WidthProfile is null || input.WidthProfile.Length == 0 || input.SurveyWidthMeters <= 0) missing.Add("widthProfile");
        if (input.TessellationToleranceMeters is null) missing.Add("tessellationToleranceMeters");
        return missing.ToArray();
    }
    private async Task ValidateTopologyAsync(GeometryDraftInputFact input, Guid project, Guid? section, GeometryPreviewFact child,
        Func<GeometryDraftInputFact, int, GeometryPreviewFact> preview, Func<Guid, LineString, double, SegmentDefinitionFact, SegmentPreviewFact> segments, CancellationToken ct)
    {
        if (!await db.Set<RoadRouteSystem>().AnyAsync(x => x.Id == input.RouteSystemId && x.ProjectId == project, ct)) Reject(422, "route_system_scope_mismatch");
        if (input.RouteKind == "MAIN") { if (input.ParentRouteVersionId is not null || input.JunctionOffsetMeters is not null) Reject(422, "route_topology_invalid"); return; }
        var junction = input.JunctionOffsetMeters ?? double.NaN;
        if (input.RouteKind != "BRANCH" || input.ParentRouteVersionId is null || !double.IsFinite(junction)) Reject(422, "route_topology_invalid");
        var parent = await db.RoadSectionVersions.AsNoTracking().SingleOrDefaultAsync(x => x.Id == input.ParentRouteVersionId, ct);
        var parentFacts = parent is null ? null : await db.Set<NativeRouteVersionFacts>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == parent.Id, ct);
        if (parent is null || parentFacts is null || parentFacts.ProjectId != project || parentFacts.RouteSystemId != input.RouteSystemId || parentFacts.CrsProfileRevisionId != input.NativeAlignment!.CrsProfileRevisionId || !parent.IsCurrent || junction < 0 || junction > parentFacts.CanonicalLengthMeters) Reject(422, "branch_parent_or_junction_invalid");
        var seen = new HashSet<Guid>(); var seenRoads = new HashSet<Guid>();
        if (section is Guid childSection) seenRoads.Add(childSection);
        var ancestor = parent;
        while (ancestor is not null)
        {
            if (seen.Count >= 100000 || !seen.Add(ancestor.Id) || !seenRoads.Add(ancestor.RoadSectionId)) Reject(422, "route_topology_cycle");
            var facts = await db.Set<NativeRouteVersionFacts>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == ancestor.Id, ct);
            ancestor = facts?.ParentRouteVersionId is Guid next ? await db.RoadSectionVersions.AsNoTracking().SingleOrDefaultAsync(x => x.Id == next, ct) : null;
        }
        var metadata = await db.Set<RoadGeometryMetadata>().AsNoTracking().SingleAsync(x => x.RoadSectionVersionId == parent!.Id, ct);
        var parentInput = Decode<GeometryDraftInputFact>(metadata.InputJson);
        var boundaries = junction == 0 || junction == parentFacts!.CanonicalLengthMeters ? new[] { 0d, parentFacts.CanonicalLengthMeters } : new[] { 0d, junction, parentFacts.CanonicalLengthMeters };
        var computed = segments(parent.Id, parent.Geometry, parentInput.StationOriginMeters, new(100, "KEEP", boundaries, parentInput.NativeAlignment, parentInput.TessellationToleranceMeters, parentInput.ChainageCalibration));
        var point = junction == parentFacts.CanonicalLengthMeters ? ((double[][])computed.Segments[^1].MetricGeometry.Coordinates)[^1]
            : ((double[][])computed.Segments[junction == 0 ? 0 : 1].MetricGeometry.Coordinates)[0];
        var start = ((double[][])child.MetricCenterline.Coordinates)[0];
        if (Math.Abs(point[0] - start[0]) > 1e-9 * Math.Max(1, Math.Abs(point[0])) || Math.Abs(point[1] - start[1]) > 1e-9 * Math.Max(1, Math.Abs(point[1]))) Reject(422, "branch_junction_mismatch");
    }
    private async Task GuardAsync(GeometryWorkflowCommand c, bool locked, CancellationToken ct)
    {
        if (locked) await Anh02ReceiptAuthority.LockAsync(db, c.ActorId, c.ProjectId, ct);
        var user = await db.Users.AsNoTracking().SingleOrDefaultAsync(x => x.Id == c.ActorId, ct);
        if (user is null || user.Status != UserStatus.Active || user.MustChangePassword || (c.Role is not null && c.Role != user.RoleCode) || !await db.Roles.AsNoTracking().AnyAsync(x => x.Code == user.RoleCode && x.IsActive, ct)) Reject(403, "access_forbidden");
        var read = c.Action is "draft-get" or "draft-readiness" or "draft-preview" or "geometry-get" or "set-get" or "set-preview" or "package" or "profile-get" or "profile-list" or "system-list";
        if (c.Action == "confirm" ? user.RoleCode != UserRoleCode.Supervisor : !read ? user.RoleCode != UserRoleCode.ProjectManager : user.RoleCode is not (UserRoleCode.ProjectManager or UserRoleCode.Supervisor or UserRoleCode.DroneOperator)) Reject(403, "access_forbidden");
        if (user.RoleCode != UserRoleCode.Supervisor)
        {
            var today = DateOnly.FromDateTime(clock.GetUtcNow().UtcDateTime);
            if (!await db.ProjectMembers.AsNoTracking().AnyAsync(x => x.ProjectId == c.ProjectId && x.UserId == c.ActorId && x.RoleCode == user.RoleCode && x.Status == ProjectMemberStatus.Active && x.ValidFrom <= today && (x.ValidTo == null || x.ValidTo >= today), ct)) Reject(403, "access_forbidden");
        }
        if (user.RoleCode == UserRoleCode.DroneOperator && (c.Action != "package" || c.RouteVersionId is not Guid route || c.SetId is not Guid set || !await CanReadAssignedGeometryAsync(c.ActorId, c.ProjectId, route, set, ct))) Reject(403, "access_forbidden");
        if (c.RoadSectionId is Guid section && !await db.RoadSections.AsNoTracking().AnyAsync(x => x.Id == section && x.ProjectId == c.ProjectId, ct)) Reject(404, "road_section_not_found");
        if (c.DraftId is Guid draft && !c.Action.StartsWith("profile", StringComparison.Ordinal) && !await db.Set<RoadGeometryDraft>().AsNoTracking().AnyAsync(x => x.Id == draft && x.ProjectId == c.ProjectId && (c.RoadSectionId == null || x.RoadSectionId == c.RoadSectionId), ct)) Reject(404, "road_geometry_draft_not_found");
        if (c.RouteVersionId is Guid version && !await (from v in db.RoadSectionVersions.AsNoTracking() join s in db.RoadSections.AsNoTracking() on v.RoadSectionId equals s.Id where v.Id == version && s.ProjectId == c.ProjectId && (c.RoadSectionId == null || v.RoadSectionId == c.RoadSectionId) select v.Id).AnyAsync(ct)) Reject(404, "road_section_version_not_found");
        if (c.SetId is Guid setId && !await db.RoadSegmentSets.AsNoTracking().AnyAsync(x => x.Id == setId && x.RoadSectionVersionId == c.RouteVersionId, ct)) Reject(404, "segment_set_not_found");
    }
    private async Task<SegmentSetViewFact> SetView(RoadSegmentSet set, CancellationToken ct)
    {
        var rows = await db.RoadSegments.AsNoTracking().Where(x => x.SegmentSetId == set.Id).OrderBy(x => x.Sequence).ToListAsync(ct);
        var parts = rows.Select(x =>
        {
            var missing = new List<string>();
            if (x.FromOffsetMeters is null) missing.Add("fromOffsetMeters");
            if (x.ToOffsetMeters is null) missing.Add("toOffsetMeters");
            if (x.StartStationMeters is null) missing.Add("startStationMeters");
            if (x.EndStationMeters is null) missing.Add("endStationMeters");
            if (x.Geometry is null) missing.Add("metricGeometry");
            return new SegmentGeometryViewFact(x.Id, x.Sequence, x.FromOffsetMeters, x.ToOffsetMeters, x.StartStationMeters, x.EndStationMeters,
                x.ToOffsetMeters - x.FromOffsetMeters, x.Geometry is null ? null : Shape(x.Geometry), null, missing.ToArray());
        }).ToArray();
        var setMissing = new List<string>();
        if (set.DefinitionJson is null) setMissing.Add("definition");
        if (set.GeometryHash is null) setMissing.Add("geometryHash");
        if (parts.Length == 0) setMissing.Add("segments");
        if (parts.Any(x => x.MissingMetadata.Length > 0)) setMissing.Add("segments.metadata");
        return new(set.Id, set.RoadSectionVersionId, set.Status, set.DefinitionJson is null ? null : Decode<SegmentDefinitionFact>(set.DefinitionJson), set.GeometryHash,
            parts, set.PublishedBy, set.PublishedAt, Version(set.RowVersion), setMissing.Count == 0 ? "COMPLETE" : "LEGACY_INCOMPLETE", setMissing.ToArray());
    }
}

using System.Security.Cryptography;
using System.Text.Json;
using NetTopologySuite.Geometries;
using NetTopologySuite.LinearReferencing;
