    private async Task<OfflineWorkflowFact> ExecuteTransferAsync(OfflineWorkflowCommand command,
        OfflineWorkflowAlgorithms algorithms, Func<CancellationToken, Task> guard, CancellationToken cancellationToken)
    {
        if (command.Action == "import")
            return await ImportAsync(command, algorithms, guard, cancellationToken);
        if (command.Action is "package-get" or "grant-get" or "artifact-get" or "batch-get" or "origin-get")
            return await OwnTransactionAsync(async token =>
            {
                await guard(token);
                return await ReadTransferAsync(command, algorithms, token);
            }, cancellationToken);
        if (command.Action == "start-reconcile")
            return await ReconcileStartAsync(command, algorithms, guard, cancellationToken);
        if (db.Database.CurrentTransaction is not null)
            throw new InvalidOperationException("Offline transfer receipts own their transaction.");
        var operation = "h5.offline." + command.Action + ".v1";
        var fingerprint = Digest(JsonSerializer.Serialize(new
        {
            command.ProjectId,
            command.Action,
            command.ResourceId,
            command.Input
        }, Json));
        var receipt = await new IdempotencyOperationService(db).ExecuteSerializableAsync(command.ActorId,
            command.ProjectId, operation, command.Key!, fingerprint, async token =>
            {
                await guard(token);
                if (await db.IdempotencyRecords.AsNoTracking().AnyAsync(row => row.ActorUserId == command.ActorId &&
                    row.ProjectId == command.ProjectId && row.Operation == operation && row.IdempotencyKey == command.Key, token))
                    throw new CommittedReceipt();
                if (!await db.Projects.AsNoTracking().AnyAsync(row => row.Id == command.ProjectId &&
                    row.Status == ProjectStatus.Active, token))
                    throw new OfflineAdmissionRejectedException(409, "project_not_active");
                var result = command.Action switch
                {
                    "package-export" or "package-prepare" => await RegisterPackageAsync(command, algorithms, token),
                    "grant-issue" => await IssueGrantAsync(command, token),
                    "grant-revoke" => await RevokeGrantAsync(command, token),
                    "artifact-register" => await RegisterArtifactAsync(command, token),
                    _ => throw new OfflineAdmissionRejectedException(400, "validation_error")
                };
                await db.SaveChangesAsync(token);
                return (result.Id, JsonSerializer.Serialize(result.Value, Json));
            }, cancellationToken, receiptAccessGuard: async token =>
            {
                await guard(token);
                await GuardTransferReceiptAsync(command, token);
            });
        if (receipt.Status == IdempotencyOperationStatus.Conflict) return new(409, "idempotency_key_reused");
        return new(receipt.Status == IdempotencyOperationStatus.Replayed ? 200 : 201,
            Value: JsonSerializer.Deserialize<JsonElement>(receipt.OutcomeJson, Json),
            Replayed: receipt.Status == IdempotencyOperationStatus.Replayed);
    }

    private async Task<OfflineWorkflowFact> ImportAsync(OfflineWorkflowCommand command,
        OfflineWorkflowAlgorithms algorithms, Func<CancellationToken, Task> guard, CancellationToken cancellationToken)
    {
        if (command.Input is not OfflinePackageImportData imported || imported.Operations is null ||
            imported.BatchId == Guid.Empty || imported.PackageId == Guid.Empty || imported.GrantId == Guid.Empty ||
            imported.RecipientDeviceRegistrationId == Guid.Empty)
            throw new ArgumentException("A bounded recipient import is required.");
        var sourceBatch = await OwnTransactionAsync(async token =>
        {
            await guard(token);
            var package = await db.Set<OfflineEncryptedPackageRecord>().AsNoTracking().SingleOrDefaultAsync(row =>
                row.Id == imported.PackageId && row.ProjectId == command.ProjectId, token)
                ?? throw new OfflineAdmissionRejectedException(404, "not_found");
            return new OfflineSignedBatchData(package.SourceBatchId, package.SourceDeviceRegistrationId,
                imported.Operations, imported.SourceSignature);
        }, cancellationToken);
        return await ProcessBatchAsync(command, algorithms, guard, sourceBatch, imported, cancellationToken);
    }

    private async Task<OfflineDeviceRegistration> GuardImportTransportAsync(OfflineWorkflowCommand command,
        OfflineWorkflowAlgorithms algorithms, OfflineSignedBatchData input, OfflinePackageImportData imported,
        CancellationToken token)
    {
        if (command.Role is not (UserRoleCode.ProjectManager or UserRoleCode.RepairCrew))
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var package = await db.Set<OfflineEncryptedPackageRecord>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineEncryptedPackages] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={imported.PackageId} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(token)
            ?? throw new OfflineAdmissionRejectedException(404, "not_found");
        var grant = await db.Set<OfflineHandoverGrant>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineHandoverGrants] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={imported.GrantId} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(token)
            ?? throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        if (grant.PackageId != package.Id || grant.SourceActorId != package.OriginalActorId ||
            grant.SourceDeviceRegistrationId != package.SourceDeviceRegistrationId ||
            grant.ManifestHash != package.ManifestHash || grant.RecipientActorId != command.ActorId ||
            grant.RecipientRole != command.Role || grant.RecipientDeviceRegistrationId != imported.RecipientDeviceRegistrationId ||
            input.BatchId != package.SourceBatchId || input.SourceDeviceRegistrationId != package.SourceDeviceRegistrationId ||
            input.Signature != package.SourceSignature || imported.SourceSignature != package.SourceSignature)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        if (await db.Set<OfflineHandoverGrantRevocation>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineHandoverGrantRevocations] WITH (UPDLOCK,HOLDLOCK) WHERE [GrantId]={grant.Id}")
            .AsNoTracking().AnyAsync(token)) throw new OfflineAdmissionRejectedException(403, "handover_grant_revoked");
        if (clock.GetUtcNow() >= grant.ExpiresAt && !await db.Set<OfflineSyncBatch>().AsNoTracking().AnyAsync(row =>
            row.Id == imported.BatchId && row.GrantId == grant.Id && row.ProjectId == command.ProjectId, token))
            throw new OfflineAdmissionRejectedException(403, "handover_grant_expired");
        var recipient = await DeviceForTransferAsync(command.ProjectId, imported.RecipientDeviceRegistrationId, token);
        if (recipient.ActorId != command.ActorId || recipient.RoleSnapshot != command.Role)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var source = await DeviceForTransferAsync(command.ProjectId, package.SourceDeviceRegistrationId, token,
            allowRevokedSource: true);
        if (source.ActorId != package.OriginalActorId ||
            await db.Set<OfflineDeviceRevocation>().AsNoTracking().AnyAsync(row =>
                row.DeviceRegistrationId == source.Id && row.RevokedAt <= package.RegisteredAt, token))
            throw new OfflineAdmissionRejectedException(403, "offline_admission_proof_unavailable");
        var descriptors = input.Operations.Select(algorithms.Describe).ToArray();
        var signedManifest = Encoding.UTF8.GetString(algorithms.CanonicalManifest(command.ProjectId,
            input.BatchId, source.Id, descriptors));
        if (signedManifest != package.SignedManifestJson || Digest(signedManifest) != package.ManifestHash)
            throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
        OfflinePackageAuthentication.VerifyClaim(Encoding.UTF8.GetBytes(signedManifest),
            package.SourceSignature, source.SigningPublicKey);
        var attached = algorithms.CanonicalAttachedPayload(input.BatchId, source.Id, input.Operations,
            input.Signature);
        var cipher = JsonSerializer.Deserialize<OfflineEncryptedPackage>(package.CipherPackageJson, Json)
            ?? throw new OfflineAdmissionRejectedException(409, "offline_admission_proof_unavailable");
        OfflinePackageAuthentication.VerifyAttachedPayload(cipher, attached, source.SigningPublicKey);
        if (cipher.Header.PackageId != package.Id || cipher.Header.ProjectId != command.ProjectId ||
            cipher.Header.OriginalActorId != source.ActorId || cipher.Header.SourceDeviceId != source.DeviceId.ToString("D") ||
            OfflineCryptoFormat.PackageContentFingerprint(cipher) != package.PackageFingerprint ||
            Digest(Encoding.UTF8.GetString(attached)) != package.PayloadHash)
            throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
        var recipientKeyHash = Convert.ToHexString(SHA256.HashData(Convert.FromBase64String(recipient.EncryptionPublicKey))).ToLowerInvariant();
        if (!cipher.Recipients.Any(wrap => wrap.ActorId == recipient.ActorId &&
            wrap.DeviceId == recipient.DeviceId.ToString("D") && wrap.RecipientKeyFingerprint == recipientKeyHash))
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        OfflinePackageAuthentication.VerifyClaim(OfflineRecipientEndorsement.CanonicalClaim(new(
            command.ProjectId, package.Id, grant.Id, imported.BatchId, recipient.Id,
            package.PayloadHash)), imported.RecipientSignature, recipient.SigningPublicKey);
        using var scopeDocument = JsonDocument.Parse(grant.ScopeJson);
        var scoped = scopeDocument.RootElement.GetProperty("items").EnumerateArray().ToArray();
        if (descriptors.Length != scoped.Length || descriptors.Any(descriptor => scoped.Count(item =>
            item.GetProperty("originId").GetGuid() == descriptor.OriginId &&
            item.GetProperty("kind").GetString() == descriptor.Kind &&
            item.GetProperty("corePayloadHash").GetString() == descriptor.CorePayloadHash &&
            item.GetProperty("envelopeHash").GetString() == descriptor.EnvelopeHash &&
            item.GetProperty("taskId").GetGuid() == descriptor.TaskId &&
            item.GetProperty("assignmentId").GetGuid() == descriptor.AssignmentId &&
            item.GetProperty("snapshotId").GetGuid() == descriptor.SnapshotId &&
            (item.GetProperty("repairResourceId").ValueKind == JsonValueKind.Null
                ? (Guid?)null : item.GetProperty("repairResourceId").GetGuid()) == descriptor.RepairResourceId) != 1))
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        return source;
    }

    private async Task<(Guid Id, object Value)> RegisterPackageAsync(OfflineWorkflowCommand command,
        OfflineWorkflowAlgorithms algorithms, CancellationToken token)
    {
        if (command.Input is not OfflinePackageExportData input || input.Manifest is null ||
            input.Package is null || input.Manifest.Items is null ||
            input.SourceFileId.HasValue || command.Action == "package-export" && command.Role != UserRoleCode.RepairCrew ||
            command.Action == "package-prepare" && command.Role != UserRoleCode.Supervisor)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var source = await DeviceForTransferAsync(command.ProjectId, input.Manifest.SourceDeviceRegistrationId, token);
        if (command.Action == "package-export" && (source.ActorId != command.ActorId || source.RoleSnapshot != command.Role))
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var cipher = input.Package;
        var canonical = algorithms.CanonicalManifest(command.ProjectId, input.Manifest.SourceBatchId,
            source.Id, input.Manifest.Items);
        if (input.Manifest.Items.Any(item => item is null || item.EffectId != item.OriginId) ||
            cipher.Header.PackageId == Guid.Empty || cipher.Header.ProjectId != command.ProjectId ||
            cipher.Header.OriginalActorId != source.ActorId || cipher.Header.SourceDeviceId != source.DeviceId.ToString("D") ||
            !cipher.Header.OriginIds.Order().SequenceEqual(input.Manifest.Items.Select(item => item.OriginId).Order()))
            throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
        foreach (var item in input.Manifest.Items)
        {
            var snapshot = await db.Set<OfflineTaskSnapshot>().FromSqlInterpolated(
                $"SELECT * FROM [OfflineTaskSnapshots] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={item.SnapshotId} AND [ProjectId]={command.ProjectId}")
                .AsNoTracking().SingleOrDefaultAsync(token);
            if (snapshot is null || snapshot.DeviceRegistrationId != source.Id ||
                snapshot.OriginalActorId != source.ActorId || snapshot.TaskId != item.TaskId ||
                snapshot.AssignmentId != item.AssignmentId)
                throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        }
        OfflinePackageAuthentication.VerifyClaim(canonical, input.Manifest.Signature, source.SigningPublicKey);
        OfflinePackageAuthentication.VerifyEncryptedSignature(cipher, source.SigningPublicKey);
        var existing = await db.Set<OfflineEncryptedPackageRecord>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineEncryptedPackages] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={cipher.Header.PackageId} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(token);
        if (existing is not null) throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
        var packageJson = input.ExactCipherPackageJson;
        var manifestJson = Encoding.UTF8.GetString(canonical);
        var fingerprint = OfflineCryptoFormat.PackageContentFingerprint(cipher);
        var row = command.Action == "package-prepare"
            ? OfflineEncryptedPackageRecord.RegisterPrepared(cipher.Header.PackageId, command.ProjectId,
                source.ActorId, source.Id, input.Manifest.SourceBatchId, command.ActorId, command.Role,
                packageJson, manifestJson, input.Manifest.Signature, cipher.Header.PayloadSha256,
                fingerprint, clock.GetUtcNow())
            : OfflineEncryptedPackageRecord.Capture(cipher.Header.PackageId, command.ProjectId,
                source.ActorId, source.Id, input.Manifest.SourceBatchId, packageJson, manifestJson,
                input.Manifest.Signature, cipher.Header.PayloadSha256, fingerprint, clock.GetUtcNow());
        db.Add(row);
        TransferAudit(command, row.Id, "offline_package_registered", "OfflineEncryptedPackage", row.RegisteredAt);
        return (row.Id, new
        {
            row.Id,
            row.ProjectId,
            row.SourceBatchId,
            row.SourceDeviceRegistrationId,
            row.ManifestHash,
            row.PayloadHash,
            row.PackageFingerprint,
            row.RegistrationMode
        });
    }

    private async Task<(Guid Id, object Value)> IssueGrantAsync(OfflineWorkflowCommand command, CancellationToken token)
    {
        if (command.Role != UserRoleCode.Supervisor || command.Input is not OfflineHandoverGrantData input ||
            input.Items is null || input.Items.Length is < 1 or > 1000 || input.Items.Any(item => item is null) ||
            input.Items.Select(item => item.OriginId).Distinct().Count() != input.Items.Length)
            throw new OfflineAdmissionRejectedException(400, "validation_error");
        var package = await db.Set<OfflineEncryptedPackageRecord>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineEncryptedPackages] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.PackageId} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(token)
            ?? throw new OfflineAdmissionRejectedException(404, "not_found");
        var source = await DeviceForTransferAsync(command.ProjectId, package.SourceDeviceRegistrationId, token,
            allowRevokedSource: true);
        if (source.ActorId != package.OriginalActorId)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var recipient = await DeviceForTransferAsync(command.ProjectId, input.RecipientDeviceRegistrationId, token);
        var cipher = JsonSerializer.Deserialize<OfflineEncryptedPackage>(package.CipherPackageJson, Json)
            ?? throw new OfflineAdmissionRejectedException(409, "offline_admission_proof_unavailable");
        OfflinePackageAuthentication.VerifyEncryptedSignature(cipher, source.SigningPublicKey);
        var keyFingerprint = Convert.ToHexString(SHA256.HashData(Convert.FromBase64String(recipient.EncryptionPublicKey))).ToLowerInvariant();
        if (!cipher.Recipients.Any(wrap => wrap.ActorId == recipient.ActorId &&
            wrap.DeviceId == recipient.DeviceId.ToString("D") && wrap.RecipientKeyFingerprint == keyFingerprint))
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        using var document = JsonDocument.Parse(package.SignedManifestJson);
        var signed = document.RootElement.GetProperty("items").EnumerateArray().ToArray();
        if (input.Items.Length != signed.Length || input.Items.Any(scope => signed.Count(item =>
            item.GetProperty("originId").GetGuid() == scope.OriginId &&
            item.GetProperty("kind").GetString() == scope.Kind &&
            item.GetProperty("corePayloadHash").GetString() == scope.CorePayloadHash &&
            item.GetProperty("envelopeHash").GetString() == scope.EnvelopeHash &&
            item.GetProperty("taskId").GetGuid() == scope.TaskId &&
            item.GetProperty("assignmentId").GetGuid() == scope.AssignmentId &&
            item.GetProperty("snapshotId").GetGuid() == scope.SnapshotId &&
            (item.GetProperty("repairResourceId").ValueKind == JsonValueKind.Null
                ? (Guid?)null : item.GetProperty("repairResourceId").GetGuid()) == scope.RepairResourceId) != 1))
            throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
        var scopeJson = JsonSerializer.Serialize(new { items = input.Items }, Json);
        var grant = OfflineHandoverGrant.Issue(Guid.NewGuid(), command.ProjectId, package.Id,
            package.OriginalActorId, source.Id, recipient.ActorId, recipient.Id, recipient.RoleSnapshot,
            command.ActorId, command.Role, clock.GetUtcNow(), package.ManifestHash, scopeJson, input.Reason);
        db.AddRange(grant, DeadlineClock.Create(Guid.NewGuid(), command.ProjectId,
            DeadlineClockKind.DeviceHandover, grant.Id, grant.Id, grant.IssuedAt));
        TransferAudit(command, grant.Id, "offline_handover_grant_issued", "OfflineHandoverGrant", grant.IssuedAt);
        return (grant.Id, GrantView(grant, null));
    }

    private async Task<(Guid Id, object Value)> RevokeGrantAsync(OfflineWorkflowCommand command, CancellationToken token)
    {
        if (command.Role != UserRoleCode.Supervisor || command.ResourceId is not Guid grantId ||
            command.Input is not OfflineGrantRevokeData input)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var grant = await db.Set<OfflineHandoverGrant>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineHandoverGrants] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={grantId} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(token) ?? throw new OfflineAdmissionRejectedException(404, "not_found");
        if (await db.Set<OfflineHandoverGrantRevocation>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineHandoverGrantRevocations] WITH (UPDLOCK,HOLDLOCK) WHERE [GrantId]={grantId}")
            .AsNoTracking().AnyAsync(token)) throw new OfflineAdmissionRejectedException(409, "handover_grant_revoked");
        var revocation = OfflineHandoverGrantRevocation.Record(Guid.NewGuid(), command.ProjectId, grant.Id,
            command.ActorId, input.Reason, clock.GetUtcNow());
        db.Add(revocation);
        TransferAudit(command, revocation.Id, "offline_handover_grant_revoked", "OfflineHandoverGrant", revocation.RevokedAt);
        return (revocation.Id, GrantView(grant, revocation));
    }

    private async Task<(Guid Id, object Value)> RegisterArtifactAsync(OfflineWorkflowCommand command,
        CancellationToken token)
    {
        if (command.Input is not OfflineCaptureArtifactData input || input.Manifest is null ||
            input.Envelope is null || input.Manifest.Chunks is null)
            throw new OfflineAdmissionRejectedException(400, "validation_error");
        var package = await db.Set<OfflineEncryptedPackageRecord>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineEncryptedPackages] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.Manifest.ParentPackageId} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(token)
            ?? throw new OfflineAdmissionRejectedException(404, "not_found");
        var source = await DeviceForTransferAsync(command.ProjectId, package.SourceDeviceRegistrationId, token,
            allowRevokedSource: true);
        if (source.ActorId != package.OriginalActorId ||
            await db.Set<OfflineDeviceRevocation>().AsNoTracking().AnyAsync(row =>
                row.DeviceRegistrationId == source.Id && row.RevokedAt <= package.RegisteredAt, token))
            throw new OfflineAdmissionRejectedException(403, "offline_admission_proof_unavailable");
        if (command.Role != UserRoleCode.Supervisor &&
            (source.ActorId != command.ActorId || source.RoleSnapshot != command.Role ||
            await db.Set<OfflineDeviceRevocation>().AsNoTracking().AnyAsync(row =>
                row.DeviceRegistrationId == source.Id, token)))
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var artifact = OfflineEncryptedCaptureArtifact.Register(package, source, input.Manifest,
            input.ManifestSignature, input.ChunkIndex, input.Envelope, command.ActorId,
            clock.GetUtcNow());
        if (await db.Set<OfflineEncryptedCaptureArtifact>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineEncryptedCaptureArtifacts] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={artifact.Id}")
            .AsNoTracking().AnyAsync(token)) throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
        db.Add(artifact);
        TransferAudit(command, artifact.Id, "offline_capture_artifact_registered",
            "OfflineEncryptedCaptureArtifact", artifact.RegisteredAt);
        return (artifact.Id, new
        {
            artifact.Id,
            artifact.ParentPackageId,
            artifact.CaptureOriginId,
            artifact.TaskId,
            artifact.ChunkIndex,
            artifact.EnvelopeFingerprint,
            artifact.ManifestHash
        });
    }

    private async Task<OfflineWorkflowFact> ReadTransferAsync(OfflineWorkflowCommand command,
        OfflineWorkflowAlgorithms algorithms, CancellationToken token)
    {
        if (command.ResourceId is not Guid id || id == Guid.Empty)
            throw new OfflineAdmissionRejectedException(400, "validation_error");
        if (command.Action == "grant-get")
        {
            var grant = await db.Set<OfflineHandoverGrant>().AsNoTracking().SingleOrDefaultAsync(row =>
                row.Id == id && row.ProjectId == command.ProjectId, token);
            if (grant is null) return new(404, "not_found");
            if (command.Role != UserRoleCode.Supervisor &&
                (grant.RecipientActorId != command.ActorId || grant.RecipientRole != command.Role ||
                 await db.Set<OfflineDeviceRevocation>().AsNoTracking().AnyAsync(row =>
                     row.DeviceRegistrationId == grant.RecipientDeviceRegistrationId, token)))
                return new(403, "access_forbidden");
            var revoked = await db.Set<OfflineHandoverGrantRevocation>().AsNoTracking()
                .SingleOrDefaultAsync(row => row.GrantId == id, token);
            return new(200, Value: GrantView(grant, revoked));
        }
        if (command.Action == "package-get")
        {
            var package = await db.Set<OfflineEncryptedPackageRecord>().AsNoTracking().SingleOrDefaultAsync(row =>
                row.Id == id && row.ProjectId == command.ProjectId, token);
            if (package is null) return new(404, "not_found");
            if (package.OriginalActorId != command.ActorId && command.Role != UserRoleCode.Supervisor &&
                !await HasCurrentRecipientGrantAsync(command, id, token))
                return new(403, "access_forbidden");
            return new(200, Value: new
            {
                package.Id,
                package.ProjectId,
                package.OriginalActorId,
                package.SourceDeviceRegistrationId,
                package.SourceBatchId,
                package.ManifestHash,
                package.PayloadHash,
                package.CipherPackageJson,
                package.SignedManifestJson,
                package.SourceSignature
            });
        }
        if (command.Action == "artifact-get")
        {
            var artifact = await db.Set<OfflineEncryptedCaptureArtifact>().AsNoTracking().SingleOrDefaultAsync(row =>
                row.Id == id && row.ProjectId == command.ProjectId, token);
            if (artifact is null) return new(404, "not_found");
            if (command.Role != UserRoleCode.Supervisor && artifact.OriginalActorId != command.ActorId)
            {
                if (!await HasCurrentRecipientGrantAsync(command, artifact.ParentPackageId, token))
                    return new(403, "access_forbidden");
            }
            return new(200, Value: new
            {
                artifact.Id,
                artifact.ProjectId,
                artifact.ParentPackageId,
                artifact.CaptureOriginId,
                artifact.TaskId,
                artifact.OriginalActorId,
                artifact.SourceDeviceRegistrationId,
                artifact.ChunkIndex,
                artifact.ChunkOffset,
                artifact.ChunkLength,
                artifact.PlaintextChecksum,
                artifact.EnvelopeFingerprint,
                artifact.ManifestHash,
                artifact.SignedManifestJson,
                artifact.ManifestSignature,
                artifact.CipherEnvelopeJson
            });
        }
        if (command.Action == "batch-get")
        {
            var batch = await db.Set<OfflineSyncBatch>().FromSqlInterpolated(
                $"SELECT * FROM [OfflineSyncBatches] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={id} AND [ProjectId]={command.ProjectId}")
                .AsNoTracking().SingleOrDefaultAsync(token);
            if (batch is null) return new(404, "not_found");
            var signed = await GuardBatchStatusAsync(command, algorithms, batch, token);
            var admissions = await db.Set<OfflineOperationAdmission>().AsNoTracking()
                .Where(row => row.BatchId == batch.Id).ToArrayAsync(token);
            var results = await db.Set<OfflineOperationResult>().AsNoTracking()
                .Where(row => row.BatchId == batch.Id).OrderByDescending(row => row.RecordedAt)
                .ThenByDescending(row => row.Id).ToArrayAsync(token);
            var current = results.GroupBy(row => row.OriginId).ToDictionary(group => group.Key,
                group => group.OrderByDescending(row => row.DurableAck).ThenByDescending(row => row.RecordedAt)
                    .ThenByDescending(row => row.Id).First());
            var originIds = signed.Operations.Select(row => row.OriginId).ToArray();
            var canonical = await db.Set<RoadGuardSystem.BusinessObjects.Inspections.FieldInspectionOperationOrigin>()
                .AsNoTracking().Where(row => row.ProjectId == command.ProjectId && originIds.Contains(row.OriginId))
                .ToDictionaryAsync(row => row.OriginId, row => row.Id, token);
            var items = signed.Operations.Select(operation => current.TryGetValue(operation.OriginId, out var result)
                ? ItemView(result, operation.Kind, result.DurableAck
                    ? canonical.GetValueOrDefault(operation.OriginId) : Guid.Empty)
                : new OfflineItemFact(operation.OriginId, operation.Kind, "PENDING_DEPENDENCY", "not_processed",
                    null, null, false, batch.ReceivedAt, "UNCERTAIN", "UNKNOWN",
                    operation.ClaimedFinishedAt, null, null, null)).ToArray();
            if (admissions.Length != signed.Operations.Length)
                throw new OfflineAdmissionRejectedException(409, "offline_admission_proof_unavailable");
            return new(200, Value: new OfflineBatchFact(batch.Id, items));
        }
        if (command.Action == "origin-get")
        {
            var binding = await db.Set<OfflineOperationBinding>().AsNoTracking().SingleOrDefaultAsync(row =>
                row.ProjectId == command.ProjectId && row.OriginId == id, token);
            if (binding is null) return new(404, "not_found");
            var admissions = await db.Set<OfflineOperationAdmission>().AsNoTracking()
                .Where(row => row.BindingId == binding.Id && row.CurrentImporterId == command.ActorId &&
                    row.ImporterRole == command.Role).OrderByDescending(row => row.AdmittedAt).ToArrayAsync(token);
            if (admissions.Length == 0) return new(403, "access_forbidden");
            var admission = admissions[0];
            var batch = await db.Set<OfflineSyncBatch>().AsNoTracking().SingleAsync(row =>
                row.Id == admission.BatchId && row.ProjectId == command.ProjectId, token);
            await GuardBatchStatusAsync(command, algorithms, batch, token);
            var result = await db.Set<OfflineOperationResult>().AsNoTracking()
                .Where(row => row.AdmissionId == admission.Id).OrderByDescending(row => row.DurableAck)
                .ThenByDescending(row => row.RecordedAt)
                .ThenByDescending(row => row.Id).FirstOrDefaultAsync(token);
            var canonical = result?.DurableAck == true
                ? await db.Set<RoadGuardSystem.BusinessObjects.Inspections.FieldInspectionOperationOrigin>()
                    .AsNoTracking().Where(row => row.ProjectId == command.ProjectId && row.OriginId == id)
                    .Select(row => row.Id).SingleOrDefaultAsync(token)
                : Guid.Empty;
            return new(200, Value: result is null
                ? new OfflineItemFact(id, binding.Kind, "PENDING_DEPENDENCY", "not_processed", null,
                    null, false, batch.ReceivedAt, "UNCERTAIN", "UNKNOWN", null, null, null, null)
                : ItemView(result, binding.Kind, canonical));
        }
        return new(409, "offline_admission_not_ready");
    }

    private Task<bool> HasCurrentRecipientGrantAsync(OfflineWorkflowCommand command, Guid packageId,
        CancellationToken token)
    {
        var now = clock.GetUtcNow();
        return db.Set<OfflineHandoverGrant>().AsNoTracking().AnyAsync(grant =>
            grant.ProjectId == command.ProjectId && grant.PackageId == packageId &&
            grant.RecipientActorId == command.ActorId && grant.RecipientRole == command.Role &&
            grant.ExpiresAt > now &&
            !db.Set<OfflineHandoverGrantRevocation>().Any(row => row.GrantId == grant.Id) &&
            !db.Set<OfflineDeviceRevocation>().Any(row =>
                row.DeviceRegistrationId == grant.RecipientDeviceRegistrationId), token);
    }

    private async Task<OfflineSignedBatchData> GuardBatchStatusAsync(OfflineWorkflowCommand command,
        OfflineWorkflowAlgorithms algorithms, OfflineSyncBatch batch, CancellationToken token)
    {
        if (batch.CurrentImporterId != command.ActorId || batch.AttachedPayloadJson is null ||
            batch.AttachedPayloadHash != Digest(batch.AttachedPayloadJson))
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var signed = JsonSerializer.Deserialize<OfflineSignedBatchData>(batch.AttachedPayloadJson, Json)
            ?? throw new OfflineAdmissionRejectedException(409, "offline_admission_proof_unavailable");
        if (signed.BatchId != batch.SourceBatchId || signed.SourceDeviceRegistrationId != batch.SourceDeviceRegistrationId ||
            signed.Signature != batch.SourceSignature || signed.Operations is null ||
            signed.Operations.Length is < 1 or > 1000)
            throw new OfflineAdmissionRejectedException(409, "offline_admission_proof_unavailable");
        if (batch.GrantId is null)
            await GuardSyncSourceAsync(command, batch.SourceDeviceRegistrationId, token);
        else
        {
            if (batch.PackageId is null || batch.RecipientDeviceRegistrationId is null ||
                batch.RecipientSignature is null)
                throw new OfflineAdmissionRejectedException(409, "offline_admission_proof_unavailable");
            await GuardImportTransportAsync(command, algorithms, signed,
                new(batch.Id, batch.PackageId.Value, batch.GrantId.Value,
                    batch.RecipientDeviceRegistrationId.Value, signed.Operations, batch.SourceSignature,
                    batch.RecipientSignature), token);
        }
        return signed;
    }

    private async Task<OfflineWorkflowFact> ReconcileStartAsync(OfflineWorkflowCommand command,
        OfflineWorkflowAlgorithms algorithms, Func<CancellationToken, Task> guard, CancellationToken cancellationToken)
    {
        if (command.Input is not OfflineStartReconcileData input || input.BatchId == Guid.Empty ||
            input.OriginId == Guid.Empty)
            throw new OfflineAdmissionRejectedException(400, "validation_error");
        var signed = await OwnTransactionAsync(async token =>
        {
            await guard(token);
            var batch = await db.Set<OfflineSyncBatch>().FromSqlInterpolated(
                $"SELECT * FROM [OfflineSyncBatches] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.BatchId} AND [ProjectId]={command.ProjectId}")
                .AsNoTracking().SingleOrDefaultAsync(token)
                ?? throw new OfflineAdmissionRejectedException(404, "not_found");
            var source = await GuardBatchStatusAsync(command, algorithms, batch, token);
            if (source.Operations.Length != 1 || source.Operations[0].Kind != "FIELD_START" ||
                source.Operations[0].OriginId != input.OriginId)
                throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
            return (batch, source);
        }, cancellationToken);
        if (signed.batch.GrantId is null)
            return await ProcessBatchAsync(command, algorithms, guard, signed.source, null, cancellationToken);
        return await ProcessBatchAsync(command, algorithms, guard, signed.source,
            new(signed.batch.Id, signed.batch.PackageId!.Value, signed.batch.GrantId.Value,
                signed.batch.RecipientDeviceRegistrationId!.Value, signed.source.Operations,
                signed.batch.SourceSignature, signed.batch.RecipientSignature!), cancellationToken);
    }

    private async Task GuardTransferReceiptAsync(OfflineWorkflowCommand command, CancellationToken token)
    {
        if (command.Action is "package-export" or "package-prepare")
        {
            if (command.Input is not OfflinePackageExportData input) throw new OfflineAdmissionRejectedException(400, "validation_error");
            var source = await DeviceForTransferAsync(command.ProjectId, input.Manifest.SourceDeviceRegistrationId, token);
            if (command.Action == "package-export" && source.ActorId != command.ActorId)
                throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        }
        if ((command.Action is "grant-issue" or "grant-revoke") && command.Role != UserRoleCode.Supervisor)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
    }

    private async Task<OfflineDeviceRegistration> DeviceForTransferAsync(Guid projectId, Guid registrationId,
        CancellationToken token, bool allowRevokedSource = false)
    {
        var device = await db.Set<OfflineDeviceRegistration>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineDeviceRegistrations] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={registrationId} AND [ProjectId]={projectId}")
            .AsNoTracking().SingleOrDefaultAsync(token) ?? throw new OfflineAdmissionRejectedException(404, "not_found");
        if (!allowRevokedSource && await db.Set<OfflineDeviceRevocation>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineDeviceRevocations] WITH (UPDLOCK,HOLDLOCK) WHERE [DeviceRegistrationId]={device.Id}")
            .AsNoTracking().AnyAsync(token)) throw new OfflineAdmissionRejectedException(403, "offline_key_revoked");
        return device;
    }

    private void TransferAudit(OfflineWorkflowCommand command, Guid eventId, string action,
        string sourceKind, DateTimeOffset at)
    {
        db.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), command.ActorId, at, action,
            sourceKind, eventId, null, JsonSerializer.Serialize(new { command.ProjectId, eventId }, Json),
            null, "h5.offline.v1", eventId, ["projectId", "eventId"]));
        db.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), action.Replace('_', '.') + ".v1", at,
            eventId, JsonSerializer.Serialize(new
            {
                projectId = command.ProjectId,
                sourceKind,
                sourceId = eventId,
                originEventId = eventId,
                occurredAtUtc = at
            }, Json)));
    }

    private static object GrantView(OfflineHandoverGrant row, OfflineHandoverGrantRevocation? revoked)
        => new
        {
            row.Id,
            row.ProjectId,
            row.PackageId,
            row.SourceActorId,
            row.SourceDeviceRegistrationId,
            row.RecipientActorId,
            row.RecipientDeviceRegistrationId,
            role = row.RecipientRole.ToString(),
            row.IssuedBy,
            row.IssuedAt,
            row.ExpiresAt,
            row.ManifestHash,
            row.ScopeJson,
            revokedAt = revoked?.RevokedAt
        };
}

[HttpPost("devices/{registrationId:guid}/revoke")]
public Task<IActionResult> RevokeDevice(Guid projectId, Guid registrationId, OfflineDeviceRevokeInput input,
    CancellationToken cancellationToken)
    => Run(projectId, "device-revoke", input, registrationId, cancellationToken);

    private async Task<IActionResult> Run(Guid projectId, string action, object? input, Guid? resourceId,
        CancellationToken cancellationToken)
    {
        if (!Guid.TryParse(User.FindFirstValue(JwtRegisteredClaimNames.Sub), out var actor) ||
            !ProjectRoleClaimParser.TryParse(User.FindFirstValue("role"), out var role)) return Error(401, "unauthorized");
        string? key = null;
        if (Request.Headers.TryGetValue("Idempotency-Key", out var keys))
        {
            if (keys.Count != 1) return Error(400, "validation_error");
            key = keys.ToString();
        }
        if (Request.Headers.IfMatch.Count > 1) return Error(400, "validation_error");
        var result = await service.ExecuteAsync(actor, role, projectId, action, input, resourceId, key,
            Request.Headers.IfMatch.Count == 0 ? null : Request.Headers.IfMatch.ToString(), cancellationToken);
        if (result.Code is not null) return Error(result.Status, result.Code);
        if (result.Version is not null) Response.Headers.ETag = $"\"{result.Version}\"";
        return StatusCode(result.Status, result.Value);
    }

    private ObjectResult Error(int status, string code)
    {
        var problem = new ProblemDetails { Status = status, Title = "Offline request failed", Instance = Request.Path };
        problem.Extensions["code"] = code;
        problem.Extensions["correlationId"] = HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString() ?? Guid.NewGuid().ToString();
        return new(problem) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }
}

using System.Data;
using System.Security.Cryptography;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Auditing;
using RoadGuardSystem.BusinessObjects.Messaging;
using RoadGuardSystem.BusinessObjects.Offline;
using RoadGuardSystem.BusinessObjects.Inspections;
using RoadGuardSystem.Repositories.Idempotency;
using RoadGuardSystem.Repositories.Integration;
using RoadGuardSystem.Repositories.Inspections;
using RoadGuardSystem.Repositories.Offline;

namespace RoadGuardSystem.Repositories.Implementations.Offline;

public sealed partial class OfflineWorkflowRepository(RoadGuardDbContext db, TimeProvider clock,
    IFieldInspectionWorkflowRepository? fieldCore = null,
    IOfflineFieldAdmissionValidator? fieldAdmission = null,
    IOfflineRepairCommandAdapter? repairCore = null) : IOfflineWorkflowRepository
{
    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web);
    private sealed class CommittedReceipt : Exception { }
    public async Task<OfflineWorkflowFact> ExecuteAsync(OfflineWorkflowCommand command, OfflineWorkflowAlgorithms algorithms,
        Func<CancellationToken, Task<bool>> currentProjectGuard, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(command); ArgumentNullException.ThrowIfNull(algorithms);
        ArgumentNullException.ThrowIfNull(currentProjectGuard);
        async Task Guard(CancellationToken token)
        {
            await Anh02ReceiptAuthority.LockAsync(db, command.ActorId, command.ProjectId, token);
            if (!await new AnhHuyFactsRepository(db).IsCurrentActorAsync(command.ActorId, command.Role, token) ||
                !await currentProjectGuard(token))
                throw new OfflineAdmissionRejectedException(403, "access_forbidden");
            if (command.Action == "device-register" && command.Role is not (UserRoleCode.ProjectManager or UserRoleCode.RepairCrew))
                throw new OfflineAdmissionRejectedException(403, "access_forbidden");
            if (command.Action == "device-revoke")
                await GuardDeviceResourceAsync(command, token);
            if (command.Action == "snapshot-create")
                await GuardSnapshotScopeAsync(command, token);
        }
        try
        {
            if (command.Action == "sync")
                return await SynchronizeAsync(command, algorithms, Guard, cancellationToken);
            if (command.Action is "package-export" or "package-prepare" or "grant-issue" or "grant-revoke" or
                "artifact-register" or "import" or "start-reconcile" or "package-get" or "grant-get" or
                "artifact-get" or "batch-get" or "origin-get")
                return await ExecuteTransferAsync(command, algorithms, Guard, cancellationToken);
            if (command.Action is "device-register" or "device-revoke" or "snapshot-create")
            {
                if (db.Database.CurrentTransaction is not null)
                    throw new InvalidOperationException("Offline command receipts own their transaction.");
                var operation = "h5.offline." + command.Action + ".v1";
                var fingerprint = command.Action == "device-revoke"
                    ? Digest(JsonSerializer.Serialize(new { command.ProjectId, command.Action, command.ResourceId, command.Input }, Json))
                    : Digest(JsonSerializer.Serialize(new { command.ProjectId, command.Action, command.Input }, Json));
                var receipt = await new IdempotencyOperationService(db).ExecuteSerializableAsync(command.ActorId, command.ProjectId,
                    operation, command.Key!, fingerprint, async token =>
                    {
                        await Guard(token);
                        if (await db.IdempotencyRecords.AsNoTracking().AnyAsync(row => row.ActorUserId == command.ActorId &&
                            row.ProjectId == command.ProjectId && row.Operation == operation && row.IdempotencyKey == command.Key, token))
                            throw new CommittedReceipt();
                        if (!await db.Projects.AsNoTracking().AnyAsync(row => row.Id == command.ProjectId && row.Status == ProjectStatus.Active, token))
                            throw new OfflineAdmissionRejectedException(409, "project_not_active");
                        var value = command.Action switch
                        {
                            "device-register" => await RegisterDeviceResultAsync(command, token),
                            "device-revoke" => await RevokeDeviceResultAsync(command, token),
                            _ => await CaptureSnapshotAsync(command, token)
                        };
                        await db.SaveChangesAsync(token);
                        return (value.Id, JsonSerializer.Serialize(value.Value, Json));
                    }, cancellationToken, receiptAccessGuard: Guard);
                if (receipt.Status == IdempotencyOperationStatus.Conflict) return new(409, "idempotency_key_reused");
                return new(receipt.Status == IdempotencyOperationStatus.Replayed ? 200 : 201,
                    Value: JsonSerializer.Deserialize<JsonElement>(receipt.OutcomeJson, Json), Replayed: receipt.Status == IdempotencyOperationStatus.Replayed);
            }
            async Task<OfflineWorkflowFact> Read(CancellationToken token)
            {
                await Guard(token);
                if (command.Action == "device-get")
                {
                    var device = await db.Set<OfflineDeviceRegistration>().AsNoTracking().SingleOrDefaultAsync(row =>
                        row.Id == command.ResourceId && row.ProjectId == command.ProjectId, token);
                    if (device is null) return new(404, "not_found");
                    if (command.Role == UserRoleCode.RepairCrew && device.ActorId != command.ActorId) return new(403, "access_forbidden");
                    var revoked = await db.Set<OfflineDeviceRevocation>().AsNoTracking().SingleOrDefaultAsync(row =>
                        row.DeviceRegistrationId == device.Id && row.ProjectId == command.ProjectId, token);
                    return new(200, Value: DeviceView(device, revoked));
                }
                if (command.Action == "snapshot-get")
                {
                    var snapshot = await db.Set<OfflineTaskSnapshot>().FromSqlInterpolated(
                        $"SELECT * FROM [OfflineTaskSnapshots] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={command.ResourceId} AND [ProjectId]={command.ProjectId}")
                        .AsNoTracking().SingleOrDefaultAsync(token);
                    if (snapshot is null) return new(404, "not_found");
                    if (command.Role != UserRoleCode.RepairCrew || snapshot.OriginalActorId != command.ActorId ||
                        !await db.Set<OfflineDeviceRegistration>().AsNoTracking().AnyAsync(device =>
                            device.Id == snapshot.DeviceRegistrationId && device.ProjectId == command.ProjectId &&
                            device.ActorId == command.ActorId && device.RoleSnapshot == command.Role, token) ||
                        await db.Set<OfflineDeviceRevocation>().AsNoTracking().AnyAsync(revocation =>
                            revocation.DeviceRegistrationId == snapshot.DeviceRegistrationId, token) ||
                        !await db.FieldInspectionTasks.AsNoTracking().AnyAsync(task =>
                            task.Id == snapshot.TaskId && task.ProjectId == command.ProjectId, token) ||
                        !await db.FieldInspectionAssignments.AsNoTracking().AnyAsync(assignment =>
                            assignment.Id == snapshot.AssignmentId && assignment.FieldInspectionTaskId == snapshot.TaskId &&
                            assignment.AssignedToUserId == command.ActorId &&
                            assignment.Status == FieldInspectionAssignmentStatus.Active && assignment.EndedAt == null, token))
                        return new(403, "access_forbidden");
                    return new(200, Value: SnapshotView(snapshot));
                }
                throw new OfflineAdmissionRejectedException(400, "validation_error");
            }
            if (db.Database.CurrentTransaction is not null) return await Read(cancellationToken);
            return await db.Database.CreateExecutionStrategy().ExecuteAsync(async () =>
            {
                await using var transaction = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable, cancellationToken);
                var result = await Read(cancellationToken);
                await transaction.CommitAsync(cancellationToken); return result;
            });
        }
        catch (CommittedReceipt)
        {
            db.ChangeTracker.Clear(); return await ExecuteAsync(command, algorithms, currentProjectGuard, cancellationToken);
        }
        catch (OfflineAdmissionRejectedException rejected) { return new(rejected.Status, rejected.Code); }
        catch (ArgumentException) { return new(400, "validation_error"); }
        catch (JsonException) { return new(400, "validation_error"); }
        catch (CryptographicException) { return new(400, "offline_signature_invalid"); }
    }

    private static string Digest(string value) => Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(value))).ToLowerInvariant();

    private async Task<(Guid Id, object Value)> RegisterDeviceResultAsync(OfflineWorkflowCommand command, CancellationToken cancellationToken)
    {
        var row = await RegisterDeviceAsync(command, cancellationToken); return (row.Id, DeviceView(row, null));
    }

    private async Task<(Guid Id, object Value)> RevokeDeviceResultAsync(OfflineWorkflowCommand command,
        CancellationToken cancellationToken)
    {
        if (command.Input is not OfflineDeviceRevokeData input || command.ResourceId is not Guid id ||
            string.IsNullOrWhiteSpace(input.Reason)) throw new ArgumentException("A bounded device and reason are required.");
        var device = await db.Set<OfflineDeviceRegistration>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineDeviceRegistrations] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={id} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(cancellationToken);
        if (device is null) throw new OfflineAdmissionRejectedException(404, "not_found");
        if (device.ActorId != command.ActorId || device.RoleSnapshot != command.Role)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        if (await db.Set<OfflineDeviceRevocation>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineDeviceRevocations] WITH (UPDLOCK,HOLDLOCK) WHERE [DeviceRegistrationId]={id}")
            .AsNoTracking().AnyAsync(cancellationToken))
            throw new OfflineAdmissionRejectedException(409, "offline_key_revoked");
        var row = OfflineDeviceRevocation.Record(Guid.NewGuid(), command.ProjectId, id, command.ActorId,
            clock.GetUtcNow(), input.Reason);
        db.Add(row);
        db.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), command.ActorId, row.RevokedAt, "offline_device_revoked",
            "OfflineDeviceRegistration", id, null, JsonSerializer.Serialize(new { row.Id, row.DeviceRegistrationId }, Json),
            row.Reason, "h5.offline.v1", row.Id, ["deviceRegistrationId"]));
        db.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), "offline.device.revoked.v1", row.RevokedAt,
            id, JsonSerializer.Serialize(new
            {
                projectId = command.ProjectId,
                sourceKind = "OfflineDeviceRegistration",
                sourceId = id,
                originEventId = row.Id,
                occurredAtUtc = row.RevokedAt
            }, Json)));
        return (row.Id, DeviceView(device, row));
    }

    private async Task GuardDeviceResourceAsync(OfflineWorkflowCommand command, CancellationToken cancellationToken)
    {
        if (command.ResourceId is not Guid id || id == Guid.Empty)
            throw new ArgumentException("A device registration is required.");
        var device = await db.Set<OfflineDeviceRegistration>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineDeviceRegistrations] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={id} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(cancellationToken);
        if (device is null) throw new OfflineAdmissionRejectedException(404, "not_found");
        if (device.ActorId != command.ActorId || device.RoleSnapshot != command.Role)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
    }

    private async Task<(Guid Id, object Value)> CaptureSnapshotAsync(OfflineWorkflowCommand command, CancellationToken cancellationToken)
    {
        var (device, task, assignment) = await GuardSnapshotScopeAsync(command, cancellationToken);
        if (task.LifecycleVersion != 2 || task.Status is FieldInspectionTaskStatus.Completed or FieldInspectionTaskStatus.Cancelled or FieldInspectionTaskStatus.Rejected)
            throw new OfflineAdmissionRejectedException(409, "source_not_ready");
        if (task.SegmentSetId is null || fieldCore is null)
            throw new OfflineAdmissionRejectedException(409, "offline_location_source_unavailable");
        object location;
        try
        {
            var geometry = await fieldCore.ApplyInTransactionAsync(new(command.ProjectId, task.Id, "geometry",
                null, null, null, new(command.ActorId, command.Role, command.ActorId, "DIRECT", false)),
                _ => Task.FromResult(true), cancellationToken);
            if (geometry.Status != 200 || geometry.Value is null)
                throw new OfflineAdmissionRejectedException(geometry.Status,
                    geometry.Code ?? "offline_location_source_unavailable");
            location = geometry.Value;
        }
        catch (FieldCoreRejectedException rejected)
        {
            throw new OfflineAdmissionRejectedException(rejected.Result.Status,
                rejected.Result.Code ?? "offline_location_source_unavailable");
        }
        object? repairSource = null;
        if (task.RepairItemId is Guid repairItemId)
        {
            if (repairCore is null)
                throw new OfflineAdmissionRejectedException(409, "repair_adapter_not_ready");
            var facts = await repairCore.ReadSnapshotInTransactionAsync(new(command.ProjectId, task.Id,
                command.ActorId, command.Role), cancellationToken);
            if (facts is null || facts.ItemId != repairItemId || facts.TaskId != task.Id ||
                facts.AssignmentId != assignment.Id || facts.OriginalActorId != command.ActorId)
                throw new OfflineAdmissionRejectedException(409, "repair_snapshot_source_unavailable");
            repairSource = facts.SafePayload;
        }
        var assignmentJson = JsonSerializer.Serialize(new
        {
            assignment.Id,
            assignment.FieldInspectionTaskId,
            assignment.AssignedToUserId,
            assignment.AssignedByUserId,
            assignment.AssignedAt
        }, Json);
        var payload = JsonSerializer.Serialize(new
        {
            task.Id,
            task.ProjectId,
            task.DefectId,
            task.SurveyId,
            task.SourceKind,
            task.RoadSectionVersionId,
            task.SegmentSetId,
            task.LayoutRevisionId,
            task.SlabId,
            task.MapPublicationId,
            task.CrsProfileRevisionId,
            task.RequiredMeasurementType,
            task.MeasurementScope,
            task.Instructions,
            task.TaskMode,
            task.RepairItemId,
            purpose = task.Purpose.ToString(),
            status = task.Status.ToString(),
            task.DueAt,
            assignmentId = assignment.Id,
            originalActorId = assignment.AssignedToUserId,
            location,
            repair = repairSource
        }, Json);
        var row = OfflineTaskSnapshot.Capture(Guid.NewGuid(), command.ProjectId, task.Id, assignment.Id,
            command.ActorId, device.Id, Convert.ToBase64String(task.RowVersion), Digest(assignmentJson), payload, clock.GetUtcNow());
        db.Add(row);
        return (row.Id, SnapshotView(row));
    }

    private static object SnapshotView(OfflineTaskSnapshot row) => new
    {
        row.Id,
        row.TaskId,
        row.AssignmentId,
        row.OriginalActorId,
        row.DeviceRegistrationId,
        row.TaskVersion,
        row.AssignmentHash,
        row.ContentHash,
        row.DownloadedAt,
        snapshot = JsonSerializer.Deserialize<JsonElement>(row.SnapshotJson, Json)
    };

    private async Task<(OfflineDeviceRegistration Device, FieldInspectionTask Task, FieldInspectionAssignment Assignment)>
        GuardSnapshotScopeAsync(OfflineWorkflowCommand command, CancellationToken cancellationToken)
    {
        if (command.Input is not OfflineSnapshotData input) throw new ArgumentException("Typed snapshot input is required.");
        var device = await db.Set<OfflineDeviceRegistration>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineDeviceRegistrations] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.DeviceRegistrationId} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(cancellationToken);
        if (device is null || device.ActorId != command.ActorId || device.RoleSnapshot != command.Role ||
            await db.Set<OfflineDeviceRevocation>().FromSqlInterpolated(
                $"SELECT * FROM [OfflineDeviceRevocations] WITH (UPDLOCK,HOLDLOCK) WHERE [DeviceRegistrationId]={input.DeviceRegistrationId}")
                .AsNoTracking().AnyAsync(cancellationToken))
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var task = await db.FieldInspectionTasks.FromSqlInterpolated(
            $"SELECT * FROM [FieldInspectionTasks] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={input.TaskId} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(cancellationToken);
        if (task is null) throw new OfflineAdmissionRejectedException(404, "not_found");
        var assignment = await db.FieldInspectionAssignments.FromSqlInterpolated(
            $"SELECT * FROM [FieldInspectionAssignments] WITH (UPDLOCK,HOLDLOCK) WHERE [FieldInspectionTaskId]={task.Id}")
            .AsNoTracking().SingleOrDefaultAsync(row => row.AssignedToUserId == command.ActorId &&
                row.Status == FieldInspectionAssignmentStatus.Active && row.EndedAt == null, cancellationToken);
        if (assignment is null) throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        return (device, task, assignment);
    }

    private async Task<OfflineDeviceRegistration> RegisterDeviceAsync(OfflineWorkflowCommand command, CancellationToken cancellationToken)
    {
        if (command.Input is not OfflineDeviceRegisterData input) throw new ArgumentException("Typed device registration is required.");
        var registrations = await db.Set<OfflineDeviceRegistration>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineDeviceRegistrations] WITH (UPDLOCK,HOLDLOCK) WHERE [ProjectId]={command.ProjectId} AND [ActorId]={command.ActorId} AND [DeviceId]={input.DeviceId}")
            .AsNoTracking().ToArrayAsync(cancellationToken);
        var proposed = OfflineDeviceRegistration.Register(Guid.NewGuid(), command.ProjectId, command.ActorId, input.DeviceId, 1,
            command.Role, input.EncryptionPublicKey, input.SigningPublicKey, clock.GetUtcNow());
        foreach (var existing in registrations.Where(row => row.KeyFingerprint == proposed.KeyFingerprint))
        {
            if (await db.Set<OfflineDeviceRevocation>().FromSqlInterpolated(
                $"SELECT * FROM [OfflineDeviceRevocations] WITH (UPDLOCK,HOLDLOCK) WHERE [DeviceRegistrationId]={existing.Id}")
                .AsNoTracking().AnyAsync(cancellationToken))
                throw new OfflineAdmissionRejectedException(409, "offline_key_revoked");
            if (existing.RoleSnapshot == command.Role) return existing;
        }
        var lastRevision = registrations.Length == 0 ? 0 : registrations.Max(row => row.Revision);
        if (lastRevision == int.MaxValue) throw new OfflineAdmissionRejectedException(409, "device_revision_limit");
        var row = OfflineDeviceRegistration.Register(proposed.Id, command.ProjectId, command.ActorId, input.DeviceId,
            lastRevision + 1, command.Role, input.EncryptionPublicKey, input.SigningPublicKey, proposed.RegisteredAt);
        db.Add(row);
        var audit = JsonSerializer.Serialize(new { projectId = row.ProjectId, deviceId = row.DeviceId, registrationId = row.Id, revision = row.Revision }, Json);
        db.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), command.ActorId, row.RegisteredAt, "offline_device_registered",
            "OfflineDeviceRegistration", row.Id, null, audit, null, "h5.offline.v1", row.Id,
            ["projectId", "deviceId", "registrationId", "revision"]));
        db.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), "offline.device.registered.v1", row.RegisteredAt, row.Id,
            JsonSerializer.Serialize(new
            {
                projectId = row.ProjectId,
                sourceKind = "OfflineDeviceRegistration",
                sourceId = row.Id,
                originEventId = row.Id,
                occurredAtUtc = row.RegisteredAt
            }, Json)));
        return row;
    }

    private static object DeviceView(OfflineDeviceRegistration row, OfflineDeviceRevocation? revocation) => new
    {
        row.Id,
        row.ProjectId,
        row.ActorId,
        row.DeviceId,
        row.Revision,
        role = row.RoleSnapshot.ToString(),
        row.EncryptionPublicKey,
        row.SigningPublicKey,
        row.KeyFingerprint,
        row.RegisteredAt,
        revokedAt = revocation?.RevokedAt
    };
}

using System.Data;
using System.Text;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Inspections;
using RoadGuardSystem.BusinessObjects.Offline;
using RoadGuardSystem.Repositories.Inspections;
using RoadGuardSystem.Repositories.Offline;

namespace RoadGuardSystem.Repositories.Implementations.Offline;

public sealed partial class OfflineWorkflowRepository
{
    private sealed record StagedBatch(OfflineSyncBatch Batch, Dictionary<Guid, OfflineOperationAdmission> Admissions);

    private async Task<OfflineWorkflowFact> SynchronizeAsync(OfflineWorkflowCommand command,
        OfflineWorkflowAlgorithms algorithms, Func<CancellationToken, Task> currentGuard, CancellationToken cancellationToken)
    {
        if (command.Input is not OfflineSignedBatchData input)
            throw new ArgumentException("A signed batch is required.");
        return await ProcessBatchAsync(command, algorithms, currentGuard, input, null, cancellationToken);
    }

    private async Task<OfflineWorkflowFact> ProcessBatchAsync(OfflineWorkflowCommand command,
        OfflineWorkflowAlgorithms algorithms, Func<CancellationToken, Task> currentGuard,
        OfflineSignedBatchData input, OfflinePackageImportData? imported, CancellationToken cancellationToken)
    {
        if (db.Database.CurrentTransaction is not null) throw new InvalidOperationException("Offline batch processing owns per-item transactions.");
        if (input.Operations is null || input.Operations.Length is < 1 or > 1000)
            throw new ArgumentException("A bounded signed batch is required.");
        var staged = await OwnTransactionAsync(async token =>
        {
            await currentGuard(token);
            var source = imported is null
                ? await GuardSyncSourceAsync(command, input.SourceDeviceRegistrationId, token)
                : await GuardImportTransportAsync(command, algorithms, input, imported, token);
            var descriptors = input.Operations.Select(algorithms.Describe).ToArray();
            var manifest = algorithms.CanonicalManifest(command.ProjectId, input.BatchId, source.Id, descriptors);
            OfflinePackageAuthentication.VerifyClaim(manifest, input.Signature, source.SigningPublicKey);
            var attached = Encoding.UTF8.GetString(algorithms.CanonicalAttachedPayload(input.BatchId, source.Id, input.Operations, input.Signature));
            var manifestJson = Encoding.UTF8.GetString(manifest); var hash = Digest(manifestJson);
            var batches = await db.Set<OfflineSyncBatch>().FromSqlInterpolated(
                $"SELECT * FROM [OfflineSyncBatches] WITH (UPDLOCK,HOLDLOCK) WHERE [ProjectId]={command.ProjectId} AND [SourceDeviceRegistrationId]={source.Id} AND [SourceBatchId]={input.BatchId} AND [CurrentImporterId]={command.ActorId}")
                .AsNoTracking().ToArrayAsync(token);
            if (batches.Length > 1) throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
            var batch = batches.SingleOrDefault();
            if (batch is not null && (batch.ContentHash != hash || batch.AttachedPayloadJson != attached ||
                batch.GrantId != imported?.GrantId || batch.PackageId != imported?.PackageId ||
                batch.RecipientDeviceRegistrationId != imported?.RecipientDeviceRegistrationId ||
                batch.RecipientSignature != imported?.RecipientSignature))
                throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
            if (batch is null)
            {
                batch = OfflineSyncBatch.ReceiveAuthenticated(imported?.BatchId ?? Guid.NewGuid(), command.ProjectId, input.BatchId, source.Id,
                    command.ActorId, imported?.PackageId, imported?.GrantId, manifestJson, input.Signature,
                    attached, clock.GetUtcNow(), imported?.RecipientDeviceRegistrationId,
                    imported?.RecipientSignature); db.Add(batch);
                await db.SaveChangesAsync(token);
            }
            var admissions = new Dictionary<Guid, OfflineOperationAdmission>();
            foreach (var operation in input.Operations)
            {
                await GuardSyncSnapshotAsync(command, source, operation, token, imported is not null);
                if (operation.Repair is not null && (repairCore is null || repairCore.ComputeCoreHash(operation) != operation.CorePayloadHash))
                    throw new OfflineAdmissionRejectedException(409, "repair_adapter_not_ready");
                var validator = fieldAdmission ?? new OfflineAdmissionValidator(db, clock);
                await validator.GuardOriginBindingAsync(command.ProjectId, operation.OriginId, operation.Kind,
                    operation.CorePayloadHash, operation.OriginalActorId, operation.TaskId, token);
                var binding = await db.Set<OfflineOperationBinding>().FromSqlInterpolated(
                    $"SELECT * FROM [OfflineOperationBindings] WITH (UPDLOCK,HOLDLOCK) WHERE [ProjectId]={command.ProjectId} AND [OriginId]={operation.OriginId}")
                    .AsNoTracking().SingleOrDefaultAsync(token);
                var envelope = JsonSerializer.Serialize(operation, Json);
                if (binding is not null && (binding.EnvelopeHash != algorithms.EnvelopeHash(operation) ||
                    binding.SourceDeviceRegistrationId != source.Id || binding.SnapshotId != operation.SnapshotId))
                    throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
                if (binding is null)
                {
                    if (await db.Set<OfflineOperationBinding>().FromSqlInterpolated(
                        $"SELECT * FROM [OfflineOperationBindings] WITH (UPDLOCK,HOLDLOCK) WHERE [EffectId]={operation.EffectId}")
                        .AsNoTracking().AnyAsync(token)) throw new OfflineAdmissionRejectedException(409, "origin_content_conflict");
                    binding = OfflineOperationBinding.Bind(Guid.NewGuid(), command.ProjectId, operation.OriginId, operation.EffectId,
                        operation.Kind, operation.CorePayloadHash, algorithms.EnvelopeHash(operation), operation.OriginalActorId,
                        source.Id, operation.TaskId, operation.AssignmentId, operation.SnapshotId, envelope, clock.GetUtcNow(), operation.Repair?.ResourceId);
                    db.Add(binding); await db.SaveChangesAsync(token);
                }
                var admission = await db.Set<OfflineOperationAdmission>().FromSqlInterpolated(
                    $"SELECT * FROM [OfflineOperationAdmissions] WITH (UPDLOCK,HOLDLOCK) WHERE [BatchId]={batch.Id} AND [BindingId]={binding.Id}")
                    .AsNoTracking().SingleOrDefaultAsync(token);
                if (admission is null)
                {
                    admission = OfflineOperationAdmission.Record(Guid.NewGuid(), command.ProjectId, batch.Id, binding.Id,
                        command.ActorId, command.Role, imported?.GrantId, JsonSerializer.Serialize(new
                        {
                            operation.TaskId,
                            operation.AssignmentId,
                            operation.SnapshotId,
                            sourceRegistrationId = source.Id,
                            claimStatus = "SIGNED_ORIGIN_UNVERIFIED_TIME"
                        }, Json), clock.GetUtcNow());
                    db.Add(admission); await db.SaveChangesAsync(token);
                }
                admissions.Add(operation.OriginId, admission);
            }
            return new StagedBatch(batch, admissions);
        }, cancellationToken);

        var outcomes = new Dictionary<Guid, OfflineOperationResult>(); var remaining = input.Operations.ToList();
        while (remaining.Count > 0)
        {
            var ready = remaining.Where(operation => operation.Dependencies.All(id => outcomes.TryGetValue(id, out var result) && result.DurableAck)).ToArray();
            if (ready.Length == 0)
            {
                foreach (var operation in remaining)
                    outcomes.Add(operation.OriginId, await RetainFailureAsync(command, input.SourceDeviceRegistrationId,
                        staged.Batch, staged.Admissions[operation.OriginId], operation, "PENDING_DEPENDENCY", "dependency_not_committed", currentGuard, imported, algorithms, input, cancellationToken));
                break;
            }
            foreach (var operation in ready)
            {
                var admission = staged.Admissions[operation.OriginId];
                try
                {
                    outcomes.Add(operation.OriginId, await ApplyItemAsync(command, input.SourceDeviceRegistrationId, staged.Batch,
                        admission, operation, outcomes, currentGuard, imported, algorithms, input, cancellationToken));
                }
                catch (FieldCoreRejectedException rejected)
                {
                    outcomes.Add(operation.OriginId, await RetainFailureAsync(command, input.SourceDeviceRegistrationId,
                        staged.Batch, admission, operation, rejected.Result.Code == "stale_snapshot" ? "STALE_SNAPSHOT" : "REJECTED",
                        rejected.Result.Code ?? "field_command_rejected", currentGuard, imported, algorithms, input, cancellationToken));
                }
                catch (OfflineAdmissionRejectedException rejected) when (rejected.Status == 409)
                {
                    outcomes.Add(operation.OriginId, await RetainFailureAsync(command, input.SourceDeviceRegistrationId,
                        staged.Batch, admission, operation, rejected.Code == "stale_snapshot" ? "STALE_SNAPSHOT" : "CONFLICT",
                        rejected.Code, currentGuard, imported, algorithms, input, cancellationToken));
                }
                remaining.Remove(operation);
            }
        }
        var canonicalIds = await OwnTransactionAsync(async token =>
        {
            await currentGuard(token);
            if (imported is null) await GuardSyncSourceAsync(command, input.SourceDeviceRegistrationId, token);
            else await GuardImportTransportAsync(command, algorithms, input, imported, token);
            foreach (var operation in input.Operations.Where(operation => outcomes[operation.OriginId].DurableAck &&
                         operation.Repair is not null))
            {
                var caller = new FieldAdmissionContext(command.ActorId, command.Role,
                    operation.OriginalActorId, imported is null ? "SYNC" : "HANDOVER", false,
                    imported?.GrantId, staged.Admissions[operation.OriginId].Id);
                await ((fieldAdmission as IOfflineRepairAdmissionValidator) ??
                    new OfflineAdmissionValidator(db, clock)).ValidateRepairAsync(operation, command.ProjectId,
                    caller, token);
            }
            foreach (var operation in input.Operations.Where(operation => outcomes[operation.OriginId].DurableAck && operation.Repair is null))
            {
                var body = FieldBody(operation);
                await (fieldAdmission ?? new OfflineAdmissionValidator(db, clock)).ValidateAsync(
                    new(command.ProjectId, operation.TaskId, FieldAction(operation) ?? throw new ArgumentException("A typed FIELD action is required."), body, null, operation.TaskVersion,
                        new(command.ActorId, command.Role, operation.OriginalActorId,
                            imported is null ? "SYNC" : "HANDOVER", false, imported?.GrantId,
                            staged.Admissions[operation.OriginId].Id)), token);
            }
            var ids = input.Operations.Select(operation => operation.OriginId).ToArray();
            return await db.Set<FieldInspectionOperationOrigin>().AsNoTracking().Where(row => row.ProjectId == command.ProjectId && ids.Contains(row.OriginId))
                .ToDictionaryAsync(row => row.OriginId, row => row.Id, token);
        }, cancellationToken);
        var items = input.Operations.Select(operation => ItemView(outcomes[operation.OriginId], operation.Kind,
            canonicalIds.GetValueOrDefault(operation.OriginId))).ToArray();
        return new(200, Value: new OfflineBatchFact(staged.Batch.Id, items));
    }

    private async Task<OfflineOperationResult> ApplyItemAsync(OfflineWorkflowCommand command, Guid sourceRegistration,
        OfflineSyncBatch batch, OfflineOperationAdmission admission, OfflineOperationData operation,
        Dictionary<Guid, OfflineOperationResult> predecessors, Func<CancellationToken, Task> currentGuard,
        OfflinePackageImportData? imported, OfflineWorkflowAlgorithms algorithms, OfflineSignedBatchData input,
        CancellationToken cancellationToken)
        => await OwnTransactionAsync(async token =>
        {
            await currentGuard(token);
            if (imported is null) await GuardSyncSourceAsync(command, sourceRegistration, token);
            else await GuardImportTransportAsync(command, algorithms, input, imported, token);
            if (operation.Repair is not null)
            {
                var caller = new FieldAdmissionContext(command.ActorId, command.Role,
                    operation.OriginalActorId, imported is null ? "SYNC" : "HANDOVER", false,
                    imported?.GrantId, admission.Id);
                var repairProof = await ((fieldAdmission as IOfflineRepairAdmissionValidator) ??
                    new OfflineAdmissionValidator(db, clock)).ValidateRepairAsync(operation, command.ProjectId,
                    caller, token) ?? throw new OfflineAdmissionRejectedException(403,
                    "offline_admission_proof_unavailable");
                var existingRepair = await db.Set<OfflineOperationResult>().FromSqlInterpolated(
                    $"SELECT * FROM [OfflineOperationResults] WITH (UPDLOCK,HOLDLOCK) WHERE [AdmissionId]={admission.Id} AND [DurableAck]=1")
                    .AsNoTracking().SingleOrDefaultAsync(token);
                if (existingRepair is not null) return existingRepair;
                if (repairCore is null) throw new OfflineAdmissionRejectedException(409, "repair_adapter_not_ready");
                var repairExpected = PredecessorVersion(operation, input.Operations, predecessors);
                if (repairExpected is null)
                {
                    var snapshotJson = await db.Set<OfflineTaskSnapshot>().AsNoTracking()
                        .Where(row => row.Id == operation.SnapshotId && row.ProjectId == command.ProjectId)
                        .Select(row => row.SnapshotJson).SingleAsync(token);
                    using var snapshot = JsonDocument.Parse(snapshotJson);
                    if (!snapshot.RootElement.TryGetProperty("repair", out var repair) ||
                        repair.ValueKind != JsonValueKind.Object ||
                        !repair.TryGetProperty("itemVersion", out var itemVersion))
                        throw new OfflineAdmissionRejectedException(409, "repair_snapshot_source_unavailable");
                    repairExpected = itemVersion.GetString();
                }
                if (string.IsNullOrWhiteSpace(repairExpected))
                    throw new OfflineAdmissionRejectedException(409, "repair_snapshot_source_unavailable");
                var repairEffect = await repairCore.ApplyInTransactionAsync(new(operation, command.ProjectId,
                    command.ActorId, command.Role, repairProof, repairExpected), token);
                if (repairEffect.Code is not null || repairEffect.Status is not (200 or 201) ||
                    repairEffect.EffectId != repairProof.EffectId || repairEffect.CanonicalOriginId is null ||
                    repairEffect.SafeOutcome is null || string.IsNullOrWhiteSpace(repairEffect.ResourceVersion))
                    throw new OfflineAdmissionRejectedException(repairEffect.Code is null ? 409 : repairEffect.Status,
                        repairEffect.Code ?? "offline_effect_identity_mismatch");
                var received = clock.GetUtcNow();
                var verifiedFinish = operation.Kind == "REPAIR_EXECUTION_FINISH"
                    ? repairEffect.IndependentlyVerifiedFinishedAt : null;
                var repairResult = OfflineOperationResult.Record(Guid.NewGuid(), command.ProjectId, batch.Id,
                    admission.Id, operation.OriginId, repairEffect.EffectId, "COMMITTED", null,
                    verifiedFinish.HasValue ? "VERIFIED_ORIGINAL" : "UNCERTAIN",
                    verifiedFinish.HasValue ? algorithms.SyncLateness(verifiedFinish, received) : "UNKNOWN",
                    operation.ClaimedFinishedAt, verifiedFinish,
                    JsonSerializer.Serialize(repairEffect.SafeOutcome, Json), repairEffect.ResourceVersion, received);
                db.Add(repairResult); await db.SaveChangesAsync(token); await currentGuard(token); return repairResult;
            }
            var action = FieldAction(operation);
            if (action is null)
            {
                if (repairCore is null) throw new OfflineAdmissionRejectedException(409, "repair_adapter_not_ready");
                throw new OfflineAdmissionRejectedException(409, "repair_admission_not_ready");
            }
            var body = FieldBody(operation);
            var expected = PredecessorVersion(operation, input.Operations, predecessors) ?? operation.TaskVersion;
            var fieldCommand = new FieldWorkflowCommand(command.ProjectId, operation.TaskId, action, body, null, expected,
                new(command.ActorId, command.Role, operation.OriginalActorId,
                    imported is null ? "SYNC" : "HANDOVER", false, imported?.GrantId, admission.Id));
            var validator = fieldAdmission ?? new OfflineAdmissionValidator(db, clock);
            var proof = await validator.ValidateAsync(fieldCommand, token)
                ?? throw new OfflineAdmissionRejectedException(403, "offline_admission_proof_unavailable");
            var existing = await db.Set<OfflineOperationResult>().FromSqlInterpolated(
                $"SELECT * FROM [OfflineOperationResults] WITH (UPDLOCK,HOLDLOCK) WHERE [AdmissionId]={admission.Id} AND [DurableAck]=1")
                .AsNoTracking().SingleOrDefaultAsync(token);
            if (existing is not null) return existing;
            if (fieldCore is null) throw new OfflineAdmissionRejectedException(409, "field_adapter_not_ready");
            var effect = await fieldCore.ApplyInternalInTransactionAsync(fieldCommand,
                async inner => { await currentGuard(inner); return true; }, token);
            if (effect.Code is not null) throw new FieldCoreRejectedException(effect);
            var canonical = await db.Set<FieldInspectionOperationOrigin>().FromSqlInterpolated(
                $"SELECT * FROM [FieldInspectionOperationOrigins] WITH (UPDLOCK,HOLDLOCK) WHERE [ProjectId]={command.ProjectId} AND [OriginId]={operation.OriginId}")
                .AsNoTracking().SingleOrDefaultAsync(token);
            if (canonical is null || canonical.Kind != operation.Kind || canonical.ContentHash != operation.CorePayloadHash ||
                canonical.EffectId != proof.EffectId || canonical.TaskId != operation.TaskId || canonical.OriginalActorId != operation.OriginalActorId)
                throw new OfflineAdmissionRejectedException(409, "offline_effect_identity_mismatch");
            var version = Convert.ToBase64String(await db.FieldInspectionTasks.AsNoTracking().Where(row => row.Id == operation.TaskId)
                .Select(row => row.RowVersion).SingleAsync(token));
            var result = OfflineOperationResult.Record(Guid.NewGuid(), command.ProjectId, batch.Id, admission.Id, operation.OriginId,
                proof.EffectId, "COMMITTED", null, proof.VerifiedOriginalAt.HasValue ? "VERIFIED_ORIGINAL" : "UNCERTAIN", "UNKNOWN",
                operation.ClaimedFinishedAt, null, JsonSerializer.Serialize(effect.Value, Json), version, clock.GetUtcNow());
            db.Add(result); await db.SaveChangesAsync(token); await currentGuard(token); return result;
        }, cancellationToken);

    private static string? PredecessorVersion(OfflineOperationData operation,
        OfflineOperationData[] signedOperations, Dictionary<Guid, OfflineOperationResult> predecessors)
    {
        var byOrigin = signedOperations.ToDictionary(row => row.OriginId);
        var visited = new HashSet<Guid>();
        var matching = new HashSet<Guid>();
        void Visit(Guid originId)
        {
            if (!visited.Add(originId)) return;
            var ancestor = byOrigin[originId];
            if (operation.Repair is not null
                ? ancestor.Repair?.ResourceId == operation.Repair.ResourceId
                : ancestor.Repair is null && ancestor.TaskId == operation.TaskId)
            {
                matching.Add(originId);
            }
            foreach (var dependency in ancestor.Dependencies) Visit(dependency);
        }
        foreach (var dependency in operation.Dependencies) Visit(dependency);
        bool AncestorOf(Guid possibleAncestor, Guid descendant)
        {
            var seen = new HashSet<Guid>();
            var pending = new Stack<Guid>(byOrigin[descendant].Dependencies);
            while (pending.Count > 0)
            {
                var candidate = pending.Pop();
                if (candidate == possibleAncestor) return true;
                if (seen.Add(candidate))
                    foreach (var parent in byOrigin[candidate].Dependencies) pending.Push(parent);
            }
            return false;
        }
        var nearest = matching.Where(candidate => !matching.Any(other =>
            other != candidate && AncestorOf(candidate, other))).ToArray();
        if (nearest.Length > 1)
            throw new OfflineAdmissionRejectedException(409, "dependency_version_ambiguous");
        return nearest.Length == 0 ? null : predecessors[nearest[0]].ResourceVersion;
    }

    private async Task<OfflineOperationResult> RetainFailureAsync(OfflineWorkflowCommand command, Guid sourceRegistration,
        OfflineSyncBatch batch, OfflineOperationAdmission admission, OfflineOperationData operation, string state, string code,
        Func<CancellationToken, Task> currentGuard, OfflinePackageImportData? imported,
        OfflineWorkflowAlgorithms algorithms, OfflineSignedBatchData input, CancellationToken cancellationToken)
        => await OwnTransactionAsync(async token =>
        {
            await currentGuard(token);
            if (imported is null) await GuardSyncSourceAsync(command, sourceRegistration, token);
            else await GuardImportTransportAsync(command, algorithms, input, imported, token);
            var result = OfflineOperationResult.Record(Guid.NewGuid(), command.ProjectId, batch.Id, admission.Id, operation.OriginId,
                null, state, code, "UNCERTAIN", "UNKNOWN", operation.ClaimedFinishedAt, null, "{}", null, clock.GetUtcNow());
            db.Add(result); await db.SaveChangesAsync(token); return result;
        }, cancellationToken);

    private async Task<OfflineDeviceRegistration> GuardSyncSourceAsync(OfflineWorkflowCommand command, Guid sourceRegistration,
        CancellationToken cancellationToken)
    {
        var source = await db.Set<OfflineDeviceRegistration>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineDeviceRegistrations] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={sourceRegistration} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(cancellationToken);
        if (source is null || source.ActorId != command.ActorId || source.RoleSnapshot != command.Role ||
            await db.Set<OfflineDeviceRevocation>().FromSqlInterpolated(
                $"SELECT * FROM [OfflineDeviceRevocations] WITH (UPDLOCK,HOLDLOCK) WHERE [DeviceRegistrationId]={sourceRegistration}")
                .AsNoTracking().AnyAsync(cancellationToken)) throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        return source;
    }

    private async Task GuardSyncSnapshotAsync(OfflineWorkflowCommand command, OfflineDeviceRegistration source,
        OfflineOperationData operation, CancellationToken cancellationToken, bool handover = false)
    {
        var snapshot = await db.Set<OfflineTaskSnapshot>().FromSqlInterpolated(
            $"SELECT * FROM [OfflineTaskSnapshots] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={operation.SnapshotId} AND [ProjectId]={command.ProjectId}")
            .AsNoTracking().SingleOrDefaultAsync(cancellationToken);
        if (snapshot is null || snapshot.DeviceRegistrationId != source.Id || snapshot.OriginalActorId != source.ActorId ||
            operation.OriginalActorId != source.ActorId || !handover && source.ActorId != command.ActorId ||
            snapshot.TaskId != operation.TaskId || snapshot.AssignmentId != operation.AssignmentId ||
            snapshot.TaskVersion != operation.TaskVersion || operation.SourceDeviceId != source.DeviceId)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
        var assignment = await db.FieldInspectionAssignments.FromSqlInterpolated(
            $"SELECT * FROM [FieldInspectionAssignments] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={operation.AssignmentId}")
            .AsNoTracking().SingleOrDefaultAsync(cancellationToken);
        if (assignment is null || assignment.FieldInspectionTaskId != operation.TaskId || assignment.AssignedToUserId != source.ActorId)
            throw new OfflineAdmissionRejectedException(403, "access_forbidden");
    }

    private async Task<T> OwnTransactionAsync<T>(Func<CancellationToken, Task<T>> work, CancellationToken cancellationToken)
        => await db.Database.CreateExecutionStrategy().ExecuteAsync(async () =>
        {
            await using var transaction = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable, cancellationToken);
            try { var value = await work(cancellationToken); await transaction.CommitAsync(cancellationToken); return value; }
            catch { db.ChangeTracker.Clear(); throw; }
        });

    private static string? FieldAction(OfflineOperationData operation)
        => operation.Kind switch { "FIELD_ACCEPT" => "accept", "FIELD_START" => "start", "FIELD_SUBMISSION" => "submit", _ => null };

    private static object? FieldBody(OfflineOperationData operation)
        => operation.Kind switch { "FIELD_ACCEPT" => operation.FieldAction, "FIELD_START" => operation.FieldStart, _ => operation.FieldSubmission };

    private static OfflineItemFact ItemView(OfflineOperationResult result, string kind, Guid canonicalId)
        => new(result.OriginId, kind, result.State, result.Code, result.EffectId, canonicalId == Guid.Empty ? null : canonicalId, result.DurableAck, result.RecordedAt,
            result.TimeProvenance, result.SyncLateness, result.ClaimedFinishedAt, result.VerifiedFinishedAt,
            result.VerifiedFinishedAt?.AddHours(24), JsonSerializer.Deserialize<JsonElement>(result.OutcomeJson, Json));
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Auditing;
using RoadGuardSystem.BusinessObjects.Clocks;
using RoadGuardSystem.BusinessObjects.Messaging;
