using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.AspNetCore.Authentication.Cookies;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Identity;
using RoadGuardSystem.Services.Authentication;

namespace RoadGuardSystem.API.Authentication;

internal static class WebCookieConfiguration
{
    internal const string Scheme = "RoadGuardWeb";
    internal const string UserScheme = "RoadGuardUser";
    internal const string CookieName = "__Host-RoadGuardSession";
    internal const string RenewalCookieName = "__Host-RoadGuardRenewal";

    internal static string SelectScheme(HttpContext context)
    {
        if (context.Request.Headers.ContainsKey("Authorization"))
            return Microsoft.AspNetCore.Authentication.JwtBearer.JwtBearerDefaults.AuthenticationScheme;
        return IsCookieEligibleRequest(context) && context.Request.Cookies.ContainsKey(CookieName)
            ? Scheme
            : Microsoft.AspNetCore.Authentication.JwtBearer.JwtBearerDefaults.AuthenticationScheme;
    }

    internal static bool IsCookieEligibleRequest(HttpContext context) =>
        context.GetEndpoint()?.Metadata.GetMetadata<WebCookieEligibleAttribute>() is not null ||
        IsCookieEligibleRequest(context.Request.Method, context.Request.Path);

    internal static bool IsCookieEligibleRequest(string method, PathString requestPath)
    {
        var path = requestPath.Value ?? "";
        // Normalize one optional trailing slash, without admitting extra segments.
        if (path.EndsWith('/')) path = path[..^1];
        if (path.Equals("/api/v1/me/inspection-tasks", StringComparison.OrdinalIgnoreCase))
            return HttpMethods.IsGet(method);
        var parts = path.Split('/');
        if (parts.Length >= 4 && parts[0] == "" &&
            parts[1].Equals("api", StringComparison.OrdinalIgnoreCase) &&
            parts[2].Equals("v1", StringComparison.OrdinalIgnoreCase) &&
            parts[3].Equals("notifications", StringComparison.OrdinalIgnoreCase))
        {
            if (parts.Length == 4) return HttpMethods.IsGet(method);
            if (!Guid.TryParse(parts[4], out _)) return false;
            if (parts.Length == 5) return HttpMethods.IsGet(method);
            return parts.Length == 6 && parts[5].Equals("read", StringComparison.OrdinalIgnoreCase)
                && HttpMethods.IsPost(method);
        }
        return IsCookieEligiblePath(requestPath);
    }

    internal static bool IsCookieEligiblePath(PathString requestPath)
    {
        var path = requestPath.Value ?? "";
        return path.Equals("/api/v1/me", StringComparison.OrdinalIgnoreCase)
            || path.StartsWith("/api/v1/profile", StringComparison.OrdinalIgnoreCase)
            || path.Equals("/api/v1/auth/change-password", StringComparison.OrdinalIgnoreCase)
            || path.StartsWith("/api/v1/reports", StringComparison.OrdinalIgnoreCase)
            || path.StartsWith("/api/v1/cases", StringComparison.OrdinalIgnoreCase)
            || IsProjectDefectPath(path)
            || path.Contains("/candidate-decisions", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/candidates", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/labels", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsProjectDefectPath(string path)
    {
        var parts = path.TrimEnd('/').Split('/');
        if (parts.Length is < 6 or > 8 || parts[0] != "" ||
            !parts[1].Equals("api", StringComparison.OrdinalIgnoreCase) ||
            !parts[2].Equals("v1", StringComparison.OrdinalIgnoreCase) ||
            !parts[3].Equals("projects", StringComparison.OrdinalIgnoreCase) ||
            !Guid.TryParse(parts[4], out _) ||
            !parts[5].Equals("defects", StringComparison.OrdinalIgnoreCase)) return false;
        if (parts.Length == 6) return true;
        if (!Guid.TryParse(parts[6], out _)) return false;
        return parts.Length == 7 || parts[7].Equals("assessments", StringComparison.OrdinalIgnoreCase) ||
            parts[7].Equals("verification-decisions", StringComparison.OrdinalIgnoreCase);
    }

    internal static void Configure(CookieAuthenticationOptions options)
    {
        options.Cookie.Name = CookieName;
        options.Cookie.HttpOnly = true;
        options.Cookie.SecurePolicy = CookieSecurePolicy.Always;
        options.Cookie.SameSite = SameSiteMode.Lax;
        options.Cookie.Path = "/";
        options.SlidingExpiration = false;
        options.ExpireTimeSpan = TimeSpan.FromHours(12);
        options.Events = new CookieAuthenticationEvents
        {
            OnValidatePrincipal = async context =>
            {
                var claims = context.Principal;
                if (!Guid.TryParse(claims?.FindFirstValue(JwtRegisteredClaimNames.Sub), out var userId) ||
                    !Guid.TryParse(claims?.FindFirstValue("sid"), out var sessionId) ||
                    !TryRole(claims?.FindFirstValue("role"), out var role))
                {
                    context.RejectPrincipal();
                    return;
                }
                var validator = context.HttpContext.RequestServices.GetRequiredService<AuthoritativeSessionValidator>();
                var result = await validator
                    .ValidateAsync(userId, sessionId, role, context.HttpContext.RequestServices.GetRequiredService<TimeProvider>().GetUtcNow(),
                        SessionTransport.Web, context.HttpContext.RequestAborted);
                if (result == AuthoritativeSessionValidation.MustChangePassword &&
                    PasswordChangeAllowed(context.Request.Method, context.Request.Path)) return;
                if (result == AuthoritativeSessionValidation.SessionRevoked &&
                    HttpMethods.IsPost(context.Request.Method) &&
                    context.Request.Path.Value?.EndsWith("/auth/web/logout", StringComparison.OrdinalIgnoreCase) == true &&
                    context.Request.Headers.TryGetValue("Idempotency-Key", out var key) &&
                    !string.IsNullOrWhiteSpace(key.ToString()) &&
                    await validator.HasCommittedReplayAsync(userId, "Logout", key.ToString().Trim(' '),
                        context.HttpContext.RequestAborted)) return;
                if (result != AuthoritativeSessionValidation.Success) context.RejectPrincipal();
            },
            OnRedirectToLogin = context =>
            {
                context.Response.StatusCode = StatusCodes.Status401Unauthorized;
                return Task.CompletedTask;
            },
            OnRedirectToAccessDenied = context =>
            {
                context.Response.StatusCode = StatusCodes.Status403Forbidden;
                return Task.CompletedTask;
            }
        };
    }

    private static bool PasswordChangeAllowed(string method, PathString path)
    {
        var value = path.Value ?? "";
        if (HttpMethods.IsGet(method))
            return value.EndsWith("/me", StringComparison.OrdinalIgnoreCase) ||
                   value.EndsWith("/auth/web/session", StringComparison.OrdinalIgnoreCase) ||
                   value.EndsWith("/auth/web/csrf", StringComparison.OrdinalIgnoreCase);
        return HttpMethods.IsPost(method) &&
            (value.EndsWith("/auth/web/logout", StringComparison.OrdinalIgnoreCase) ||
             value.EndsWith("/auth/change-password", StringComparison.OrdinalIgnoreCase));
    }

    private static bool TryRole(string? value, out UserRoleCode role)
    {
        try { role = UserRoleCodeExtensions.FromDbCode(value ?? ""); return role != UserRoleCode.Unknown; }
        catch (ArgumentOutOfRangeException) { role = UserRoleCode.Unknown; return false; }
    }
}

using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Antiforgery;
using Microsoft.AspNetCore.Authentication;
using RoadGuardSystem.API.Authentication;
using RoadGuardSystem.aBusinessObjects.Commons;

namespace RoadGuardSystem.API.Middlewares;

public sealed class WebCookieRequestMiddleware(RequestDelegate next)
{
    public async Task InvokeAsync(HttpContext context, IAntiforgery antiforgery)
    {
        if (context.Request.Headers.ContainsKey("Authorization") &&
            context.Request.Cookies.ContainsKey(WebCookieConfiguration.CookieName) &&
            WebCookieConfiguration.IsCookieEligibleRequest(context) &&
            context.User.Identity?.IsAuthenticated == true)
        {
            var cookie = await context.AuthenticateAsync(WebCookieConfiguration.Scheme);
            var bearerActor = context.User.FindFirstValue(JwtRegisteredClaimNames.Sub);
            var cookieActor = cookie.Principal?.FindFirstValue(JwtRegisteredClaimNames.Sub);
            if (cookie.Succeeded && cookieActor is not null && cookieActor != bearerActor)
            {
                await DenyAsync(context, StatusCodes.Status400BadRequest, "validation_error");
                return;
            }
        }

        if (context.User.Identity?.AuthenticationType != WebCookieConfiguration.Scheme ||
            context.Request.Path.StartsWithSegments("/api/v1/auth/web", StringComparison.OrdinalIgnoreCase))
        {
            await next(context);
            return;
        }

        if (!HttpMethods.IsGet(context.Request.Method) && !HttpMethods.IsHead(context.Request.Method) &&
            !HttpMethods.IsOptions(context.Request.Method))
        {
            try { await antiforgery.ValidateRequestAsync(context); }
            catch (AntiforgeryValidationException)
            {
                await DenyAsync(context, StatusCodes.Status403Forbidden, "csrf_failed");
                return;
            }
        }

        await next(context);
    }

    private static Task DenyAsync(HttpContext context, int status, string code)
    {
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/problem+json";
        context.Response.Headers.CacheControl = "no-store";
        return context.Response.WriteAsync(JsonSerializer.Serialize(new
        {
            type = "about:blank",
            title = status switch { 400 => "Bad Request", 403 => "Forbidden", _ => "Unauthorized" },
            status,
            detail = status switch
            {
                400 => "Credentials identify different actors.",
                403 => "The CSRF token is invalid or missing.",
                _ => "The session is no longer active."
            },
            instance = context.Request.Path.Value,
            code,
            correlationId = context.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString()
        }), context.RequestAborted);
    }
}

    private async Task<IActionResult> Run(Guid project, string action, CancellationToken ct,
        Guid? route = null, Guid? set = null, Guid? resource = null, object? input = null, string? hash = null)
    {
        if (!Guid.TryParse(User.FindFirstValue(JwtRegisteredClaimNames.Sub), out var actor) ||
            !ProjectRoleClaimParser.TryParse(User.FindFirstValue("role"), out var role)) return Error(401, "unauthorized");
        if (Request.Headers.TryGetValue("Idempotency-Key", out var keys) && keys.Count != 1)
            return Error(400, "validation_error");
        var etags = Request.Headers.IfMatch;
        if (etags.Count > 1) return Error(400, "validation_error");
        var etag = etags.ToString();
        if (hash is not null && (hash.Length != 64 || hash.Any(c => !Uri.IsHexDigit(c)))) return Error(400, "validation_error");
        if (etag.Length > 0 && (etag.Length != 66 || etag[0] != '"' || etag[^1] != '"' || etag[1..^1].Any(c => !Uri.IsHexDigit(c))))
            return Error(412, "content_hash_mismatch");
        if (hash is not null && etag.Length > 0 && !string.Equals(hash, etag[1..^1], StringComparison.OrdinalIgnoreCase))
            return Error(409, "geometry_version_mismatch");
        var result = await service.ExecuteAsync(role, new(actor, project, action, route, set, resource, input,
            keys.ToString(), (hash ?? (etag.Length == 0 ? null : etag[1..^1]))?.ToLowerInvariant()), ct);
        if (result.Code is not null) return Error(result.Status, result.Code);
        var json = System.Text.Json.JsonSerializer.SerializeToElement(result.Value, PublicJson);
        if (json.ValueKind == System.Text.Json.JsonValueKind.Object && json.TryGetProperty("contentHash", out var contentHash))
            Response.Headers.ETag = $"\"{contentHash.GetString()}\"";
        if (result.Status == 201 && json.ValueKind == System.Text.Json.JsonValueKind.Object)
        {
            if (json.TryGetProperty("publicationId", out var publicationId)) Response.Headers.Location = $"/api/v1/projects/{project}/geometry-map-publications/{publicationId.GetGuid()}";
            else if (json.TryGetProperty("kind", out _) && json.TryGetProperty("id", out var layoutId)) Response.Headers.Location = $"/api/v1/projects/{project}/pavement-layouts/{layoutId.GetGuid()}";
            else if (action == "impact-create" && json.TryGetProperty("id", out var impactId)) Response.Headers.Location = $"/api/v1/projects/{project}/geometry-location-impacts/{impactId.GetGuid()}";
        }
        return StatusCode(result.Status, result.Value);
    }
    private ObjectResult Error(int status, string code)
    {
        var problem = new ProblemDetails { Status = status, Title = "Pavement request failed", Instance = Request.Path };
        problem.Extensions["code"] = code;
        problem.Extensions["correlationId"] = HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString() ?? Guid.NewGuid().ToString();
        return new(problem) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }
}

using RoadGuardSystem.Repositories.Projects;
using RoadGuardSystem.Services.Authorization;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.DTOs.Projects;
namespace RoadGuardSystem.Services.Projects;

public sealed class PavementWorkflowService(IPavementWorkflowRepository repository, IProjectScopeGuard guard) : IPavementWorkflowService
{
    public async Task<GeometryWorkflowResult> ExecuteAsync(UserRoleCode role, PavementWorkflowCommand command,
        CancellationToken cancellationToken = default)
    {
        var read = command.Action is "layout-get" or "manifest" or "page" or "impact-get" or "impact-list";
        var write = command.Action is "plan-create" or "asbuilt-create" or "publish" or "impact-create" or "impact-decide";
        if (!read && !write) return new(400, "validation_error");
        // No FIELD segment-set pin exists in the legacy task schema. Crew access stays denied
        // until H3 supplies its actual task-bound producer, rather than project-wide admission.
        if (command.ActorId == Guid.Empty || command.ProjectId == Guid.Empty ||
            (read ? role is not (UserRoleCode.ProjectManager or UserRoleCode.Supervisor) : role != UserRoleCode.ProjectManager))
            return new(403, "access_forbidden");
        if (write && (string.IsNullOrWhiteSpace(command.Key) || command.Key.Length > 150 || command.Key.Any(c => c is < '!' or > '~')))
            return new(428, "idempotency_key_required");
        if (command.Action is "page" or "publish" or "asbuilt-create" && string.IsNullOrWhiteSpace(command.ExpectedContentHash))
            return new(428, "content_hash_required");
        try
        {
            var result = await repository.ExecuteAsync(role, command with { Input = RoadGuardSystem.DTOs.BoundaryFactMappings.ToFacts(command.Input) },
                async token => await guard.AuthorizeAsync(command.ActorId, role, command.ProjectId, token) is not null,
                (metadata, legacy, input) => PavementFootprintEngine.Planned(metadata?.NativeAlignment is { } native
                    ? NativeAlignment.Create(native) : NativeAlignment.FromLegacy(legacy), input),
                (snapshot, input) => PavementFootprintEngine.AsBuilt(snapshot, input),
                (input, srid) => GeometryEngine.Preview(input, srid),
                (snapshot, query, hash) => GeometryMapPageEngine.Page(snapshot, query.Layer, hash, query.Limit, query.Bbox, query.Cursor),
                cancellationToken);
            return result with { Value = RoadGuardSystem.DTOs.BoundaryFactMappings.ToWire(result.Value) };
        }
        catch (GeometryValidationException e)
        {
            return new(e.Code switch
            {
                "geometry_version_mismatch" or "geometry_layer_unavailable" => 409,
                "geometry_layer_not_found" => 404,
                "geometry_cursor_invalid" or "geometry_page_invalid" => 400,
                _ => 422
            }, e.Code);
        }
        catch (ArgumentException) { return new(422, "pavement_layout_invalid"); }
    }
}

using System.Data;
using System.Security.Cryptography;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using NetTopologySuite.Geometries;
using NetTopologySuite.Operation.Union;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Auditing;
using RoadGuardSystem.BusinessObjects.Files;
using RoadGuardSystem.BusinessObjects.Messaging;
using RoadGuardSystem.BusinessObjects.Projects;
using RoadGuardSystem.BusinessObjects.PersistenceFacts.Projects;
using RoadGuardSystem.Repositories.Idempotency;
using RoadGuardSystem.Repositories.Integration;

namespace RoadGuardSystem.Repositories.Projects;

public sealed class PavementWorkflowRepository(RoadGuardDbContext db, IdempotencyOperationService idempotency,
    TimeProvider timeProvider) : IPavementWorkflowRepository
{
    private static readonly JsonSerializerOptions PublicJson = new(JsonSerializerDefaults.Web);
    private sealed class Rejected(int status, string code) : Exception
    { public GeometryWorkflowResult Result { get; } = new(status, code); }
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Reject(int status, string code) => throw new Rejected(status, code);
    private static string Hash(object value) => Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(value))).ToLowerInvariant();
    private static T Decode<T>(string json) => JsonSerializer.Deserialize<T>(json, PublicJson) ?? throw new InvalidOperationException("Invalid persisted pavement snapshot.");

    private sealed class CommittedReceipt : Exception { }
    private sealed record SourceCapture(ReporterFileFacts File, Guid ScopeId, Guid? TargetId, DateTimeOffset ScopeCreatedAt, Guid? UploadedByUserId);
    public async Task<GeometryWorkflowResult> ExecuteAsync(UserRoleCode role, PavementWorkflowCommand command,
        Func<CancellationToken, Task<bool>> scopeGuard,
        Func<GeometryDraftInputFact?, LineString, PavementPlanCreateInputFact, PavementGeometryPreviewFact> plan,
        Func<PavementGeometryPreviewFact, AsBuiltLayoutInputFact, PavementGeometryPreviewFact> asBuilt,
        Func<GeometryDraftInputFact, int, GeometryPreviewFact> geometryPreview,
        Func<GeometryMapSnapshotFact, PavementLayerQuery, string, GeometryMapPageFact> page, CancellationToken cancellationToken)
    {
        var c = command; var ct = cancellationToken;
        async Task Guard(CancellationToken token)
        {
            await Anh02ReceiptAuthority.LockAsync(db, c.ActorId, c.ProjectId, token);
            var read = c.Action is "layout-get" or "manifest" or "page" or "impact-get" or "impact-list";
            if (read ? role is not (UserRoleCode.ProjectManager or UserRoleCode.Supervisor) : role != UserRoleCode.ProjectManager)
                Reject(403, "access_forbidden");
            if (!await new AnhHuyFactsRepository(db).IsCurrentActorAsync(c.ActorId, role, token) ||
                !await db.Projects.AsNoTracking().AnyAsync(x => x.Id == c.ProjectId, token) ||
                !await scopeGuard(token)) Reject(403, "access_forbidden");
            // Protect resource scope before both new effects and receipt/conflict recovery.
            // Historical receipt access deliberately does not require the old workflow status.
            if (c.Action == "asbuilt-create" && c.Input is AsBuiltLayoutInputFact built) await Layout(c.ProjectId, built.SourcePlanId, token);
            if (c.Action == "publish" && c.Input is GeometryMapPublishInputFact publication) await Layout(c.ProjectId, publication.LayoutRevisionId, token);
            if (c.Action == "plan-create")
            {
                var route = await Route(c.ProjectId, c.RouteVersionId, token);
                if (!await db.RoadSegmentSets.AnyAsync(x => x.Id == c.SegmentSetId && x.RoadSectionVersionId == route.Id, token))
                    Reject(409, "geometry_version_mismatch");
            }
            if (c.Action == "impact-decide" && !await db.Set<GeometryLocationImpact>().AnyAsync(x => x.Id == c.ResourceId && x.ProjectId == c.ProjectId, token))
                Reject(404, "not_found");
            if (c.Action == "impact-create" && c.Input is GeometryImpactInputFact impact)
            { await Route(c.ProjectId, impact.PreviousRouteVersionId, token); await Route(c.ProjectId, impact.NewRouteVersionId, token); }
        }
        try
        {
            if (c.Action is "layout-get" or "manifest" or "page" or "impact-get" or "impact-list")
            {
                if (db.Database.CurrentTransaction is not null)
                { await Guard(ct); return await Read(c, page, ct); }
                return await db.Database.CreateExecutionStrategy().ExecuteAsync(async () =>
                {
                    await using var transaction = await db.Database.BeginTransactionAsync(IsolationLevel.Serializable, ct);
                    await Guard(ct); var result = await Read(c, page, ct);
                    await transaction.CommitAsync(ct); return result;
                });
            }
            var fingerprint = Hash(new { c.ProjectId, c.Action, c.RouteVersionId, c.SegmentSetId, c.ResourceId, c.Input, c.ExpectedContentHash });
            var outcome = await idempotency.ExecuteSerializableAsync(c.ActorId, c.ProjectId, $"h2.pavement.{c.Action}.v1", c.Key!, fingerprint,
                async token =>
                {
                    await Guard(token);
                    var existing = await db.IdempotencyRecords.AsNoTracking().AnyAsync(x => x.ActorUserId == c.ActorId &&
                        x.ProjectId == c.ProjectId && x.Operation == $"h2.pavement.{c.Action}.v1" && x.IdempotencyKey == c.Key, token);
                    if (existing) throw new CommittedReceipt();
                    if (!await db.Projects.AsNoTracking().AnyAsync(x => x.Id == c.ProjectId && x.Status == ProjectStatus.Active, token))
                        Reject(409, "project_not_active");
                    var value = await Write(c, plan, asBuilt, geometryPreview, token);
                    var now = timeProvider.GetUtcNow();
                    db.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), c.ActorId, now, $"pavement_{c.Action}", "PavementWorkflow",
                        value.Id, null, null, "Versioned pavement workflow", "h2.pavement", null));
                    db.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), $"h2.pavement.{c.Action}.v1", now, null,
                        JsonSerializer.Serialize(new { c.ProjectId, resourceId = value.Id })));
                    await db.SaveChangesAsync(token);
                    return (value.Id, JsonSerializer.Serialize(value.Value, PublicJson));
                }, ct, receiptAccessGuard: Guard);
            return outcome.Status == IdempotencyOperationStatus.Conflict ? new(409, "idempotency_conflict")
                : new(outcome.Status == IdempotencyOperationStatus.Replayed ? 200 : 201, Value: Decode<JsonElement>(outcome.OutcomeJson));
        }
        catch (Rejected e) { return e.Result; }
        catch (CommittedReceipt)
        {
            db.ChangeTracker.Clear();
            // Project authority locks serialized a competing writer. Its receipt is durable;
            // re-enter the shared guarded lookup after rollback without a second effect.
            return await ExecuteAsync(role, command, scopeGuard, plan, asBuilt, geometryPreview, page, cancellationToken);
        }
        catch (DbUpdateException e) when (e.InnerException is Microsoft.Data.SqlClient.SqlException { Number: 2601 or 2627 })
        { return new(409, "resource_conflict"); }
    }

    private async Task<GeometryWorkflowResult> Read(PavementWorkflowCommand c,
        Func<GeometryMapSnapshotFact, PavementLayerQuery, string, GeometryMapPageFact> page, CancellationToken ct)
    {
        if (c.Action == "layout-get") return new(200, Value: View(await Layout(c.ProjectId, c.ResourceId, ct)));
        if (c.Action == "impact-list")
        {
            var rows = await db.Set<GeometryLocationImpact>().AsNoTracking().Where(x => x.ProjectId == c.ProjectId &&
                (c.RouteVersionId == null || x.PreviousRouteVersionId == c.RouteVersionId) &&
                (c.SegmentSetId == null || x.NewRouteVersionId == c.SegmentSetId))
                .OrderByDescending(x => x.RecordedAt).ThenBy(x => x.Id).Take(100).ToArrayAsync(ct);
            return new(200, Value: rows.Select(ImpactView).ToArray());
        }
        if (c.Action == "impact-get")
        {
            var impact = await db.Set<GeometryLocationImpact>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == c.ResourceId && x.ProjectId == c.ProjectId, ct);
            if (impact is null) throw new Rejected(404, "not_found");
            return new(200, Value: ImpactView(impact));
        }
        var publication = await db.Set<GeometryMapPublication>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == c.ResourceId && x.ProjectId == c.ProjectId, ct)
            ?? throw new Rejected(404, "not_found");
        var snapshot = Decode<GeometryMapSnapshotFact>(publication.SnapshotJson);
        if (c.RouteVersionId is { } route && route != publication.RouteVersionId ||
            c.SegmentSetId is { } set && set != publication.SegmentSetId) Reject(409, "geometry_version_mismatch");
        return new(200, Value: c.Action == "manifest" ? snapshot.Manifest
            : page(snapshot, c.Input as PavementLayerQuery ?? throw new ArgumentException("A layer query is required."), c.ExpectedContentHash!));
    }

    private async Task<(Guid Id, object Value)> Write(PavementWorkflowCommand c,
        Func<GeometryDraftInputFact?, LineString, PavementPlanCreateInputFact, PavementGeometryPreviewFact> plan,
        Func<PavementGeometryPreviewFact, AsBuiltLayoutInputFact, PavementGeometryPreviewFact> asBuilt,
        Func<GeometryDraftInputFact, int, GeometryPreviewFact> geometryPreview, CancellationToken ct)
    {
        var now = timeProvider.GetUtcNow();
        if (c.Action == "plan-create")
        {
            var (route, set, metadata, native) = await Pins(c.ProjectId, c.RouteVersionId, c.SegmentSetId, ct);
            var input = c.Input as PavementPlanCreateInputFact ?? throw new ArgumentException("A plan is required.");
            var geometry = plan(metadata is null ? null : Decode<GeometryDraftInputFact>(metadata.InputJson), route.Geometry, input);
            var definition = new
            {
                input,
                RouteHash = metadata?.GeometryHash ?? Hash(route.Geometry.AsText()),
                SetHash = set.GeometryHash,
                SetVersion = Convert.ToBase64String(set.RowVersion),
                Native = native
            };
            var layout = new PavementLayoutRevision
            {
                Id = Guid.NewGuid(),
                ProjectId = c.ProjectId,
                RouteVersionId = route.Id,
                SegmentSetId = set.Id,
                CrsProfileRevisionId = native?.CrsProfileRevisionId,
                DefinitionJson = JsonSerializer.Serialize(definition),
                SnapshotJson = JsonSerializer.Serialize(geometry),
                ContentHash = Hash(new { definition, geometry }),
                CreatedBy = c.ActorId,
                CreatedAt = now
            };
            db.Add(layout); return (layout.Id, View(layout));
        }
        if (c.Action == "asbuilt-create")
        {
            var input = c.Input as AsBuiltLayoutInputFact ?? throw new ArgumentException("As-built evidence is required.");
            var source = await Layout(c.ProjectId, input.SourcePlanId, ct);
            if (source.Kind != "PLANNED") Reject(409, "planned_source_required");
            if (source.ContentHash != c.ExpectedContentHash) Reject(412, "content_hash_mismatch");
            await Pins(c.ProjectId, source.RouteVersionId, source.SegmentSetId, ct);
            var geometry = asBuilt(Decode<PavementGeometryPreviewFact>(source.SnapshotJson), input);
            var files = new List<SourceCapture>();
            foreach (var fileId in input.Slabs.Where(x => x.SourceFileId.HasValue).Select(x => x.SourceFileId!.Value).Distinct().Order())
            {
                await db.Files.FromSqlInterpolated($"SELECT * FROM [Files] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={fileId}").AsNoTracking().ToListAsync(ct);
                await db.FileScopes.FromSqlInterpolated($"SELECT * FROM [FileScopes] WITH (UPDLOCK,HOLDLOCK) WHERE [FileId]={fileId}").AsNoTracking().ToListAsync(ct);
                await db.UploadSessions.FromSqlInterpolated($"SELECT * FROM [UploadSessions] WITH (UPDLOCK,HOLDLOCK) WHERE [FileId]={fileId}").AsNoTracking().ToListAsync(ct);
                var file = await new AnhHuyFactsRepository(db).GetFileAsync(fileId, ct);
                if (file is null || file.ProjectId != c.ProjectId || file.State != "VERIFIED") Reject(409, "source_file_not_ready");
                var fileScope = await db.FileScopes.AsNoTracking().SingleAsync(x => x.FileId == fileId, ct);
                var uploader = await db.Files.AsNoTracking().Where(x => x.Id == fileId).Select(x => x.UploadedByUserId).SingleAsync(ct);
                if (uploader != file!.OwnerId) Reject(409, "source_file_provenance_unresolved");
                if (file!.Purpose is not ("ROUTE_SOURCE" or "DOCUMENT" or "SURVEY_VIDEO" or "TELEMETRY")) Reject(403, "source_file_purpose_forbidden");
                if (file.Purpose is "SURVEY_VIDEO" or "TELEMETRY")
                {
                    if (!await db.SurveyRequests.AnyAsync(x => x.Id == fileScope.TargetId && x.ProjectId == c.ProjectId, ct))
                        Reject(403, "source_file_purpose_forbidden");
                }
                files.Add(new(file, fileScope.Id, fileScope.TargetId, fileScope.CreatedAt, uploader));
            }
            var definition = new { input, SourcePlanHash = source.ContentHash, SourceFiles = files };
            var layout = new PavementLayoutRevision
            {
                Id = Guid.NewGuid(),
                ProjectId = c.ProjectId,
                RouteVersionId = source.RouteVersionId,
                SegmentSetId = source.SegmentSetId,
                SourcePlanId = source.Id,
                CrsProfileRevisionId = source.CrsProfileRevisionId,
                Kind = "AS_BUILT",
                DefinitionJson = JsonSerializer.Serialize(definition),
                SnapshotJson = JsonSerializer.Serialize(geometry),
                ContentHash = Hash(new { definition, geometry }),
                CreatedBy = c.ActorId,
                CreatedAt = now
            };
            db.Add(layout);
            foreach (var file in files)
                db.Add(new PavementSourceFileReference
                {
                    Id = Guid.NewGuid(),
                    LayoutRevisionId = layout.Id,
                    FileId = file.File.FileId,
                    ContentChecksum = file.File.Checksum,
                    CaptureFactsJson = JsonSerializer.Serialize(file)
                });
            return (layout.Id, View(layout));
        }
        if (c.Action == "publish")
        {
            var input = c.Input as GeometryMapPublishInputFact ?? throw new ArgumentException("A publication input is required.");
            Reason(input.Reason);
            if (input.PublicationMode == "OFFICIAL") Reject(409, "official_crs_acceptance_pending");
            if (input.PublicationMode != "SAMPLE") Reject(422, "publication_mode_invalid");
            var layout = await Layout(c.ProjectId, input.LayoutRevisionId, ct);
            if (layout.ContentHash != c.ExpectedContentHash) Reject(412, "content_hash_mismatch");
            var (route, set, metadata, native) = await Pins(c.ProjectId, layout.RouteVersionId, layout.SegmentSetId, ct);
            if (layout.CrsProfileRevisionId != native?.CrsProfileRevisionId) Reject(409, "geometry_version_mismatch");
            var profile = native is null ? null : await db.Set<CrsProfileRevision>().AsNoTracking().SingleAsync(x => x.Id == native.CrsProfileRevisionId && x.ProjectId == c.ProjectId, ct);
            var id = Guid.NewGuid();
            var snapshot = await Snapshot(id, layout, route, set, metadata, profile, geometryPreview, ct);
            var publication = new GeometryMapPublication
            {
                Id = id,
                ProjectId = c.ProjectId,
                RouteVersionId = route.Id,
                SegmentSetId = set.Id,
                LayoutRevisionId = layout.Id,
                CrsProfileRevisionId = layout.CrsProfileRevisionId,
                ContentHash = snapshot.Manifest.ContentHash,
                SnapshotJson = JsonSerializer.Serialize(snapshot, PublicJson),
                PublicationMode = "SAMPLE",
                PublishedBy = c.ActorId,
                PublishedAt = now
            };
            db.Add(publication); return (id, snapshot.Manifest);
        }
        if (c.Action == "impact-create")
        {
            var input = c.Input as GeometryImpactInputFact ?? throw new ArgumentException("Impact versions are required."); Reason(input.Reason);
            if (input.PreviousRouteVersionId == input.NewRouteVersionId) Reject(422, "impact_versions_invalid");
            var previous = await Route(c.ProjectId, input.PreviousRouteVersionId, ct);
            var next = await Route(c.ProjectId, input.NewRouteVersionId, ct);
            if (previous.RoadSectionId != next.RoadSectionId) Reject(409, "impact_road_section_mismatch");
            var references = await ImpactReferences(c.ProjectId, input.PreviousRouteVersionId, ct);
            var impact = new GeometryLocationImpact
            {
                Id = Guid.NewGuid(),
                ProjectId = c.ProjectId,
                PreviousRouteVersionId = input.PreviousRouteVersionId,
                NewRouteVersionId = input.NewRouteVersionId,
                AffectedReferencesJson = JsonSerializer.Serialize(references),
                RecordedBy = c.ActorId,
                RecordedAt = now
            };
            db.Add(impact); return (impact.Id, ImpactView(impact));
        }
        if (c.Action == "impact-decide")
        {
            var input = c.Input as GeometryImpactDecisionInputFact ?? throw new ArgumentException("An impact decision is required."); Reason(input.Reason);
            if (input.Action is not ("VERIFY" or "CONTINUE" or "STOP" or "REASSIGN")) Reject(422, "impact_action_invalid");
            var impact = await db.Set<GeometryLocationImpact>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == c.ResourceId && x.ProjectId == c.ProjectId, ct)
                ?? throw new Rejected(404, "not_found");
            var reference = Decode<GeometryAffectedReferenceFact[]>(impact.AffectedReferencesJson)
                .FirstOrDefault(x => x.Id == input.TaskId && x.Kind is "FIELD_TASK" or "SURVEY_TASK");
            if (reference is null) Reject(409, "task_not_in_impact");
            var decision = new GeometryLocationImpactDecision
            {
                Id = Guid.NewGuid(),
                ImpactId = impact.Id,
                TaskId = input.TaskId,
                Action = input.Action,
                Reason = input.Reason.Trim(),
                ActorId = c.ActorId,
                OccurredAt = now
            };
            db.Add(decision); return (decision.Id, new GeometryImpactDecisionView(decision.Id, impact.Id, input.TaskId, decision.Action, decision.Reason, now));
        }
        throw new ArgumentException("Unsupported pavement operation.");
    }

    private static void Reason(string reason)
    { if (string.IsNullOrWhiteSpace(reason) || reason.Trim().Length > 2000) throw new ArgumentException("A bounded reason is required."); }
    private async Task<RoadSectionVersion> Route(Guid project, Guid? routeId, CancellationToken ct)
    {
        if (routeId is null || routeId == Guid.Empty) throw new Rejected(422, "route_version_required");
        await db.RoadSectionVersions.FromSqlInterpolated($"SELECT * FROM [RoadSectionVersions] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={routeId}").AsNoTracking().ToListAsync(ct);
        return await (from route in db.RoadSectionVersions.AsNoTracking()
                      join road in db.RoadSections.AsNoTracking() on route.RoadSectionId equals road.Id
                      where route.Id == routeId && road.ProjectId == project
                      select route).SingleOrDefaultAsync(ct) ?? throw new Rejected(404, "not_found");
    }
    private async Task<(RoadSectionVersion Route, RoadSegmentSet Set, RoadGeometryMetadata? Metadata, NativeRouteVersionFacts? Native)> Pins(
        Guid project, Guid? routeId, Guid? setId, CancellationToken ct)
    {
        var route = await Route(project, routeId, ct);
        await db.RoadSegmentSets.FromSqlInterpolated($"SELECT * FROM [RoadSegmentSets] WITH (UPDLOCK,HOLDLOCK) WHERE [Id]={setId}").AsNoTracking().ToListAsync(ct);
        var set = await db.RoadSegmentSets.AsNoTracking().SingleOrDefaultAsync(x => x.Id == setId && x.RoadSectionVersionId == route.Id, ct)
            ?? throw new Rejected(409, "geometry_version_mismatch");
        if (set.Status != "PUBLISHED") Reject(409, "segment_set_not_published");
        var metadata = await db.Set<RoadGeometryMetadata>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == route.Id, ct);
        var native = await db.Set<NativeRouteVersionFacts>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == route.Id, ct);
        if (native is not null && (native.ProjectId != project || !await db.Set<CrsProfileRevision>().AnyAsync(x => x.Id == native.CrsProfileRevisionId && x.ProjectId == project, ct)))
            Reject(409, "geometry_version_mismatch");
        if (metadata is not null)
        {
            var input = Decode<GeometryDraftInputFact>(metadata.InputJson);
            if (input.NativeAlignment is { } alignment &&
                (native is null || alignment.CrsProfileRevisionId != native.CrsProfileRevisionId || alignment.SpatialSrid != route.Geometry.SRID))
                Reject(409, "geometry_version_mismatch");
            if (native is not null && input.NativeAlignment is null) Reject(409, "geometry_version_mismatch");
        }
        else if (native is not null) Reject(409, "native_route_metadata_missing");
        return (route, set, metadata, native);
    }
    private async Task<PavementLayoutRevision> Layout(Guid project, Guid? id, CancellationToken ct)
        => await db.Set<PavementLayoutRevision>().AsNoTracking().SingleOrDefaultAsync(x => x.Id == id && x.ProjectId == project, ct)
            ?? throw new Rejected(404, "not_found");
    private static PavementLayoutView View(PavementLayoutRevision x) => new(x.Id, x.ProjectId, x.RouteVersionId, x.SegmentSetId,
        x.SourcePlanId, x.CrsProfileRevisionId, x.Kind, x.ContentHash, Decode<PavementGeometryPreviewFact>(x.SnapshotJson), x.CreatedAt);
    private static GeometryImpactView ImpactView(GeometryLocationImpact x) => new(x.Id, x.ProjectId, x.PreviousRouteVersionId,
        x.NewRouteVersionId, Decode<GeometryAffectedReferenceFact[]>(x.AffectedReferencesJson), x.RecordedAt);

    private async Task<GeometryAffectedReferenceFact[]> ImpactReferences(Guid project, Guid route, CancellationToken ct)
    {
        var result = new List<GeometryAffectedReferenceFact>();
        var field = await db.FieldInspectionTasks.AsNoTracking().Where(x => x.ProjectId == project && x.RoadSectionVersionId == route).Select(x => new { x.Id, x.SegmentSetId }).ToArrayAsync(ct);
        result.AddRange(field.Select(x => new GeometryAffectedReferenceFact("FIELD_TASK", x.Id, route, x.SegmentSetId,
            x.SegmentSetId.HasValue ? "PINNED_REFERENCE" : "INCOMPLETE", x.SegmentSetId.HasValue ? [] : ["LEGACY_SEGMENT_SET_UNPINNED"])));
        var survey = await (from scope in db.SurveyRequestScopes.AsNoTracking()
                            join task in db.SurveyRequests.AsNoTracking() on scope.SurveyRequestId equals task.Id
                            where task.ProjectId == project && scope.RouteSectionVersionId == route
                            select new { task.Id, scope.SegmentSetId }).Distinct().ToArrayAsync(ct);
        result.AddRange(survey.Select(x => new GeometryAffectedReferenceFact("SURVEY_TASK", x.Id, route, x.SegmentSetId, "READY", [])));
        var defects = await db.Defects.AsNoTracking().Where(x => x.ProjectId == project && x.RoadSectionVersionId == route).Select(x => x.Id).ToArrayAsync(ct);
        result.AddRange(defects.Select(x => new GeometryAffectedReferenceFact("DEFECT", x, route, null, "INCOMPLETE", ["SEGMENT_SET_NOT_PINNED"])));
        var layouts = await db.Set<PavementLayoutRevision>().AsNoTracking().Where(x => x.ProjectId == project && x.RouteVersionId == route).Select(x => new { x.Id, x.SegmentSetId }).ToArrayAsync(ct);
        result.AddRange(layouts.Select(x => new GeometryAffectedReferenceFact("LAYOUT", x.Id, route, x.SegmentSetId, "PINNED_REFERENCE", [])));
        var maps = await db.Set<GeometryMapPublication>().AsNoTracking().Where(x => x.ProjectId == project && x.RouteVersionId == route).Select(x => new { x.Id, x.SegmentSetId }).ToArrayAsync(ct);
        result.AddRange(maps.Select(x => new GeometryAffectedReferenceFact("MAP", x.Id, route, x.SegmentSetId, "PINNED_REFERENCE", [])));
        var branches = await db.Set<NativeRouteVersionFacts>().AsNoTracking().Where(x => x.ProjectId == project && x.ParentRouteVersionId == route).Select(x => x.RoadSectionVersionId).ToArrayAsync(ct);
        result.AddRange(branches.Select(x => new GeometryAffectedReferenceFact("BRANCH", x, route, null, "PINNED_REFERENCE", [])));
        return result.DistinctBy(x => (x.Kind, x.Id, x.RouteVersionId, x.SegmentSetId)).OrderBy(x => x.Kind, StringComparer.Ordinal).ThenBy(x => x.Id).ThenBy(x => x.SegmentSetId).ToArray();
    }

    private async Task<GeometryMapSnapshotFact> Snapshot(Guid id, PavementLayoutRevision layout, RoadSectionVersion route,
        RoadSegmentSet set, RoadGeometryMetadata? metadata, CrsProfileRevision? profile,
        Func<GeometryDraftInputFact, int, GeometryPreviewFact> geometryPreview, CancellationToken ct)
    {
        var preview = Decode<PavementGeometryPreviewFact>(layout.SnapshotJson);
        var features = new List<GeometryMapFeatureFact>();
        static double[] Bbox(IEnumerable<GeometryPointFact> points)
        { var a = points.ToArray(); return [a.Min(x => x.X), a.Min(x => x.Y), a.Max(x => x.X), a.Max(x => x.Y)]; }
        var routePoints = route.Geometry.Coordinates.Select(x => new GeometryPointFact(x.X, x.Y)).ToArray();
        features.Add(new($"route:{route.Id:N}", "route", new("LineString", routePoints.Select(x => new[] { x.X, x.Y }).ToArray()), Bbox(routePoints), new { route.VersionNo }));
        var segments = await db.RoadSegments.AsNoTracking().Where(x => x.SegmentSetId == set.Id && x.RoadSectionVersionId == route.Id).OrderBy(x => x.Sequence).ToArrayAsync(ct);
        var missingSegments = segments.Length == 0 || segments.Any(x => x.Geometry is null);
        if (!missingSegments)
            foreach (var s in segments)
            {
                var points = s.Geometry!.Coordinates.Select(x => new GeometryPointFact(x.X, x.Y)).ToArray();
                features.Add(new($"segment:{s.Id:N}", "segments", new("LineString", points.Select(x => new[] { x.X, x.Y }).ToArray()), Bbox(points),
                    new { s.Sequence, s.FromOffsetMeters, s.ToOffsetMeters, s.StartStationMeters, s.EndStationMeters }));
            }
        foreach (var slab in preview.Slabs)
            features.Add(new($"slab:{layout.Id:N}:{slab.Key}", "slabs", new("Polygon", new[] { slab.Footprint.Select(x => new[] { x.X, x.Y }).ToArray() }), Bbox(slab.Footprint), slab));
        var layers = new List<GeometryMapLayerFact> { new("route", "READY", "LineString", 1, [], route.Geometry.SRID, layout.CrsProfileRevisionId, true),
            new GeometryMapLayerFact("segments", missingSegments ? "INCOMPLETE" : "READY", "LineString", missingSegments ? 0 : segments.Length, missingSegments ? ["SEGMENT_GEOMETRY_MISSING"] : []),
            new GeometryMapLayerFact("slabs", "READY", "Polygon", preview.Slabs.Length, []),
            new GeometryMapLayerFact("wgs84", "UNAVAILABLE", "Geometry", 0, ["OFFICIAL_CRS_ACCEPTANCE_PENDING"], 4326, layout.CrsProfileRevisionId, true) };
        var planned = layout.Kind == "PLANNED" ? preview : Decode<PavementGeometryPreviewFact>((await Layout(layout.ProjectId, layout.SourcePlanId, ct)).SnapshotJson);
        void SlabLayer(string key, PavementGeometryPreviewFact? geometry, Guid sourceId)
        {
            foreach (var slab in geometry?.Slabs ?? [])
                features.Add(new($"{key}:{sourceId:N}:{slab.Key}", key, new("Polygon", new[] { slab.Footprint.Select(x => new[] { x.X, x.Y }).ToArray() }), Bbox(slab.Footprint), slab));
            layers.Add(new(key, geometry is null ? "UNAVAILABLE" : "READY", "Polygon", geometry?.Slabs.Length ?? 0,
                geometry is null ? ["AS_BUILT_NOT_CAPTURED"] : [], route.Geometry.SRID, layout.CrsProfileRevisionId, true));
        }
        SlabLayer("plannedSlabs", planned, layout.SourcePlanId ?? layout.Id);
        SlabLayer("asBuiltSlabs", layout.Kind == "AS_BUILT" ? preview : null, layout.Id);
        var shapeFactory = new GeometryFactory(new PrecisionModel(), route.Geometry.SRID);
        if (planned.Plan is not null)
        {
            foreach (var strip in planned.Plan.Cells.GroupBy(x => x.Strip).OrderBy(x => x.Key))
            {
                var sequences = strip.Select(x => x.Sequence).ToHashSet();
                var polygons = planned.Slabs.Where(x => x.PlannedSequence is { } sequence && sequences.Contains(sequence))
                    .Select(x => (Geometry)shapeFactory.CreatePolygon(x.Footprint.Select(p => new Coordinate(p.X, p.Y)).ToArray())).ToList();
                var union = UnaryUnionOp.Union(polygons);
                features.Add(new($"strip:{layout.SourcePlanId ?? layout.Id:N}:{strip.Key}", "strips", Shape(union), Envelope(union), new { strip = strip.Key }));
            }
        }
        layers.Add(new("strips", planned.Plan is null ? "INCOMPLETE" : "READY", "PolygonOrMultiPolygon", features.Count(x => x.Layer == "strips"),
            planned.Plan is null ? ["PLANNED_GRID_MISSING"] : [], route.Geometry.SRID, layout.CrsProfileRevisionId, true));
        if (metadata is not null)
        {
            var input = Decode<GeometryDraftInputFact>(metadata.InputJson) with
            { ResolvedCrsProfile = profile is null ? null : Decode<CrsProfileInputFact>(profile.PayloadJson) };
            var actual = geometryPreview(input, route.Geometry.SRID);
            AddShape("roadSurface", actual.RoadSurface, route.Geometry.SRID);
            AddShape("surveyArea", actual.SurveyArea, route.Geometry.SRID);
            if (actual.Wgs84Centerline is not null) AddShape("wgs84Sample", actual.Wgs84Centerline, 4326);
            else layers.Add(new("wgs84Sample", "UNAVAILABLE", "LineString", 0, ["WGS84_TRANSFORM_NOT_CONFIGURED"], 4326, layout.CrsProfileRevisionId, true));
        }
        else
            foreach (var key in new[] { "roadSurface", "surveyArea", "wgs84Sample" })
                layers.Add(new(key, "INCOMPLETE", "Geometry", 0, ["LEGACY_ROUTE_METADATA_MISSING"], key == "wgs84Sample" ? 4326 : route.Geometry.SRID, null, true));
        var defects = await db.Defects.AsNoTracking().Where(x => x.ProjectId == layout.ProjectId && x.RoadSectionVersionId == route.Id).OrderBy(x => x.Id).ToArrayAsync(ct);
        foreach (var pair in new[] { (Key: "defects", Srid: route.Geometry.SRID), (Key: "defectsWgs84", Srid: 4326) })
        {
            foreach (var defect in defects.Where(x => x.Geometry is { IsEmpty: false } && x.Geometry.SRID == pair.Srid))
                features.Add(new($"defect:{defect.Id:N}", pair.Key, Shape(defect.Geometry!), Envelope(defect.Geometry!),
                    new { defect.Id, defect.DefectTypeCode, defect.Severity, defect.Status }));
            layers.Add(new(pair.Key, "READY", "Geometry", features.Count(x => x.Layer == pair.Key), [], pair.Srid,
                pair.Key == "defects" ? layout.CrsProfileRevisionId : null, true));
        }
        void AddShape(string key, GeometryShapeFact shape, int srid)
        {
            var coordinates = JsonSerializer.SerializeToElement(shape.Coordinates);
            var points = new List<GeometryPointFact>();
            static void Visit(JsonElement value, List<GeometryPointFact> points)
            {
                if (value.ValueKind != JsonValueKind.Array) return;
                var values = value.EnumerateArray().ToArray();
                if (values.Length >= 2 && values[0].ValueKind == JsonValueKind.Number && values[1].ValueKind == JsonValueKind.Number)
                    points.Add(new(values[0].GetDouble(), values[1].GetDouble()));
                else foreach (var child in values) Visit(child, points);
            }
            Visit(coordinates, points);
            if (points.Count == 0) throw new ArgumentException("Produced map geometry is empty.");
            features.Add(new($"{key}:{route.Id:N}", key, shape, Bbox(points), new { routeVersionId = route.Id }));
            layers.Add(new(key, "READY", shape.Type, 1, [], srid, layout.CrsProfileRevisionId, true));
        }
        for (var index = 0; index < layers.Count; index++)
            if (layers[index].SpatialSrid is null) layers[index] = layers[index] with
            { SpatialSrid = route.Geometry.SRID, CrsProfileRevisionId = layout.CrsProfileRevisionId, SampleOnly = true };
        var manifest = new GeometryMapManifestFact(id, layout.ProjectId, route.Id, set.Id, layout.Id, layout.CrsProfileRevisionId,
            route.Geometry.SRID, profile?.Status ?? "LEGACY_UNKNOWN", true, preview.DisplayToleranceMeters, "", layers.ToArray());
        var native = await db.Set<NativeRouteVersionFacts>().AsNoTracking().SingleOrDefaultAsync(x => x.RoadSectionVersionId == route.Id, ct);
        manifest = manifest with
        {
            RouteSystemId = native?.RouteSystemId,
            RoadSectionId = route.RoadSectionId,
            CanonicalLengthMeters = native?.CanonicalLengthMeters ?? route.Geometry.Length,
            DeclaredLengthMeters = native?.DeclaredLengthMeters,
            ChainageStatus = native is null ? "LEGACY" : native.CalibrationJson is null ? "GEOMETRIC" : "CALIBRATED"
        };
        var hash = Hash(new
        {
            manifest,
            features,
            LayoutHash = layout.ContentHash,
            RouteHash = metadata?.GeometryHash,
            SetVersion = Convert.ToBase64String(set.RowVersion),
            SetHash = set.GeometryHash,
            ProfileHash = profile is null ? null : Hash(profile.PayloadJson)
        });
        return new(manifest with { ContentHash = hash }, features.ToArray());
    }
    private static double[] Envelope(Geometry geometry)
        => [geometry.EnvelopeInternal.MinX, geometry.EnvelopeInternal.MinY, geometry.EnvelopeInternal.MaxX, geometry.EnvelopeInternal.MaxY];
    private static GeometryShapeFact Shape(Geometry geometry) => geometry switch
    {
        Point point => new("Point", new[] { point.X, point.Y }),
        LineString line => new("LineString", line.Coordinates.Select(x => new[] { x.X, x.Y }).ToArray()),
        Polygon polygon => new("Polygon", new[] { polygon.ExteriorRing }.Concat(Enumerable.Range(0, polygon.NumInteriorRings).Select(polygon.GetInteriorRingN))
            .Select(x => x.Coordinates.Select(p => new[] { p.X, p.Y }).ToArray()).ToArray()),
        MultiPolygon multi => new("MultiPolygon", Enumerable.Range(0, multi.NumGeometries).Select(x => Shape(multi.GetGeometryN(x)).Coordinates).ToArray()),
        MultiPoint points => new("MultiPoint", Enumerable.Range(0, points.NumGeometries).Select(x => Shape(points.GetGeometryN(x)).Coordinates).ToArray()),
        MultiLineString lines => new("MultiLineString", Enumerable.Range(0, lines.NumGeometries).Select(x => Shape(lines.GetGeometryN(x)).Coordinates).ToArray()),
        _ => throw new ArgumentException("Unsupported persisted map shape.")
    };
}

using RoadGuardSystem.DTOs.Projects;
using System.Security.Cryptography;
using System.Text.Json;

namespace RoadGuardSystem.Services.Projects;

public static class GeometryMapPageEngine
{
    public static GeometryMapPage Page(GeometryMapSnapshot snapshot, string layer, string expectedHash,
        int limit, double[]? bbox = null, string? cursor = null)
    {
        ArgumentNullException.ThrowIfNull(snapshot);
        if (limit is < 1 or > 500 || string.IsNullOrWhiteSpace(layer) ||
            bbox is not null && (bbox.Length != 4 || bbox.Any(x => !double.IsFinite(x)) || bbox[0] > bbox[2] || bbox[1] > bbox[3]))
            Fail("geometry_page_invalid");
        if (expectedHash != snapshot.Manifest.ContentHash) Fail("geometry_version_mismatch");
        var descriptor = snapshot.Manifest.Layers.SingleOrDefault(x => x.Key == layer);
        if (descriptor is null) Fail("geometry_layer_not_found");
        if (descriptor.Status != "READY") Fail("geometry_layer_unavailable");
        var filterHash = Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(bbox)));
        var offset = 0;
        if (cursor is not null)
        {
            Cursor decoded;
            try
            {
                if (cursor.Length > 4096) Fail("geometry_cursor_invalid");
                decoded = JsonSerializer.Deserialize<Cursor>(Convert.FromBase64String(cursor))
                    ?? throw new JsonException();
            }
            catch (Exception e) when (e is JsonException or FormatException) { Fail("geometry_cursor_invalid"); throw; }
            if (decoded.PublicationId != snapshot.Manifest.PublicationId || decoded.Hash != expectedHash ||
                decoded.Layer != layer || decoded.FilterHash != filterHash) Fail("geometry_version_mismatch");
            offset = decoded.Offset;
        }
        var all = snapshot.Features.Where(x => x.Layer == layer).OrderBy(x => x.Id, StringComparer.Ordinal).ToArray();
        if (all.Length != descriptor.Count || all.Select(x => x.Id).Distinct(StringComparer.Ordinal).Count() != all.Length ||
            all.Any(f => f.Bbox.Length != 4 || f.Bbox.Any(x => !double.IsFinite(x)))) Fail("geometry_snapshot_invalid");
        var features = bbox is null ? all : all.Where(f => f.Bbox[0] <= bbox[2] && f.Bbox[2] >= bbox[0] && f.Bbox[1] <= bbox[3] && f.Bbox[3] >= bbox[1]).ToArray();
        if (offset < 0 || offset > features.Length) Fail("geometry_cursor_invalid");
        var selected = features.Skip(offset).Take(limit).ToArray();
        var nextOffset = offset + selected.Length;
        var next = nextOffset < features.Length ? Convert.ToBase64String(JsonSerializer.SerializeToUtf8Bytes(
            new Cursor(snapshot.Manifest.PublicationId, expectedHash, layer, filterHash, nextOffset))) : null;
        return new(snapshot.Manifest.PublicationId, expectedHash, layer, selected, next);
    }
    private sealed record Cursor(Guid PublicationId, string Hash, string Layer, string FilterHash, int Offset);
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Fail(string code) => throw new GeometryValidationException(code, "The pinned map request could not be completed.");
}

using RoadGuardSystem.DTOs.Projects;
using NetTopologySuite.Geometries;
using NetTopologySuite.Operation.Union;

namespace RoadGuardSystem.Services.Projects;

public static class PavementFootprintEngine
{
    public static PavementGeometryPreview Planned(NativeAlignment alignment, PavementPlanCreateInput input)
    {
        ArgumentNullException.ThrowIfNull(alignment); ArgumentNullException.ThrowIfNull(input);
        if (!double.IsFinite(input.DisplayToleranceMeters) || input.DisplayToleranceMeters <= 0)
            throw new ArgumentException("An explicit positive display tolerance is required.", nameof(input));
        if (alignment.Length >= (double)decimal.MaxValue)
            throw new ArgumentException("The alignment exceeds supported metric dimensions.", nameof(input));
        ArgumentNullException.ThrowIfNull(input.Layout);
        var canonicalLength = (decimal)alignment.Length;
        var layoutInput = input.Layout;
        var normalized = false;
        if (layoutInput.WidthProfile is { Length: > 0 } widths && widths[^1] is { ToOffsetMeters: > 0 } last &&
            last.ToOffsetMeters != canonicalLength && Math.Abs(last.ToOffsetMeters - canonicalLength) <= (decimal)(1e-12 * Math.Max(1, alignment.Length)))
        {
            // Numeric conversion consistency only: JSON round-trip double versus decimal.
            // This neither changes strip widths nor represents survey accuracy/tolerance.
            var adjusted = widths.ToArray(); adjusted[^1] = last with { ToOffsetMeters = canonicalLength };
            layoutInput = layoutInput with { WidthProfile = adjusted }; normalized = true;
        }
        var plan = PavementLayoutEngine.Plan(canonicalLength, layoutInput);
        if (normalized) plan = plan with { Warnings = plan.Warnings.Append("NATIVE_OFFSET_NUMERIC_CONVERSION_NORMALIZED").ToArray() };
        if (plan.Cells.Length > 10000) throw new ArgumentException("Footprint preview exceeds the feature bound.", nameof(input));
        long vertexCount = 0;
        var slabs = plan.Cells.Select(cell =>
        {
            var from = Math.Min(alignment.Length, (double)cell.FromOffsetMeters);
            var to = Math.Min(alignment.Length, (double)cell.ToOffsetMeters);
            var left = (double)cell.FromLateralMeters; var right = (double)cell.ToLateralMeters;
            var offsets = new SortedSet<double> { from, to };
            foreach (var boundary in alignment.PrimitiveBoundaries.Where(x => x > from && x < to)) offsets.Add(boundary);
            foreach (var arc in alignment.ArcRanges.Where(x => x.FromOffsetMeters < to && x.ToOffsetMeters > from))
            {
                var lateral = Math.Max(Math.Abs(left), Math.Abs(right));
                if (arc.Radius <= lateral) throw new ArgumentException("A slab offset reaches or crosses the inner curve centre.", nameof(input));
                var outerRadius = arc.Radius + lateral;
                var angle = Math.Min(Math.PI / 2, 2 * Math.Acos(Math.Clamp(1 - input.DisplayToleranceMeters / outerRadius, -1, 1)));
                if (angle <= 0) throw new ArgumentException("Display tolerance is below numeric resolution.", nameof(input));
                var low = Math.Max(from, arc.FromOffsetMeters); var high = Math.Min(to, arc.ToOffsetMeters);
                var required = Math.Ceiling((high - low) / arc.Radius / angle);
                if (required > 4096) throw new ArgumentException("Footprint vertex bound exceeded.", nameof(input));
                var steps = (int)Math.Max(1, required);
                for (var index = 0; index <= steps; index++) offsets.Add(low + (high - low) * index / steps);
            }
            if (offsets.Count > 4097) throw new ArgumentException("Footprint vertex bound exceeded.", nameof(input));
            vertexCount += 2L * offsets.Count + 1;
            if (vertexCount > 1000000) throw new ArgumentException("The footprint batch exceeds the vertex bound.", nameof(input));
            GeometryPoint Offset(double at, double lateral)
            {
                var point = alignment.PointAt(at); var tangent = alignment.TangentAt(at);
                return new(point.X - tangent.Y * lateral, point.Y + tangent.X * lateral);
            }
            var ring = offsets.Select(x => Offset(x, left)).Concat(offsets.Reverse().Select(x => Offset(x, right))).ToList();
            ring.Add(ring[0]);
            ValidatePolygon(ring.ToArray());
            return new SlabGeometrySnapshot(cell.Sequence.ToString(System.Globalization.CultureInfo.InvariantCulture), cell.Sequence,
                ring.ToArray(), (double)(cell.ToOffsetMeters - cell.FromOffsetMeters), (double)(cell.ToLateralMeters - cell.FromLateralMeters), null, "ANALYTIC_PLAN", ProvenanceStatus: "SERVER_ANALYTIC_MODEL");
        }).ToArray();
        if (slabs.Sum(s => (long)s.Footprint.Length) > 1000000)
            throw new ArgumentException("The footprint batch exceeds the vertex bound.", nameof(input));
        return new(plan, slabs, plan.Warnings, input.DisplayToleranceMeters);
    }
    public static PavementGeometryPreview AsBuilt(PavementGeometryPreview planned, AsBuiltLayoutInput input)
    {
        ArgumentNullException.ThrowIfNull(planned); ArgumentNullException.ThrowIfNull(input);
        if (input.SourcePlanId == Guid.Empty || input.Slabs is null || input.Slabs.Length is < 1 or > 10000 ||
            string.IsNullOrWhiteSpace(input.Reason) || input.Reason.Trim().Length > 2000)
            throw new ArgumentException("A source plan, bounded slab evidence and a reason are required.", nameof(input));
        if (input.Slabs.Any(s => s is null || s.Footprint is null) || input.Slabs.Sum(s => (long)s.Footprint.Length) > 1000000)
            throw new ArgumentException("A bounded set of non-null slab footprints is required.", nameof(input));
        var keys = new HashSet<string>(StringComparer.Ordinal);
        var polygons = new List<Geometry>();
        var slabs = input.Slabs.Select(slab =>
        {
            if (string.IsNullOrWhiteSpace(slab.Key) || slab.Key.Length > 80 || !keys.Add(slab.Key) ||
                slab.Key.Any(c => c is < '!' or > '~') ||
                string.IsNullOrWhiteSpace(slab.Source) || slab.Source.Length > 80 ||
                slab.PlannedSequence is { } sequence && !planned.Slabs.Any(s => s.PlannedSequence == sequence) ||
                slab.LengthMeters is { } length && (!double.IsFinite(length) || length <= 0) ||
                slab.WidthMeters is { } width && (!double.IsFinite(width) || width <= 0) ||
                (slab.LengthMeters is null || slab.WidthMeters is null) && (string.IsNullOrWhiteSpace(slab.DimensionUnknownReason) || slab.DimensionUnknownReason.Length > 500))
                throw new ArgumentException("Slab identity, provenance and explicit known/unknown dimensions are required.", nameof(input));
            polygons.Add(ValidatePolygon(slab.Footprint));
            return new SlabGeometrySnapshot(slab.Key, slab.PlannedSequence, slab.Footprint.ToArray(), slab.LengthMeters,
                slab.WidthMeters, slab.DimensionUnknownReason, slab.Source, slab.SourceFileId);
        }).ToArray();
        if (slabs.Sum(s => (long)s.Footprint.Length) > 1000000)
            throw new ArgumentException("The footprint batch exceeds the vertex bound.", nameof(input));
        var plannedArea = UnaryUnionOp.Union(planned.Slabs.Select(s => (Geometry)ValidatePolygon(s.Footprint)).ToList());
        var builtArea = UnaryUnionOp.Union(polygons);
        var overlap = Math.Max(0, polygons.Sum(p => p.Area) - builtArea.Area);
        var gap = plannedArea.Difference(builtArea).Area;
        var outside = builtArea.Difference(plannedArea).Area;
        var warnings = new List<string> { "RENDERED_COVERAGE_IS_NOT_SURVEY_ACCURACY" };
        if (gap > 0) warnings.Add("AS_BUILT_GAPS");
        if (overlap > 0) warnings.Add("AS_BUILT_OVERLAPS");
        if (outside > 0) warnings.Add("AS_BUILT_OUTSIDE_PLAN");
        return new(null, slabs, warnings.ToArray(), planned.DisplayToleranceMeters, gap, overlap);
    }
    private static Polygon ValidatePolygon(GeometryPoint[] points)
    {
        if (points is null || points.Length is < 4 or > 8195 || points.Any(p => p is null || !double.IsFinite(p.X) || !double.IsFinite(p.Y)) || points[0] != points[^1])
            throw new ArgumentException("A bounded closed native footprint is required.", nameof(points));
        var polygon = new GeometryFactory().CreatePolygon(points.Select(p => new Coordinate(p.X, p.Y)).ToArray());
        if (!polygon.IsValid || polygon.IsEmpty || !double.IsFinite(polygon.Area) || polygon.Area <= 0)
            throw new ArgumentException("Footprint must be a valid positive-area polygon.", nameof(points));
        return polygon;
    }
}

using NetTopologySuite.Geometries;
using RoadGuardSystem.DTOs.Projects;

namespace RoadGuardSystem.Services.Projects;

// Native projected E/N metres. Sampling is a rendering/query approximation, never the canonical length.
public sealed class NativeAlignment
{
    private readonly NativeAlignmentPrimitive[] primitives;
    private readonly double[] ends;
    private readonly int srid;
    public Guid CrsProfileRevisionId { get; }
    public bool IsLegacy { get; }
    public double Length => ends[^1];
    public IReadOnlyList<NativeArcRange> ArcRanges { get; } = [];
    public IReadOnlyList<double> PrimitiveBoundaries => new[] { 0d }.Concat(ends).ToArray();

    private NativeAlignment(NativeAlignmentInput input, bool legacy)
    {
        if ((!legacy && input.CrsProfileRevisionId == Guid.Empty) || input.SpatialSrid < 0 || input.Primitives is null || input.Primitives.Length is < 1 or > 100000)
            Fail("Profile and a bounded primitive sequence are required.");
        CrsProfileRevisionId = input.CrsProfileRevisionId; IsLegacy = legacy; srid = input.SpatialSrid;
        primitives = input.Primitives.ToArray(); ends = new double[primitives.Length];
        var arcs = new List<NativeArcRange>(); double offset = 0;
        for (var index = 0; index < primitives.Length; index++)
        {
            var p = primitives[index];
            if (p is null || !Finite(p.Start) || !Finite(p.End)) Fail("Finite native coordinates are required.");
            if (index > 0 && !Same(primitives[index - 1].End, p.Start)) Fail("Primitive sequence has a gap.");
            double length;
            if (p.Kind == "LINE")
            {
                if (p.Center is not null || p.Radius is not null || p.StartAngleRadians is not null || p.SweepRadians is not null) Fail("LINE cannot contain ARC parameters.");
                length = Distance(p.Start, p.End);
            }
            else if (p.Kind == "ARC")
            {
                if (!Finite(p.Center) || p.Radius is not double r || !double.IsFinite(r) || r <= 0 || p.StartAngleRadians is not double start || !double.IsFinite(start) || p.SweepRadians is not double sweep || !double.IsFinite(sweep) || sweep == 0 || Math.Abs(sweep) >= 2 * Math.PI)
                    Fail("ARC requires a positive radius and a finite signed sweep smaller than a full circle.");
                if (!Same(p.Start, ArcPoint(p, 0)) || !Same(p.End, ArcPoint(p, 1))) Fail("ARC endpoints disagree with its analytic parameters.");
                length = p.Radius!.Value * Math.Abs(p.SweepRadians!.Value);
                arcs.Add(new(offset, offset + length, p.Radius.Value));
            }
            else { Fail("Only LINE and ARC primitives are supported."); return; }
            if (!double.IsFinite(length) || length <= 0 || !double.IsFinite(offset + length)) Fail("Primitive length must be finite and positive.");
            offset += length; ends[index] = offset;
        }
        ArcRanges = arcs.AsReadOnly();
    }

    public static NativeAlignment Create(NativeAlignmentInput input) => new(input, false);
    public static NativeAlignment FromLegacy(LineString geometry)
    {
        ArgumentNullException.ThrowIfNull(geometry);
        return new(new(Guid.Empty, geometry.Coordinates.Zip(geometry.Coordinates.Skip(1))
            .Select(pair => new NativeAlignmentPrimitive("LINE", new(pair.First.X, pair.First.Y), new(pair.Second.X, pair.Second.Y))).ToArray(), geometry.SRID), true);
    }
    public GeometryPoint PointAt(double offset)
    {
        var (p, fraction) = Locate(offset);
        return p.Kind == "ARC" ? ArcPoint(p, fraction) : new(p.Start.X + fraction * (p.End.X - p.Start.X), p.Start.Y + fraction * (p.End.Y - p.Start.Y));
    }
    public GeometryPoint TangentAt(double offset)
    {
        var (p, fraction) = Locate(offset);
        if (p.Kind == "LINE") { var d = Distance(p.Start, p.End); return new((p.End.X - p.Start.X) / d, (p.End.Y - p.Start.Y) / d); }
        var angle = p.StartAngleRadians!.Value + fraction * p.SweepRadians!.Value;
        var direction = Math.Sign(p.SweepRadians.Value);
        return new(-direction * Math.Sin(angle), direction * Math.Cos(angle));
    }
    public LineString Extract(double from, double to, double tessellationTolerance)
    {
        ValidateOffset(from); ValidateOffset(to);
        if (to <= from || !double.IsFinite(tessellationTolerance) || tessellationTolerance <= 0) Fail("Ordered offsets and an explicit positive rendering tolerance are required.");
        var coordinates = new List<Coordinate>();
        for (var index = 0; index < primitives.Length; index++)
        {
            var begin = index == 0 ? 0 : ends[index - 1]; var end = ends[index];
            var lo = Math.Max(from, begin); var hi = Math.Min(to, end);
            if (hi <= lo) continue;
            var p = primitives[index]; int count = 1;
            if (p.Kind == "ARC")
            {
                var radius = p.Radius!.Value;
                var angleStep = 2 * Math.Acos(Math.Clamp(1 - tessellationTolerance / radius, -1, 1));
                if (angleStep <= 0) Fail("Rendering tolerance is below numeric resolution.");
                var required = Math.Ceiling((hi - lo) / radius / Math.Min(angleStep, Math.PI / 2));
                if (required > 100000) Fail("Rendering exceeds the feature vertex bound.");
                count = (int)Math.Max(1, required);
            }
            for (var step = 0; step <= count; step++)
            {
                var point = PointOn(index, lo + (hi - lo) * step / count);
                if (coordinates.Count == 0 || !coordinates[^1].Equals2D(new Coordinate(point.X, point.Y))) coordinates.Add(new(point.X, point.Y));
                if (coordinates.Count > 100001) Fail("Rendering exceeds the feature vertex bound.");
            }
        }
        return new GeometryFactory(new PrecisionModel(), srid).CreateLineString(coordinates.ToArray());
    }
    private GeometryPoint PointOn(int index, double offset)
    {
        var begin = index == 0 ? 0 : ends[index - 1]; var fraction = (offset - begin) / (ends[index] - begin); var p = primitives[index];
        return p.Kind == "ARC" ? ArcPoint(p, fraction) : new(p.Start.X + fraction * (p.End.X - p.Start.X), p.Start.Y + fraction * (p.End.Y - p.Start.Y));
    }
    private (NativeAlignmentPrimitive Primitive, double Fraction) Locate(double offset)
    {
        ValidateOffset(offset);
        var index = Array.FindIndex(ends, end => offset < end);
        if (index < 0) index = ends.Length - 1;
        var start = index == 0 ? 0 : ends[index - 1];
        return (primitives[index], (offset - start) / (ends[index] - start));
    }
    private void ValidateOffset(double offset) { if (!double.IsFinite(offset) || offset < 0 || offset > Length) Fail("Offset is outside the analytic alignment."); }
    private static GeometryPoint ArcPoint(NativeAlignmentPrimitive p, double fraction) => new(p.Center!.X + p.Radius!.Value * Math.Cos(p.StartAngleRadians!.Value + fraction * p.SweepRadians!.Value), p.Center.Y + p.Radius.Value * Math.Sin(p.StartAngleRadians.Value + fraction * p.SweepRadians.Value));
    private static bool Finite(GeometryPoint? p) => p is not null && double.IsFinite(p.X) && double.IsFinite(p.Y);
    private static double Distance(GeometryPoint a, GeometryPoint b) => Math.Sqrt(Math.Pow(a.X - b.X, 2) + Math.Pow(a.Y - b.Y, 2));
    // Floating-point consistency bound only; this does not represent survey accuracy or a CRS tolerance.
    private static bool Same(GeometryPoint a, GeometryPoint b) => Distance(a, b) <= 1e-10 * Math.Max(1, Math.Max(Math.Abs(a.X), Math.Max(Math.Abs(a.Y), Math.Max(Math.Abs(b.X), Math.Abs(b.Y)))));
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Fail(string detail) => throw new GeometryValidationException("native_alignment_invalid", detail);
}

using RoadGuardSystem.DTOs.Projects;
namespace RoadGuardSystem.Services.Projects;

public static class CrsProfileEngine
{
    public static void Validate(CrsProfileInput profile)
    {
        if (string.IsNullOrWhiteSpace(profile.Code) || profile.Code.Length > 80 || profile.SourceSrid < 0 || string.IsNullOrWhiteSpace(profile.Datum) || string.IsNullOrWhiteSpace(profile.Projection) || profile.AxisOrder is not ("EN" or "NE") || !double.IsFinite(profile.MetresPerUnit) || profile.MetresPerUnit <= 0 || string.IsNullOrWhiteSpace(profile.SourceReference) || !Hash(profile.SourceChecksum)) Fail("Profile definition and provenance must be explicit.");
        if (profile.Operation is { } operation)
        {
            if (string.IsNullOrWhiteSpace(operation.Method) || string.IsNullOrWhiteSpace(operation.Convention) || operation.Direction != "NATIVE_TO_WGS84" || string.IsNullOrWhiteSpace(operation.SourceReference) || operation.Parameters is null || operation.Parameters.Any(x => !double.IsFinite(x))) Fail("Operation identity, direction, parameters and source must be explicit.");
            if (operation.Method == "SAMPLE_AFFINE_TO_WGS84" && (!profile.SampleOnly || operation.Parameters.Length != 6)) Fail("Sample affine operation cannot be used for official real data.");
            if (operation.PublishedAccuracyMeters is { } accuracy && (!double.IsFinite(accuracy) || accuracy <= 0 || string.IsNullOrWhiteSpace(operation.AccuracySource))) Fail("Operation accuracy requires a source.");
        }
        if (profile.Ellipsoid is { } ellipsoid && (!double.IsFinite(ellipsoid.SemiMajorAxisMeters) || ellipsoid.SemiMajorAxisMeters <= 0 || !double.IsFinite(ellipsoid.InverseFlattening) || ellipsoid.InverseFlattening <= 1 || string.IsNullOrWhiteSpace(ellipsoid.SourceReference))) Fail("Ellipsoid parameters require a source.");
        if (profile.ProjectionDefinition is { } projection && (projection.Parameters is null || projection.Parameters.Count == 0 || projection.Parameters.Any(x => string.IsNullOrWhiteSpace(x.Key) || !double.IsFinite(x.Value)) || string.IsNullOrWhiteSpace(projection.SourceReference))) Fail("Projection parameters require a source.");
        if (profile.SourcedToleranceMeters is { } tolerance && (!double.IsFinite(tolerance) || tolerance <= 0 || string.IsNullOrWhiteSpace(profile.ToleranceSource))) Fail("Accuracy tolerance requires a source.");
        if (profile.IndependentControls?.Any(c => c is null || !Finite(c.Native) || !Finite(c.Wgs84) || string.IsNullOrWhiteSpace(c.IndependentSource)) == true) Fail("Controls require independent provenance and finite coordinates.");
    }
    public static GeometryPoint NormalizeSource(GeometryPoint point, CrsProfileInput profile)
    {
        Validate(profile); if (!Finite(point)) Fail("Source coordinate is not finite.");
        var normalized = profile.AxisOrder == "EN" ? new GeometryPoint(point.X * profile.MetresPerUnit, point.Y * profile.MetresPerUnit) : new GeometryPoint(point.Y * profile.MetresPerUnit, point.X * profile.MetresPerUnit);
        if (!Finite(normalized)) Fail("Source normalization overflowed.");
        return normalized;
    }
    // Executable synthetic adapter only. Other pinned operation identities require an actual verified adapter;
    // no projection/datum parameters or controls are inferred from a province, EPSG label or UTM number.
    public static bool TryTransformCanonical(GeometryPoint point, CrsProfileInput profile, out GeometryPoint? wgs84)
    {
        Validate(profile); wgs84 = null;
        if (!Finite(point) || !profile.SampleOnly || profile.Operation?.Method != "SAMPLE_AFFINE_TO_WGS84") return false;
        var a = profile.Operation.Parameters;
        var candidate = new GeometryPoint(a[0] * point.X + a[1] * point.Y + a[2], a[3] * point.X + a[4] * point.Y + a[5]);
        if (!Finite(candidate) || candidate.X is < -180 or > 180 || candidate.Y is < -90 or > 90) Fail("Configured sample operation is outside WGS84 coordinate bounds.");
        wgs84 = candidate; return true;
    }
    public static GeometryDraftReadiness Readiness(GeometryDraftInput input, CrsProfileInput? profile)
    {
        var missing = new List<string>(); var errors = new List<string>();
        if (!double.IsFinite(input.StationOriginMeters) || !double.IsFinite(input.SurveyWidthMeters)) errors.Add("native_numeric_value_invalid");
        if (input.WidthProfile?.Any(x => x is null || !double.IsFinite(x.FromOffsetMeters) || !double.IsFinite(x.ToOffsetMeters) || !double.IsFinite(x.WidthMeters)) == true) errors.Add("native_width_invalid");
        if (input.NativeAlignment is null) missing.Add("nativeAlignment");
        if (profile is null) missing.Add("crsProfileRevision");
        if (input.RouteSystemId is null || input.RouteSystemId == Guid.Empty) missing.Add("routeSystemId");
        if (input.RouteKind is not ("MAIN" or "BRANCH")) missing.Add("routeKind");
        if (input.WidthProfile is null || input.WidthProfile.Length == 0 || input.SurveyWidthMeters <= 0) missing.Add("widthProfile");
        if (input.TessellationToleranceMeters is null) missing.Add("tessellationToleranceMeters");
        if (string.IsNullOrWhiteSpace(input.ChangeReason)) missing.Add("changeReason");
        if (input.RouteKind == "BRANCH" && (input.ParentRouteVersionId is null || input.JunctionOffsetMeters is null)) missing.Add("branchJunction");
        if (input.RouteKind == "MAIN" && (input.ParentRouteVersionId is not null || input.JunctionOffsetMeters is not null)) errors.Add("main_route_cannot_have_parent");
        if (input.DeclaredLengthMeters is { } declared && (!double.IsFinite(declared) || declared <= 0)) errors.Add("declared_length_invalid");
        try
        {
            if (profile is not null) Validate(profile);
            if (input.NativeAlignment is not null)
            {
                var alignment = NativeAlignment.Create(input.NativeAlignment);
                if (!double.IsFinite(input.StationOriginMeters + alignment.Length)) Fail("Station range overflowed.");
                if (input.WidthProfile is { Length: > 0 })
                {
                    double end = 0;
                    foreach (var width in input.WidthProfile)
                    {
                        if (width is null || !double.IsFinite(width.FromOffsetMeters) || !double.IsFinite(width.ToOffsetMeters) || !double.IsFinite(width.WidthMeters) || width.FromOffsetMeters != end || width.ToOffsetMeters <= end || width.ToOffsetMeters > alignment.Length || width.WidthMeters <= 0 || width.WidthMeters > input.SurveyWidthMeters) Fail("Width intervals must cover canonical length inside survey width.");
                        end = width.ToOffsetMeters;
                    }
                    if (Math.Abs(end - alignment.Length) > 1e-9 * Math.Max(1, alignment.Length)) Fail("Width intervals must cover canonical length.");
                }
                if (input.TessellationToleranceMeters is { } tolerance) alignment.Extract(0, alignment.Length, tolerance);
                ValidateCalibration(input.ChainageCalibration, alignment.Length);
            }
        }
        catch (GeometryValidationException exception) { errors.Add(exception.Code); }
        return new(missing.Count == 0 && errors.Count == 0, missing.ToArray(), errors.ToArray(), "CANDIDATE", profile?.SampleOnly ?? false,
            ["OFFICIAL_CRS_OPERATION_AND_INDEPENDENT_CONTROL_NOT_VERIFIED"]);
    }
    public static void ValidateCalibration(ChainageCalibrationInput? calibration, double length)
    {
        if (calibration is null) return;
        if (string.IsNullOrWhiteSpace(calibration.SourceReference) || !Hash(calibration.SourceChecksum) || string.IsNullOrWhiteSpace(calibration.SelectedReason) || calibration.Controls is null || calibration.Controls.Length < 2 || calibration.Controls.Any(c => c is null || !double.IsFinite(c.GeometricOffsetMeters) || !double.IsFinite(c.StationMeters)) || calibration.Controls[0].GeometricOffsetMeters != 0 || calibration.Controls[^1].GeometricOffsetMeters != length || calibration.Controls.Zip(calibration.Controls.Skip(1)).Any(p => p.Second.GeometricOffsetMeters <= p.First.GeometricOffsetMeters || p.Second.StationMeters <= p.First.StationMeters)) Fail("Chainage calibration must be sourced, PM-selected and monotonically cover the geometric alignment.");
    }
    public static double StationAt(double offset, double origin, ChainageCalibrationInput? calibration, double length)
    {
        ValidateCalibration(calibration, length);
        if (!double.IsFinite(offset) || offset < 0 || offset > length || !double.IsFinite(origin)) Fail("Chainage offset is invalid.");
        if (calibration is null)
        {
            var station = origin + offset;
            if (!double.IsFinite(station)) Fail("Station range overflowed.");
            return station;
        }
        var pair = calibration.Controls.Zip(calibration.Controls.Skip(1)).First(p => offset <= p.Second.GeometricOffsetMeters);
        var fraction = (offset - pair.First.GeometricOffsetMeters) / (pair.Second.GeometricOffsetMeters - pair.First.GeometricOffsetMeters);
        var result = (1 - fraction) * pair.First.StationMeters + fraction * pair.Second.StationMeters;
        if (!double.IsFinite(result)) Fail("Calibrated station overflowed.");
        return result;
    }
    private static bool Hash(string value) => value is { Length: 64 } && value.All(c => c is >= '0' and <= '9' or >= 'a' and <= 'f');
    private static bool Finite(GeometryPoint? point) => point is not null && double.IsFinite(point.X) && double.IsFinite(point.Y);
    [System.Diagnostics.CodeAnalysis.DoesNotReturn]
    private static void Fail(string detail) => throw new GeometryValidationException("crs_profile_invalid", detail);
}

using RoadGuardSystem.DTOs.Projects;

namespace RoadGuardSystem.Services.Projects;

public static class PavementLayoutEngine
{
    public static PavementLayoutPreview Plan(decimal analyticLengthMeters, PavementLayoutInput input)
    {
        const int maximumCells = 100000;
        ArgumentNullException.ThrowIfNull(input);
        if (analyticLengthMeters <= 0 || input.StripWidthMeters <= 0 || input.SlabLengthMeters <= 0 ||
            input.WidthProfile is null || input.WidthProfile.Length == 0 || input.WidthProfile.Length > maximumCells)
            throw new ArgumentException("Positive dimensions and a complete width profile are required.", nameof(input));
        if (input.SlabLengthMeters < analyticLengthMeters / int.MaxValue)
            throw new ArgumentException("The longitudinal grid exceeds supported row numbering.", nameof(input));
        decimal previousEnd = 0;
        foreach (var interval in input.WidthProfile)
        {
            if (interval is null || interval.FromOffsetMeters != previousEnd || interval.ToOffsetMeters <= interval.FromOffsetMeters ||
                interval.ToOffsetMeters > analyticLengthMeters || interval.WidthMeters <= 0 ||
                interval.WidthMeters % input.StripWidthMeters != 0)
                throw new ArgumentException("Width intervals must cover the alignment contiguously and divide into equal strips exactly.", nameof(input));
            if (input.StripWidthMeters < interval.WidthMeters / maximumCells ||
                input.SlabLengthMeters < (interval.ToOffsetMeters - interval.FromOffsetMeters) / maximumCells)
                throw new ArgumentException("The layout exceeds the bounded cell count.", nameof(input));
            var strips = interval.WidthMeters / input.StripWidthMeters;
            var rows = decimal.Ceiling((interval.ToOffsetMeters - interval.FromOffsetMeters) / input.SlabLengthMeters);
            if (strips > maximumCells || rows > maximumCells / strips)
                throw new ArgumentException("The layout exceeds the bounded cell count.", nameof(input));
            previousEnd = interval.ToOffsetMeters;
        }
        if (previousEnd != analyticLengthMeters)
            throw new ArgumentException("The width profile must cover the complete analytic alignment.", nameof(input));

        var cells = new List<PlannedSlabCell>();
        foreach (var interval in input.WidthProfile)
        {
            var offset = interval.FromOffsetMeters;
            var strips = (int)(interval.WidthMeters / input.StripWidthMeters);
            while (offset < interval.ToOffsetMeters)
            {
                var rowIndex = decimal.Floor(offset / input.SlabLengthMeters);
                if (rowIndex >= int.MaxValue)
                    throw new ArgumentException("The longitudinal grid exceeds supported row numbering.", nameof(input));
                var rowStart = rowIndex * input.SlabLengthMeters;
                var rowEnd = rowStart > decimal.MaxValue - input.SlabLengthMeters
                    ? decimal.MaxValue : rowStart + input.SlabLengthMeters;
                var end = Math.Min(interval.ToOffsetMeters, rowEnd);
                var residual = end == analyticLengthMeters && analyticLengthMeters % input.SlabLengthMeters != 0;
                var transition = offset != rowStart || end != rowEnd && end != analyticLengthMeters;
                if (cells.Count > maximumCells - strips)
                    throw new ArgumentException("The layout exceeds the bounded cell count.", nameof(input));
                for (var strip = 0; strip < strips; strip++)
                    cells.Add(new(cells.Count + 1, (int)rowIndex + 1, strip + 1, offset, end,
                        strip * input.StripWidthMeters - interval.WidthMeters / 2,
                        (strip + 1) * input.StripWidthMeters - interval.WidthMeters / 2, residual, transition));
                offset = end;
            }
        }
        var warnings = new List<string>();
        if (cells.Any(c => c.IsTerminalResidual)) warnings.Add("EXPLICIT_TERMINAL_RESIDUAL");
        if (input.WidthProfile.Length > 1) warnings.Add("WIDTH_TRANSITION_BOUNDARIES");
        return new(analyticLengthMeters, input.StripWidthMeters, input.SlabLengthMeters, cells.ToArray(), warnings.ToArray());
    }
}

