using RoadGuardSystem.BusinessObjects.Auditing;

namespace RoadGuardSystem.BusinessObjects.Idempotency;

public sealed class IdempotencyRecord
{
    private IdempotencyRecord()
    {
    }

    public Guid Id { get; private set; }

    public Guid? ActorUserId { get; private set; }

    public Guid? ProjectId { get; private set; }

    public string Operation { get; private set; } = string.Empty;

    public string IdempotencyKey { get; private set; } = string.Empty;

    public string RequestFingerprint { get; private set; } = string.Empty;

    public Guid OperationId { get; private set; }

    public string OutcomeJson { get; private set; } = string.Empty;

    public DateTimeOffset CreatedAtUtc { get; private set; }

    public static IdempotencyRecord Create(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Guid operationId,
        string outcomeJson,
        DateTimeOffset createdAt)
    {
        ValidateRequired(operation, nameof(operation), 100);
        ValidateRequired(idempotencyKey, nameof(idempotencyKey), 200);
        ValidateFingerprint(requestFingerprint, nameof(requestFingerprint));
        ValidateJson(outcomeJson, nameof(outcomeJson));
        if (operationId == Guid.Empty)
        {
            throw new ArgumentException("Operation id must not be empty.", nameof(operationId));
        }

        return new IdempotencyRecord
        {
            // The receipt has its own identity. One business resource can legitimately
            // participate in several idempotent operations (for example create and retry).
            Id = Guid.NewGuid(),
            ActorUserId = actorUserId,
            ProjectId = projectId,
            Operation = operation.Trim(),
            IdempotencyKey = idempotencyKey.Trim(),
            RequestFingerprint = requestFingerprint,
            OperationId = operationId,
            OutcomeJson = outcomeJson,
            CreatedAtUtc = createdAt.ToUniversalTime()
        };
    }

    public static void ValidateScope(
        string operation,
        string idempotencyKey,
        string requestFingerprint)
    {
        ValidateRequired(operation, nameof(operation), 100);
        ValidateRequired(idempotencyKey, nameof(idempotencyKey), 200);
        ValidateFingerprint(requestFingerprint, nameof(requestFingerprint));
    }

    private static void ValidateRequired(string value, string parameterName, int maxLength)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(value, parameterName);
        if (value.Length > maxLength)
        {
            throw new ArgumentException($"Value exceeds maximum length {maxLength}.", parameterName);
        }
    }

    private static void ValidateFingerprint(string value, string parameterName)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(value, parameterName);
        if (value.Length != 64 || value.Any(character => character is not (>= '0' and <= '9') and not (>= 'a' and <= 'f')))
        {
            throw new ArgumentException(
                "Request fingerprint must be a lowercase SHA-256 hexadecimal value.",
                parameterName);
        }
    }

    private static void ValidateJson(string json, string parameterName)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(json, parameterName);
        try
        {
            using var document = JsonDocument.Parse(json);
            if (document.RootElement.ValueKind is not (JsonValueKind.Object or JsonValueKind.Array))
            {
                throw new ArgumentException("JSON root must be an object or array.", parameterName);
            }
        }
        catch (JsonException exception)
        {
            throw new ArgumentException("Value must be valid JSON.", parameterName, exception);
        }
    }
}

using Microsoft.Data.SqlClient;
using System.Data;
using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.BusinessObjects.Idempotency;

namespace RoadGuardSystem.Repositories.Idempotency;

public sealed class IdempotencyOperationService
{
    private readonly RoadGuardDbContext _context;

    public IdempotencyOperationService(RoadGuardDbContext context)
    {
        _context = context;
    }

    public Task<IdempotencyOperationResult> ExecuteAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        CancellationToken cancellationToken = default)
        => ExecuteCoreAsync(actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            operationHandler, null, null, cancellationToken);

    /// <param name="receiptAccessGuard">Current authoritative receipt access check, in a service-owned
    /// short transaction on the same scoped DbContext. Called before replay/conflict on every path;
    /// original cancellation token and guard exceptions are preserved. Must only read/lock rows.</param>
    [System.Diagnostics.CodeAnalysis.SuppressMessage("Design", "CA1068:CancellationToken parameters must come last",
        Justification = "Keep the original seven-parameter overload, and place the additive guard after its positional CancellationToken.")]
    public Task<IdempotencyOperationResult> ExecuteAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        CancellationToken cancellationToken,
        Func<CancellationToken, Task>? receiptAccessGuard)
        => ExecuteCoreAsync(actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            operationHandler, null, receiptAccessGuard, cancellationToken);

    public Task<IdempotencyOperationResult> ExecuteSerializableAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        CancellationToken cancellationToken = default)
        => ExecuteCoreAsync(actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            operationHandler, IsolationLevel.Serializable, null, cancellationToken);

    // The original seven-parameter overload remains available, including reflection callers.
    /// <param name="receiptAccessGuard">Same receipt guard contract as ExecuteAsync. Serializable
    /// isolation applies to new writes; the guard owns its authoritative read locks in the short
    /// service-owned receipt transaction.</param>
    [System.Diagnostics.CodeAnalysis.SuppressMessage("Design", "CA1068:CancellationToken parameters must come last",
        Justification = "Keep the original seven-parameter overload, and place the additive guard after its positional CancellationToken.")]
    public Task<IdempotencyOperationResult> ExecuteSerializableAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        CancellationToken cancellationToken,
        Func<CancellationToken, Task>? receiptAccessGuard)
        => ExecuteCoreAsync(actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            operationHandler, IsolationLevel.Serializable, receiptAccessGuard, cancellationToken);

    /// <summary>
    /// A supplied receipt guard is called before every replay/conflict, including retry and recovery.
    /// It must read/lock authoritative rows through this service's scoped DbContext, without opening
    /// or completing a transaction, saving writes, or using cached preflight authority. The service
    /// owns a short transaction inside the execution strategy and holds those locks through mapping
    /// and commit. It passes the original command token (also after acknowledgement loss). Guard
    /// exceptions, including cancellation and otherwise retryable exceptions, escape unchanged;
    /// they never become stored outcomes, conflict results, or create-handler invocations.
    /// Without a guard, the previous replay and transaction-isolation semantics remain unchanged.
    /// </summary>
    private async Task<IdempotencyOperationResult> ExecuteCoreAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        IsolationLevel? isolationLevel,
        Func<CancellationToken, Task>? receiptAccessGuard,
        CancellationToken cancellationToken)
    {
        try
        {
            return await ExecuteOperationAsync(actorUserId, projectId, operation, idempotencyKey,
                requestFingerprint, operationHandler, isolationLevel, receiptAccessGuard, cancellationToken);
        }
        catch (ReceiptAccessGuardException exception)
        {
            System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(exception.Cause).Throw();
            throw;
        }
    }

    private async Task<IdempotencyOperationResult> ExecuteOperationAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        IsolationLevel? isolationLevel,
        Func<CancellationToken, Task>? receiptAccessGuard,
        CancellationToken cancellationToken)
    {
        IdempotencyRecord.ValidateScope(operation, idempotencyKey, requestFingerprint);
        ArgumentNullException.ThrowIfNull(operationHandler);

        operation = operation.Trim();
        idempotencyKey = idempotencyKey.Trim();

        var executionStrategy = _context.Database.CreateExecutionStrategy();
        Task<IdempotencyOperationResult?> LookupAsync() => FindAndMapExistingAsync(
            actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            receiptAccessGuard, cancellationToken);
        var existingResult = receiptAccessGuard is null
            ? await LookupAsync()
            : await executionStrategy.ExecuteAsync(LookupAsync);
        if (existingResult is not null)
        {
            return existingResult;
        }

        try
        {
            return await executionStrategy.ExecuteAsync(
                () => ExecuteAttemptAsync(
                    actorUserId,
                    projectId,
                    operation,
                    idempotencyKey,
                    requestFingerprint,
                    operationHandler,
                    isolationLevel,
                    receiptAccessGuard,
                    cancellationToken));
        }
        catch (DbUpdateException exception) when (IsUniqueConstraintViolation(exception))
        {
            _context.ChangeTracker.Clear();
            var recovered = receiptAccessGuard is null
                ? await LookupAsync()
                : await executionStrategy.ExecuteAsync(LookupAsync);
            if (recovered is null)
            {
                throw;
            }

            return recovered;
        }
    }

    private async Task<IdempotencyOperationResult> ExecuteAttemptAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        IsolationLevel? isolationLevel,
        Func<CancellationToken, Task>? receiptAccessGuard,
        CancellationToken cancellationToken)
    {
        // A commit acknowledgement can fail after the database transaction is durable. Each retry must
        // discard stale tracked state and prefer the durable outcome over invoking the handler again.
        _context.ChangeTracker.Clear();
        var existing = await FindExistingAsync(
            actorUserId,
            projectId,
            operation,
            idempotencyKey,
            cancellationToken);
        if (existing is not null)
        {
            return await MapAuthorizedAsync(existing, requestFingerprint, receiptAccessGuard, cancellationToken);
        }

        IdempotencyRecord record;
        Exception? commitFailure = null;
        await using (var transaction = isolationLevel is { } selectedIsolation
            ? await _context.Database.BeginTransactionAsync(selectedIsolation, cancellationToken)
            : await _context.Database.BeginTransactionAsync(cancellationToken))
        {
            try
            {
                var outcome = await operationHandler(cancellationToken);
                record = IdempotencyRecord.Create(
                    actorUserId,
                    projectId,
                    operation,
                    idempotencyKey,
                    requestFingerprint,
                    outcome.OperationId,
                    outcome.OutcomeJson,
                    DateTimeOffset.UtcNow);
                _context.Set<IdempotencyRecord>().Add(record);
                await _context.SaveChangesAsync(cancellationToken);
            }
            catch
            {
                await transaction.RollbackAsync(CancellationToken.None);
                throw;
            }

            try
            {
                await transaction.CommitAsync(cancellationToken);
                return new IdempotencyOperationResult(
                    IdempotencyOperationStatus.Executed,
                    record.OperationId,
                    record.OutcomeJson,
                    record.ActorUserId,
                    record.ProjectId,
                    record.Operation);
            }
            catch (Exception exception)
            {
                commitFailure = exception;
                try
                {
                    await transaction.RollbackAsync(CancellationToken.None);
                }
                catch
                {
                    // The transaction may already be committed. Its durable state is checked below.
                }
            }
        }

        // A post-commit acknowledgement failure is indistinguishable from a failed commit until the
        // transaction is disposed. Query only after that boundary so uncommitted local writes cannot
        // be mistaken for a durable replay.
        _context.ChangeTracker.Clear();
        var durableRecord = await FindExistingAsync(
            actorUserId,
            projectId,
            operation,
            idempotencyKey,
            CancellationToken.None);
        if (durableRecord is not null)
        {
            return await MapAuthorizedAsync(durableRecord, requestFingerprint, receiptAccessGuard, cancellationToken);
        }

        System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(commitFailure!).Throw();
        throw new InvalidOperationException("Commit recovery did not produce an exception.");
    }

    private async Task<IdempotencyOperationResult?> FindAndMapExistingAsync(
        Guid? actorUserId, Guid? projectId, string operation, string idempotencyKey,
        string requestFingerprint, Func<CancellationToken, Task>? receiptAccessGuard,
        CancellationToken cancellationToken)
    {
        var record = await FindExistingAsync(actorUserId, projectId, operation, idempotencyKey, cancellationToken);
        return record is null ? null : await MapAuthorizedAsync(record, requestFingerprint, receiptAccessGuard, cancellationToken);
    }

    // Called only within an execution-strategy boundary when a guard is supplied.
    private async Task<IdempotencyOperationResult> MapAuthorizedAsync(
        IdempotencyRecord record, string requestFingerprint,
        Func<CancellationToken, Task>? receiptAccessGuard, CancellationToken cancellationToken)
    {
        if (receiptAccessGuard is null)
        {
            return MapExisting(record, requestFingerprint);
        }

        await using var transaction = await _context.Database.BeginTransactionAsync(cancellationToken);
        try
        {
            await receiptAccessGuard(cancellationToken);
        }
        catch (Exception exception)
        {
            // Do not let a guard's SQL/DbUpdate/transient error enter receipt recovery or retry.
            // Keep the cause outside InnerException so provider retry unwrapping cannot reach it.
            throw new ReceiptAccessGuardException(exception);
        }

        var result = MapExisting(record, requestFingerprint);
        await transaction.CommitAsync(cancellationToken);
        return result;
    }

    private sealed class ReceiptAccessGuardException(Exception cause) : Exception
    {
        public Exception Cause { get; } = cause;
    }

    private Task<IdempotencyRecord?> FindExistingAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        CancellationToken cancellationToken)
        => _context.Set<IdempotencyRecord>()
            .AsNoTracking()
            .SingleOrDefaultAsync(
                record =>
                    record.ActorUserId == actorUserId &&
                    record.ProjectId == projectId &&
                    record.Operation == operation &&
                    record.IdempotencyKey == idempotencyKey,
                cancellationToken);

    private static IdempotencyOperationResult MapExisting(
        IdempotencyRecord record,
        string requestFingerprint)
        => new(
            record.RequestFingerprint == requestFingerprint
                ? IdempotencyOperationStatus.Replayed
                : IdempotencyOperationStatus.Conflict,
            record.OperationId,
            record.OutcomeJson,
            record.ActorUserId,
            record.ProjectId,
            record.Operation);

    private static bool IsUniqueConstraintViolation(DbUpdateException exception)
    {
        Exception? current = exception;
        while (current is not null)
        {
            if (current is SqlException { Number: 2601 or 2627 })
            {
                return true;
            }

            current = current.InnerException;
        }

        return false;
    }
}

namespace RoadGuardSystem.DTOs.Processing;

public sealed record ProcessingJobResponseDto(
    Guid Id,
    string Status,
    Guid? ResultId,
    int AttemptNumber,
    string Version,
    string JobType,
    string? Error);

public async Task<IActionResult> GetProcessingJob(Guid jobId, CancellationToken cancellationToken)
    {
        if (!TryActor(out var actor, out var role)) return Problem(401, ApiErrorCodes.Unauthorized, "Unauthorized");
        return Map(await _service.GetAsync(actor, role, jobId, cancellationToken));
    }

    private ObjectResult Map(ProcessingV2ServiceResult result, bool created = false)
    {
        if (result.Job is not null) Response.Headers.ETag = $"\"{result.Job.Version}\"";
        return result.Status switch
        {
            ProcessingV2ServiceStatus.Success or ProcessingV2ServiceStatus.Replayed when result.Job is not null => created ? Accepted($"/api/v1/processing-jobs/{result.Job.Id}", result.Job) : Ok(result.Job),
            ProcessingV2ServiceStatus.Forbidden => Problem(403, ApiErrorCodes.AccessForbidden, "Forbidden"),
            ProcessingV2ServiceStatus.NotFound => Problem(404, ApiErrorCodes.NotFound, "Not found"),
            ProcessingV2ServiceStatus.ConcurrencyConflict => Problem(412, ApiErrorCodes.ConcurrencyConflict, "Precondition failed"),
            ProcessingV2ServiceStatus.IdempotentConflict => Problem(409, ApiErrorCodes.DuplicateRequest, "Idempotency key was reused with a different request"),
            ProcessingV2ServiceStatus.Conflict => Problem(409, ApiErrorCodes.ValidationError, "Processing transition is not allowed"),
            _ => Problem(422, ApiErrorCodes.ValidationError, "Processing request is invalid")
        };
    }

    private AcceptedResult ValidationAccepted(ProcessingJobResponseDto job)
    {
        Response.Headers.ETag = $"\"{job.Version}\"";
        return Accepted($"/api/v1/validation-runs/{job.Id}", job);
    }

    private bool TryActor(out Guid id, out UserRoleCode role)
    {
        id = Guid.Empty;
        role = UserRoleCode.Unknown;
        if (!Guid.TryParse(User.FindFirstValue(JwtRegisteredClaimNames.Sub), out id)) return false;
        try { role = UserRoleCodeExtensions.FromDbCode(User.FindFirstValue("role") ?? string.Empty); return role != UserRoleCode.Unknown; }
        catch (ArgumentOutOfRangeException) { return false; }
    }

    private Guid? CorrelationId() => Guid.TryParse(HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString(), out var value) ? value : null;
    private ObjectResult Problem(int status, string code, string title)
    {
        var details = new ProblemDetails { Status = status, Title = title, Detail = "The processing request could not be completed.", Instance = Request.Path };
        details.Extensions["code"] = code;
        details.Extensions["correlationId"] = HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString() ?? Guid.NewGuid().ToString();
        return new ObjectResult(details) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using RoadGuardSystem.DTOs.Processing;
using RoadGuardSystem.Repositories.Processing;
using RoadGuardSystem.Services.Authorization;
using RoadGuardSystem.Services.Processing;
using RoadGuardSystem.aBusinessObjects.Commons;

namespace RoadGuardSystem.Services.Implementations.Processing;

public sealed class ProcessingV2Service : IProcessingV2Service
{
    private static readonly JsonSerializerOptions WebJson = new(JsonSerializerDefaults.Web);
    private readonly IProcessingV2Repository _repository;
    private readonly IProjectScopeGuard _scopeGuard;

    public ProcessingV2Service(IProcessingV2Repository repository, IProjectScopeGuard scopeGuard)
    {
        _repository = repository;
        _scopeGuard = scopeGuard;
    }

    public async Task<ProcessingV2ServiceResult> CreateAsync(Guid actorUserId, UserRoleCode role, CreateProcessingJobRequestDto request, string idempotencyKey, Guid? correlationId, CancellationToken cancellationToken = default)
    {
        if (!IsManager(actorUserId, role) || request is null || request.DatasetId == Guid.Empty || request.ModelVersionId == Guid.Empty || request.Scope is null || !ValidScope(request.Scope) || !IsMode(request.Mode) || string.IsNullOrWhiteSpace(request.PreprocessingVersion) || string.IsNullOrWhiteSpace(request.ConfigVersion) || string.IsNullOrWhiteSpace(idempotencyKey)) return new(ProcessingV2ServiceStatus.InvalidInput);
        var datasetProjectId = await _repository.GetDatasetProjectIdAsync(request.DatasetId, cancellationToken);
        if (datasetProjectId is null) return new(ProcessingV2ServiceStatus.NotFound);
        if (!await InScope(actorUserId, role, datasetProjectId.Value, cancellationToken)) return new(ProcessingV2ServiceStatus.Forbidden);
        var scopeJson = JsonSerializer.Serialize(request.Scope);
        var result = await _repository.CreateAsync(new(actorUserId, request.DatasetId, scopeJson, request.ModelVersionId, request.PreprocessingVersion, request.ConfigVersion, request.Mode, idempotencyKey, Hash($"{request.DatasetId:N}|{scopeJson}|{request.ModelVersionId:N}|{request.PreprocessingVersion}|{request.ConfigVersion}|{request.Mode}"), correlationId), cancellationToken);
        return Map(result);
    }

    public async Task<ProcessingV2ServiceResult> GetAsync(Guid actorUserId, UserRoleCode role, Guid jobId, CancellationToken cancellationToken = default)
    {
        if (actorUserId == Guid.Empty || role is not (UserRoleCode.ProjectManager or UserRoleCode.Supervisor or UserRoleCode.DroneOperator)) return new(ProcessingV2ServiceStatus.Forbidden);
        var job = await _repository.GetAsync(jobId, cancellationToken);
        if (job is null) return new(ProcessingV2ServiceStatus.NotFound);
        if (!await InScope(actorUserId, role, job.ProjectId, cancellationToken)) return new(ProcessingV2ServiceStatus.Forbidden);
        return new(ProcessingV2ServiceStatus.Success, ToDto(job));
    }

    public async Task<ProcessingV2ServiceResult> RetryAsync(Guid actorUserId, UserRoleCode role, Guid jobId, RetryProcessingJobRequestDto request, string idempotencyKey, string expectedVersion, Guid? correlationId, CancellationToken cancellationToken = default)
    {
        if (!IsManager(actorUserId, role) || request is null || string.IsNullOrWhiteSpace(request.Reason) || string.IsNullOrWhiteSpace(idempotencyKey) || string.IsNullOrWhiteSpace(expectedVersion)) return new(ProcessingV2ServiceStatus.InvalidInput);
        var job = await _repository.GetAsync(jobId, cancellationToken);
        if (job is null) return new(ProcessingV2ServiceStatus.NotFound);
        if (!await InScope(actorUserId, role, job.ProjectId, cancellationToken)) return new(ProcessingV2ServiceStatus.Forbidden);
        return Map(await _repository.RetryAsync(new(actorUserId, jobId, request.Reason, expectedVersion.Trim().Trim('"'), idempotencyKey, Hash($"{jobId:N}|{request.Reason}|{expectedVersion}"), correlationId), cancellationToken));
    }

    public async Task<ProcessingV2ServiceResult> ReceiveResultAsync(Guid jobId, ReceiveAiResultRequestDto request, string idempotencyKey, CancellationToken cancellationToken = default)
    {
        if (jobId == Guid.Empty || request is null || request.JobAttemptId == Guid.Empty || request.ModelVersionId == Guid.Empty || request.RawResultFileId == Guid.Empty || !IsMode(request.Mode) || !Sha256(request.ManifestHash) || !Sha256(request.ChecksumSha256) || request.Detections is null || string.IsNullOrWhiteSpace(idempotencyKey)) return new(ProcessingV2ServiceStatus.InvalidInput);
        if (request.Detections.Any(item => !Guid.TryParse(item.DetectionId, out _) || item.FrameFileId == Guid.Empty || item.TimestampMs < 0 || string.IsNullOrWhiteSpace(item.TypeCode) || item.Confidence is < 0m or > 1m || item.Bbox is not { Count: 4 } || item.Bbox.Any(value => value is < 0m or > 1m) || item.Bbox[0] + item.Bbox[2] > 1m || item.Bbox[1] + item.Bbox[3] > 1m)) return new(ProcessingV2ServiceStatus.InvalidInput);
        var detectionsJson = JsonSerializer.Serialize(
            request.Detections.Select(item => new
            {
                detectionId = Guid.Parse(item.DetectionId),
                item.FrameFileId,
                item.TimestampMs,
                item.TypeCode,
                item.Confidence,
                item.Bbox
            }),
            WebJson);
        return Map(await _repository.ReceiveResultAsync(new(jobId, request.JobAttemptId, request.ManifestHash, request.ModelVersionId, request.Mode, request.RawResultFileId, request.ChecksumSha256, detectionsJson, idempotencyKey), cancellationToken));
    }

    public async Task<ProcessingV2ServiceResult> CreateValidationAsync(Guid actorUserId, UserRoleCode role, Guid projectId, CreateValidationRunRequestDto request, string idempotencyKey, Guid? correlationId, CancellationToken cancellationToken = default)
    {
        if (actorUserId == Guid.Empty || projectId == Guid.Empty || request is null || request.ModelVersionId == Guid.Empty || request.DatasetSplitId == Guid.Empty || request.Pairs is not { Count: > 0 } || request.Pairs.Any(item => item.GroundTruthId == Guid.Empty || item.DerivedMeasurementId == Guid.Empty) || string.IsNullOrWhiteSpace(request.MeasurementType) || string.IsNullOrWhiteSpace(request.Unit) || string.IsNullOrWhiteSpace(idempotencyKey)) return new(ProcessingV2ServiceStatus.InvalidInput);
        if (role != UserRoleCode.ProjectManager) return new(ProcessingV2ServiceStatus.Forbidden);
        if (!await InScope(actorUserId, role, projectId, cancellationToken)) return new(ProcessingV2ServiceStatus.Forbidden);
        var result = await _repository.CreateValidationAsync(new(actorUserId, projectId, request.ModelVersionId, request.DatasetSplitId.ToString(), request.MeasurementType, request.Unit, JsonSerializer.Serialize(request.Pairs), idempotencyKey, Hash($"{projectId:N}|{request.ModelVersionId:N}|{request.DatasetSplitId:N}|{request.MeasurementType}|{request.Unit}|{JsonSerializer.Serialize(request.Pairs)}"), correlationId), cancellationToken);
        var validation = result.Run is null ? null : ToValidationDto(result.Run);
        return result.Status switch { ProcessingJobPersistenceStatus.Success => new(ProcessingV2ServiceStatus.Success, Job: result.Run is null ? null : ToValidationJob(result.Run), Validation: validation), ProcessingJobPersistenceStatus.Replayed => new(ProcessingV2ServiceStatus.Replayed, Job: result.Run is null ? null : ToValidationJob(result.Run), Validation: validation), ProcessingJobPersistenceStatus.IdempotentConflict => new(ProcessingV2ServiceStatus.IdempotentConflict), ProcessingJobPersistenceStatus.Conflict => new(ProcessingV2ServiceStatus.Conflict), _ => new(ProcessingV2ServiceStatus.InvalidInput) };
    }

    public async Task<ValidationResultDto?> GetValidationAsync(Guid actorUserId, UserRoleCode role, Guid runId, CancellationToken cancellationToken = default)
    {
        if (actorUserId == Guid.Empty || role is not (UserRoleCode.ProjectManager or UserRoleCode.Supervisor)) return null;
        var run = await _repository.GetValidationAsync(runId, cancellationToken);
        if (run is null || !await InScope(actorUserId, role, run.ProjectId, cancellationToken)) return null;
        try { return ToValidationDto(run); } catch (JsonException) { return null; }
    }

    private async Task<bool> InScope(Guid actor, UserRoleCode role, Guid projectId, CancellationToken token) => await _scopeGuard.AuthorizeAsync(actor, role, projectId, token) is not null;
    private static bool IsManager(Guid actor, UserRoleCode role) => actor != Guid.Empty && role is UserRoleCode.ProjectManager or UserRoleCode.Supervisor;
    private static bool IsMode(string value) => value is "MOCK" or "REAL";
    private static bool Sha256(string value) => value is { Length: 64 } && value.All(character => character is >= '0' and <= '9' or >= 'a' and <= 'f');
    private static bool ValidScope(RoadGuardSystem.DTOs.Surveys.BandScopeDto scope) => scope.RouteVersionId != Guid.Empty && scope.SegmentSetId != Guid.Empty && scope.SegmentIds is { Count: > 0 } && scope.SegmentIds.All(value => value != Guid.Empty) && scope.TargetBand is "SURFACE" or "LEFT_EDGE" or "RIGHT_EDGE";
    private static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
    private static ProcessingJobResponseDto ToDto(ProcessingJobPersistenceView value) => new(value.Id, value.Status, value.ResultId, value.AttemptNumber, value.Version, "AI_ANALYSIS", value.Error);
    private static ProcessingJobResponseDto ToValidationJob(ValidationRunPersistenceView value) => new(value.Id, value.Status, null, 0, value.Version, "VALIDATION", null);
    private static ValidationResultDto ToValidationDto(ValidationRunPersistenceView value) => new(value.Id, value.UsedCount, value.ExcludedCount, value.Bias, value.Mae, value.Rmse, value.Unit, JsonSerializer.Deserialize<IReadOnlyList<string>>(value.ExclusionReasonsJson) ?? []);
    private static ProcessingV2ServiceResult Map(ProcessingJobPersistenceResult value) => value.Status switch { ProcessingJobPersistenceStatus.Success => new(ProcessingV2ServiceStatus.Success, ToDto(value.Job!)), ProcessingJobPersistenceStatus.Replayed => new(ProcessingV2ServiceStatus.Replayed, ToDto(value.Job!)), ProcessingJobPersistenceStatus.NotFound => new(ProcessingV2ServiceStatus.NotFound), ProcessingJobPersistenceStatus.ConcurrencyConflict => new(ProcessingV2ServiceStatus.ConcurrencyConflict), ProcessingJobPersistenceStatus.IdempotentConflict => new(ProcessingV2ServiceStatus.IdempotentConflict), ProcessingJobPersistenceStatus.Conflict => new(ProcessingV2ServiceStatus.Conflict), _ => new(ProcessingV2ServiceStatus.InvalidInput) };
}

