    private static readonly JsonSerializerOptions WebJson = new(JsonSerializerDefaults.Web);
    private readonly RoadGuardDbContext _context;
    private readonly IdempotencyOperationService _idempotency;

    public ProcessingV2PersistenceService(RoadGuardDbContext context, IdempotencyOperationService idempotency)
    {
        _context = context;
        _idempotency = idempotency;
    }

    public Task<Guid?> GetDatasetProjectIdAsync(Guid datasetId, CancellationToken cancellationToken = default)
        => (from data in _context.SurveyDataVersions.AsNoTracking()
            join survey in _context.Surveys.AsNoTracking() on data.SurveyId equals survey.Id
            where data.Id == datasetId
            select (Guid?)survey.ProjectId).SingleOrDefaultAsync(cancellationToken);

    public async Task<ProcessingJobPersistenceResult> CreateAsync(ProcessingJobCreateRequest request, CancellationToken cancellationToken = default)
    {
        if (request.ActorUserId == Guid.Empty || request.DatasetId == Guid.Empty || request.ModelVersionId == Guid.Empty ||
            !IsMode(request.Mode) || string.IsNullOrWhiteSpace(request.ScopeJson) || string.IsNullOrWhiteSpace(request.IdempotencyKey))
            return new(ProcessingJobPersistenceStatus.InvalidInput);
        try
        {
            var outcome = await _idempotency.ExecuteAsync(request.ActorUserId, null, "ProcessingJobCreated", request.IdempotencyKey, request.RequestFingerprint, async token =>
            {
                var dataset = await (from data in _context.SurveyDataVersions.AsNoTracking()
                                     join survey in _context.Surveys.AsNoTracking() on data.SurveyId equals survey.Id
                                     where data.Id == request.DatasetId && data.Status == SurveyDataVersionStatus.ServerConfirmed && data.IntegrityStatus == SurveyDataIntegrityStatus.Passed
                                     select new { data, survey.ProjectId }).SingleOrDefaultAsync(token) ?? throw new ScopeNotFoundException();
                var modelReleased = await _context.AIModelVersions.AsNoTracking().AnyAsync(model => model.Id == request.ModelVersionId && model.Status == AIModelVersionStatus.Released, token);
                if (!modelReleased) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Conflict, null)));
                var rangeMetadata = JsonSerializer.Serialize(new { scope = JsonSerializer.Deserialize<JsonElement>(request.ScopeJson) });
                var block = await _context.ProcessingBlocks.SingleOrDefaultAsync(
                    value => value.SurveyDataVersionId == request.DatasetId && value.RangeMetadata == rangeMetadata,
                    token);
                if (block is null)
                {
                    var nextBlockNo = (await _context.ProcessingBlocks
                        .Where(value => value.SurveyDataVersionId == request.DatasetId)
                        .MaxAsync(value => (int?)value.BlockNo, token) ?? 0) + 1;
                    block = ProcessingBlock.Create(Guid.NewGuid(), request.DatasetId, nextBlockNo, rangeMetadata);
                    _context.ProcessingBlocks.Add(block);
                }
                var manifest = JsonSerializer.Serialize(new { datasetId = request.DatasetId, sourceManifest = dataset.data.SourceManifest, scope = JsonSerializer.Deserialize<JsonElement>(request.ScopeJson), request.ModelVersionId, request.PreprocessingVersion, request.ConfigVersion, request.Mode });
                var job = ProcessingJob.CreateQueued(Guid.NewGuid(), block.Id, request.ModelVersionId, dataset.ProjectId, Sha256(manifest), manifest, request.Mode.Trim());
                var attempt = ProcessingAttempt.Create(Guid.NewGuid(), job.Id, 1, DateTimeOffset.UtcNow, null, null, null);
                _context.ProcessingJobs.Add(job);
                _context.ProcessingAttempts.Add(attempt);
                _context.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), "processing_job.dispatch", DateTimeOffset.UtcNow, job.Id, JsonSerializer.Serialize(new { jobId = job.Id, attemptId = attempt.Id, job.ManifestHash })));
                _context.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), request.ActorUserId, DateTimeOffset.UtcNow, "processing_job_created", "ProcessingJob", job.Id, null, "{}", "Processing manifest created", "p2-030", request.CorrelationId, ["datasetId", "modelVersionId"]));
                await _context.SaveChangesAsync(token);
                var view = new ProcessingJobPersistenceView(job.Id, job.ProjectId, ToApiStatus(job.Status), null, 1, Version(job), null);
                return (job.Id, JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Success, view)));
            }, cancellationToken);
            return ReadJobOutcome(outcome);
        }
        catch (ScopeNotFoundException) { return new(ProcessingJobPersistenceStatus.NotFound); }
        catch (ArgumentException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (JsonException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (DbUpdateException exception) when (IsUnique(exception)) { return new(ProcessingJobPersistenceStatus.Conflict); }
    }

    public async Task<ProcessingJobPersistenceView?> GetAsync(Guid jobId, CancellationToken cancellationToken = default)
    {
        var job = await _context.ProcessingJobs.AsNoTracking().SingleOrDefaultAsync(value => value.Id == jobId, cancellationToken);
        if (job is null) return null;
        var attempt = await _context.ProcessingAttempts.AsNoTracking().Where(value => value.ProcessingJobId == jobId).MaxAsync(value => (int?)value.AttemptNo, cancellationToken) ?? 0;
        var result = job.Status == ProcessingJobStatus.Completed
            ? await _context.AIDetections.AsNoTracking().Where(value => value.ProcessingJobId == jobId).Select(value => (Guid?)value.Id).FirstOrDefaultAsync(cancellationToken)
            : null;
        return new(job.Id, job.ProjectId, ToApiStatus(job.Status), result, attempt, Version(job), job.ErrorCode);
    }

    public async Task<ProcessingJobPersistenceResult> RetryAsync(ProcessingJobRetryRequest request, CancellationToken cancellationToken = default)
    {
        var job = await _context.ProcessingJobs.AsNoTracking().SingleOrDefaultAsync(value => value.Id == request.JobId, cancellationToken);
        if (job is null) return new(ProcessingJobPersistenceStatus.NotFound);
        try
        {
            var outcome = await _idempotency.ExecuteAsync(request.ActorUserId, job.ProjectId, "ProcessingJobRetried", request.IdempotencyKey, request.RequestFingerprint, async token =>
            {
                var tracked = await _context.ProcessingJobs.SingleOrDefaultAsync(value => value.Id == request.JobId, token) ?? throw new ScopeNotFoundException();
                if (!TryDecodeVersion(request.ExpectedVersion, out var expected) || !tracked.RowVersion.SequenceEqual(expected)) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.ConcurrencyConflict, null)));
                _context.Entry(tracked).Property(value => value.RowVersion).OriginalValue = expected;
                try { tracked.Retry(); } catch (InvalidOperationException) { return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Conflict, null))); }
                var nextAttempt = (await _context.ProcessingAttempts.AsNoTracking().Where(value => value.ProcessingJobId == tracked.Id).MaxAsync(value => (int?)value.AttemptNo, token) ?? 0) + 1;
                _context.ProcessingAttempts.Add(ProcessingAttempt.Create(Guid.NewGuid(), tracked.Id, nextAttempt, DateTimeOffset.UtcNow, null, null, null));
                _context.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), "processing_job.dispatch", DateTimeOffset.UtcNow, tracked.Id, JsonSerializer.Serialize(new { jobId = tracked.Id, attemptNumber = nextAttempt, tracked.ManifestHash })));
                _context.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), request.ActorUserId, DateTimeOffset.UtcNow, "processing_job_retried", "ProcessingJob", tracked.Id, null, JsonSerializer.Serialize(new { request.Reason }), "Processing job retried", "p2-032", request.CorrelationId, ["reason"]));
                await _context.SaveChangesAsync(token);
                return (tracked.Id, JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Success, new ProcessingJobPersistenceView(tracked.Id, tracked.ProjectId, ToApiStatus(tracked.Status), null, nextAttempt, Version(tracked), null))));
            }, cancellationToken);
            return ReadJobOutcome(outcome);
        }
        catch (ScopeNotFoundException) { return new(ProcessingJobPersistenceStatus.NotFound); }
        catch (DbUpdateConcurrencyException) { return new(ProcessingJobPersistenceStatus.ConcurrencyConflict); }
    }

    public async Task<ProcessingJobPersistenceResult> ReceiveResultAsync(ProcessingAiResultRequest request, CancellationToken cancellationToken = default)
    {
        var existingJob = await _context.ProcessingJobs.AsNoTracking().SingleOrDefaultAsync(value => value.Id == request.JobId, cancellationToken);
        if (existingJob is null) return new(ProcessingJobPersistenceStatus.NotFound);
        try
        {
            var outcome = await _idempotency.ExecuteAsync(null, existingJob.ProjectId, "ProcessingAiResultReceived", request.IdempotencyKey, Sha256(request.DetectionsJson + request.ChecksumSha256), async token =>
            {
                var job = await _context.ProcessingJobs.SingleOrDefaultAsync(value => value.Id == request.JobId, token) ?? throw new ScopeNotFoundException();
                var attempt = await _context.ProcessingAttempts.AsNoTracking().SingleOrDefaultAsync(value => value.Id == request.AttemptId && value.ProcessingJobId == job.Id, token);
                if (attempt is null || job.ManifestHash != request.ManifestHash || job.ModelVersionId != request.ModelVersionId || job.Mode != request.Mode) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Conflict, null)));
                var rawFile = await (
                    from file in _context.Files.AsNoTracking()
                    join upload in _context.UploadSessions.AsNoTracking() on file.Id equals upload.FileId
                    join scope in _context.FileScopes.AsNoTracking() on file.Id equals scope.FileId
                    where file.Id == request.RawResultFileId && file.Checksum == request.ChecksumSha256 &&
                          upload.Status == UploadSessionStatus.Verified && scope.ProjectId == job.ProjectId
                    select file).SingleOrDefaultAsync(token);
                if (rawFile is null) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Conflict, null)));
                using var document = JsonDocument.Parse(request.DetectionsJson);
                if (document.RootElement.ValueKind != JsonValueKind.Array) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.InvalidInput, null)));
                foreach (var detection in document.RootElement.EnumerateArray())
                {
                    var id = detection.GetProperty("detectionId").GetGuid();
                    var type = detection.GetProperty("typeCode").GetString();
                    var confidence = detection.GetProperty("confidence").GetDecimal();
                    _context.AIDetections.Add(AIDetection.Create(id, job.Id, job.ModelVersionId, null, null, type, confidence, null, null, detection.GetRawText()));
                }
                job.Complete(DateTimeOffset.UtcNow);
                await _context.SaveChangesAsync(token);
                var resultId = await _context.AIDetections.AsNoTracking().Where(value => value.ProcessingJobId == job.Id).Select(value => (Guid?)value.Id).FirstOrDefaultAsync(token);
                return (job.Id, JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Success, new ProcessingJobPersistenceView(job.Id, job.ProjectId, ToApiStatus(job.Status), resultId, attempt.AttemptNo, Version(job), null))));
            }, cancellationToken);
            return ReadJobOutcome(outcome);
        }
        catch (JsonException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (KeyNotFoundException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (InvalidOperationException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (ArgumentException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (DbUpdateException exception) when (IsUnique(exception)) { return new(ProcessingJobPersistenceStatus.Conflict); }
    }

    public async Task<ValidationRunPersistenceResult> CreateValidationAsync(ValidationRunCreateRequest request, CancellationToken cancellationToken = default)
    {
        if (request.ActorUserId == Guid.Empty || request.ProjectId == Guid.Empty || request.ModelVersionId == Guid.Empty || string.IsNullOrWhiteSpace(request.PairsJson)) return new(ProcessingJobPersistenceStatus.InvalidInput);
        try
        {
            var outcome = await _idempotency.ExecuteAsync(request.ActorUserId, request.ProjectId, "ValidationRunCreated", request.IdempotencyKey, request.RequestFingerprint, async token =>
            {
                var released = await _context.AIModelVersions.AsNoTracking().AnyAsync(value => value.Id == request.ModelVersionId && value.Status == AIModelVersionStatus.Released, token);
                if (!released) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredValidationOutcome(ProcessingJobPersistenceStatus.Conflict, null)));
                var measurementType = ParseMeasurementType(request.MeasurementType);
                var requestedPairs = JsonSerializer.Deserialize<IReadOnlyList<ValidationPairReference>>(request.PairsJson, WebJson);
                if (measurementType == MeasurementType.Unknown || requestedPairs is not { Count: > 0 } || requestedPairs.Any(value => value.GroundTruthId == Guid.Empty || value.DerivedMeasurementId == Guid.Empty))
                    return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredValidationOutcome(ProcessingJobPersistenceStatus.InvalidInput, null)));
                var facts = await LoadValidationPairFactsAsync(request.ProjectId, requestedPairs, token);
                if (facts.Count != requestedPairs.Count || !PairsAreEligible(facts, requestedPairs, measurementType, request.Unit))
                    return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredValidationOutcome(ProcessingJobPersistenceStatus.InvalidInput, null)));
                var run = ValidationRun.CreateQueued(Guid.NewGuid(), request.ProjectId, request.ModelVersionId, request.DatasetSplitId, request.MeasurementType, request.Unit, request.PairsJson);
                _context.ValidationRuns.Add(run);
                foreach (var pair in requestedPairs)
                {
                    var fact = facts.Single(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId);
                    var signedError = ConvertUnit(fact.DerivedValue, fact.Unit, request.Unit) - ConvertUnit(fact.GroundTruthValue, fact.Unit, request.Unit);
                    _context.MeasurementValidationSamples.Add(MeasurementValidationSample.Create(Guid.NewGuid(), run.Id, fact.GroundTruthId, fact.DerivedMeasurementId, signedError, ValidationSampleInclusionStatus.Included, null));
                }
                _context.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), "validation_run.dispatch", DateTimeOffset.UtcNow, run.Id, JsonSerializer.Serialize(new { validationRunId = run.Id, request.ModelVersionId, request.DatasetSplitId })));
                _context.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), request.ActorUserId, DateTimeOffset.UtcNow, "validation_run_created", "ValidationRun", run.Id, null, "{}", "Validation run queued", "p2-034", request.CorrelationId, ["modelVersionId", "datasetSplitId"]));
                await _context.SaveChangesAsync(token);
                return (run.Id, JsonSerializer.Serialize(new StoredValidationOutcome(ProcessingJobPersistenceStatus.Success, ToValidationView(run))));
            }, cancellationToken);
            if (outcome.Status == IdempotencyOperationStatus.Conflict) return new(ProcessingJobPersistenceStatus.IdempotentConflict);
            var stored = JsonSerializer.Deserialize<StoredValidationOutcome>(outcome.OutcomeJson) ?? throw new InvalidOperationException();
            // A replayed receipt preserves the original business outcome. Only a stored
            // success is exposed as Replayed; failed validation must remain a failure so
            // the HTTP layer does not turn it into a null-success fallback.
            return new(outcome.Status == IdempotencyOperationStatus.Replayed && stored.Status == ProcessingJobPersistenceStatus.Success
                ? ProcessingJobPersistenceStatus.Replayed
                : stored.Status, stored.Run);
        }
        catch (ArgumentException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (JsonException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
    }

    public async Task<ValidationRunPersistenceView?> GetValidationAsync(Guid runId, CancellationToken cancellationToken = default)
    {
        var run = await _context.ValidationRuns.AsNoTracking().SingleOrDefaultAsync(value => value.Id == runId, cancellationToken);
        return run is null ? null : ToValidationView(run);
    }

    public async Task<bool> CompleteNextValidationRunAsync(CancellationToken cancellationToken = default)
    {
        var message = await _context.OutboxMessages
            .Where(value => value.MessageType == "validation_run.dispatch" && value.DeliveryStatus == OutboxDeliveryStatus.Pending && value.NextAttemptAtUtc <= DateTimeOffset.UtcNow)
            .OrderBy(value => value.OccurredAtUtc)
            .FirstOrDefaultAsync(cancellationToken);
        if (message?.CorrelationId is not Guid runId) return false;

        message.AcquireLease("validation-run-worker", DateTimeOffset.UtcNow, TimeSpan.FromMinutes(1), 3);
        var run = await _context.ValidationRuns.SingleOrDefaultAsync(value => value.Id == runId && value.Status == ValidationRunStatus.Queued, cancellationToken);
        if (run is null)
        {
            message.CompleteLease("validation-run-worker");
            await _context.SaveChangesAsync(cancellationToken);
            return true;
        }

        var samples = await _context.MeasurementValidationSamples.AsNoTracking()
            .Where(value => value.ValidationRunId == run.Id && value.InclusionStatus == ValidationSampleInclusionStatus.Included)
            .ToListAsync(cancellationToken);
        if (samples.Count == 0)
        {
            message.ScheduleRetry("validation-run-worker", DateTimeOffset.UtcNow.AddMinutes(5), "validation_samples_missing", "Validation run has no included sample provenance.", 3);
            await _context.SaveChangesAsync(cancellationToken);
            return true;
        }

        var bias = decimal.Round(samples.Average(value => value.SignedError), 6, MidpointRounding.AwayFromZero);
        var mae = decimal.Round(samples.Average(value => value.AbsoluteError), 6, MidpointRounding.AwayFromZero);
        var rmse = decimal.Round((decimal)Math.Sqrt(samples.Average(value => (double)(value.SignedError * value.SignedError))), 6, MidpointRounding.AwayFromZero);
        try
        {
            run.Complete(samples.Count, 0, bias, mae, rmse, "[]");
            message.CompleteLease("validation-run-worker");
            await _context.SaveChangesAsync(cancellationToken);
            return true;
        }
        catch (DbUpdateConcurrencyException)
        {
            return false;
        }
    }

    private static ProcessingJobPersistenceResult ReadJobOutcome(IdempotencyOperationResult outcome)
    {
        if (outcome.Status == IdempotencyOperationStatus.Conflict) return new(ProcessingJobPersistenceStatus.IdempotentConflict);
        var stored = JsonSerializer.Deserialize<StoredJobOutcome>(outcome.OutcomeJson) ?? throw new InvalidOperationException("Processing outcome is invalid.");
        return new(outcome.Status == IdempotencyOperationStatus.Replayed && stored.Status == ProcessingJobPersistenceStatus.Success ? ProcessingJobPersistenceStatus.Replayed : stored.Status, stored.Job);
    }

    private async Task<List<ValidationPairFact>> LoadValidationPairFactsAsync(Guid projectId, IReadOnlyList<ValidationPairReference> pairs, CancellationToken cancellationToken)
    {
        var groundTruthIds = pairs.Select(value => value.GroundTruthId).Distinct().ToArray();
        var derivedIds = pairs.Select(value => value.DerivedMeasurementId).Distinct().ToArray();
        return await (from groundTruth in _context.GroundTruthMeasurements.AsNoTracking()
                      join session in _context.FieldInspectionSessions.AsNoTracking() on groundTruth.FieldInspectionSessionId equals session.Id
                      join derived in _context.DerivedMeasurements.AsNoTracking() on groundTruth.SampleId equals derived.SampleId
                      join data in _context.SurveyDataVersions.AsNoTracking() on derived.SurveyDataVersionId equals data.Id
                      join survey in _context.Surveys.AsNoTracking() on data.SurveyId equals survey.Id
                      where groundTruthIds.Contains(groundTruth.Id) && derivedIds.Contains(derived.Id) &&
                            session.ProjectId == projectId && survey.ProjectId == projectId &&
                            groundTruth.Value.HasValue && groundTruth.ValueState == "KNOWN"
                      select new ValidationPairFact(groundTruth.Id, derived.Id, groundTruth.SampleId, groundTruth.RoadSectionVersionId, derived.RoadSectionVersionId, groundTruth.MeasurementType, derived.MeasurementType, groundTruth.Value!.Value, derived.Value, groundTruth.Unit, derived.Unit, derived.Status)).ToListAsync(cancellationToken);
    }

    private static bool PairsAreEligible(IReadOnlyList<ValidationPairFact> facts, IReadOnlyList<ValidationPairReference> pairs, MeasurementType measurementType, string unit)
    {
        if (!IsSupportedUnit(unit)) return false;
        return pairs.Distinct().Count() == pairs.Count && pairs.All(pair => facts.Count(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId) == 1 &&
            facts.Single(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId) is { MeasurementType: var groundTruthType, DerivedMeasurementType: var derivedType, GroundTruthRoadSectionVersionId: var groundTruthRoadVersion, DerivedRoadSectionVersionId: var derivedRoadVersion, Status: DerivedMeasurementStatus.Published } &&
            groundTruthType == measurementType && derivedType == measurementType && groundTruthRoadVersion == derivedRoadVersion && IsSupportedUnit(facts.Single(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId).Unit) && IsSupportedUnit(facts.Single(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId).DerivedUnit));
    }

    private static MeasurementType ParseMeasurementType(string value) => value.Trim() switch { "DEPRESSION_DEPTH" => MeasurementType.DepressionDepth, "SLAB_FAULTING_HEIGHT" => MeasurementType.SlabFaultingHeight, "SHOULDER_EROSION_EXTENT" => MeasurementType.ShoulderErosionExtent, _ => MeasurementType.Unknown };
    private static bool IsSupportedUnit(string value) => value.Trim().ToLowerInvariant() is "mm" or "cm" or "m";
    private static decimal ConvertUnit(decimal value, string sourceUnit, string destinationUnit)
    {
        var millimetres = sourceUnit.Trim().ToLowerInvariant() switch { "mm" => value, "cm" => value * 10m, "m" => value * 1000m, _ => throw new ArgumentException("Unsupported source unit.", nameof(sourceUnit)) };
        return destinationUnit.Trim().ToLowerInvariant() switch { "mm" => millimetres, "cm" => millimetres / 10m, "m" => millimetres / 1000m, _ => throw new ArgumentException("Unsupported destination unit.", nameof(destinationUnit)) };
    }
    private static ValidationRunPersistenceView ToValidationView(ValidationRun run) => new(run.Id, run.ProjectId, run.Status.ToString().ToUpperInvariant(), Convert.ToBase64String(run.RowVersion), run.UsedCount, run.ExcludedCount, run.Bias, run.Mae, run.Rmse, run.Unit, run.ExclusionReasonsJson);
    private static bool IsMode(string value) => value is "MOCK" or "REAL";
    private static string ToApiStatus(ProcessingJobStatus status) => status switch { ProcessingJobStatus.Completed => "SUCCEEDED", ProcessingJobStatus.RetryableFailure or ProcessingJobStatus.DataFailure => "FAILED", _ => status.ToString().ToUpperInvariant() };
    private static string Version(ProcessingJob job) => Convert.ToBase64String(job.RowVersion);
    private static string Sha256(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
    private static bool TryDecodeVersion(string value, out byte[] result) { try { result = Convert.FromBase64String(value.Trim().Trim('"')); return result.Length > 0; } catch (FormatException) { result = []; return false; } }
    private static bool IsUnique(DbUpdateException exception) { for (Exception? current = exception; current is not null; current = current.InnerException) if (current is SqlException { Number: 2601 or 2627 }) return true; return false; }

    private sealed record StoredJobOutcome(ProcessingJobPersistenceStatus Status, ProcessingJobPersistenceView? Job);
    private sealed record StoredValidationOutcome(ProcessingJobPersistenceStatus Status, ValidationRunPersistenceView? Run);
    private sealed record ValidationPairReference(Guid GroundTruthId, Guid DerivedMeasurementId);
    private sealed record ValidationPairFact(Guid GroundTruthId, Guid DerivedMeasurementId, string SampleId, Guid GroundTruthRoadSectionVersionId, Guid DerivedRoadSectionVersionId, MeasurementType MeasurementType, MeasurementType DerivedMeasurementType, decimal GroundTruthValue, decimal DerivedValue, string Unit, string DerivedUnit, DerivedMeasurementStatus Status);
    private sealed class ScopeNotFoundException : Exception;
}

namespace RoadGuardSystem.DTOs.Processing;

public sealed record ProcessingJobResponseDto(
    Guid Id,
    string Status,
    Guid? ResultId,
    int AttemptNumber,
    string Version,
    string JobType,
    string? Error);

public async Task<IActionResult> RetryProcessingJob(Guid jobId, [FromHeader(Name = "Idempotency-Key")] string? idempotencyKey, [FromHeader(Name = "If-Match")] string? ifMatch, RetryProcessingJobRequestDto request, CancellationToken cancellationToken)
    {
        if (!TryActor(out var actor, out var role)) return Problem(401, ApiErrorCodes.Unauthorized, "Unauthorized");
        if (string.IsNullOrWhiteSpace(idempotencyKey) || string.IsNullOrWhiteSpace(ifMatch)) return Problem(428, ApiErrorCodes.ValidationError, "Required precondition headers are missing");
        return Map(await _service.RetryAsync(actor, role, jobId, request, idempotencyKey, ifMatch, CorrelationId(), cancellationToken));
    }

    private ObjectResult Map(ProcessingV2ServiceResult result, bool created = false)
    {
        if (result.Job is not null) Response.Headers.ETag = $"\"{result.Job.Version}\"";
        return result.Status switch
        {
            ProcessingV2ServiceStatus.Success or ProcessingV2ServiceStatus.Replayed when result.Job is not null => created ? Accepted($"/api/v1/processing-jobs/{result.Job.Id}", result.Job) : Ok(result.Job),
            ProcessingV2ServiceStatus.Forbidden => Problem(403, ApiErrorCodes.AccessForbidden, "Forbidden"),
            ProcessingV2ServiceStatus.NotFound => Problem(404, ApiErrorCodes.NotFound, "Not found"),
            ProcessingV2ServiceStatus.ConcurrencyConflict => Problem(412, ApiErrorCodes.ConcurrencyConflict, "Precondition failed"),
            ProcessingV2ServiceStatus.IdempotentConflict => Problem(409, ApiErrorCodes.DuplicateRequest, "Idempotency key was reused with a different request"),
            ProcessingV2ServiceStatus.Conflict => Problem(409, ApiErrorCodes.ValidationError, "Processing transition is not allowed"),
            _ => Problem(422, ApiErrorCodes.ValidationError, "Processing request is invalid")
        };
    }

    private AcceptedResult ValidationAccepted(ProcessingJobResponseDto job)
    {
        Response.Headers.ETag = $"\"{job.Version}\"";
        return Accepted($"/api/v1/validation-runs/{job.Id}", job);
    }

    private bool TryActor(out Guid id, out UserRoleCode role)
    {
        id = Guid.Empty;
        role = UserRoleCode.Unknown;
        if (!Guid.TryParse(User.FindFirstValue(JwtRegisteredClaimNames.Sub), out id)) return false;
        try { role = UserRoleCodeExtensions.FromDbCode(User.FindFirstValue("role") ?? string.Empty); return role != UserRoleCode.Unknown; }
        catch (ArgumentOutOfRangeException) { return false; }
    }

    private Guid? CorrelationId() => Guid.TryParse(HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString(), out var value) ? value : null;
    private ObjectResult Problem(int status, string code, string title)
    {
        var details = new ProblemDetails { Status = status, Title = title, Detail = "The processing request could not be completed.", Instance = Request.Path };
        details.Extensions["code"] = code;
        details.Extensions["correlationId"] = HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString() ?? Guid.NewGuid().ToString();
        return new ObjectResult(details) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using RoadGuardSystem.DTOs.Processing;
using RoadGuardSystem.Repositories.Processing;
using RoadGuardSystem.Services.Authorization;
using RoadGuardSystem.Services.Processing;
using RoadGuardSystem.aBusinessObjects.Commons;

namespace RoadGuardSystem.Services.Implementations.Processing;

public sealed class ProcessingV2Service : IProcessingV2Service
{
    private static readonly JsonSerializerOptions WebJson = new(JsonSerializerDefaults.Web);
    private readonly IProcessingV2Repository _repository;
    private readonly IProjectScopeGuard _scopeGuard;

    public ProcessingV2Service(IProcessingV2Repository repository, IProjectScopeGuard scopeGuard)
    {
        _repository = repository;
        _scopeGuard = scopeGuard;
    }

    public async Task<ProcessingV2ServiceResult> CreateAsync(Guid actorUserId, UserRoleCode role, CreateProcessingJobRequestDto request, string idempotencyKey, Guid? correlationId, CancellationToken cancellationToken = default)
    {
        if (!IsManager(actorUserId, role) || request is null || request.DatasetId == Guid.Empty || request.ModelVersionId == Guid.Empty || request.Scope is null || !ValidScope(request.Scope) || !IsMode(request.Mode) || string.IsNullOrWhiteSpace(request.PreprocessingVersion) || string.IsNullOrWhiteSpace(request.ConfigVersion) || string.IsNullOrWhiteSpace(idempotencyKey)) return new(ProcessingV2ServiceStatus.InvalidInput);
        var datasetProjectId = await _repository.GetDatasetProjectIdAsync(request.DatasetId, cancellationToken);
        if (datasetProjectId is null) return new(ProcessingV2ServiceStatus.NotFound);
        if (!await InScope(actorUserId, role, datasetProjectId.Value, cancellationToken)) return new(ProcessingV2ServiceStatus.Forbidden);
        var scopeJson = JsonSerializer.Serialize(request.Scope);
        var result = await _repository.CreateAsync(new(actorUserId, request.DatasetId, scopeJson, request.ModelVersionId, request.PreprocessingVersion, request.ConfigVersion, request.Mode, idempotencyKey, Hash($"{request.DatasetId:N}|{scopeJson}|{request.ModelVersionId:N}|{request.PreprocessingVersion}|{request.ConfigVersion}|{request.Mode}"), correlationId), cancellationToken);
        return Map(result);
    }

    public async Task<ProcessingV2ServiceResult> GetAsync(Guid actorUserId, UserRoleCode role, Guid jobId, CancellationToken cancellationToken = default)
    {
        if (actorUserId == Guid.Empty || role is not (UserRoleCode.ProjectManager or UserRoleCode.Supervisor or UserRoleCode.DroneOperator)) return new(ProcessingV2ServiceStatus.Forbidden);
        var job = await _repository.GetAsync(jobId, cancellationToken);
        if (job is null) return new(ProcessingV2ServiceStatus.NotFound);
        if (!await InScope(actorUserId, role, job.ProjectId, cancellationToken)) return new(ProcessingV2ServiceStatus.Forbidden);
        return new(ProcessingV2ServiceStatus.Success, ToDto(job));
    }

    public async Task<ProcessingV2ServiceResult> RetryAsync(Guid actorUserId, UserRoleCode role, Guid jobId, RetryProcessingJobRequestDto request, string idempotencyKey, string expectedVersion, Guid? correlationId, CancellationToken cancellationToken = default)
    {
        if (!IsManager(actorUserId, role) || request is null || string.IsNullOrWhiteSpace(request.Reason) || string.IsNullOrWhiteSpace(idempotencyKey) || string.IsNullOrWhiteSpace(expectedVersion)) return new(ProcessingV2ServiceStatus.InvalidInput);
        var job = await _repository.GetAsync(jobId, cancellationToken);
        if (job is null) return new(ProcessingV2ServiceStatus.NotFound);
        if (!await InScope(actorUserId, role, job.ProjectId, cancellationToken)) return new(ProcessingV2ServiceStatus.Forbidden);
        return Map(await _repository.RetryAsync(new(actorUserId, jobId, request.Reason, expectedVersion.Trim().Trim('"'), idempotencyKey, Hash($"{jobId:N}|{request.Reason}|{expectedVersion}"), correlationId), cancellationToken));
    }

    public async Task<ProcessingV2ServiceResult> ReceiveResultAsync(Guid jobId, ReceiveAiResultRequestDto request, string idempotencyKey, CancellationToken cancellationToken = default)
    {
        if (jobId == Guid.Empty || request is null || request.JobAttemptId == Guid.Empty || request.ModelVersionId == Guid.Empty || request.RawResultFileId == Guid.Empty || !IsMode(request.Mode) || !Sha256(request.ManifestHash) || !Sha256(request.ChecksumSha256) || request.Detections is null || string.IsNullOrWhiteSpace(idempotencyKey)) return new(ProcessingV2ServiceStatus.InvalidInput);
        if (request.Detections.Any(item => !Guid.TryParse(item.DetectionId, out _) || item.FrameFileId == Guid.Empty || item.TimestampMs < 0 || string.IsNullOrWhiteSpace(item.TypeCode) || item.Confidence is < 0m or > 1m || item.Bbox is not { Count: 4 } || item.Bbox.Any(value => value is < 0m or > 1m) || item.Bbox[0] + item.Bbox[2] > 1m || item.Bbox[1] + item.Bbox[3] > 1m)) return new(ProcessingV2ServiceStatus.InvalidInput);
        var detectionsJson = JsonSerializer.Serialize(
            request.Detections.Select(item => new
            {
                detectionId = Guid.Parse(item.DetectionId),
                item.FrameFileId,
                item.TimestampMs,
                item.TypeCode,
                item.Confidence,
                item.Bbox
            }),
            WebJson);
        return Map(await _repository.ReceiveResultAsync(new(jobId, request.JobAttemptId, request.ManifestHash, request.ModelVersionId, request.Mode, request.RawResultFileId, request.ChecksumSha256, detectionsJson, idempotencyKey), cancellationToken));
    }

    public async Task<ProcessingV2ServiceResult> CreateValidationAsync(Guid actorUserId, UserRoleCode role, Guid projectId, CreateValidationRunRequestDto request, string idempotencyKey, Guid? correlationId, CancellationToken cancellationToken = default)
    {
        if (actorUserId == Guid.Empty || projectId == Guid.Empty || request is null || request.ModelVersionId == Guid.Empty || request.DatasetSplitId == Guid.Empty || request.Pairs is not { Count: > 0 } || request.Pairs.Any(item => item.GroundTruthId == Guid.Empty || item.DerivedMeasurementId == Guid.Empty) || string.IsNullOrWhiteSpace(request.MeasurementType) || string.IsNullOrWhiteSpace(request.Unit) || string.IsNullOrWhiteSpace(idempotencyKey)) return new(ProcessingV2ServiceStatus.InvalidInput);
        if (role != UserRoleCode.ProjectManager) return new(ProcessingV2ServiceStatus.Forbidden);
        if (!await InScope(actorUserId, role, projectId, cancellationToken)) return new(ProcessingV2ServiceStatus.Forbidden);
        var result = await _repository.CreateValidationAsync(new(actorUserId, projectId, request.ModelVersionId, request.DatasetSplitId.ToString(), request.MeasurementType, request.Unit, JsonSerializer.Serialize(request.Pairs), idempotencyKey, Hash($"{projectId:N}|{request.ModelVersionId:N}|{request.DatasetSplitId:N}|{request.MeasurementType}|{request.Unit}|{JsonSerializer.Serialize(request.Pairs)}"), correlationId), cancellationToken);
        var validation = result.Run is null ? null : ToValidationDto(result.Run);
        return result.Status switch { ProcessingJobPersistenceStatus.Success => new(ProcessingV2ServiceStatus.Success, Job: result.Run is null ? null : ToValidationJob(result.Run), Validation: validation), ProcessingJobPersistenceStatus.Replayed => new(ProcessingV2ServiceStatus.Replayed, Job: result.Run is null ? null : ToValidationJob(result.Run), Validation: validation), ProcessingJobPersistenceStatus.IdempotentConflict => new(ProcessingV2ServiceStatus.IdempotentConflict), ProcessingJobPersistenceStatus.Conflict => new(ProcessingV2ServiceStatus.Conflict), _ => new(ProcessingV2ServiceStatus.InvalidInput) };
    }

    public async Task<ValidationResultDto?> GetValidationAsync(Guid actorUserId, UserRoleCode role, Guid runId, CancellationToken cancellationToken = default)
    {
        if (actorUserId == Guid.Empty || role is not (UserRoleCode.ProjectManager or UserRoleCode.Supervisor)) return null;
        var run = await _repository.GetValidationAsync(runId, cancellationToken);
        if (run is null || !await InScope(actorUserId, role, run.ProjectId, cancellationToken)) return null;
        try { return ToValidationDto(run); } catch (JsonException) { return null; }
    }

    private async Task<bool> InScope(Guid actor, UserRoleCode role, Guid projectId, CancellationToken token) => await _scopeGuard.AuthorizeAsync(actor, role, projectId, token) is not null;
    private static bool IsManager(Guid actor, UserRoleCode role) => actor != Guid.Empty && role is UserRoleCode.ProjectManager or UserRoleCode.Supervisor;
    private static bool IsMode(string value) => value is "MOCK" or "REAL";
    private static bool Sha256(string value) => value is { Length: 64 } && value.All(character => character is >= '0' and <= '9' or >= 'a' and <= 'f');
    private static bool ValidScope(RoadGuardSystem.DTOs.Surveys.BandScopeDto scope) => scope.RouteVersionId != Guid.Empty && scope.SegmentSetId != Guid.Empty && scope.SegmentIds is { Count: > 0 } && scope.SegmentIds.All(value => value != Guid.Empty) && scope.TargetBand is "SURFACE" or "LEFT_EDGE" or "RIGHT_EDGE";
    private static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
    private static ProcessingJobResponseDto ToDto(ProcessingJobPersistenceView value) => new(value.Id, value.Status, value.ResultId, value.AttemptNumber, value.Version, "AI_ANALYSIS", value.Error);
    private static ProcessingJobResponseDto ToValidationJob(ValidationRunPersistenceView value) => new(value.Id, value.Status, null, 0, value.Version, "VALIDATION", null);
    private static ValidationResultDto ToValidationDto(ValidationRunPersistenceView value) => new(value.Id, value.UsedCount, value.ExcludedCount, value.Bias, value.Mae, value.Rmse, value.Unit, JsonSerializer.Deserialize<IReadOnlyList<string>>(value.ExclusionReasonsJson) ?? []);
    private static ProcessingV2ServiceResult Map(ProcessingJobPersistenceResult value) => value.Status switch { ProcessingJobPersistenceStatus.Success => new(ProcessingV2ServiceStatus.Success, ToDto(value.Job!)), ProcessingJobPersistenceStatus.Replayed => new(ProcessingV2ServiceStatus.Replayed, ToDto(value.Job!)), ProcessingJobPersistenceStatus.NotFound => new(ProcessingV2ServiceStatus.NotFound), ProcessingJobPersistenceStatus.ConcurrencyConflict => new(ProcessingV2ServiceStatus.ConcurrencyConflict), ProcessingJobPersistenceStatus.IdempotentConflict => new(ProcessingV2ServiceStatus.IdempotentConflict), ProcessingJobPersistenceStatus.Conflict => new(ProcessingV2ServiceStatus.Conflict), _ => new(ProcessingV2ServiceStatus.InvalidInput) };
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.BusinessObjects.Auditing;
using RoadGuardSystem.BusinessObjects.Files;
using RoadGuardSystem.BusinessObjects.Inspections;
using RoadGuardSystem.BusinessObjects.Messaging;
using RoadGuardSystem.BusinessObjects.Processing;
using RoadGuardSystem.Repositories.Idempotency;
using RoadGuardSystem.Repositories.Processing;
using RoadGuardSystem.aBusinessObjects.Commons;

namespace RoadGuardSystem.Repositories.Implementations.Processing;

public sealed class ProcessingV2PersistenceService : IProcessingV2Repository
{
    private static readonly JsonSerializerOptions WebJson = new(JsonSerializerDefaults.Web);
    private readonly RoadGuardDbContext _context;
    private readonly IdempotencyOperationService _idempotency;

    public ProcessingV2PersistenceService(RoadGuardDbContext context, IdempotencyOperationService idempotency)
    {
        _context = context;
        _idempotency = idempotency;
    }

    public Task<Guid?> GetDatasetProjectIdAsync(Guid datasetId, CancellationToken cancellationToken = default)
        => (from data in _context.SurveyDataVersions.AsNoTracking()
            join survey in _context.Surveys.AsNoTracking() on data.SurveyId equals survey.Id
            where data.Id == datasetId
            select (Guid?)survey.ProjectId).SingleOrDefaultAsync(cancellationToken);

    public async Task<ProcessingJobPersistenceResult> CreateAsync(ProcessingJobCreateRequest request, CancellationToken cancellationToken = default)
    {
        if (request.ActorUserId == Guid.Empty || request.DatasetId == Guid.Empty || request.ModelVersionId == Guid.Empty ||
            !IsMode(request.Mode) || string.IsNullOrWhiteSpace(request.ScopeJson) || string.IsNullOrWhiteSpace(request.IdempotencyKey))
            return new(ProcessingJobPersistenceStatus.InvalidInput);
        try
        {
            var outcome = await _idempotency.ExecuteAsync(request.ActorUserId, null, "ProcessingJobCreated", request.IdempotencyKey, request.RequestFingerprint, async token =>
            {
                var dataset = await (from data in _context.SurveyDataVersions.AsNoTracking()
                                     join survey in _context.Surveys.AsNoTracking() on data.SurveyId equals survey.Id
                                     where data.Id == request.DatasetId && data.Status == SurveyDataVersionStatus.ServerConfirmed && data.IntegrityStatus == SurveyDataIntegrityStatus.Passed
                                     select new { data, survey.ProjectId }).SingleOrDefaultAsync(token) ?? throw new ScopeNotFoundException();
                var modelReleased = await _context.AIModelVersions.AsNoTracking().AnyAsync(model => model.Id == request.ModelVersionId && model.Status == AIModelVersionStatus.Released, token);
                if (!modelReleased) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Conflict, null)));
                var rangeMetadata = JsonSerializer.Serialize(new { scope = JsonSerializer.Deserialize<JsonElement>(request.ScopeJson) });
                var block = await _context.ProcessingBlocks.SingleOrDefaultAsync(
                    value => value.SurveyDataVersionId == request.DatasetId && value.RangeMetadata == rangeMetadata,
                    token);
                if (block is null)
                {
                    var nextBlockNo = (await _context.ProcessingBlocks
                        .Where(value => value.SurveyDataVersionId == request.DatasetId)
                        .MaxAsync(value => (int?)value.BlockNo, token) ?? 0) + 1;
                    block = ProcessingBlock.Create(Guid.NewGuid(), request.DatasetId, nextBlockNo, rangeMetadata);
                    _context.ProcessingBlocks.Add(block);
                }
                var manifest = JsonSerializer.Serialize(new { datasetId = request.DatasetId, sourceManifest = dataset.data.SourceManifest, scope = JsonSerializer.Deserialize<JsonElement>(request.ScopeJson), request.ModelVersionId, request.PreprocessingVersion, request.ConfigVersion, request.Mode });
                var job = ProcessingJob.CreateQueued(Guid.NewGuid(), block.Id, request.ModelVersionId, dataset.ProjectId, Sha256(manifest), manifest, request.Mode.Trim());
                var attempt = ProcessingAttempt.Create(Guid.NewGuid(), job.Id, 1, DateTimeOffset.UtcNow, null, null, null);
                _context.ProcessingJobs.Add(job);
                _context.ProcessingAttempts.Add(attempt);
                _context.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), "processing_job.dispatch", DateTimeOffset.UtcNow, job.Id, JsonSerializer.Serialize(new { jobId = job.Id, attemptId = attempt.Id, job.ManifestHash })));
                _context.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), request.ActorUserId, DateTimeOffset.UtcNow, "processing_job_created", "ProcessingJob", job.Id, null, "{}", "Processing manifest created", "p2-030", request.CorrelationId, ["datasetId", "modelVersionId"]));
                await _context.SaveChangesAsync(token);
                var view = new ProcessingJobPersistenceView(job.Id, job.ProjectId, ToApiStatus(job.Status), null, 1, Version(job), null);
                return (job.Id, JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Success, view)));
            }, cancellationToken);
            return ReadJobOutcome(outcome);
        }
        catch (ScopeNotFoundException) { return new(ProcessingJobPersistenceStatus.NotFound); }
        catch (ArgumentException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (JsonException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (DbUpdateException exception) when (IsUnique(exception)) { return new(ProcessingJobPersistenceStatus.Conflict); }
    }

    public async Task<ProcessingJobPersistenceView?> GetAsync(Guid jobId, CancellationToken cancellationToken = default)
    {
        var job = await _context.ProcessingJobs.AsNoTracking().SingleOrDefaultAsync(value => value.Id == jobId, cancellationToken);
        if (job is null) return null;
        var attempt = await _context.ProcessingAttempts.AsNoTracking().Where(value => value.ProcessingJobId == jobId).MaxAsync(value => (int?)value.AttemptNo, cancellationToken) ?? 0;
        var result = job.Status == ProcessingJobStatus.Completed
            ? await _context.AIDetections.AsNoTracking().Where(value => value.ProcessingJobId == jobId).Select(value => (Guid?)value.Id).FirstOrDefaultAsync(cancellationToken)
            : null;
        return new(job.Id, job.ProjectId, ToApiStatus(job.Status), result, attempt, Version(job), job.ErrorCode);
    }

    public async Task<ProcessingJobPersistenceResult> RetryAsync(ProcessingJobRetryRequest request, CancellationToken cancellationToken = default)
    {
        var job = await _context.ProcessingJobs.AsNoTracking().SingleOrDefaultAsync(value => value.Id == request.JobId, cancellationToken);
        if (job is null) return new(ProcessingJobPersistenceStatus.NotFound);
        try
        {
            var outcome = await _idempotency.ExecuteAsync(request.ActorUserId, job.ProjectId, "ProcessingJobRetried", request.IdempotencyKey, request.RequestFingerprint, async token =>
            {
                var tracked = await _context.ProcessingJobs.SingleOrDefaultAsync(value => value.Id == request.JobId, token) ?? throw new ScopeNotFoundException();
                if (!TryDecodeVersion(request.ExpectedVersion, out var expected) || !tracked.RowVersion.SequenceEqual(expected)) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.ConcurrencyConflict, null)));
                _context.Entry(tracked).Property(value => value.RowVersion).OriginalValue = expected;
                try { tracked.Retry(); } catch (InvalidOperationException) { return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Conflict, null))); }
                var nextAttempt = (await _context.ProcessingAttempts.AsNoTracking().Where(value => value.ProcessingJobId == tracked.Id).MaxAsync(value => (int?)value.AttemptNo, token) ?? 0) + 1;
                _context.ProcessingAttempts.Add(ProcessingAttempt.Create(Guid.NewGuid(), tracked.Id, nextAttempt, DateTimeOffset.UtcNow, null, null, null));
                _context.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), "processing_job.dispatch", DateTimeOffset.UtcNow, tracked.Id, JsonSerializer.Serialize(new { jobId = tracked.Id, attemptNumber = nextAttempt, tracked.ManifestHash })));
                _context.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), request.ActorUserId, DateTimeOffset.UtcNow, "processing_job_retried", "ProcessingJob", tracked.Id, null, JsonSerializer.Serialize(new { request.Reason }), "Processing job retried", "p2-032", request.CorrelationId, ["reason"]));
                await _context.SaveChangesAsync(token);
                return (tracked.Id, JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Success, new ProcessingJobPersistenceView(tracked.Id, tracked.ProjectId, ToApiStatus(tracked.Status), null, nextAttempt, Version(tracked), null))));
            }, cancellationToken);
            return ReadJobOutcome(outcome);
        }
        catch (ScopeNotFoundException) { return new(ProcessingJobPersistenceStatus.NotFound); }
        catch (DbUpdateConcurrencyException) { return new(ProcessingJobPersistenceStatus.ConcurrencyConflict); }
    }

    public async Task<ProcessingJobPersistenceResult> ReceiveResultAsync(ProcessingAiResultRequest request, CancellationToken cancellationToken = default)
    {
        var existingJob = await _context.ProcessingJobs.AsNoTracking().SingleOrDefaultAsync(value => value.Id == request.JobId, cancellationToken);
        if (existingJob is null) return new(ProcessingJobPersistenceStatus.NotFound);
        try
        {
            var outcome = await _idempotency.ExecuteAsync(null, existingJob.ProjectId, "ProcessingAiResultReceived", request.IdempotencyKey, Sha256(request.DetectionsJson + request.ChecksumSha256), async token =>
            {
                var job = await _context.ProcessingJobs.SingleOrDefaultAsync(value => value.Id == request.JobId, token) ?? throw new ScopeNotFoundException();
                var attempt = await _context.ProcessingAttempts.AsNoTracking().SingleOrDefaultAsync(value => value.Id == request.AttemptId && value.ProcessingJobId == job.Id, token);
                if (attempt is null || job.ManifestHash != request.ManifestHash || job.ModelVersionId != request.ModelVersionId || job.Mode != request.Mode) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Conflict, null)));
                var rawFile = await (
                    from file in _context.Files.AsNoTracking()
                    join upload in _context.UploadSessions.AsNoTracking() on file.Id equals upload.FileId
                    join scope in _context.FileScopes.AsNoTracking() on file.Id equals scope.FileId
                    where file.Id == request.RawResultFileId && file.Checksum == request.ChecksumSha256 &&
                          upload.Status == UploadSessionStatus.Verified && scope.ProjectId == job.ProjectId
                    select file).SingleOrDefaultAsync(token);
                if (rawFile is null) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Conflict, null)));
                using var document = JsonDocument.Parse(request.DetectionsJson);
                if (document.RootElement.ValueKind != JsonValueKind.Array) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.InvalidInput, null)));
                foreach (var detection in document.RootElement.EnumerateArray())
                {
                    var id = detection.GetProperty("detectionId").GetGuid();
                    var type = detection.GetProperty("typeCode").GetString();
                    var confidence = detection.GetProperty("confidence").GetDecimal();
                    _context.AIDetections.Add(AIDetection.Create(id, job.Id, job.ModelVersionId, null, null, type, confidence, null, null, detection.GetRawText()));
                }
                job.Complete(DateTimeOffset.UtcNow);
                await _context.SaveChangesAsync(token);
                var resultId = await _context.AIDetections.AsNoTracking().Where(value => value.ProcessingJobId == job.Id).Select(value => (Guid?)value.Id).FirstOrDefaultAsync(token);
                return (job.Id, JsonSerializer.Serialize(new StoredJobOutcome(ProcessingJobPersistenceStatus.Success, new ProcessingJobPersistenceView(job.Id, job.ProjectId, ToApiStatus(job.Status), resultId, attempt.AttemptNo, Version(job), null))));
            }, cancellationToken);
            return ReadJobOutcome(outcome);
        }
        catch (JsonException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (KeyNotFoundException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (InvalidOperationException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (ArgumentException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (DbUpdateException exception) when (IsUnique(exception)) { return new(ProcessingJobPersistenceStatus.Conflict); }
    }

    public async Task<ValidationRunPersistenceResult> CreateValidationAsync(ValidationRunCreateRequest request, CancellationToken cancellationToken = default)
    {
        if (request.ActorUserId == Guid.Empty || request.ProjectId == Guid.Empty || request.ModelVersionId == Guid.Empty || string.IsNullOrWhiteSpace(request.PairsJson)) return new(ProcessingJobPersistenceStatus.InvalidInput);
        try
        {
            var outcome = await _idempotency.ExecuteAsync(request.ActorUserId, request.ProjectId, "ValidationRunCreated", request.IdempotencyKey, request.RequestFingerprint, async token =>
            {
                var released = await _context.AIModelVersions.AsNoTracking().AnyAsync(value => value.Id == request.ModelVersionId && value.Status == AIModelVersionStatus.Released, token);
                if (!released) return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredValidationOutcome(ProcessingJobPersistenceStatus.Conflict, null)));
                var measurementType = ParseMeasurementType(request.MeasurementType);
                var requestedPairs = JsonSerializer.Deserialize<IReadOnlyList<ValidationPairReference>>(request.PairsJson, WebJson);
                if (measurementType == MeasurementType.Unknown || requestedPairs is not { Count: > 0 } || requestedPairs.Any(value => value.GroundTruthId == Guid.Empty || value.DerivedMeasurementId == Guid.Empty))
                    return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredValidationOutcome(ProcessingJobPersistenceStatus.InvalidInput, null)));
                var facts = await LoadValidationPairFactsAsync(request.ProjectId, requestedPairs, token);
                if (facts.Count != requestedPairs.Count || !PairsAreEligible(facts, requestedPairs, measurementType, request.Unit))
                    return (Guid.NewGuid(), JsonSerializer.Serialize(new StoredValidationOutcome(ProcessingJobPersistenceStatus.InvalidInput, null)));
                var run = ValidationRun.CreateQueued(Guid.NewGuid(), request.ProjectId, request.ModelVersionId, request.DatasetSplitId, request.MeasurementType, request.Unit, request.PairsJson);
                _context.ValidationRuns.Add(run);
                foreach (var pair in requestedPairs)
                {
                    var fact = facts.Single(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId);
                    var signedError = ConvertUnit(fact.DerivedValue, fact.Unit, request.Unit) - ConvertUnit(fact.GroundTruthValue, fact.Unit, request.Unit);
                    _context.MeasurementValidationSamples.Add(MeasurementValidationSample.Create(Guid.NewGuid(), run.Id, fact.GroundTruthId, fact.DerivedMeasurementId, signedError, ValidationSampleInclusionStatus.Included, null));
                }
                _context.OutboxMessages.Add(OutboxMessage.Create(Guid.NewGuid(), "validation_run.dispatch", DateTimeOffset.UtcNow, run.Id, JsonSerializer.Serialize(new { validationRunId = run.Id, request.ModelVersionId, request.DatasetSplitId })));
                _context.AuditLogs.Add(AuditLog.Create(Guid.NewGuid(), request.ActorUserId, DateTimeOffset.UtcNow, "validation_run_created", "ValidationRun", run.Id, null, "{}", "Validation run queued", "p2-034", request.CorrelationId, ["modelVersionId", "datasetSplitId"]));
                await _context.SaveChangesAsync(token);
                return (run.Id, JsonSerializer.Serialize(new StoredValidationOutcome(ProcessingJobPersistenceStatus.Success, ToValidationView(run))));
            }, cancellationToken);
            if (outcome.Status == IdempotencyOperationStatus.Conflict) return new(ProcessingJobPersistenceStatus.IdempotentConflict);
            var stored = JsonSerializer.Deserialize<StoredValidationOutcome>(outcome.OutcomeJson) ?? throw new InvalidOperationException();
            // A replayed receipt preserves the original business outcome. Only a stored
            // success is exposed as Replayed; failed validation must remain a failure so
            // the HTTP layer does not turn it into a null-success fallback.
            return new(outcome.Status == IdempotencyOperationStatus.Replayed && stored.Status == ProcessingJobPersistenceStatus.Success
                ? ProcessingJobPersistenceStatus.Replayed
                : stored.Status, stored.Run);
        }
        catch (ArgumentException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
        catch (JsonException) { return new(ProcessingJobPersistenceStatus.InvalidInput); }
    }

    public async Task<ValidationRunPersistenceView?> GetValidationAsync(Guid runId, CancellationToken cancellationToken = default)
    {
        var run = await _context.ValidationRuns.AsNoTracking().SingleOrDefaultAsync(value => value.Id == runId, cancellationToken);
        return run is null ? null : ToValidationView(run);
    }

    public async Task<bool> CompleteNextValidationRunAsync(CancellationToken cancellationToken = default)
    {
        var message = await _context.OutboxMessages
            .Where(value => value.MessageType == "validation_run.dispatch" && value.DeliveryStatus == OutboxDeliveryStatus.Pending && value.NextAttemptAtUtc <= DateTimeOffset.UtcNow)
            .OrderBy(value => value.OccurredAtUtc)
            .FirstOrDefaultAsync(cancellationToken);
        if (message?.CorrelationId is not Guid runId) return false;

        message.AcquireLease("validation-run-worker", DateTimeOffset.UtcNow, TimeSpan.FromMinutes(1), 3);
        var run = await _context.ValidationRuns.SingleOrDefaultAsync(value => value.Id == runId && value.Status == ValidationRunStatus.Queued, cancellationToken);
        if (run is null)
        {
            message.CompleteLease("validation-run-worker");
            await _context.SaveChangesAsync(cancellationToken);
            return true;
        }

        var samples = await _context.MeasurementValidationSamples.AsNoTracking()
            .Where(value => value.ValidationRunId == run.Id && value.InclusionStatus == ValidationSampleInclusionStatus.Included)
            .ToListAsync(cancellationToken);
        if (samples.Count == 0)
        {
            message.ScheduleRetry("validation-run-worker", DateTimeOffset.UtcNow.AddMinutes(5), "validation_samples_missing", "Validation run has no included sample provenance.", 3);
            await _context.SaveChangesAsync(cancellationToken);
            return true;
        }

        var bias = decimal.Round(samples.Average(value => value.SignedError), 6, MidpointRounding.AwayFromZero);
        var mae = decimal.Round(samples.Average(value => value.AbsoluteError), 6, MidpointRounding.AwayFromZero);
        var rmse = decimal.Round((decimal)Math.Sqrt(samples.Average(value => (double)(value.SignedError * value.SignedError))), 6, MidpointRounding.AwayFromZero);
        try
        {
            run.Complete(samples.Count, 0, bias, mae, rmse, "[]");
            message.CompleteLease("validation-run-worker");
            await _context.SaveChangesAsync(cancellationToken);
            return true;
        }
        catch (DbUpdateConcurrencyException)
        {
            return false;
        }
    }

    private static ProcessingJobPersistenceResult ReadJobOutcome(IdempotencyOperationResult outcome)
    {
        if (outcome.Status == IdempotencyOperationStatus.Conflict) return new(ProcessingJobPersistenceStatus.IdempotentConflict);
        var stored = JsonSerializer.Deserialize<StoredJobOutcome>(outcome.OutcomeJson) ?? throw new InvalidOperationException("Processing outcome is invalid.");
        return new(outcome.Status == IdempotencyOperationStatus.Replayed && stored.Status == ProcessingJobPersistenceStatus.Success ? ProcessingJobPersistenceStatus.Replayed : stored.Status, stored.Job);
    }

    private async Task<List<ValidationPairFact>> LoadValidationPairFactsAsync(Guid projectId, IReadOnlyList<ValidationPairReference> pairs, CancellationToken cancellationToken)
    {
        var groundTruthIds = pairs.Select(value => value.GroundTruthId).Distinct().ToArray();
        var derivedIds = pairs.Select(value => value.DerivedMeasurementId).Distinct().ToArray();
        return await (from groundTruth in _context.GroundTruthMeasurements.AsNoTracking()
                      join session in _context.FieldInspectionSessions.AsNoTracking() on groundTruth.FieldInspectionSessionId equals session.Id
                      join derived in _context.DerivedMeasurements.AsNoTracking() on groundTruth.SampleId equals derived.SampleId
                      join data in _context.SurveyDataVersions.AsNoTracking() on derived.SurveyDataVersionId equals data.Id
                      join survey in _context.Surveys.AsNoTracking() on data.SurveyId equals survey.Id
                      where groundTruthIds.Contains(groundTruth.Id) && derivedIds.Contains(derived.Id) &&
                            session.ProjectId == projectId && survey.ProjectId == projectId &&
                            groundTruth.Value.HasValue && groundTruth.ValueState == "KNOWN"
                      select new ValidationPairFact(groundTruth.Id, derived.Id, groundTruth.SampleId, groundTruth.RoadSectionVersionId, derived.RoadSectionVersionId, groundTruth.MeasurementType, derived.MeasurementType, groundTruth.Value!.Value, derived.Value, groundTruth.Unit, derived.Unit, derived.Status)).ToListAsync(cancellationToken);
    }

    private static bool PairsAreEligible(IReadOnlyList<ValidationPairFact> facts, IReadOnlyList<ValidationPairReference> pairs, MeasurementType measurementType, string unit)
    {
        if (!IsSupportedUnit(unit)) return false;
        return pairs.Distinct().Count() == pairs.Count && pairs.All(pair => facts.Count(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId) == 1 &&
            facts.Single(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId) is { MeasurementType: var groundTruthType, DerivedMeasurementType: var derivedType, GroundTruthRoadSectionVersionId: var groundTruthRoadVersion, DerivedRoadSectionVersionId: var derivedRoadVersion, Status: DerivedMeasurementStatus.Published } &&
            groundTruthType == measurementType && derivedType == measurementType && groundTruthRoadVersion == derivedRoadVersion && IsSupportedUnit(facts.Single(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId).Unit) && IsSupportedUnit(facts.Single(value => value.GroundTruthId == pair.GroundTruthId && value.DerivedMeasurementId == pair.DerivedMeasurementId).DerivedUnit));
    }

    private static MeasurementType ParseMeasurementType(string value) => value.Trim() switch { "DEPRESSION_DEPTH" => MeasurementType.DepressionDepth, "SLAB_FAULTING_HEIGHT" => MeasurementType.SlabFaultingHeight, "SHOULDER_EROSION_EXTENT" => MeasurementType.ShoulderErosionExtent, _ => MeasurementType.Unknown };
    private static bool IsSupportedUnit(string value) => value.Trim().ToLowerInvariant() is "mm" or "cm" or "m";
    private static decimal ConvertUnit(decimal value, string sourceUnit, string destinationUnit)
    {
        var millimetres = sourceUnit.Trim().ToLowerInvariant() switch { "mm" => value, "cm" => value * 10m, "m" => value * 1000m, _ => throw new ArgumentException("Unsupported source unit.", nameof(sourceUnit)) };
        return destinationUnit.Trim().ToLowerInvariant() switch { "mm" => millimetres, "cm" => millimetres / 10m, "m" => millimetres / 1000m, _ => throw new ArgumentException("Unsupported destination unit.", nameof(destinationUnit)) };
    }
    private static ValidationRunPersistenceView ToValidationView(ValidationRun run) => new(run.Id, run.ProjectId, run.Status.ToString().ToUpperInvariant(), Convert.ToBase64String(run.RowVersion), run.UsedCount, run.ExcludedCount, run.Bias, run.Mae, run.Rmse, run.Unit, run.ExclusionReasonsJson);
    private static bool IsMode(string value) => value is "MOCK" or "REAL";
    private static string ToApiStatus(ProcessingJobStatus status) => status switch { ProcessingJobStatus.Completed => "SUCCEEDED", ProcessingJobStatus.RetryableFailure or ProcessingJobStatus.DataFailure => "FAILED", _ => status.ToString().ToUpperInvariant() };
    private static string Version(ProcessingJob job) => Convert.ToBase64String(job.RowVersion);
    private static string Sha256(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
    private static bool TryDecodeVersion(string value, out byte[] result) { try { result = Convert.FromBase64String(value.Trim().Trim('"')); return result.Length > 0; } catch (FormatException) { result = []; return false; } }
    private static bool IsUnique(DbUpdateException exception) { for (Exception? current = exception; current is not null; current = current.InnerException) if (current is SqlException { Number: 2601 or 2627 }) return true; return false; }

    private sealed record StoredJobOutcome(ProcessingJobPersistenceStatus Status, ProcessingJobPersistenceView? Job);
    private sealed record StoredValidationOutcome(ProcessingJobPersistenceStatus Status, ValidationRunPersistenceView? Run);
    private sealed record ValidationPairReference(Guid GroundTruthId, Guid DerivedMeasurementId);
    private sealed record ValidationPairFact(Guid GroundTruthId, Guid DerivedMeasurementId, string SampleId, Guid GroundTruthRoadSectionVersionId, Guid DerivedRoadSectionVersionId, MeasurementType MeasurementType, MeasurementType DerivedMeasurementType, decimal GroundTruthValue, decimal DerivedValue, string Unit, string DerivedUnit, DerivedMeasurementStatus Status);
    private sealed class ScopeNotFoundException : Exception;
}

using System.ComponentModel.DataAnnotations;

namespace RoadGuardSystem.DTOs.Processing;

public sealed record RetryProcessingJobRequestDto([param: Required, MinLength(1), MaxLength(1000)] string Reason);

using System.Text.Json;
using RoadGuardSystem.BusinessObjects.Auditing;

namespace RoadGuardSystem.BusinessObjects.Idempotency;

public sealed class IdempotencyRecord
{
    private IdempotencyRecord()
    {
    }

    public Guid Id { get; private set; }

    public Guid? ActorUserId { get; private set; }

    public Guid? ProjectId { get; private set; }

    public string Operation { get; private set; } = string.Empty;

    public string IdempotencyKey { get; private set; } = string.Empty;

    public string RequestFingerprint { get; private set; } = string.Empty;

    public Guid OperationId { get; private set; }

    public string OutcomeJson { get; private set; } = string.Empty;

    public DateTimeOffset CreatedAtUtc { get; private set; }

    public static IdempotencyRecord Create(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Guid operationId,
        string outcomeJson,
        DateTimeOffset createdAt)
    {
        ValidateRequired(operation, nameof(operation), 100);
        ValidateRequired(idempotencyKey, nameof(idempotencyKey), 200);
        ValidateFingerprint(requestFingerprint, nameof(requestFingerprint));
        ValidateJson(outcomeJson, nameof(outcomeJson));
        if (operationId == Guid.Empty)
        {
            throw new ArgumentException("Operation id must not be empty.", nameof(operationId));
        }

        return new IdempotencyRecord
        {
            // The receipt has its own identity. One business resource can legitimately
            // participate in several idempotent operations (for example create and retry).
            Id = Guid.NewGuid(),
            ActorUserId = actorUserId,
            ProjectId = projectId,
            Operation = operation.Trim(),
            IdempotencyKey = idempotencyKey.Trim(),
            RequestFingerprint = requestFingerprint,
            OperationId = operationId,
            OutcomeJson = outcomeJson,
            CreatedAtUtc = createdAt.ToUniversalTime()
        };
    }

    public static void ValidateScope(
        string operation,
        string idempotencyKey,
        string requestFingerprint)
    {
        ValidateRequired(operation, nameof(operation), 100);
        ValidateRequired(idempotencyKey, nameof(idempotencyKey), 200);
        ValidateFingerprint(requestFingerprint, nameof(requestFingerprint));
    }

    private static void ValidateRequired(string value, string parameterName, int maxLength)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(value, parameterName);
        if (value.Length > maxLength)
        {
            throw new ArgumentException($"Value exceeds maximum length {maxLength}.", parameterName);
        }
    }

    private static void ValidateFingerprint(string value, string parameterName)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(value, parameterName);
        if (value.Length != 64 || value.Any(character => character is not (>= '0' and <= '9') and not (>= 'a' and <= 'f')))
        {
            throw new ArgumentException(
                "Request fingerprint must be a lowercase SHA-256 hexadecimal value.",
                parameterName);
        }
    }

    private static void ValidateJson(string json, string parameterName)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(json, parameterName);
        try
        {
            using var document = JsonDocument.Parse(json);
            if (document.RootElement.ValueKind is not (JsonValueKind.Object or JsonValueKind.Array))
            {
                throw new ArgumentException("JSON root must be an object or array.", parameterName);
            }
        }
        catch (JsonException exception)
        {
            throw new ArgumentException("Value must be valid JSON.", parameterName, exception);
        }
    }
}

using Microsoft.Data.SqlClient;
using System.Data;
using Microsoft.EntityFrameworkCore;
using RoadGuardSystem.BusinessObjects.Idempotency;

namespace RoadGuardSystem.Repositories.Idempotency;

public sealed class IdempotencyOperationService
{
    private readonly RoadGuardDbContext _context;

    public IdempotencyOperationService(RoadGuardDbContext context)
    {
        _context = context;
    }

    public Task<IdempotencyOperationResult> ExecuteAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        CancellationToken cancellationToken = default)
        => ExecuteCoreAsync(actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            operationHandler, null, null, cancellationToken);

    /// <param name="receiptAccessGuard">Current authoritative receipt access check, in a service-owned
    /// short transaction on the same scoped DbContext. Called before replay/conflict on every path;
    /// original cancellation token and guard exceptions are preserved. Must only read/lock rows.</param>
    [System.Diagnostics.CodeAnalysis.SuppressMessage("Design", "CA1068:CancellationToken parameters must come last",
        Justification = "Keep the original seven-parameter overload, and place the additive guard after its positional CancellationToken.")]
    public Task<IdempotencyOperationResult> ExecuteAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        CancellationToken cancellationToken,
        Func<CancellationToken, Task>? receiptAccessGuard)
        => ExecuteCoreAsync(actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            operationHandler, null, receiptAccessGuard, cancellationToken);

    public Task<IdempotencyOperationResult> ExecuteSerializableAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        CancellationToken cancellationToken = default)
        => ExecuteCoreAsync(actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            operationHandler, IsolationLevel.Serializable, null, cancellationToken);

    // The original seven-parameter overload remains available, including reflection callers.
    /// <param name="receiptAccessGuard">Same receipt guard contract as ExecuteAsync. Serializable
    /// isolation applies to new writes; the guard owns its authoritative read locks in the short
    /// service-owned receipt transaction.</param>
    [System.Diagnostics.CodeAnalysis.SuppressMessage("Design", "CA1068:CancellationToken parameters must come last",
        Justification = "Keep the original seven-parameter overload, and place the additive guard after its positional CancellationToken.")]
    public Task<IdempotencyOperationResult> ExecuteSerializableAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        CancellationToken cancellationToken,
        Func<CancellationToken, Task>? receiptAccessGuard)
        => ExecuteCoreAsync(actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            operationHandler, IsolationLevel.Serializable, receiptAccessGuard, cancellationToken);

    /// <summary>
    /// A supplied receipt guard is called before every replay/conflict, including retry and recovery.
    /// It must read/lock authoritative rows through this service's scoped DbContext, without opening
    /// or completing a transaction, saving writes, or using cached preflight authority. The service
    /// owns a short transaction inside the execution strategy and holds those locks through mapping
    /// and commit. It passes the original command token (also after acknowledgement loss). Guard
    /// exceptions, including cancellation and otherwise retryable exceptions, escape unchanged;
    /// they never become stored outcomes, conflict results, or create-handler invocations.
    /// Without a guard, the previous replay and transaction-isolation semantics remain unchanged.
    /// </summary>
    private async Task<IdempotencyOperationResult> ExecuteCoreAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        IsolationLevel? isolationLevel,
        Func<CancellationToken, Task>? receiptAccessGuard,
        CancellationToken cancellationToken)
    {
        try
        {
            return await ExecuteOperationAsync(actorUserId, projectId, operation, idempotencyKey,
                requestFingerprint, operationHandler, isolationLevel, receiptAccessGuard, cancellationToken);
        }
        catch (ReceiptAccessGuardException exception)
        {
            System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(exception.Cause).Throw();
            throw;
        }
    }

    private async Task<IdempotencyOperationResult> ExecuteOperationAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        IsolationLevel? isolationLevel,
        Func<CancellationToken, Task>? receiptAccessGuard,
        CancellationToken cancellationToken)
    {
        IdempotencyRecord.ValidateScope(operation, idempotencyKey, requestFingerprint);
        ArgumentNullException.ThrowIfNull(operationHandler);

        operation = operation.Trim();
        idempotencyKey = idempotencyKey.Trim();

        var executionStrategy = _context.Database.CreateExecutionStrategy();
        Task<IdempotencyOperationResult?> LookupAsync() => FindAndMapExistingAsync(
            actorUserId, projectId, operation, idempotencyKey, requestFingerprint,
            receiptAccessGuard, cancellationToken);
        var existingResult = receiptAccessGuard is null
            ? await LookupAsync()
            : await executionStrategy.ExecuteAsync(LookupAsync);
        if (existingResult is not null)
        {
            return existingResult;
        }

        try
        {
            return await executionStrategy.ExecuteAsync(
                () => ExecuteAttemptAsync(
                    actorUserId,
                    projectId,
                    operation,
                    idempotencyKey,
                    requestFingerprint,
                    operationHandler,
                    isolationLevel,
                    receiptAccessGuard,
                    cancellationToken));
        }
        catch (DbUpdateException exception) when (IsUniqueConstraintViolation(exception))
        {
            _context.ChangeTracker.Clear();
            var recovered = receiptAccessGuard is null
                ? await LookupAsync()
                : await executionStrategy.ExecuteAsync(LookupAsync);
            if (recovered is null)
            {
                throw;
            }

            return recovered;
        }
    }

    private async Task<IdempotencyOperationResult> ExecuteAttemptAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        string requestFingerprint,
        Func<CancellationToken, Task<(Guid OperationId, string OutcomeJson)>> operationHandler,
        IsolationLevel? isolationLevel,
        Func<CancellationToken, Task>? receiptAccessGuard,
        CancellationToken cancellationToken)
    {
        // A commit acknowledgement can fail after the database transaction is durable. Each retry must
        // discard stale tracked state and prefer the durable outcome over invoking the handler again.
        _context.ChangeTracker.Clear();
        var existing = await FindExistingAsync(
            actorUserId,
            projectId,
            operation,
            idempotencyKey,
            cancellationToken);
        if (existing is not null)
        {
            return await MapAuthorizedAsync(existing, requestFingerprint, receiptAccessGuard, cancellationToken);
        }

        IdempotencyRecord record;
        Exception? commitFailure = null;
        await using (var transaction = isolationLevel is { } selectedIsolation
            ? await _context.Database.BeginTransactionAsync(selectedIsolation, cancellationToken)
            : await _context.Database.BeginTransactionAsync(cancellationToken))
        {
            try
            {
                var outcome = await operationHandler(cancellationToken);
                record = IdempotencyRecord.Create(
                    actorUserId,
                    projectId,
                    operation,
                    idempotencyKey,
                    requestFingerprint,
                    outcome.OperationId,
                    outcome.OutcomeJson,
                    DateTimeOffset.UtcNow);
                _context.Set<IdempotencyRecord>().Add(record);
                await _context.SaveChangesAsync(cancellationToken);
            }
            catch
            {
                await transaction.RollbackAsync(CancellationToken.None);
                throw;
            }

            try
            {
                await transaction.CommitAsync(cancellationToken);
                return new IdempotencyOperationResult(
                    IdempotencyOperationStatus.Executed,
                    record.OperationId,
                    record.OutcomeJson,
                    record.ActorUserId,
                    record.ProjectId,
                    record.Operation);
            }
            catch (Exception exception)
            {
                commitFailure = exception;
                try
                {
                    await transaction.RollbackAsync(CancellationToken.None);
                }
                catch
                {
                    // The transaction may already be committed. Its durable state is checked below.
                }
            }
        }

        // A post-commit acknowledgement failure is indistinguishable from a failed commit until the
        // transaction is disposed. Query only after that boundary so uncommitted local writes cannot
        // be mistaken for a durable replay.
        _context.ChangeTracker.Clear();
        var durableRecord = await FindExistingAsync(
            actorUserId,
            projectId,
            operation,
            idempotencyKey,
            CancellationToken.None);
        if (durableRecord is not null)
        {
            return await MapAuthorizedAsync(durableRecord, requestFingerprint, receiptAccessGuard, cancellationToken);
        }

        System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(commitFailure!).Throw();
        throw new InvalidOperationException("Commit recovery did not produce an exception.");
    }

    private async Task<IdempotencyOperationResult?> FindAndMapExistingAsync(
        Guid? actorUserId, Guid? projectId, string operation, string idempotencyKey,
        string requestFingerprint, Func<CancellationToken, Task>? receiptAccessGuard,
        CancellationToken cancellationToken)
    {
        var record = await FindExistingAsync(actorUserId, projectId, operation, idempotencyKey, cancellationToken);
        return record is null ? null : await MapAuthorizedAsync(record, requestFingerprint, receiptAccessGuard, cancellationToken);
    }

    // Called only within an execution-strategy boundary when a guard is supplied.
    private async Task<IdempotencyOperationResult> MapAuthorizedAsync(
        IdempotencyRecord record, string requestFingerprint,
        Func<CancellationToken, Task>? receiptAccessGuard, CancellationToken cancellationToken)
    {
        if (receiptAccessGuard is null)
        {
            return MapExisting(record, requestFingerprint);
        }

        await using var transaction = await _context.Database.BeginTransactionAsync(cancellationToken);
        try
        {
            await receiptAccessGuard(cancellationToken);
        }
        catch (Exception exception)
        {
            // Do not let a guard's SQL/DbUpdate/transient error enter receipt recovery or retry.
            // Keep the cause outside InnerException so provider retry unwrapping cannot reach it.
            throw new ReceiptAccessGuardException(exception);
        }

        var result = MapExisting(record, requestFingerprint);
        await transaction.CommitAsync(cancellationToken);
        return result;
    }

    private sealed class ReceiptAccessGuardException(Exception cause) : Exception
    {
        public Exception Cause { get; } = cause;
    }

    private Task<IdempotencyRecord?> FindExistingAsync(
        Guid? actorUserId,
        Guid? projectId,
        string operation,
        string idempotencyKey,
        CancellationToken cancellationToken)
        => _context.Set<IdempotencyRecord>()
            .AsNoTracking()
            .SingleOrDefaultAsync(
                record =>
                    record.ActorUserId == actorUserId &&
                    record.ProjectId == projectId &&
                    record.Operation == operation &&
                    record.IdempotencyKey == idempotencyKey,
                cancellationToken);

    private static IdempotencyOperationResult MapExisting(
        IdempotencyRecord record,
        string requestFingerprint)
        => new(
            record.RequestFingerprint == requestFingerprint
                ? IdempotencyOperationStatus.Replayed
                : IdempotencyOperationStatus.Conflict,
            record.OperationId,
            record.OutcomeJson,
            record.ActorUserId,
            record.ProjectId,
            record.Operation);

    private static bool IsUniqueConstraintViolation(DbUpdateException exception)
    {
        Exception? current = exception;
        while (current is not null)
        {
            if (current is SqlException { Number: 2601 or 2627 })
            {
                return true;
            }

            current = current.InnerException;
        }

        return false;
    }
}

