using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using Microsoft.AspNetCore.Authentication.Cookies;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Identity;
using RoadGuardSystem.Services.Authentication;

namespace RoadGuardSystem.API.Authentication;

internal static class WebCookieConfiguration
{
    internal const string Scheme = "RoadGuardWeb";
    internal const string UserScheme = "RoadGuardUser";
    internal const string CookieName = "__Host-RoadGuardSession";
    internal const string RenewalCookieName = "__Host-RoadGuardRenewal";

    internal static string SelectScheme(HttpContext context)
    {
        if (context.Request.Headers.ContainsKey("Authorization"))
            return Microsoft.AspNetCore.Authentication.JwtBearer.JwtBearerDefaults.AuthenticationScheme;
        return IsCookieEligibleRequest(context) && context.Request.Cookies.ContainsKey(CookieName)
            ? Scheme
            : Microsoft.AspNetCore.Authentication.JwtBearer.JwtBearerDefaults.AuthenticationScheme;
    }

    internal static bool IsCookieEligibleRequest(HttpContext context) =>
        context.GetEndpoint()?.Metadata.GetMetadata<WebCookieEligibleAttribute>() is not null ||
        IsCookieEligibleRequest(context.Request.Method, context.Request.Path);

    internal static bool IsCookieEligibleRequest(string method, PathString requestPath)
    {
        var path = requestPath.Value ?? "";
        // Normalize one optional trailing slash, without admitting extra segments.
        if (path.EndsWith('/')) path = path[..^1];
        if (path.Equals("/api/v1/me/inspection-tasks", StringComparison.OrdinalIgnoreCase))
            return HttpMethods.IsGet(method);
        var parts = path.Split('/');
        if (parts.Length >= 4 && parts[0] == "" &&
            parts[1].Equals("api", StringComparison.OrdinalIgnoreCase) &&
            parts[2].Equals("v1", StringComparison.OrdinalIgnoreCase) &&
            parts[3].Equals("notifications", StringComparison.OrdinalIgnoreCase))
        {
            if (parts.Length == 4) return HttpMethods.IsGet(method);
            if (!Guid.TryParse(parts[4], out _)) return false;
            if (parts.Length == 5) return HttpMethods.IsGet(method);
            return parts.Length == 6 && parts[5].Equals("read", StringComparison.OrdinalIgnoreCase)
                && HttpMethods.IsPost(method);
        }
        return IsCookieEligiblePath(requestPath);
    }

    internal static bool IsCookieEligiblePath(PathString requestPath)
    {
        var path = requestPath.Value ?? "";
        return path.Equals("/api/v1/me", StringComparison.OrdinalIgnoreCase)
            || path.StartsWith("/api/v1/profile", StringComparison.OrdinalIgnoreCase)
            || path.Equals("/api/v1/auth/change-password", StringComparison.OrdinalIgnoreCase)
            || path.StartsWith("/api/v1/reports", StringComparison.OrdinalIgnoreCase)
            || path.StartsWith("/api/v1/cases", StringComparison.OrdinalIgnoreCase)
            || IsProjectDefectPath(path)
            || path.Contains("/candidate-decisions", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/candidates", StringComparison.OrdinalIgnoreCase)
            || path.Contains("/labels", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsProjectDefectPath(string path)
    {
        var parts = path.TrimEnd('/').Split('/');
        if (parts.Length is < 6 or > 8 || parts[0] != "" ||
            !parts[1].Equals("api", StringComparison.OrdinalIgnoreCase) ||
            !parts[2].Equals("v1", StringComparison.OrdinalIgnoreCase) ||
            !parts[3].Equals("projects", StringComparison.OrdinalIgnoreCase) ||
            !Guid.TryParse(parts[4], out _) ||
            !parts[5].Equals("defects", StringComparison.OrdinalIgnoreCase)) return false;
        if (parts.Length == 6) return true;
        if (!Guid.TryParse(parts[6], out _)) return false;
        return parts.Length == 7 || parts[7].Equals("assessments", StringComparison.OrdinalIgnoreCase) ||
            parts[7].Equals("verification-decisions", StringComparison.OrdinalIgnoreCase);
    }

    internal static void Configure(CookieAuthenticationOptions options)
    {
        options.Cookie.Name = CookieName;
        options.Cookie.HttpOnly = true;
        options.Cookie.SecurePolicy = CookieSecurePolicy.Always;
        options.Cookie.SameSite = SameSiteMode.Lax;
        options.Cookie.Path = "/";
        options.SlidingExpiration = false;
        options.ExpireTimeSpan = TimeSpan.FromHours(12);
        options.Events = new CookieAuthenticationEvents
        {
            OnValidatePrincipal = async context =>
            {
                var claims = context.Principal;
                if (!Guid.TryParse(claims?.FindFirstValue(JwtRegisteredClaimNames.Sub), out var userId) ||
                    !Guid.TryParse(claims?.FindFirstValue("sid"), out var sessionId) ||
                    !TryRole(claims?.FindFirstValue("role"), out var role))
                {
                    context.RejectPrincipal();
                    return;
                }
                var validator = context.HttpContext.RequestServices.GetRequiredService<AuthoritativeSessionValidator>();
                var result = await validator
                    .ValidateAsync(userId, sessionId, role, context.HttpContext.RequestServices.GetRequiredService<TimeProvider>().GetUtcNow(),
                        SessionTransport.Web, context.HttpContext.RequestAborted);
                if (result == AuthoritativeSessionValidation.MustChangePassword &&
                    PasswordChangeAllowed(context.Request.Method, context.Request.Path)) return;
                if (result == AuthoritativeSessionValidation.SessionRevoked &&
                    HttpMethods.IsPost(context.Request.Method) &&
                    context.Request.Path.Value?.EndsWith("/auth/web/logout", StringComparison.OrdinalIgnoreCase) == true &&
                    context.Request.Headers.TryGetValue("Idempotency-Key", out var key) &&
                    !string.IsNullOrWhiteSpace(key.ToString()) &&
                    await validator.HasCommittedReplayAsync(userId, "Logout", key.ToString().Trim(' '),
                        context.HttpContext.RequestAborted)) return;
                if (result != AuthoritativeSessionValidation.Success) context.RejectPrincipal();
            },
            OnRedirectToLogin = context =>
            {
                context.Response.StatusCode = StatusCodes.Status401Unauthorized;
                return Task.CompletedTask;
            },
            OnRedirectToAccessDenied = context =>
            {
                context.Response.StatusCode = StatusCodes.Status403Forbidden;
                return Task.CompletedTask;
            }
        };
    }

    private static bool PasswordChangeAllowed(string method, PathString path)
    {
        var value = path.Value ?? "";
        if (HttpMethods.IsGet(method))
            return value.EndsWith("/me", StringComparison.OrdinalIgnoreCase) ||
                   value.EndsWith("/auth/web/session", StringComparison.OrdinalIgnoreCase) ||
                   value.EndsWith("/auth/web/csrf", StringComparison.OrdinalIgnoreCase);
        return HttpMethods.IsPost(method) &&
            (value.EndsWith("/auth/web/logout", StringComparison.OrdinalIgnoreCase) ||
             value.EndsWith("/auth/change-password", StringComparison.OrdinalIgnoreCase));
    }

    private static bool TryRole(string? value, out UserRoleCode role)
    {
        try { role = UserRoleCodeExtensions.FromDbCode(value ?? ""); return role != UserRoleCode.Unknown; }
        catch (ArgumentOutOfRangeException) { role = UserRoleCode.Unknown; return false; }
    }
}

using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Antiforgery;
using Microsoft.AspNetCore.Authentication;
using RoadGuardSystem.API.Authentication;
using RoadGuardSystem.aBusinessObjects.Commons;

namespace RoadGuardSystem.API.Middlewares;

public sealed class WebCookieRequestMiddleware(RequestDelegate next)
{
    public async Task InvokeAsync(HttpContext context, IAntiforgery antiforgery)
    {
        if (context.Request.Headers.ContainsKey("Authorization") &&
            context.Request.Cookies.ContainsKey(WebCookieConfiguration.CookieName) &&
            WebCookieConfiguration.IsCookieEligibleRequest(context) &&
            context.User.Identity?.IsAuthenticated == true)
        {
            var cookie = await context.AuthenticateAsync(WebCookieConfiguration.Scheme);
            var bearerActor = context.User.FindFirstValue(JwtRegisteredClaimNames.Sub);
            var cookieActor = cookie.Principal?.FindFirstValue(JwtRegisteredClaimNames.Sub);
            if (cookie.Succeeded && cookieActor is not null && cookieActor != bearerActor)
            {
                await DenyAsync(context, StatusCodes.Status400BadRequest, "validation_error");
                return;
            }
        }

        if (context.User.Identity?.AuthenticationType != WebCookieConfiguration.Scheme ||
            context.Request.Path.StartsWithSegments("/api/v1/auth/web", StringComparison.OrdinalIgnoreCase))
        {
            await next(context);
            return;
        }

        if (!HttpMethods.IsGet(context.Request.Method) && !HttpMethods.IsHead(context.Request.Method) &&
            !HttpMethods.IsOptions(context.Request.Method))
        {
            try { await antiforgery.ValidateRequestAsync(context); }
            catch (AntiforgeryValidationException)
            {
                await DenyAsync(context, StatusCodes.Status403Forbidden, "csrf_failed");
                return;
            }
        }

        await next(context);
    }

    private static Task DenyAsync(HttpContext context, int status, string code)
    {
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/problem+json";
        context.Response.Headers.CacheControl = "no-store";
        return context.Response.WriteAsync(JsonSerializer.Serialize(new
        {
            type = "about:blank",
            title = status switch { 400 => "Bad Request", 403 => "Forbidden", _ => "Unauthorized" },
            status,
            detail = status switch
            {
                400 => "Credentials identify different actors.",
                403 => "The CSRF token is invalid or missing.",
                _ => "The session is no longer active."
            },
            instance = context.Request.Path.Value,
            code,
            correlationId = context.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString()
        }), context.RequestAborted);
    }
}

public async Task<IActionResult> Timeline(Guid projectId, [FromQuery] string aggregateType, [FromQuery] Guid aggregateId,
        [FromQuery] DateTimeOffset? from, [FromQuery] DateTimeOffset? to, [FromQuery] string? cursor, CancellationToken token, [FromQuery] int pageSize = 50)
    {
        if (!Actor(out var actor)) return Error("unauthorized");
        var result = await service.TimelineAsync(actor, projectId, aggregateType, aggregateId, new(from, to), cursor, pageSize, token);
        return result.Value is { } value ? Ok(value) : Error(result.Code);
    }

    private bool Actor(out Guid actor) => Guid.TryParse(User.FindFirstValue(JwtRegisteredClaimNames.Sub) ?? User.FindFirstValue(ClaimTypes.NameIdentifier), out actor);
    private ObjectResult Error(string code)
    {
        var status = code switch { "unauthorized" => 401, "access_forbidden" => 403, "not_found" => 404, "cursor_invalid" => 400, _ => 422 };
        var problem = new ProblemDetails { Status = status, Title = code, Detail = "The reporting request could not be completed.", Instance = Request.Path };
        problem.Extensions["code"] = code;
        problem.Extensions["correlationId"] = HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey]?.ToString() ?? Guid.NewGuid().ToString();
        return new ObjectResult(problem) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }
}

using System.Data.SqlTypes;
using RoadGuardSystem.DTOs.Reporting;
using RoadGuardSystem.Repositories.Identity;
using RoadGuardSystem.Repositories.Reporting;
using RoadGuardSystem.Services.Authorization;
using RoadGuardSystem.aBusinessObjects.Commons;

namespace RoadGuardSystem.Services.Reporting;

public sealed class ReportingService(IReportingRepository repository, IIdentityRepository identity, IProjectScopeGuard guard, TimeProvider clock,
    IEnumerable<RoadGuardSystem.Services.Integration.ICaseDefectReadReader>? caseDefectReaders = null,
    IEnumerable<ICurrentRepairFactsReader>? currentRepairReaders = null,
    IEnumerable<IDefectStatisticsRepository>? defectStatisticsReaders = null) : IReportingService
{
    public async Task<ReportingResult<ReportingCaptureDto>> CaptureAsync(Guid actor, Guid project, ReportingFiltersDto filters, CancellationToken token)
    {
        if (!TryNormalize(filters, out var normalized)) return new("validation_error");
        return await repository.ReadConsistentlyAsync(async ct =>
        {
            if (!await Authorized(actor, project, ct)) return new ReportingResult<ReportingCaptureDto>("access_forbidden");
            var readAt = clock.GetUtcNow();
            var facts = await repository.CaptureAsync(project, normalized, ct);
            if (facts.Facts is null) return new(facts.Code);
            var capture = ReportingDefinitions.Create(project, readAt, normalized, facts.Facts);
            var reader = caseDefectReaders?.SingleOrDefault();
            if (reader is not null)
            {
                var actorState = await identity.GetUserSecurityStateAsync(actor, ct);
                if (actorState is null) return new("access_forbidden");
                try
                {
                    var snapshot = await reader.CaptureAsync(actor, actorState.RoleCode, project, normalized, ct);
                    if (snapshot is not null)
                    {
                        try { capture = CaseDefectCaptureConsumer.Apply(capture, snapshot); }
                        catch (InvalidOperationException) { return new("producer_invalid"); }
                    }
                }
                catch (UnauthorizedAccessException) { return new("access_forbidden"); }
            }
            var repairReader = currentRepairReaders?.SingleOrDefault();
            if (repairReader is not null)
            {
                try { capture = CurrentRepairCaptureConsumer.Apply(capture, await repairReader.CaptureAsync(actor, project, normalized, ct)); }
                catch (UnauthorizedAccessException)
                {
                    // Preserve legacy report access without exposing new protected repair facts.
                    if (!await Authorized(actor, project, ct)) return new("access_forbidden");
                    capture = CurrentRepairCaptureConsumer.Apply(capture, new(project, [], ["REPAIR_PROJECT_AUTHORITY_NOT_VERIFIED"]));
                }
                catch (InvalidOperationException) { return new("producer_invalid"); }
            }
            var statisticsReader = defectStatisticsReaders?.SingleOrDefault();
            if (statisticsReader is not null)
            {
                var actorState = await identity.GetUserSecurityStateAsync(actor, ct);
                if (actorState is null) return new("access_forbidden");
                var statistics = await statisticsReader.ReadAsync(actor, actorState.RoleCode, project, normalized, ct);
                if (statistics.Value is not null) capture = DefectStatisticsCaptureConsumer.Apply(capture, statistics.Value.Statistics);
                else return new(statistics.Status switch { 403 => "access_forbidden", 404 => "not_found", 400 => "validation_error", _ => "producer_invalid" });
            }
            return new("success", capture);
        }, token);
    }
    public async Task<ReportingResult<ProjectSummaryV1>> SummaryAsync(Guid actor, Guid project, ReportingFiltersDto filters, CancellationToken token)
    {
        var capture = await CaptureAsync(actor, project, filters, token); return new(capture.Code, capture.Value?.Summary);
    }
    public async Task<ReportingResult<ReportingItemsPageDto>> ItemsAsync(Guid actor, Guid project, ReportingFiltersDto filters, string metric, string? cursor, int pageSize, CancellationToken token)
    {
        if (!ReportingDefinitions.Codes.Contains(metric) || pageSize is < 1 or > 200 || !TryNormalize(filters, out var normalized)) return new("validation_error");
        var hash = ReportingCursor.FilterHash(project, normalized, metric);
        if (!ReportingCursor.TryDecode(cursor, hash, out var key)) return new("cursor_invalid");
        var capture = await CaptureAsync(actor, project, normalized, token);
        if (capture.Value is not { } value) return new(capture.Code);
        var rows = value.Items.Where(i => i.Metric == metric && (key is null || new SqlGuid(i.Id).CompareTo(new SqlGuid(key.Id)) > 0))
            .OrderBy(i => new SqlGuid(i.Id)).Take(pageSize + 1).ToArray();
        var page = rows.Take(pageSize).ToArray();
        var metricRows = value.Summary.Metrics.Where(m => m.Code == metric).ToArray();
        var availability = metricRows.Any(m => m.Availability == "UNAVAILABLE") ? "UNAVAILABLE" : metricRows.Any(m => m.Availability == "PARTIAL") ? "PARTIAL" : "AVAILABLE";
        return new("success", new(ReportingDefinitions.Schema, metric, value.Summary.ReadAt, page,
            rows.Length > pageSize ? ReportingCursor.Encode(hash, DateTimeOffset.UnixEpoch, page[^1].Id) : null,
            new(availability, metricRows.SelectMany(m => m.ReasonCodes).Distinct().ToArray())));
    }
    public async Task<ReportingResult<ReportingTimelinePageDto>> TimelineAsync(Guid actor, Guid project, string aggregateType, Guid aggregateId, ReportingFiltersDto filters, string? cursor, int pageSize, CancellationToken token)
    {
        if (aggregateType is not ("Project" or "SurveyRequest" or "SurveyDataVersion" or "DatasetAssessment" or "BaselineSelection") || aggregateId == Guid.Empty ||
            pageSize is < 1 or > 200 || !TryNormalize(filters, out var normalized) || normalized.RouteVersionId.HasValue || normalized.SegmentSetId.HasValue || normalized.SegmentIds!.Length > 0)
            return new("validation_error");
        var hash = ReportingCursor.FilterHash(project, normalized, "timeline", aggregateType, aggregateId);
        if (!ReportingCursor.TryDecode(cursor, hash, out var key)) return new("cursor_invalid");
        return await repository.ReadConsistentlyAsync(async ct =>
        {
            if (!await Authorized(actor, project, ct)) return new ReportingResult<ReportingTimelinePageDto>("access_forbidden");
            if (!await repository.AggregateBelongsAsync(project, aggregateType, aggregateId, ct)) return new ReportingResult<ReportingTimelinePageDto>("not_found");
            var readAt = clock.GetUtcNow();
            ReportingTimelineItemDto[] rows;
            if (aggregateType == "Project")
            {
                var facts = await repository.CaptureAsync(project, normalized, ct);
                rows = (facts.Facts?.Timeline ?? []).Where(i => key is null || i.OccurredAt > key.Time || i.OccurredAt == key.Time && new SqlGuid(i.EventId).CompareTo(new SqlGuid(key.Id)) > 0)
                    .OrderBy(i => i.OccurredAt).ThenBy(i => new SqlGuid(i.EventId)).Take(pageSize + 1).Select(item => (ReportingTimelineItemDto)item).ToArray();
            }
            else rows = (await repository.TimelineAsync(aggregateType, aggregateId, normalized, key?.Time, key?.Id, pageSize + 1, ct)).Select(item => (ReportingTimelineItemDto)item).ToArray();
            var page = rows.Take(pageSize).ToArray();
            return new ReportingResult<ReportingTimelinePageDto>("success", new(ReportingDefinitions.Schema, readAt, page,
                rows.Length > pageSize ? ReportingCursor.Encode(hash, page[^1].OccurredAt, page[^1].EventId) : null, ReportingDefinitions.TimelineAvailability));
        }, token);
    }
    private async Task<bool> Authorized(Guid actor, Guid project, CancellationToken token)
    {
        if (actor == Guid.Empty || project == Guid.Empty) return false;
        var user = await identity.GetUserSecurityStateAsync(actor, token);
        return user is { Status: UserStatus.Active, MustChangePassword: false, RoleCode: UserRoleCode.ProjectManager or UserRoleCode.Supervisor } &&
            await identity.IsRoleActiveAsync(user.RoleCode, token) && await guard.AuthorizeAsync(actor, user.RoleCode, project, token) is not null;
    }
    public static bool TryNormalize(ReportingFiltersDto filters, out ReportingFiltersDto normalized)
    {
        normalized = filters with { From = filters.From?.ToUniversalTime(), To = filters.To?.ToUniversalTime(), SegmentIds = (filters.SegmentIds ?? []).Distinct().Order().ToArray() };
        return filters.From.HasValue == filters.To.HasValue && (!filters.From.HasValue || filters.From.Value.Offset == TimeSpan.Zero && filters.To!.Value.Offset == TimeSpan.Zero && filters.From < filters.To) &&
            filters.RouteVersionId != Guid.Empty && filters.SegmentSetId != Guid.Empty && normalized.SegmentIds.Length <= 500 && !normalized.SegmentIds.Contains(Guid.Empty);
    }
}

