    }
    public async Task<RetentionEvaluationView> AdmitEvaluationAsync(Guid actor, Guid project, CreateRetentionEvaluationRequest request, string key, CancellationToken token)
    {
        Key(key);
        if (request.FileIds is { } ids && (ids.Length == 0 || ids.Length > 500 || ids.Distinct().Count() != ids.Length || ids.Contains(Guid.Empty))) throw new RetentionRequestException(422, "validation_error");
        return await repository.AdmitEvaluationAsync(actor, project, request, key, token);
    }
