public Task<IActionResult> Release(Guid id, ReleaseRetentionHoldRequest request, CancellationToken token) => Run(async actor =>
    {
        var view = await service.ReleaseHoldAsync(actor, id, request, Key(), Expected(), token); Tag(view.Version); return Ok(view);
    });

    private async Task<IActionResult> Run(Func<Guid, Task<IActionResult>> action)
    {
        if (!Guid.TryParse(User.FindFirstValue(JwtRegisteredClaimNames.Sub) ?? User.FindFirstValue(ClaimTypes.NameIdentifier), out var actor) || actor == Guid.Empty) return Error(401, "unauthorized");
        try
        {
            UserRoleCode role;
            try { role = UserRoleCodeExtensions.FromDbCode(User.FindFirstValue("role")); }
            catch (ArgumentOutOfRangeException) { return Error(401, "unauthorized"); }
            await service.AuthorizePrincipalAsync(actor, role, HttpContext.RequestAborted);
            return await action(actor);
        }
        catch (RetentionRequestException exception) { return Error(exception.Status, exception.Code); }
    }
    private ObjectResult Error(int status, string code)
    {
        var problem = new ProblemDetails { Status = status, Title = "Retention request could not be completed", Detail = "The request failed a retention scope, policy, or concurrency check.", Instance = Request.Path };
        problem.Extensions["code"] = code; problem.Extensions["correlationId"] = HttpContext.Items[CorrelationIdMiddleware.CorrelationIdItemKey] ?? HttpContext.TraceIdentifier;
        return new ObjectResult(problem) { StatusCode = status, ContentTypes = { "application/problem+json" } };
    }
    private string Key() => Request.Headers["Idempotency-Key"].Count == 1 ? Request.Headers["Idempotency-Key"].ToString() : "";
    private string Expected()
    {
        if (!Request.Headers.TryGetValue("If-Match", out var value) || string.IsNullOrWhiteSpace(value)) throw new RetentionRequestException(428, "validation_error");
        var text = value.ToString();
        if (value.Count != 1 || text.Length < 3 || text[0] != '"' || text[^1] != '"' || text[1..^1].Contains('"')) throw new RetentionRequestException(412, "concurrency_conflict");
        return text[1..^1];
    }
    private void Tag(string version) => Response.Headers.ETag = $"\"{version}\"";
}

using RoadGuardSystem.DTOs.Retention;
using RoadGuardSystem.Repositories.Retention;
using RoadGuardSystem.aBusinessObjects.Commons;
namespace RoadGuardSystem.Services.Retention;

public sealed class RetentionService(IRetentionRepository repository) : IRetentionService
{
    public Task AuthorizePrincipalAsync(Guid actor, UserRoleCode role, CancellationToken token) => repository.AuthorizePrincipalAsync(actor, role, token);
    public Task AuthorizeAsync(Guid actor, Guid? project, bool supervisorOnly, CancellationToken token) => repository.AuthorizeAsync(actor, project, supervisorOnly, token);
    public async Task<RetentionFileView> GetFileAsync(Guid actor, Guid project, Guid file, CancellationToken token) => await repository.GetFileAsync(actor, project, file, token);
    public async Task<RetentionBasisView> ConfirmBasisAsync(Guid actor, Guid project, Guid file, ConfirmRetentionBasisRequest request, string key, string expected, CancellationToken token)
    {
        Reason(request.Reason); Key(key); Version(expected);
        if (request.WarrantyIds is null || request.WarrantyIds.Distinct().Count() != request.WarrantyIds.Length || request.WarrantyIds.Contains(Guid.Empty) || string.IsNullOrWhiteSpace(request.ExpectedReferenceInventoryVersion)) throw new RetentionRequestException(422, "basis_invalid");
        return await repository.ConfirmBasisAsync(actor, project, file, request, key, expected, token);
    }
    public async Task<RetentionHoldView> CreateHoldAsync(Guid actor, CreateRetentionHoldRequest request, string key, CancellationToken token)
    {
        Reason(request.Reason); Key(key);
        if (request.ScopeType is not ("PROJECT" or "FILE") || request.ScopeId == Guid.Empty) throw new RetentionRequestException(422, "validation_error");
        return await repository.CreateHoldAsync(actor, request, key, token);
    }
    public async Task<RetentionHoldView> GetHoldAsync(Guid actor, Guid holdId, CancellationToken token) => await repository.GetHoldAsync(actor, holdId, token);
    public async Task<RetentionHoldView> ReleaseHoldAsync(Guid actor, Guid holdId, ReleaseRetentionHoldRequest request, string key, string expected, CancellationToken token)
    {
        Reason(request.Reason); Key(key); Version(expected);
        return await repository.ReleaseHoldAsync(actor, holdId, request, key, expected, token);
    }
    public async Task<RetentionEvaluationView> AdmitEvaluationAsync(Guid actor, Guid project, CreateRetentionEvaluationRequest request, string key, CancellationToken token)
    {
        Key(key);
        if (request.FileIds is { } ids && (ids.Length == 0 || ids.Length > 500 || ids.Distinct().Count() != ids.Length || ids.Contains(Guid.Empty))) throw new RetentionRequestException(422, "validation_error");
        return await repository.AdmitEvaluationAsync(actor, project, request, key, token);
    }
    public async Task<RetentionEvaluationView> GetEvaluationAsync(Guid actor, Guid project, Guid id, Guid? afterFile, int pageSize, CancellationToken token)
    {
        if (pageSize is < 1 or > 200) throw new RetentionRequestException(422, "validation_error");
        return await repository.GetEvaluationAsync(actor, project, id, afterFile, pageSize, token);
    }
    public Task<bool> ProcessOneAsync(CancellationToken token) => repository.ProcessOneAsync(token);
    private static void Reason(string? reason) { if (string.IsNullOrWhiteSpace(reason) || reason.Trim().Length > 2000) throw new RetentionRequestException(422, "validation_error"); }
    private static void Key(string key) { if (string.IsNullOrWhiteSpace(key)) throw new RetentionRequestException(428, "validation_error"); if (key.Length > 128) throw new RetentionRequestException(422, "validation_error"); }
    private static void Version(string version) { if (string.IsNullOrWhiteSpace(version)) throw new RetentionRequestException(428, "validation_error"); }
}

