    {
        using var doc = JsonDocument.Parse(json);
        return doc.RootElement.ValueKind == JsonValueKind.Object && doc.RootElement.TryGetProperty("accessPoint", out var point) && point.ValueKind != JsonValueKind.Null ? point.Clone() : null;
    }

