private async Task<UploadServiceResult> CreateCoreAsync(Guid actorUserId, UserRoleCode role,
    UploadCreateRequestDto request, string idempotencyKey, Guid? correlationId,
    OfflineUploadCreateRequestDto? offline, CancellationToken cancellationToken)
{
    if (!IsSupportedRole(role) || !IsValidCreate(actorUserId, request, idempotencyKey) || !ValidOptions())
    {
        return new(UploadServiceStatus.InvalidInput);
    }

    if (!await InProjectScopeAsync(actorUserId, role, request.ProjectId!.Value, cancellationToken))
    {
        return new(UploadServiceStatus.Forbidden);
    }

    if (offline is null && IsFieldPurpose(request.Purpose) && (request.TargetId is not Guid fieldTask ||
        !await _repository.IsCurrentFieldActorAsync(actorUserId, role, request.ProjectId.Value, fieldTask, request.Purpose.Trim().ToUpperInvariant(), true, cancellationToken)))
        return new(UploadServiceStatus.Forbidden);

    if (IsSurveyPurpose(request.Purpose) && (role != UserRoleCode.DroneOperator || request.TargetId is not { } taskId ||
        !await _repository.IsCurrentSurveyOperatorAsync(actorUserId, request.ProjectId.Value, taskId, true, cancellationToken)))
        return new(UploadServiceStatus.Forbidden);

    var maximum = UploadAdmissionPolicy.MaximumBytes(request.Purpose, request.MediaType);
    if (maximum is null || request.SizeBytes > maximum)
        return new(UploadServiceStatus.InvalidInput, MaxBytes: maximum, ActualBytes: request.SizeBytes);

    var now = _timeProvider.GetUtcNow();
    var normalized = Normalize(request);
    var persistence = new UploadCreatePersistenceRequest(
        actorUserId,
        normalized.ProjectId!.Value,
        normalized.TargetId,
        normalized.Purpose,
        normalized.FileName,
        normalized.MediaType,
        normalized.SizeBytes,
        normalized.ChecksumSha256,
        _options.PartSizeBytes,
        now.AddHours(_options.SessionLifetimeHours),
        idempotencyKey.Trim(),
        Fingerprint($"{normalized.Purpose}|{normalized.ProjectId}|{normalized.TargetId}|{normalized.FileName}|{normalized.MediaType}|{normalized.SizeBytes}|{normalized.ChecksumSha256}"),
        correlationId);
    var result = offline is null ? await _repository.CreateAsync(persistence, cancellationToken) :
        await _repository.CreateOfflineAsync(new(normalized.ProjectId!.Value, normalized.TargetId!.Value,
            offline.AdmissionId, offline.CaptureOriginId, actorUserId, role,
            persistence with { RequestFingerprint = Fingerprint($"{persistence.RequestFingerprint}|{offline.AdmissionId:D}|{offline.CaptureOriginId:D}") }), cancellationToken);

private async Task<UploadMutationPersistenceResult> CreateCoreAsync(UploadCreatePersistenceRequest request,
    RoadGuardSystem.Repositories.Offline.OfflineUploadCaptureRequest? offline, CancellationToken cancellationToken)
{
    if (request.SizeBytes <= 0 || UploadAdmissionPolicy.MaximumBytes(request.Purpose, request.MediaType) is not { } maximum || request.SizeBytes > maximum)
    {
        return new(UploadPersistenceStatus.InvalidInput, null);
    }

    try
    {
        var outcome = await _idempotency.ExecuteAsync(
            request.ActorUserId,
            request.ProjectId,
            offline is null ? CreateOperation : "OfflineUploadSessionCreated",
            request.IdempotencyKey,
            request.RequestFingerprint,
            async token =>
            {
                var capture = offline is null ? null : await OfflineUploads.GuardNewUploadAsync(offline, token);
                if (request.ProjectId is null) await GuardPrivateAsync(request.ActorUserId, null, token);
                else if (offline is null && FieldPurpose(request.Purpose)) await GuardFieldScopeAsync(request.ActorUserId, request.ProjectId.Value, request.TargetId, request.Purpose, true, token);
                var now = _fieldClock.GetUtcNow();
                var fileId = Guid.NewGuid();
                var objectKey = $"uploads/{fileId:N}";
                var file = StoredFile.Create(
                    fileId,
                    objectKey,
                    request.FileName,
                    request.MediaType,
                    request.SizeBytes,
                    request.ChecksumSha256,
                    request.ActorUserId,
                    now,
                    retentionUntil: null);
                var session = UploadSession.Create(
                    Guid.NewGuid(),
                    fileId,
                    request.ActorUserId,
                    objectKey,
                    request.Purpose,
                    request.MediaType,
                    request.SizeBytes,
                    request.ChecksumSha256,
                    request.PartSizeBytes,
                    request.ExpiresAt);
                _context.Files.Add(file);
                _context.FileScopes.Add(request.ProjectId is { } projectId
                    ? FileScope.Create(Guid.NewGuid(), fileId, projectId, request.TargetId, request.ActorUserId, request.Purpose, now)
                    : request.Purpose == "REPORT_PHOTO" && request.TargetId is null
                        ? FileScope.CreatePrivate(Guid.NewGuid(), fileId, request.ActorUserId, now)
                        : throw new ArgumentException("Invalid private scope."));
                _context.UploadSessions.Add(session);
                _context.AuditLogs.Add(AuditLog.Create(
                    Guid.NewGuid(),
                    request.ActorUserId,
                    now,
                    "upload_session_created",
                    "UploadSession",
                    session.Id,
                    null,
                    JsonSerializer.Serialize(new { session.Id, session.FileId, request.ProjectId, request.Purpose }),
                    "Upload session created",
                    "p2-023",
                    request.CorrelationId,
                    ["id", "fileId", "projectId", "purpose"]));
                await _context.SaveChangesAsync(token);
                if (capture is not null)
                {
                    await OfflineUploads.BindCreatedFileAsync(capture, fileId, session.Id, now, token);
                    await _context.SaveChangesAsync(token);
                }
                return (session.Id, JsonSerializer.Serialize(ToView(session, request.ProjectId, request.TargetId)));
            },
            cancellationToken,
            receiptAccessGuard: offline is not null ? token => GuardOfflineUploadReceiptAsync(offline, token) : request.ProjectId is null
                ? token => GuardPrivateAsync(request.ActorUserId, null, token) : FieldPurpose(request.Purpose)
                    ? token => GuardFieldScopeAsync(request.ActorUserId, request.ProjectId.Value, request.TargetId, request.Purpose, false, token) : null);

        if (outcome.Status == IdempotencyOperationStatus.Conflict)
        {
            return new(UploadPersistenceStatus.Conflict, null);
        }

        var view = JsonSerializer.Deserialize<UploadSessionPersistenceView>(outcome.OutcomeJson)
            ?? throw new InvalidOperationException("Upload session replay payload is invalid.");
        return new(outcome.Status == IdempotencyOperationStatus.Replayed ? UploadPersistenceStatus.Replayed : UploadPersistenceStatus.Success, view);
    }
    catch (UploadNotFoundException)
    {
        return new(UploadPersistenceStatus.NotFound, null);
    }
    catch (RoadGuardSystem.Repositories.Offline.OfflineAdmissionRejectedException)
    {
        _context.ChangeTracker.Clear(); return new(UploadPersistenceStatus.NotFound, null);
    }
    catch (ArgumentException)
    {
        return new(UploadPersistenceStatus.InvalidInput, null);
    }
}

    public static long? MaximumBytes(string purpose, string mediaType)
    {
        var mime = mediaType.Trim().ToLowerInvariant();
        return purpose.Trim().ToUpperInvariant() switch
        {
            "REPORT_PHOTO" or "BEFORE" or "AFTER" or "MEASUREMENT" when mime is "image/jpeg" or "image/png" => PhotoMaxBytes,
            "SURVEY_VIDEO" when mime == "video/mp4" => VideoMaxBytes,
            "TELEMETRY" when mime == "application/x-subrip" => TelemetryMaxBytes,
            // These purposes retain the existing int ceiling; PR-38 assigns no new limit.
            "DOCUMENT" or "ROUTE_SOURCE" => int.MaxValue,
            _ => null
        };
    }
}

